def _compose_ai_history_reason(ai_result: dict) -> str:
    """One dashboard line: decision plus reject/block comment."""
    decision = str((ai_result or {}).get("decision") or "").strip()
    reason = str((ai_result or {}).get("reason") or "").strip()
    comment = str((ai_result or {}).get("comment") or "").strip()
    parts = []
    if decision:
        parts.append(decision)
    if reason and reason not in parts:
        parts.append(reason)
    if comment and comment not in parts and comment != reason:
        parts.append(comment[:300])
    return " | ".join(parts)[:500]


def json_for_js(value) -> str:
    """Serialize a value as a JS expression (JSON), safe inside a script/file.

    Restored AI payloads can contain backticks, quotes, and newlines. Embedding
    them in a template literal or an unescaped Python ``\\n`` inside DASHBOARD_JS
    breaks the dashboard file. JSON text uses double quotes, so those characters
    stay inside string values and cannot close surrounding JS syntax.
    """
    blob = json.dumps(value, default=str, ensure_ascii=False)
    return (
        blob.replace("\u2028", "\\u2028")
        .replace("\u2029", "\\u2029")
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
    )


def restore_last_ai_payload_from_log(path: str = None) -> bool:
    """After restart, LAST_AI_PAYLOAD is RAM-only. Reload the last logged context."""
    global LAST_AI_PAYLOAD, LAST_AI_TIMESTAMP
    path = path or AI_INPUT_LOG_FILE
    if not os.path.isfile(path):
        return False
    last = None
    try:
        with open(path, "r", encoding="utf-8") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                ctx = row.get("context")
                if isinstance(ctx, dict) and ctx:
                    last = row
        if not last:
            return False
        payload = copy.deepcopy(last.get("context") or {})
        payload = json.loads(json.dumps(payload, default=str))
        payload["_dashboard_restore"] = {
            "status": "RESTORED_AFTER_RESTART",
            "message": (
                "Last AI payload restored from ai_input_log.jsonl after process start. "
                "The next live scan replaces this snapshot."
            ),
            "logged_ts": last.get("ts"),
            "decision": (last.get("ai") or {}).get("decision"),
        }
        LAST_AI_PAYLOAD = payload
        LAST_AI_TIMESTAMP = last.get("ts") or utc_iso()
        logger.info(
            "[AI PAYLOAD] restored last snapshot from %s ts=%s decision=%s [PIPELINE ENFORCEMENT]",
            path,
            LAST_AI_TIMESTAMP,
            (last.get("ai") or {}).get("decision"),
        )
        return True
    except Exception as exc:
        logger.warning(f"[AI PAYLOAD] restore failed: {exc} [PIPELINE ENFORCEMENT]")
        return False


def get_golden_stack_thresholds() -> dict:
    """Production vs research-relaxed golden stack limits."""
    if is_research_data_collection() and AI_RESEARCH_MODE_ENABLED:
        return {
            "chop_max": GOLDEN_STACK_CHOP_MAX,
            "spread_min": 1,
            "spread_max": GOLDEN_STACK_SPREAD_MAX,
            "short_struct_max": -2.0,
            "ema_dist_max_pct": 1.5,
        }
    return {
        "chop_max": GOLDEN_STACK_CHOP_MAX,
        "spread_min": GOLDEN_STACK_SPREAD_MIN,
        "spread_max": GOLDEN_STACK_SPREAD_MAX,
        "short_struct_max": GOLDEN_STACK_SHORT_STRUCT_MAX,
        "ema_dist_max_pct": GOLDEN_STACK_EMA_DIST_MAX_PCT,
    }


def golden_stack_config_for_dashboard() -> dict:
    """Static gate definitions for dashboard (mirrors v86 enforce rules)."""
    gs = get_golden_stack_thresholds()
    return {
        "chop_max": gs["chop_max"],
        "adx_block_low": GOLDEN_STACK_ADX_BLOCK_LOW,
        "adx_block_high": GOLDEN_STACK_ADX_BLOCK_HIGH,
        "spread_min": gs["spread_min"],
        "spread_max": gs["spread_max"],
        "short_struct_max": gs["short_struct_max"],
        "ema_dist_max_pct": gs["ema_dist_max_pct"],
        "ema_dist_ideal_pct": GOLDEN_STACK_EMA_DIST_IDEAL_MAX_PCT,
        "entry_mode_required": ENTRY_MODE_EMA_HYBRID,
        "block_high_pos_funding": GOLDEN_STACK_BLOCK_HIGH_POS_FUNDING,
        "ladder_first_rung": f"{TRAIL_LADDER[0][0]}% peak → lock {TRAIL_LADDER[0][1]}%",
        "full_margin_when_on": True,
        "edge_ai_gated": False,
    }

def capture_golden_stack_eval(signal: dict, ai: dict, edge_score: float, features: dict = None) -> dict:
    """Frozen v86 golden-stack check breakdown for analyzer replay."""
    direction = str(signal.get("final_direction") or ai.get("direction") or "").upper()
    ctx = signal.get("context") or {}
    features = features or signal.get("features") or {}
    mc = ctx.get("market_context") or state.get("market_context") or {}
    mtf = (mc.get("multi_tf") or {}) if isinstance(mc.get("multi_tf"), dict) else {}
    ts = (mc.get("trend_strength") or {}) if isinstance(mc.get("trend_strength"), dict) else {}
    ms = (mc.get("market_structure") or {}) if isinstance(mc.get("market_structure"), dict) else {}
    gs_thr = get_golden_stack_thresholds()
    adx = float(ts.get("adx") or 0)
    mom = round(_compute_momentum_metric(features), 4)
    spread = int(compute_directional_spread(direction, ai))
    struct = float(ms.get("structure_score") or 0)
    agreement = str(mtf.get("agreement") or "")
    entry_mode = str(signal.get("entry_mode") or "")
    dist_pct = signal.get("dist_to_ema_hybrid_pct")
    if dist_pct is None:
        dist_pct = signal.get("dist_to_micro_sr_pct")
    regime = capture_entry_regime_snapshot(signal, features)
    funding_bucket = regime.get("funding_bucket") or _funding_bucket(state.get("funding") or {})
    checks = {
        "enabled": True,
        "chop_max": gs_thr["chop_max"],
        "mom": mom,
        "chop_pass": mom <= gs_thr["chop_max"] + 1e-9,
        "adx": adx,
        "adx_block_band": GOLDEN_STACK_ADX_BLOCK_LOW <= adx < GOLDEN_STACK_ADX_BLOCK_HIGH,
        "adx_pass": not (GOLDEN_STACK_ADX_BLOCK_LOW <= adx < GOLDEN_STACK_ADX_BLOCK_HIGH),
        "mtf_agreement": agreement,
        "mtf_pass": (direction != "SHORT") or agreement == "BEAR_ALIGNED",
        "structure_score": struct,
        "struct_pass": (direction != "SHORT") or struct <= gs_thr["short_struct_max"],
        "spread": spread,
        "spread_pass": gs_thr["spread_min"] <= spread <= gs_thr["spread_max"],
        "entry_mode": entry_mode,
        "ema_hybrid_required": entry_mode in (ENTRY_MODE_EMA_HYBRID, ENTRY_MODE_MICRO_SR, ENTRY_MODE_AI_PLANNER),
        "dist_to_ema_hybrid_pct": dist_pct,
        "ema_dist_pass": dist_pct is None or float(dist_pct) <= gs_thr["ema_dist_max_pct"],
        "ema_dist_ideal": dist_pct is not None and float(dist_pct) <= GOLDEN_STACK_EMA_DIST_IDEAL_MAX_PCT,
        "funding_bucket": funding_bucket,
        "funding_pass": funding_bucket in ("NEUTRAL", "LOW_NEG", "LOW_POS") or not GOLDEN_STACK_BLOCK_HIGH_POS_FUNDING,
        "session_utc": regime.get("session_utc"),
        "vol_bucket": regime.get("volatility_bucket"),
        "sr_state": regime.get("sr_state"),
    }
    checks["golden_stack_pass"] = all(
        checks[k] for k in (
            "chop_pass", "adx_pass", "mtf_pass", "struct_pass", "spread_pass",
            "ema_hybrid_required", "ema_dist_pass", "funding_pass",
        )
    )
    checks["would_fail"] = golden_stack_would_fail_list(checks)
    checks["would_fail_mtf"] = not checks["mtf_pass"]
    checks["would_fail_spread"] = not checks["spread_pass"]
    checks["would_fail_structure"] = not checks["struct_pass"]
    checks["would_fail_chop"] = not checks["chop_pass"]
    checks["would_fail_adx"] = not checks["adx_pass"]
    checks["would_fail_ema"] = not checks["ema_hybrid_required"] or not checks["ema_dist_pass"]
    checks["would_fail_funding"] = not checks["funding_pass"]
    return checks


def golden_stack_would_fail_list(checks: dict) -> list:
    """Human-readable list of gates that failed for golden_stack_rejections.jsonl."""
    fails = []
    if not checks.get("chop_pass"):
        fails.append("chop")
    if not checks.get("adx_pass"):
        fails.append("adx")
    if not checks.get("mtf_pass"):
        fails.append("mtf")
    if not checks.get("struct_pass"):
        fails.append("structure")
    if not checks.get("spread_pass"):
        fails.append("spread")
    if not checks.get("ema_hybrid_required"):
        fails.append("entry_mode")
    elif not checks.get("ema_dist_pass"):
        fails.append("ema_dist")
    if not checks.get("funding_pass"):
        fails.append("funding")
    return fails


def evaluate_golden_stack_filter(
    direction: str, ctx: dict, ai: dict, features: dict, edge_score: float, signal: dict
) -> tuple:
    """v86 combined gate stack. Edge/AI thresholds intentionally excluded (dashboard)."""
    if not direction:
        return False, None
    features = features or {}
    mc = ctx.get("market_context") or state.get("market_context") or {}
    mtf = (mc.get("multi_tf") or {}) if isinstance(mc.get("multi_tf"), dict) else {}
    ts = (mc.get("trend_strength") or {}) if isinstance(mc.get("trend_strength"), dict) else {}
    ms = (mc.get("market_structure") or {}) if isinstance(mc.get("market_structure"), dict) else {}
    gs_thr = get_golden_stack_thresholds()
    adx = float(ts.get("adx") or 0)
    mom = _compute_momentum_metric(features)
    if mom > gs_thr["chop_max"]:
        return True, f"MOMENTUM_CHOP_{mom:.2f}"
    if GOLDEN_STACK_ADX_BLOCK_LOW <= adx < GOLDEN_STACK_ADX_BLOCK_HIGH:
        return True, f"ADX_BAND_{adx:.1f}"
    agreement = str(mtf.get("agreement") or "")
    if direction == "SHORT" and agreement != "BEAR_ALIGNED":
        if is_research_data_collection() and not MTF_BLOCKING_RESEARCH:
            signal.setdefault("golden_stack_mtf_warn", f"SHORT_MTF_{agreement or 'UNKNOWN'}")
        else:
            return True, f"SHORT_REQUIRES_BEAR_MTF_{agreement or 'UNKNOWN'}"
    struct = float(ms.get("structure_score") or 0)
    if direction == "SHORT" and struct > gs_thr["short_struct_max"]:
        return True, f"STRUCTURE_{struct:.1f}"
    spread = int(compute_directional_spread(direction, ai))
    if spread < gs_thr["spread_min"]:
        return True, f"SPREAD_LOW_{spread}"
    if spread > gs_thr["spread_max"]:
        return True, f"SPREAD_HIGH_{spread}"
    entry_mode = str(signal.get("entry_mode") or "")
    if entry_mode not in (
        ENTRY_MODE_EMA_HYBRID, ENTRY_MODE_MICRO_SR, ENTRY_MODE_AI_PLANNER,
        ENTRY_MODE_AI_DIRECT, ENTRY_MODE_5M_TRIGGER,
    ):
        return True, f"ENTRY_MODE_{entry_mode or 'UNKNOWN'}"
    dist_pct = signal.get("dist_to_ema_hybrid_pct")
    if dist_pct is None:
        dist_pct = signal.get("dist_to_micro_sr_pct")
    if dist_pct is not None and float(dist_pct) > gs_thr["ema_dist_max_pct"]:
        return True, f"EMA_DIST_{float(dist_pct):.3f}"
    if GOLDEN_STACK_BLOCK_HIGH_POS_FUNDING:
        funding_bucket = _funding_bucket(state.get("funding") or {})
        if funding_bucket == "HIGH_POS":
            return True, f"FUNDING_{funding_bucket}"
    return False, None

def _golden_stack_gate_exit(signal, ai, reason: str, edge_score: float) -> bool:
    """Golden-stack eval is log-only — never blocks benchmark/spawn lanes."""
    trade_id = signal.get("trade_id")
    tag = f"GOLDEN_STACK_{reason}"
    gs_eval = signal.get("golden_stack_eval") or {}
    log_golden_stack_rejection(signal, ai, gs_eval, edge_score, block_reason=reason)
    if is_research_data_collection():
        _research_log_would_block(signal, ai, tag, edge_score)
        return False
    logger.info(f"[GOLDEN_STACK] BLOCK {reason} trade_id={trade_id} [PIPELINE ENFORCEMENT]")
    log_blocked_signal(signal, ai, tag)
    log_pipeline_event("POST_AI", "BLOCKED", tag, trade_id, edge_score, force=True)
    exit_pipeline(signal, ai, tag)
    with state_lock:
        state["debug_state"]["last_block_reason"] = tag
        state["debug_state"]["last_pipeline_stage"] = "BLOCKED"
        state["debug_state"]["skip_reason"] = tag
    update_debug_state_always(tag, {"edge": edge_score, "golden_stack": True})
    return True

def _rollover_daily_pnl_if_new_utc_day() -> tuple:
    """Reset daily PnL / loss-streak counters at UTC midnight.

    Without this, daily_pnl_usd only resets on process restart, so a single
    losing day trips DAILY_DRAWDOWN and the bot stays paused forever — /api/resume
    cannot clear it because the very next risk_trading_allowed() call re-trips
    the same drawdown check on stale (yesterday's) PnL. This unblocks that
    deadlock by resetting the calendar bucket when the UTC date advances.

    Returns (rolled_over: bool, pause_reason_before_reset: str). The caller is
    responsible for clearing a stale DAILY_DRAWDOWN pause OUTSIDE state_lock.
    """
    today = datetime.now(timezone.utc).date()
    with state_lock:
        last_day = state.get("current_trading_day")
        if last_day == today:
            return False, ""
        prev_pnl = float(state.get("daily_pnl_usd", 0.0) or 0.0)
        prev_reason = str(state.get("execution_reason") or "")
        state["daily_pnl_usd"] = 0.0
        state["consecutive_losses"] = 0
        state["current_trading_day"] = today
    logger.info(
        f"[RISK] DAILY PnL rolled over for UTC day {today} "
        f"(prev daily_pnl_usd={prev_pnl:.2f}) [PIPELINE ENFORCEMENT]"
    )
    return True, prev_reason


def risk_trading_allowed() -> bool:
    now = time.time()
    # UTC-day rollover runs first so the drawdown gate always evaluates
    # against the current UTC calendar day, not yesterday's bucket. We do
    # this BEFORE acquiring state_lock for the gates below, because clearing
    # a stale DAILY_DRAWDOWN pause via set_execution_paused("") must not run
    # while we hold state_lock (it cancels pending orders outside the lock).
    rolled_over, pause_reason = _rollover_daily_pnl_if_new_utc_day()
    if rolled_over and pause_reason == "DAILY_DRAWDOWN":
        set_execution_paused("")

    # A successful operator resume/reset can leave the persisted pause label
    # behind after its loss counters and timer have already been cleared.  Do
    # not let that stale label re-pause an otherwise healthy executor forever.
    # Snapshot under the lock, but clear through the canonical pause setter
    # outside it: that setter performs disarm/order work and must not be called
    # recursively while state_lock is held.
    with state_lock:
        loss_pause_until = float(state.get("loss_pause_until", 0) or 0)
        consecutive_losses = int(state.get("consecutive_losses", 0) or 0)
        stale_loss_pause = (
            bool(state.get("execution_paused"))
            and state.get("execution_reason") == "LOSS_STREAK"
            and loss_pause_until <= 0
            and consecutive_losses < CONSECUTIVE_LOSS_PAUSE
        )
        expired_loss_pause = (
            state.get("execution_reason") == "LOSS_STREAK"
            and loss_pause_until > 0
            and loss_pause_until <= now
        )
        if expired_loss_pause:
            state["loss_pause_until"] = 0
    if stale_loss_pause or expired_loss_pause:
        set_execution_paused("")

    # Paper/research Showcase must keep collecting. A -$20 DAILY_DRAWDOWN cap
    # or 2h LOSS_STREAK pause stops new paper trades and starves the dataset.
    # Live copy (FORCE_PAPER_MODE off and not unarmed RESEARCH) still uses both.
    if _paper_skips_entry_risk_pauses():
        with state_lock:
            paper_risk_paused = bool(state.get("execution_paused")) and state.get(
                "execution_reason"
            ) in ("DAILY_DRAWDOWN", "LOSS_STREAK")
        if paper_risk_paused:
            set_execution_paused("")
        return True

    with state_lock:
        pause_until = state.get("loss_pause_until", 0)
        if pause_until > now:
            return False
        if state.get("daily_pnl_usd", 0) <= -DAILY_DRAWDOWN_PAUSE_USD:
            if not state.get("execution_paused") or state.get("execution_reason") != "DAILY_DRAWDOWN":
                set_execution_paused("DAILY_DRAWDOWN")
            return False
        if state.get("consecutive_losses", 0) >= CONSECUTIVE_LOSS_PAUSE:
            if state.get("loss_pause_until", 0) <= now:
                state["loss_pause_until"] = now + LOSS_PAUSE_SEC
                set_execution_paused("LOSS_STREAK")
            return False
    if state.get("execution_paused") and state.get("execution_reason") in ("DAILY_DRAWDOWN", "LOSS_STREAK"):
        return False
    return True

def ensure_directional_capacity(direction: str, lane: str = None) -> bool:
    direction = direction.upper()
    if is_research_data_collection():
        cap = get_effective_max_active_signals()
        return count_directional_exposure(direction, lane=None) < cap
    prof = get_regime_risk_profile()
    cap = prof["max_long"] if direction == "LONG" else prof["max_short"]
    cap = min(cap, MAX_LONGS if direction == "LONG" else MAX_SHORTS)
    return count_directional_exposure(direction) < cap

def get_effective_max_active_signals() -> int:
    with state_lock:
        user_max = int(state.get("max_active_signals") or MAX_CONCURRENT_POSITIONS_DEFAULT)
    # Dashboard value is authoritative (research capped at RESEARCH_MAX_CONCURRENT_CAP).
    return min(user_max, RESEARCH_MAX_CONCURRENT_CAP)

def _ws_trade_timestamp_sec(trade: dict) -> float:
    trade_ts_raw = trade.get("T")
    if not trade_ts_raw:
        return time.time()
    return float(trade_ts_raw) / 1000 if float(trade_ts_raw) > 1e12 else float(trade_ts_raw)

def _is_stale_ws_trade(trade: dict) -> bool:
    """Reject aged or pre-reconnect replay ticks that inflate MFE / false fills."""
    now = time.time()
    trade_ts = _ws_trade_timestamp_sec(trade)
    age = now - trade_ts
    if age < -1.0:
        return True
    if age > WS_MAX_STALE_TRADE_SEC:
        return True
    ws_conn = float(state.get("ws_connected_ts") or 0)
    if ws_conn > 0 and (now - ws_conn) < WS_RECONNECT_STALE_GRACE_SEC and trade_ts < (ws_conn - 0.5):
        return True
    return False

def _position_monitor_interval_sec() -> float:
    trigger = TRAIL_LADDER[0][0]
    health = state.get("trend_health") or {}
    ts = str(health.get("trend_state") or "")
    with trade_lock:
        for pos in open_positions:
            if isinstance(pos, dict) and pos.get("status") == "OPEN":
                if float(pos.get("max_pnl_pct") or 0) >= trigger:
                    return LADDER_ARMED_MONITOR_INTERVAL_SEC
                direction = str(pos.get("dir") or "").upper()
                if direction == "LONG" and ts == "BULL_WEAKENING":
                    return LADDER_ARMED_MONITOR_INTERVAL_SEC
                if direction == "SHORT" and ts == "BEAR_WEAKENING":
                    return LADDER_ARMED_MONITOR_INTERVAL_SEC
    return POSITION_MONITOR_INTERVAL_SEC

def _log_ladder_exit_audit(pos: dict, price: float, unreal_pct: float, peak: float, lock_floor: float):
    if peak < TRAIL_LADDER[0][0] or lock_floor is None:
        return
    now = time.time()
    last_log = float(pos.get("_ladder_audit_ts") or 0)
    near_floor = unreal_pct <= (lock_floor + 3.0)
    crossed = pos.get("_prev_unreal_pct") is not None and float(pos["_prev_unreal_pct"]) > lock_floor >= unreal_pct
    if not near_floor and not crossed:
        return
    if not crossed and (now - last_log) < LADDER_AUDIT_LOG_INTERVAL_SEC:
        return
    pos["_ladder_audit_ts"] = now
    entry = float(pos.get("entry") or 0)
    logger.info(
        f"[LADDER AUDIT] trade_id={pos.get('trade_id')} entry={fmt(entry)} price={fmt(price)} "
        f"source={state.get('price_source', 'WS')} peak={peak:.2f}% lock={lock_floor:.2f}% "
        f"unreal={unreal_pct:.2f}% crossed={crossed} [PIPELINE ENFORCEMENT]"
    )

def _apply_offset_029_atr_exit(pos: dict, price: float, now: float) -> bool:
    """Exact paper exit for the selected replay policy, without Scenario C."""
    if str(pos.get("research_lane") or "").upper() != RESEARCH_LANE_OFFSET_029_ATR_TP_25:
        return False
    entry = float(pos.get("entry") or 0)
    direction = str(pos.get("dir") or "").upper()
    entry_ts = float(pos.get("entry_ts") or 0)
    atr_abs = _buf_float(pos.get("atr14_3m"), 0.0)
    atr_pct = _buf_float(pos.get("atr14_pct_3m"), 0.0)
    reason, target = offset029_policy.exit_decision(
        entry=entry, direction=direction, price=price, atr_abs=atr_abs,
        atr_pct=atr_pct, age_sec=(now - entry_ts if entry_ts else 0),
    )
    if target is not None:
        pos["atr_tp_price"] = round(target, 2)
    if reason:
        pos["exit_policy_id"] = offset029_policy.POLICY_ID
        if reason == "PATH_END_120M":
            pos["path_end_mark_price"] = float(price)
        close_position(pos, reason)
        return True
    if target is None:
        pos["atr_tp_unavailable"] = True
    return False


def _apply_protected_patient_chase_exit(pos: dict, price: float, now: float) -> bool:
    """Apply a frozen protected policy and persist partial/transition receipts."""
    position_before_action = copy.deepcopy(pos)
    lane = str(pos.get("research_lane") or "").upper()
    entry = float(pos.get("entry") or 0); direction = str(pos.get("dir") or "").upper()
    atr_abs = _buf_float(pos.get("atr14_3m"), 0.0)
    if atr_abs <= 0:
        atr_abs = entry * _buf_float(pos.get("atr14_pct_3m"), 0.0) / 100.0
    age = now - float(pos.get("entry_ts") or now)
    remaining = float(pos.get("policy_remaining_fraction", 1.0))
    if lane == RESEARCH_LANE_OFFSET_029_ATR_REGIME:
        health = state.get("trend_health") or {}
        market_context = state.get("market_context") or {}
        observed = offset029_regime_policy.classify_regime(
            direction=direction,
            market_regime=state.get("regime"),
            trend_state=health.get("trend_state"),
            base_state=health.get("base_state"),
            adx=(market_context.get("trend_strength") or {}).get("adx"),
        )
        prior = str(pos.get("policy_regime") or observed)
        prior_stop = float(pos.get("policy_stop_distance_atr") or offset029_regime_policy.PROFILES[offset029_regime_policy.normalize_regime(prior)]["stop"])
        change = offset029_regime_policy.transition(previous_regime=prior, observed_regime=observed,
                                                     current_stop_distance_atr=prior_stop)
        if change["changed"]:
            pos.setdefault("regime_transition_receipts", []).append({"ts": utc_iso(), **change})
        pos["policy_regime"] = change["to"]
        pos["policy_stop_distance_atr"] = change["applied_stop_atr"]
        action = offset029_regime_policy.exit_action(
            entry=entry, direction=direction, price=price, atr_abs=atr_abs, age_sec=age,
            regime=change["to"], current_stop_distance_atr=change["applied_stop_atr"],
            remaining_fraction=remaining, completed_partials=pos.get("policy_completed_partials") or (),
            peak_price=pos.get("policy_peak_price"),
        )
        if action:
            pos["policy_peak_price"] = action["peak_price"]
            if action.get("partial_key") is not None:
                pos.setdefault("policy_completed_partials", []).append(action["partial_key"])
    else:
        action = offset029_protected_policy.exit_action(
            entry=entry, direction=direction, price=price, atr_abs=atr_abs, age_sec=age,
            leverage=float(pos.get("leverage") or 100), remaining_fraction=remaining,
            first_partial_done=bool(pos.get("policy_first_partial_done")),
            second_partial_done=bool(pos.get("policy_second_partial_done")),
            break_even_armed=bool(pos.get("policy_break_even_armed")),
            peak_price=pos.get("policy_peak_price"),
        )
        if action:
            pos["policy_first_partial_done"] = action.first_partial_done
            pos["policy_second_partial_done"] = action.second_partial_done
            pos["policy_break_even_armed"] = action.break_even_armed
            pos["policy_peak_price"] = action.peak_price
    if not action:
        return False
    close_fraction = float(action.get("close_fraction") if isinstance(action, dict) else action.close_fraction)
    remaining_after = float(action.get("remaining_fraction") if isinstance(action, dict) else action.remaining_fraction)
    reason = str(action.get("reason") if isinstance(action, dict) else action.reason)
    original_qty = float(pos.get("policy_original_qty") or pos.get("qty") or 0)
    pos.setdefault("policy_original_qty", original_qty)
    # Terminal actions are valued by close_position.  Only an action that
    # leaves a runner books an intermediate realized leg here.
    close_qty = max(0.0, original_qty * close_fraction) if remaining_after > 0 else 0.0
    dir_factor = 1.0 if direction == "LONG" else -1.0
    realized_gross = (float(price) - entry) * dir_factor * close_qty
    pos["policy_partial_realized_gross_usd"] = round(
        _buf_float(pos.get("policy_partial_realized_gross_usd"), 0.0) + realized_gross, 8
    )
    # BITFINEX_ZERO is the active research fee model.  Keep a distinct net
    # field so a future non-zero model can allocate costs per reduction without
    # changing the lifecycle schema.
    pos["policy_partial_realized_net_usd"] = pos["policy_partial_realized_gross_usd"]
    reduction_seq = 1 + max(
        [
            int(receipt.get("event_seq") or 0)
            for receipt in (pos.get("partial_exit_receipts") or [])
            if isinstance(receipt, dict)
        ]
        or [0]
    )
    reduction_key = str(
        action.get("partial_key") if isinstance(action, dict) else reason
    ).strip().replace(" ", "_")
    reduction_event_id = f"{pos.get('trade_id')}:POSITION_REDUCED:{reduction_key}"
    reduction_id = f"{pos.get('trade_id')}:{reduction_key}"
    before_qty = float(pos.get("qty") or 0)
    after_qty = max(0.0, original_qty * remaining_after)
    reduction_receipt = {
        "schema": "paper_position_reduction_v1",
        "event": "POSITION_REDUCED",
        "event_id": reduction_event_id,
        "reduction_id": reduction_id,
        "receipt_id": reduction_id,
        "event_seq": reduction_seq,
        "ts": utc_iso(), "reason": reason, "close_fraction": close_fraction,
        "remaining_fraction": remaining_after, "fill_price": float(price), "policy_id": pos.get("policy_id"),
        "original_qty": round(original_qty, 8),
        "prior_qty": round(before_qty, 8),
        "reduced_qty": round(close_qty if remaining_after > 0 else before_qty, 8),
        "closed_qty": round(close_qty if remaining_after > 0 else before_qty, 8),
        "remaining_qty": round(after_qty, 8),
        "realized_gross_usd": round(realized_gross, 8) if remaining_after > 0 else None,
        "cumulative_realized_net_usd": pos["policy_partial_realized_net_usd"],
        "direction": direction,
        "research_lane": lane,
        "policy_signature": pos.get("policy_signature"),
        "policy_epoch_id": pos.get("policy_epoch_id"),
    }
    pos["policy_remaining_fraction"] = remaining_after
    if remaining_after <= 0:
        # A terminal stop/target is a full close, not a partial reduction.
        # Putting it in the partial ledger makes a valid terminal lifecycle
        # appear to contain an unsigned partial-close receipt.
        close_position(pos, reason)
        return True
    pos.setdefault("partial_exit_receipts", []).append(copy.deepcopy(reduction_receipt))
    # Reduce only the local paper leg. Relay reconciliation consumes the signed
    # receipt and may copy it only when separately armed.
    # Persist the immutable outbox receipt in the same atomic paper snapshot as
    # the reduced quantity. Delivery happens only after that local commit.
    pos.setdefault("partial_reduction_outbox", []).append(copy.deepcopy(reduction_receipt))
    pos["qty"] = after_qty
    if not save_paper_lifecycle(reason=f"partial_exit:{reason}"):
        pos.clear()
        pos.update(position_before_action)
        logger.error(
            f"[PAPER REDUCTION] persistence failed; rolled back trade="
            f"{pos.get('trade_id')} event={reduction_event_id}"
        )
        return False
    if _push_showcase_relay_event(
        "POSITION_REDUCED",
        pos.get("trade_id"),
        copy.deepcopy(reduction_receipt),
        wait_for_durable_receipt=True,
    ):
        _ack_partial_reduction_outbox(
            pos.get("trade_id"), reduction_receipt["event_id"]
        )
    return False


def _apply_position_exits(pos: dict, price: float, now: float = None):
    if now is None:
        now = time.time()
    if pos.get("status") == "CLOSED" or pos.get("_close_in_progress"):
        return False
    unreal_pct = unrealized_margin_pct(pos, price)
    with state_lock:
        replay_book = copy.deepcopy(state.get("order_book") or {})
    replay_bid = _buf_float(replay_book.get("best_bid") or replay_book.get("bid"), 0)
    replay_ask = _buf_float(replay_book.get("best_ask") or replay_book.get("ask"), 0)
    append_replay_tick(
        pos.get("trade_id"), price, unreal_pct,
        best_bid=replay_bid or None, best_ask=replay_ask or None, observed_ts=now,
    )
    pos["max_pnl_pct"] = max(pos.get("max_pnl_pct", 0.0), unreal_pct)
    if pos.get("max_drawdown", 0) is None or unreal_pct < pos.get("max_drawdown", 0):
        pos["max_drawdown"] = min(pos.get("max_drawdown", 0.0), unreal_pct)
    entry_ts = float(pos.get("entry_ts") or 0)
    if entry_ts > 0:
        cur_candle = int((now - entry_ts) // CANDLE_INTERVAL_SEC) + 1
        prev_candle = int(pos.get("_candle_track_idx") or 0)
        if cur_candle > prev_candle and cur_candle <= 3:
            pos.setdefault("first_3_candles", {})[str(cur_candle)] = {
                "mfe_pct": round(float(pos.get("max_pnl_pct") or 0), 2),
                "mae_pct": round(float(pos.get("max_drawdown") or 0), 2),
                "unreal_pct": round(float(unreal_pct), 2),
            }
            pos["_candle_track_idx"] = cur_candle

    prev_peak = float(pos.get("_genome_peak_pct") or -999.0)
    new_peak = float(pos.get("max_pnl_pct") or 0)
    if new_peak > prev_peak + 0.01:
        pos["_genome_peak_pct"] = new_peak
        _emit_genome_execution_event("MFE_UPDATED", {
            "trade_id": pos.get("trade_id"),
            "mfe_pct": round(new_peak, 4),
            "research_lane": pos.get("research_lane"),
        })
    prev_mae = float(pos.get("_genome_mae_pct") or 999.0)
    new_mae = float(pos.get("max_drawdown") or 0)
    if new_mae < prev_mae - 0.01:
        pos["_genome_mae_pct"] = new_mae
        _emit_genome_execution_event("MAE_UPDATED", {
            "trade_id": pos.get("trade_id"),
            "mae_pct": round(new_mae, 4),
            "research_lane": pos.get("research_lane"),
        })

    # Booked paper exits must reuse this same side-correct trigger, not a
    # later book-walk VWAP that can make a stop look like a much better fill.
    pos["_exit_eval_price"] = float(price or 0)

    if str(pos.get("research_lane") or "").upper() == RESEARCH_LANE_OFFSET_029_ATR_TP_25:
        return _apply_offset_029_atr_exit(pos, price, now)
    if str(pos.get("research_lane") or "").upper() in {
        RESEARCH_LANE_OFFSET_029_ATR_PROTECTED,
        RESEARCH_LANE_OFFSET_029_ATR_REGIME,
    }:
        return _apply_protected_patient_chase_exit(pos, price, now)

    age_sec = (now - entry_ts) if entry_ts > 0 else 0.0
    if _check_phase_margin_stop(pos, unreal_pct, age_sec):
        return True

    peak = pos.get("max_pnl_pct", 0.0)
    lock_floor = _effective_profit_lock_floor(pos, peak)
    ladder = _position_trail_ladder(pos)
    if peak >= ladder[0][0] and not pos.get("_genome_ladder_armed"):
        pos["_genome_ladder_armed"] = True
        _emit_genome_execution_event("LADDER_STEP_ARMED", {
            "trade_id": pos.get("trade_id"),
            "rung_peak_pct": ladder[0][0],
            "lock_floor_pct": lock_floor,
            "research_lane": pos.get("research_lane"),
        })
    if lock_floor is not None:
        prev_stop = pos.get("_genome_stop_floor")
        if prev_stop is None or float(lock_floor) > float(prev_stop) + 0.01:
            pos["_genome_stop_floor"] = lock_floor
            _emit_genome_execution_event("STOP_UPDATED", {
                "trade_id": pos.get("trade_id"),
                "stop_floor_pct": round(float(lock_floor), 4),
                "peak_pct": round(float(peak), 4),
                "research_lane": pos.get("research_lane"),
            })
    last_pos_update = float(pos.get("_genome_pos_update_ts") or 0)
    if now - last_pos_update >= 60.0:
        pos["_genome_pos_update_ts"] = now
        _emit_genome_execution_event("POSITION_UPDATED", {
            "trade_id": pos.get("trade_id"),
            "unreal_pct": round(float(unreal_pct), 4),
            "peak_pct": round(float(peak), 4),
            "mae_pct": round(float(pos.get("max_drawdown") or 0), 4),
            "research_lane": pos.get("research_lane"),
        })
    _log_ladder_exit_audit(pos, price, unreal_pct, peak, lock_floor)
    # v12: peak-never-loser can fire a PROFIT_LOCK_LADDER exit BELOW the first
    # ladder rung for TYPE_B_HUNTER_V1 (its 3% min_peak is below the 10% first
    # rung). For CONTINUOUS / SR_MICRO the 40% min_peak sits above the first
    # rung so the legacy "peak >= ladder[0][0]" gate remains the operative one.
    pnl_min_peak = _buf_float((pos.get("exit_config") or {}).get("peak_never_loser_min_peak"), PEAK_NEVER_LOSER_MIN_PEAK)
    peak_above_ladder = peak >= ladder[0][0]
    peak_in_pnl_zone = peak >= pnl_min_peak and pnl_min_peak < ladder[0][0]
    if lock_floor is not None and (peak_above_ladder or peak_in_pnl_zone) and unreal_pct <= lock_floor:
        entry = float(pos.get("entry") or 0)
        logger.info(
            f"[EXIT TRIGGER] PROFIT_LOCK_LADDER trade_id={pos.get('trade_id')} peak={peak:.1f}% "
            f"lock={lock_floor:.1f}% now={unreal_pct:.1f}% entry={fmt(entry)} exit={fmt(price)} "
            f"source={state.get('price_source', 'WS')} [PIPELINE ENFORCEMENT]"
        )
        pos["_ladder_lock_floor_pct"] = lock_floor
        _emit_genome_execution_event("LADDER_STEP_HIT", {
            "trade_id": pos.get("trade_id"),
            "peak_pct": round(float(peak), 4),
            "lock_floor_pct": round(float(lock_floor), 4),
            "unreal_pct": round(float(unreal_pct), 4),
            "research_lane": pos.get("research_lane"),
        })
        close_position(pos, "PROFIT_LOCK_LADDER")
        return True
    pos["_prev_unreal_pct"] = unreal_pct

    if check_thesis_invalidation(pos, price):
        return True

    # Paper natural cycle: if ladder and thesis have not fired, never close.
    # Hard STOP_LOSS on a 13bps last-trade tick previously skipped this cycle.
    # POST_FILL_GRACE_SEC is intentionally not used as a hold here.
    if _paper_natural_cycle_exits():
        return False

    if state.get("early_fail_enabled", True) and not _in_post_fill_grace(pos, now) and unreal_pct <= EARLY_FAIL_PCT_THRESHOLD:
        logger.info(f"[EXIT TRIGGER] EARLY_FAIL trade_id={pos.get('trade_id')} pnl={fmt(unreal_pct)} [PIPELINE ENFORCEMENT]")
        close_position(pos, "EARLY_FAIL")
        return True

    if (pos.get("dir") == "LONG" and price <= pos.get("sl", 0)) or (pos.get("dir") == "SHORT" and price >= pos.get("sl", 0)):
        logger.info(f"[EXIT TRIGGER] STOP_LOSS trade_id={pos.get('trade_id')} [PIPELINE ENFORCEMENT]")
        close_position(pos, "STOP_LOSS")
        return True

    if check_type_a_first_candle_exit(pos, unreal_pct, now):
        return True

    if check_type_a_early_fail_exit(pos, unreal_pct, now):
        return True

    if check_type_a_stall_exit(pos, unreal_pct, now):
        return True

    if check_trend_weakening_exit(pos, unreal_pct, now):
        return True

    tp_price = pos.get("tp", 0)
    if tp_price > 0:
        if (pos.get("dir") == "LONG" and price >= tp_price) or (pos.get("dir") == "SHORT" and price <= tp_price):
            logger.info(f"[EXIT TRIGGER] TAKE_PROFIT_EMERGENCY trade_id={pos.get('trade_id')} [PIPELINE ENFORCEMENT]")
            close_position(pos, "TAKE_PROFIT")
            return True

    if FIXED_TIME_EXIT_ENABLED:
        time_in_trade = now - pos.get("entry_ts", 0)
        if time_in_trade > MAX_POSITION_AGE_SEC:
            logger.info(f"[EXIT TRIGGER] TIME_EXIT trade_id={pos.get('trade_id')} duration={(time_in_trade/60):.1f}min [PIPELINE ENFORCEMENT]")
            close_position(pos, "TIME_EXIT")
            return True
    else:
        time_in_trade = now - pos.get("entry_ts", 0)
        if time_in_trade > EMERGENCY_MAX_HOLD_SEC:
            logger.warning(
                f"[EXIT TRIGGER] EMERGENCY_MAX_HOLD trade_id={pos.get('trade_id')} "
                f"duration={(time_in_trade/3600):.1f}h [PIPELINE ENFORCEMENT]"
            )
            close_position(pos, "EMERGENCY_MAX_HOLD")
            return True
    return False

CIRCUIT_BREAKER_REASONS = frozenset({
    "STALE_DATA_HARD_STOP", "THREAD_CRASH", "WS_STALE", "PRICE_STALE_OR_MISSING",
    "ENGINE_FAILURE", "CSV_FAILURE", "PRELOAD_FAILED",
})
# Brief WS blips should not wipe pending limits. Hard infra failures and the
# operator's explicit manual pause cancel every unfilled executable order.
CIRCUIT_BREAKER_CANCEL_REASONS = frozenset({
    "STALE_DATA_HARD_STOP", "ENGINE_FAILURE", "CSV_FAILURE", "PRELOAD_FAILED",
    "ADMIN_MANUAL",
})


def circuit_breaker_cancel_pending(reason: str):
    """Cancel pending orders on WS stale / API errors — optional flatten log for research."""
    if reason not in CIRCUIT_BREAKER_CANCEL_REASONS:
        return 0
    cancelled = 0
    failed = 0
    expire_reason = f"CIRCUIT_BREAKER_{reason}"
    with trade_lock:
        candidates = [
            o for o in list(pending_orders)
            if isinstance(o, dict)
            and str(o.get("status") or "").upper()
            in ("PENDING", "CANCEL_PENDING_LIVE")
        ]
    for o in candidates:
        outcome = _cancel_pending_order_confirmed(
            o,
            expire_reason,
            record_expired=True,
            expire_signal=True,
        )
        if outcome.get("finalized"):
            cancelled += 1
        else:
            failed += 1
    if cancelled or failed:
        logger.warning(
            f"[CIRCUIT_BREAKER] confirmed_cancelled={cancelled} "
            f"retained_unconfirmed={failed} reason={reason} "
            f"[PIPELINE ENFORCEMENT]"
        )
    return cancelled


def live_copy_coordination_state() -> str:
    """Railway↔Fly coordinated operating state for live-copy lanes."""
    with state_lock:
        raw = str(state.get("live_copy_coordination_state") or COORD_STATE_RUNNING_TOGETHER).upper()
    if raw in {
        COORD_STATE_RUNNING_TOGETHER,
        COORD_STATE_RELAY_EXIT_ONLY,
        COORD_STATE_SOURCE_RESEARCH_ONLY,
        COORD_STATE_FULLY_PAUSED,
    }:
        return raw
    return COORD_STATE_RUNNING_TOGETHER


def set_live_copy_coordination_state(next_state: str, reason: str = "") -> dict:
    """Apply coordinated state. RELAY_EXIT_ONLY blocks NEW executable CONTINUOUS entries."""
    wanted = str(next_state or "").strip().upper()
    if wanted not in {
        COORD_STATE_RUNNING_TOGETHER,
        COORD_STATE_RELAY_EXIT_ONLY,
        COORD_STATE_SOURCE_RESEARCH_ONLY,
        COORD_STATE_FULLY_PAUSED,
    }:
        raise ValueError(f"unsupported coordination state: {next_state}")
    reason_text = str(reason or "").strip() or (
        LIVE_RELAY_COORDINATION_REASON if wanted != COORD_STATE_RUNNING_TOGETHER else ""
    )
    with state_lock:
        prev = str(state.get("live_copy_coordination_state") or COORD_STATE_RUNNING_TOGETHER)
        state["live_copy_coordination_state"] = wanted
        state["live_copy_coordination_reason"] = reason_text
        state["live_copy_coordination_updated_at"] = utc_iso()
        if wanted == COORD_STATE_FULLY_PAUSED:
            state["manual_admin_pause"] = True
        elif wanted == COORD_STATE_RUNNING_TOGETHER:
            if state.get("execution_reason") == LIVE_RELAY_COORDINATION_REASON:
                state["execution_paused"] = False
                state["execution_reason"] = ""
                state["_pause_priority"] = 0
    if wanted == COORD_STATE_FULLY_PAUSED:
        set_execution_paused(LIVE_RELAY_COORDINATION_REASON)
    cancelled_executable = 0
    if prev == COORD_STATE_RUNNING_TOGETHER and wanted != COORD_STATE_RUNNING_TOGETHER:
        cancelled_executable = _expire_executable_live_copy_pendings(reason_text)
    logger.warning(
        f"[LIVE-COPY-COORD] {prev} -> {wanted} reason={reason_text or '-'} "
        f"cancelled_executable={cancelled_executable} "
        "[PIPELINE ENFORCEMENT]"
    )
    return {
        "ok": True,
        "previous": prev,
        "state": wanted,
        "reason": reason_text,
        "cancelled_executable": cancelled_executable,
        "ui_reason": LIVE_RELAY_COORDINATION_REASON if wanted != COORD_STATE_RUNNING_TOGETHER else "",
    }


def _expire_executable_live_copy_pendings(reason: str) -> int:
    """Drop already-resting CONTINUOUS copy intents when live relay pauses.

    Labelled coordination_shadow / non-CONTINUOUS research stays visible.
    Open Showcase positions are not flattened here (exit-only remains).
    """
    expire_reason = reason or LIVE_RELAY_COORDINATION_REASON
    with trade_lock:
        candidates = [
            order for order in list(pending_orders)
            if isinstance(order, dict)
            and str(order.get("status") or "").upper() in ("PENDING", "CANCEL_PENDING_LIVE")
            and order.get("coordination_shadow") is not True
            and str(order.get("research_lane") or RESEARCH_LANE_CONTINUOUS).upper()
            in ("", "CONTINUOUS")
        ]
    cancelled = 0
    for order in candidates:
        outcome = _cancel_pending_order_confirmed(
            order,
            expire_reason,
            record_expired=True,
            expire_signal=True,
        )
        if outcome.get("finalized"):
            cancelled += 1
    return cancelled


def executable_live_copy_entries_blocked() -> tuple:
    """True when Showcase must not emit NEW executable CONTINUOUS copy intents."""
    coord = live_copy_coordination_state()
    if coord in {COORD_STATE_RELAY_EXIT_ONLY, COORD_STATE_FULLY_PAUSED, COORD_STATE_SOURCE_RESEARCH_ONLY}:
        with state_lock:
            reason = str(state.get("live_copy_coordination_reason") or LIVE_RELAY_COORDINATION_REASON)
        return True, reason, coord
    return False, "", coord


def set_execution_paused(reason: str):
    global last_console_update
    cancel_reason = None
    with state_lock:
        if reason == "":
            # [DEMO_PAUSE_2026-07-08] Keep SIMULATION_ONLY sticky while
            # EXECUTION_PAUSED=True (demo_mode.py). Soft recovery paths must
            # not clear the demo/sim pause gate.
            if (
                str(os.environ.get("EXECUTION_PAUSED", "")).strip().lower() == "true"
                and state.get("execution_reason") == "SIMULATION_ONLY"
            ):
                logger.info(
                    "[RECOVERY] ignored clear — EXECUTION_PAUSED=True keeps SIMULATION_ONLY "
                    "[PIPELINE ENFORCEMENT]"
                )
                return
            state["execution_paused"] = False
            state["execution_reason"] = ""
            state["_pause_priority"] = 0
            state["ws_stale_count"] = 0
            logger.info("[RECOVERY] Soft recovery - state preserved [PIPELINE ENFORCEMENT]")
            return
        priority = PAUSE_PRIORITIES.get(reason, 0)
        current = state.get("_pause_priority", 0)
        if priority >= current:
            state["execution_paused"] = True
            state["execution_reason"] = reason
            state["_pause_priority"] = priority
            logger.warning(f"[EXECUTION] paused: {reason} [PIPELINE ENFORCEMENT]")
            cancel_reason = reason
    # Persistence/cancellation may wait on filesystem or trade state. Never
    # hold the global state lock across either operation: health, canonical
    # relay snapshots, and the admin response must remain independently
    # responsive while a control action is being finalized.
    if cancel_reason:
        circuit_breaker_cancel_pending(cancel_reason)


_WS_RECOVERABLE_PAUSE_REASONS = frozenset({
    "WS_STALE",
    "STALE_DATA_HARD_STOP",
    "PRICE_STALE_OR_MISSING",
})


def _clear_execution_pause_if_reason(expected_reason: str) -> bool:
    """Clear only the exact WS-derived pause observed by the caller."""
    expected = str(expected_reason or "")
    if expected not in _WS_RECOVERABLE_PAUSE_REASONS:
        return False
    with state_lock:
        if state.get("manual_admin_pause"):
            return False
        if str(state.get("execution_reason") or "") != expected:
            return False
        state["execution_paused"] = False
        state["execution_reason"] = ""
        state["_pause_priority"] = 0
        state["ws_stale_count"] = 0
    logger.info(
        f"[RECOVERY] cleared exact WS-derived pause {expected} "
        "[PIPELINE ENFORCEMENT]"
    )
    return True


def manual_admin_pause_active() -> bool:
    """Return True while the operator has explicitly stopped new execution."""
    return bool(state.get("manual_admin_pause")) or bool(
        state.get("execution_paused")
        and state.get("execution_reason") == "ADMIN_MANUAL"
    )


def _manual_pause_block_entry(source: dict = None, stage: str = "ENTRY") -> bool:
    """Fail closed before any new paper/live order or position mutation."""
    if not manual_admin_pause_active():
        return False
    payload = source if isinstance(source, dict) else {}
    payload["status"] = "BLOCKED"
    payload["outcome"] = "ADMIN_MANUAL_PAUSE"
    payload["exit_reason"] = "ADMIN_MANUAL_PAUSE"
    logger.warning(
        f"[ADMIN PAUSE] blocked new entry stage={stage} "
        f"trade_id={payload.get('trade_id')} lane={payload.get('research_lane')} "
        f"[PIPELINE ENFORCEMENT]"
    )
    return True


def get_execution_status() -> str:
    system_health_check()
    with state_lock:
        system_ready = is_system_ready()
        paused = state.get("execution_paused", False)
        live_armed = state.get("live_armed", False)
        mode = state.get("strategy_mode", "RESEARCH")
        if mode == "RESEARCH":
            return "RESEARCH_ALLOW" if (system_ready and not paused) else "BLOCKED"
        return "ACTIVE" if (system_ready and not paused and live_armed) else "BLOCKED"

def get_display_balance():
    with state_lock:
        # RESEARCH balance showcase [PIPELINE ENFORCEMENT]
        if state.get("strategy_mode") == "RESEARCH":
            return round(float(state.get("account_balance", STARTING_BALANCE)), 4)
        if not state.get("live_armed", False):
            return STARTING_BALANCE
        return state.get("account_balance", STARTING_BALANCE)

def _pending_trade_ids():
    with trade_lock:
        pending = {
            o.get("trade_id")
            for o in pending_orders
            if o.get("trade_id")
            and str(o.get("status") or "").upper()
            in ("PENDING", "CANCEL_PENDING_LIVE")
        }
        # A natural fill has a short but important handoff: the pending order
        # is removed before the OPEN lifecycle is committed.  Cleanup must not
        # mistake that atomic transition for a stale signal with no exposure.
        return pending | set(fill_handoff_trade_ids)

def is_terminal_signal(sig: dict) -> bool:
    if not isinstance(sig, dict):
        return False
    st = sig.get("status")
    outcome = sig.get("outcome") or sig.get("exit_reason")
    return st in TERMINAL_SIGNAL_STATUSES or outcome in TERMINAL_SIGNAL_OUTCOMES

def _open_trade_ids():
    with trade_lock:
        return {p.get("trade_id") for p in open_positions if p.get("trade_id")}

def expire_signal_for_order(order: dict, reason: str = "TTL_EXPIRED"):
    tid = order.get("trade_id")
    if not tid:
        return False
    with trade_lock:
        master = trades_map.get(tid, {}).get("signal_ref")
        if not master:
            _agent_dbg("H1", "expire_signal_for_order", "no_signal_ref", {"trade_id": tid, "reason": reason})
            return False
        prev_status = master.get("status")
        master["status"] = "EXPIRED"
        master["outcome"] = reason
        master["exit_reason"] = reason
    with state_lock:
        if state.get("pending_trade_id") == tid:
            state["pending_trade_id"] = None
    _agent_dbg("H1", "expire_signal_for_order", "signal_expired", {"trade_id": tid, "prev_status": prev_status, "reason": reason})
    pipeline_state_sync()
    return True

def sync_cooldown_debug_state():
    now = time.time()
    ai_rem = max(0, get_effective_ai_cooldown_sec() - (now - state.get("last_ai_call_ts", 0)))
    sig_rem = max(0, GLOBAL_SIGNAL_COOLDOWN - (now - state.get("last_signal_create_ts", 0)))
    with state_lock:
        state["debug_state"]["ai_cooldown_active"] = ai_rem > 0
        state["debug_state"]["cooldown_remaining_ai"] = int(ai_rem)
        state["debug_state"]["signal_cooldown_active"] = sig_rem > 0
        state["debug_state"]["cooldown_remaining_signal"] = int(sig_rem)
        ag = state["debug_state"].get("ai_gate") or {}
        ai_was_called = bool(ag.get("called"))
        if ai_rem <= 0 and sig_rem <= 0:
            sr = state["debug_state"].get("skip_reason")
            if sr in ("AI_COOLDOWN_ACTIVE", "GLOBAL_COOLDOWN", None):
                state["debug_state"]["skip_reason"] = None
            elif sr and not ai_was_called and _is_misleading_ai_skip_label(sr):
                state["debug_state"]["skip_reason"] = None
                state["debug_state"]["last_block_reason"] = None
            elif sr and str(sr).startswith("AI_") and state.get("last_pipeline_stage") == "IDLE":
                state["debug_state"]["skip_reason"] = None
                state["debug_state"]["last_block_reason"] = None
            if not ai_was_called and state.get("last_pipeline_stage") == "IDLE":
                if state.get("final_decision") == "AI_REJECTED":
                    state["final_decision"] = None
                if state.get("ai_decision") == "REJECTED":
                    state["ai_decision"] = None
    _agent_dbg("H4", "sync_cooldown_debug_state", "synced", {"ai_rem": int(ai_rem), "sig_rem": int(sig_rem), "skip_reason": state.get("debug_state", {}).get("skip_reason")})

def purge_dead_pending_orders():
    removed = 0
    with trade_lock:
        dead = [
            o for o in pending_orders
            if (
                not isinstance(o, dict)
                or (
                    str(o.get("status") or "").upper()
                    not in ("PENDING", "CANCEL_PENDING_LIVE")
                    and not o.get("bitfinex_order_id")
                )
            )
        ]
        for o in dead:
            if o in pending_orders:
                lane_unregister_pending_order(o)
                removed += 1
    if removed:
        logger.info(f"[EXECUTION FIX {EXECUTION_FIX_VERSION}] purged {removed} dead pending_orders (non-PENDING)")
        _agent_dbg("H3", "purge_dead_pending_orders", "purged", {"removed": removed, "remaining": len(pending_orders)})
    return removed

def execution_allowed(lane: str = None) -> bool:
    # Preserve the operator's kill switch as the authoritative reason. The
    # older flow called get_execution_status() and replaced ADMIN_MANUAL with
    # the generic string BLOCKED, which made health and dashboard snapshots
    # disagree even though the entry gate itself remained closed.
    if manual_admin_pause_active():
        with state_lock:
            state["manual_admin_pause"] = True
            state["execution_paused"] = True
            state["execution_reason"] = "ADMIN_MANUAL"
            state["_pause_priority"] = PAUSE_PRIORITIES["ADMIN_MANUAL"]
        logger.warning("[EXECUTION BLOCK] operator manual pause [PIPELINE ENFORCEMENT]")
        return False
    if lane and is_ai_scan_lane(lane):
        with state_lock:
            state["execution_reason"] = "AI_SCAN_NO_ORDERS"
        return False
    if lane and not lane_orders_allowed(lane):
        with state_lock:
            state["execution_reason"] = "LANE_DISABLED"
        logger.warning(
            f"[EXECUTION BLOCK] lane={lane} toggle OFF — no limit orders "
            f"[PIPELINE ENFORCEMENT]"
        )
        return False
    if not risk_trading_allowed():
        with state_lock:
            state["execution_reason"] = state.get("execution_reason") or "RISK_PAUSE"
        logger.warning(f"[EXECUTION BLOCK] risk pause reason={state.get('execution_reason')} [PIPELINE ENFORCEMENT]")
        return False
    lane_key = str(lane).upper() if lane and research_isolation_enabled() else None
    active = get_active_signal_count()
    max_pos = get_effective_max_active_signals()
    if active >= max_pos:
        state["execution_reason"] = "MAX_ACTIVE_SIGNALS"
        logger.warning(
            f"[LIMIT] Max active signals reached (global pool): {active}/{max_pos} "
            f"lane={lane_key or 'ALL'} [PIPELINE ENFORCEMENT]"
        )
        return False
    status = get_execution_status()
    if status not in ["ACTIVE", "RESEARCH_ALLOW"]:
        state["execution_reason"] = status
        logger.warning(f"[EXECUTION BLOCK] status={status} [PIPELINE ENFORCEMENT]")
        return False
    state["execution_reason"] = "ALLOWED"
    return True

def clear_pending_trade():
    with state_lock:
        state["pending_trade_id"] = None

def safe_clear_pending():
    with state_lock:
        if state.get("pending_trade_id"):
            logger.warning("[FORCE CLEAR] pending_trade_id stuck - cleared [PIPELINE ENFORCEMENT]")
            state["pending_trade_id"] = None

def map_signal_to_exchange_side(final_direction: str) -> str:
    if final_direction == "LONG":
        return "buy"
    elif final_direction == "SHORT":
        return "sell"
    else:
        raise ValueError(f"Invalid final_direction: {final_direction}")

def _normalize_order_side_to_dir(side) -> str:
    if not side:
        return "UNKNOWN"
    s = str(side).strip()
    su = s.upper()
    if su in ("LONG", "BUY"):
        return "LONG"
    if su in ("SHORT", "SELL"):
        return "SHORT"
    sl = s.lower()
    if sl == "buy":
        return "LONG"
    if sl == "sell":
        return "SHORT"
    return su if su in ("LONG", "SHORT") else "UNKNOWN"

melbourne_tz = pytz.timezone("Australia/Melbourne")

def _timestamp_to_melbourne_display(ts: float) -> str:
    """Unix epoch (UTC) → Melbourne display string (24h, AEST/AEDT)."""
    if not ts:
        return "-"
    try:
        dt = datetime.fromtimestamp(float(ts), tz=timezone.utc)
        return _format_melbourne_hm(dt.isoformat())
    except Exception:
        return "-"


def _enrich_melbourne_time_fields(row: dict) -> dict:
    """Add ts_melbourne / close_ts_melbourne for dashboard + Agent Hub matching."""
    if not isinstance(row, dict):
        return row
    out = dict(row)
    raw = out.get("close_ts") or out.get("ts") or out.get("time")
    if raw is not None and raw != "" and raw != "-":
        if isinstance(raw, (int, float)):
            mel = _timestamp_to_melbourne_display(float(raw))
        else:
            mel = _format_melbourne_hm(str(raw))
        if mel and mel != "-":
            out["ts_melbourne"] = mel
            out["close_ts_melbourne"] = mel
            if not out.get("time_melbourne"):
                out["time_melbourne"] = mel
    return out


def _experimental_entry_filter_detail(lane_id: str, spec: dict) -> list:
    """Pre-entry gates shown on experimental Pathway Lab tiles."""
    ef = spec.get("entry_filters")
    if ef == "benchmark_all_approve":
        return ["Entry filters: every AI_SCAN APPROVE (no extra pre-entry gates)"]
    if ef == "ai_approve_replay_reject":
        return ["Entry filters: AI APPROVE + replay model would REJECT"]
    if ef == "ai_reject_replay_approve":
        return ["Entry filters: AI REJECT (or soft reject) + replay model APPROVE"]
    if isinstance(ef, dict):
        parts = [
            "Entry filters (ALL must pass on AI_SCAN APPROVE):",
            f"  · AI win_prob ≥ {ef.get('ai_min', '?')}%",
            f"  · Directional spread ≥ {ef.get('spread_min', '?')}",
            f"  · ADX ≥ {ef.get('adx_min', '?')}",
            f"  · Volume ratio ≥ {ef.get('volume_ratio_min', '?')}",
            f"  · Structure score ≤ {ef.get('structure_max', '?')} (bearish structure)",
        ]
        if lane_id == RESEARCH_LANE_TYPE_B_PREDICTOR_V1:
            parts.append(
                "  · Rare combo — most APPROVEs fail ADX/vol/structure even when AI/spread pass"
            )
        return parts
    return []


