def get_edge_threshold():
    with state_lock:
        return round(float(state["edge_threshold"]), 1)

def get_edge_threshold_max():
    """Optional upper cap; None = no max (min-only gate)."""
    with state_lock:
        raw = state.get("edge_threshold_max")
    if raw is None or raw == "":
        return None
    try:
        return round(float(raw), 1)
    except (TypeError, ValueError):
        return None

def _edge_range_label() -> str:
    lo = get_edge_threshold()
    hi = get_edge_threshold_max()
    if hi is None:
        return f">={lo:.1f}"
    return f"{lo:.1f}–{hi:.1f}"

def edge_range_allows(edge_score: float) -> tuple:
    """Compatibility field for research rows; Edge never gates runtime work."""
    float(edge_score)
    return True, "EDGE_IN_RANGE"

def get_dynamic_flat_momentum_floor(base: float = None) -> float:
    """
    Flat-momentum extra bar scales with dashboard edge:
    edge 2.0 → no flat penalty (experiment mode); edge 4.0+ → full FLAT_MOMENTUM_EDGE_FLOOR.
    """
    base = round(float(base if base is not None else get_edge_threshold()), 1)
    if base <= FLAT_MOMENTUM_FLOOR_LOW_EDGE:
        return base
    if base >= FLAT_MOMENTUM_FLOOR_HIGH_EDGE:
        return round(FLAT_MOMENTUM_EDGE_FLOOR, 1)
    span = FLAT_MOMENTUM_FLOOR_HIGH_EDGE - FLAT_MOMENTUM_FLOOR_LOW_EDGE
    t = (base - FLAT_MOMENTUM_FLOOR_LOW_EDGE) / span
    return round(FLAT_MOMENTUM_FLOOR_LOW_EDGE + t * (FLAT_MOMENTUM_EDGE_FLOOR - FLAT_MOMENTUM_FLOOR_LOW_EDGE), 1)

_relay_push_state = {
    "seq": 0,
    "last_ts": 0.0,
    "last_event": None,
    "last_ok": None,
    "last_error": None,
    "last_latency_ms": None,
    "last_platform_received_at": None,
}
_relay_push_history = deque(maxlen=20)
_relay_push_history_lock = threading.Lock()
_partial_reduction_drain_lock = threading.Lock()
_relay_http_session = requests.Session()
_relay_http_adapter = requests.adapters.HTTPAdapter(
    pool_connections=4,
    pool_maxsize=8,
    max_retries=0,
    pool_block=False,
)
_relay_http_session.mount("https://", _relay_http_adapter)
_relay_http_session.mount("http://", _relay_http_adapter)


def _platform_relay_keepalive_url() -> str:
    """Return a health-only URL on the exact relay origin."""
    raw = (os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip()
    try:
        parsed = urlsplit(raw)
    except Exception:
        return ""
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return ""
    return f"{parsed.scheme}://{parsed.netloc}/api/health"


def _platform_relay_connection_keepalive_loop():
    """Keep Fly -> platform DNS/TLS/HTTP transport warm without mutations."""
    url = _platform_relay_keepalive_url()
    if not url:
        return
    while not shutdown_event.is_set():
        _drain_partial_reduction_outbox_once()
        try:
            response = _relay_http_session.get(
                url,
                headers={"Accept": "application/json"},
                timeout=1.5,
            )
            response.close()
        except Exception:
            # Relay POST durability and retries remain authoritative. Warm-up
            # failure is intentionally silent and never changes bot state.
            pass
        if shutdown_event.wait(3.0):
            return


def _relay_delivery_lag_ms(source_ts, platform_received_at):
    try:
        source_dt = datetime.fromisoformat(str(source_ts).replace("Z", "+00:00"))
        platform_dt = datetime.fromisoformat(
            str(platform_received_at).replace("Z", "+00:00")
        )
        return round((platform_dt - source_dt).total_seconds() * 1000, 1)
    except (TypeError, ValueError):
        return None


def _record_relay_delivery(
    event,
    trade_id,
    source_ts,
    *,
    ok,
    http_latency_ms,
    platform_received_at=None,
    error=None,
):
    row = {
        "event": str(event),
        "trade_id": str(trade_id) if trade_id else None,
        "source_event_at": source_ts,
        "platform_received_at": platform_received_at,
        "source_to_platform_ms": _relay_delivery_lag_ms(
            source_ts, platform_received_at
        ),
        "http_round_trip_ms": round(float(http_latency_ms), 1),
        "delivery_completed_at": utc_iso(),
        "ok": bool(ok),
        "error": str(error)[:240] if error else None,
    }
    with _relay_push_history_lock:
        _relay_push_history.append(row)


def _relay_response_has_durable_receipt(response_payload, expected_payload=None) -> bool:
    """True only after Railway confirms durable lifecycle persistence."""
    base_ok = bool(
        isinstance(response_payload, dict)
        and response_payload.get("persisted") is True
        and response_payload.get("intentCreated") is True
        and response_payload.get("canonical_revision_applied") is True
        and response_payload.get("platform_received_at")
    )
    if not base_ok or not expected_payload:
        return base_ok
    try:
        return bool(
            response_payload.get("canonical_event_id") == expected_payload.get("event_id")
            and int(response_payload.get("canonical_event_seq"))
            == int(expected_payload.get("event_seq"))
            and response_payload.get("canonical_trade_id") == expected_payload.get("trade_id")
            and abs(
                float(response_payload.get("canonical_limit_price"))
                - float(expected_payload.get("limit_price"))
            )
            < 0.005
        )
    except (TypeError, ValueError):
        return False


def _relay_delivery_history_snapshot(limit=10):
    with _relay_push_history_lock:
        return list(_relay_push_history)[-max(1, int(limit)):]

