def _estimate_token_count(text) -> int:
    if not text:
        return 0
    return max(1, len(str(text)) // 4)


# Batched token usage reporter — accumulates entries and flushes periodically
# with retries, avoiding per-call HTTP overhead and silent drop on transient
# failures. Flushes happen on batch-size threshold OR time interval (60s).
_inference_usage_buffer = []
_inference_usage_lock = threading.Lock()
_inference_usage_last_flush = time.time()
_INFERENCE_USAGE_BATCH_MAX = 20
_INFERENCE_USAGE_FLUSH_INTERVAL_SEC = 60
_INFERENCE_USAGE_RETRY_MAX = 3
_INFERENCE_USAGE_RETRY_BASE_DELAY = 1.0
_inference_usage_flusher_started = False


def _ensure_usage_flusher():
    """Start a periodic flush thread if not already running."""
    global _inference_usage_flusher_started
    if _inference_usage_flusher_started:
        return
    _inference_usage_flusher_started = True
    def _flusher_loop():
        while True:
            time.sleep(_INFERENCE_USAGE_FLUSH_INTERVAL_SEC)
            _flush_inference_usage()
    threading.Thread(target=_flusher_loop, daemon=True).start()


def _flush_inference_usage():
    """POST accumulated entries to the platform API with retries."""
    global _inference_usage_buffer, _inference_usage_last_flush
    with _inference_usage_lock:
        if not _inference_usage_buffer:
            return
        entries = list(_inference_usage_buffer)
        _inference_usage_buffer.clear()
        _inference_usage_last_flush = time.time()

    url = SHOWCASE_INFERENCE_USAGE_URL
    if not url:
        return
    secret = (os.getenv("BOT_CONTROL_SECRET") or "").strip()
    payload = {"entries": entries}
    headers = {"Content-Type": "application/json", "Accept": "application/json"}
    if secret:
        headers["X-Bot-Control-Secret"] = secret

    for attempt in range(1, _INFERENCE_USAGE_RETRY_MAX + 1):
        try:
            res = requests.post(url, json=payload, headers=headers, timeout=5.0)
            if res.status_code < 500:
                return
            delay = _INFERENCE_USAGE_RETRY_BASE_DELAY * (2 ** attempt)
            logger.warning(
                f"[INFERENCE USAGE] flush attempt {attempt}/{_INFERENCE_USAGE_RETRY_MAX} "
                f"got {res.status_code}, retrying in {delay:.1f}s"
            )
        except Exception as exc:
            delay = _INFERENCE_USAGE_RETRY_BASE_DELAY * (2 ** attempt)
            logger.warning(
                f"[INFERENCE USAGE] flush attempt {attempt}/{_INFERENCE_USAGE_RETRY_MAX} "
                f"failed: {exc}, retrying in {delay:.1f}s"
            )
        if attempt < _INFERENCE_USAGE_RETRY_MAX:
            time.sleep(delay)

    # All retries exhausted — drop silently (avoid jam on dead API), already warned above.
    logger.warning(
        f"[INFERENCE USAGE] all {_INFERENCE_USAGE_RETRY_MAX} flush attempts failed, "
        f"dropped {len(entries)} entries"
    )


def _report_showcase_inference_usage(
    prompt_tokens: int,
    completion_tokens: int,
    *,
    source: str = "showcase_bot",
    model: str = None,
) -> None:
    """Enqueue DeepSeek token counts for batched push to the platform adoption chart."""
    url = SHOWCASE_INFERENCE_USAGE_URL
    if not url or (prompt_tokens <= 0 and completion_tokens <= 0):
        return
    entry = {
        "promptTokens": int(prompt_tokens),
        "completionTokens": int(completion_tokens),
        "provider": "deepseek",
        "model": model or _deepseek_model(),
        "source": source,
        "billingSource": "platform_showcase",
    }
    _ensure_usage_flusher()
    with _inference_usage_lock:
        _inference_usage_buffer.append(entry)

    # Flush immediately if batch is full, otherwise rely on periodic flush timer.
    if len(_inference_usage_buffer) >= _INFERENCE_USAGE_BATCH_MAX:
        threading.Thread(target=_flush_inference_usage, daemon=True).start()


def _platform_relay_lane_for_event(
    trade_id: str = None,
    research_lane: str = None,
) -> str:
    """Resolve a relay lane from an allow-listed trade prefix, failing closed.

    An explicit lane may confirm the prefix-derived lane but cannot override it.
    This prevents a paper/research trade from becoming mirrorable by carrying a
    stale or incorrectly defaulted ``research_lane=CONTINUOUS`` field.
    """
    trade_key = str(trade_id or "").strip().lower()
    prefix, separator, _ = trade_key.partition("-")
    if not separator:
        return ""
    derived_lane = PLATFORM_RELAY_TRADE_PREFIX_LANES.get(prefix, "")
    explicit_lane = str(research_lane or "").strip().upper()
    if not derived_lane:
        return ""
    if explicit_lane and explicit_lane != derived_lane:
        return ""
    return derived_lane


def _platform_relay_evidence_lane_for_event(
    trade_id: str = None,
    research_lane: str = None,
) -> str:
    """Resolve signed evidence identity without granting live-copy authority."""
    trade_key = str(trade_id or "").strip().lower()
    prefix, separator, _ = trade_key.partition("-")
    if not separator:
        return ""
    derived_lane = PLATFORM_RELAY_EVIDENCE_PREFIX_LANES.get(prefix, "")
    explicit_lane = str(research_lane or "").strip().upper()
    if not derived_lane or (explicit_lane and explicit_lane != derived_lane):
        return ""
    return derived_lane


def _push_showcase_relay_event(
    event: str,
    trade_id: str = None,
    extra: dict = None,
    *,
    wait_for_durable_receipt: bool = False,
) -> bool:
    """Push a lifecycle event, optionally waiting for Railway durability.

    Ordinary chase updates remain fire-and-forget.  The terminal marketable
    reprice is different: the source must not declare a fill until Railway has
    durably persisted the signed exact-limit revision.  In that one path the
    caller sets ``wait_for_durable_receipt`` and this function returns ``True``
    only after a response containing both ``persisted=true`` and a platform
    receipt timestamp.
    """
    if not is_active_dashboard_owner():
        logger.warning(f"[RELAY PUSH] blocked non-owner process event={event} trade={trade_id}")
        return False
    url = (os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip()
    if not url:
        return False
    secret = (os.getenv("BOT_CONTROL_SECRET") or "").strip()
    webhook_secret = (os.getenv("SHOWCASE_WEBHOOK_SECRET") or "").strip()
    if wait_for_durable_receipt and not webhook_secret:
        logger.warning(
            f"[RELAY PUSH] durable receipt blocked without HMAC secret "
            f"event={event} trade={trade_id}"
        )
        return False
    payload = {
        "event": event,
        "trade_id": trade_id,
        "ts": utc_iso(),
        **_dashboard_owner_metadata(),
    }
    if extra and isinstance(extra, dict):
        payload.update(extra)
    if event in ("LIMIT_UPDATED", "POSITION_OPENED", "POSITION_CLOSED", "ORDER_EXPIRED", "POSITION_REDUCED"):
        evidence_only = event == "POSITION_REDUCED"
        relay_lane = (
            _platform_relay_evidence_lane_for_event
            if evidence_only else _platform_relay_lane_for_event
        )(
            trade_id,
            payload.get("research_lane"),
        )
        allowed_lanes = PLATFORM_RELAY_CONFIGURED_LANES if evidence_only else PLATFORM_RELAY_ELIGIBLE_LANES
        if relay_lane not in allowed_lanes:
            logger.warning(
                f"[RELAY PUSH] blocked non-relay lifecycle lane="
                f"{payload.get('research_lane') or 'UNKNOWN'} "
                f"event={event} trade={trade_id or 'MISSING'}"
            )
            return False
        payload["research_lane"] = relay_lane
    payload["event_id"] = str(
        payload.get("event_id")
        or (
            f"{trade_id or 'none'}:{event}:"
            f"{payload.get('event_seq', 'na')}:{payload['ts']}"
        )
    )
    # Exact chase updates are safe to consume without waiting for a platform callback
    # only when this canonical owner also HMAC-signs the payload.
    if (
        webhook_secret
        and event in ("LIMIT_UPDATED", "POSITION_OPENED", "POSITION_CLOSED", "ORDER_EXPIRED", "POSITION_REDUCED")
        and str(payload.get("direction") or "").upper() in ("LONG", "SHORT")
        and (
            (
                event == "LIMIT_UPDATED"
                and isinstance(payload.get("limit_price"), (int, float))
                and isinstance(payload.get("qty"), (int, float))
                and float(payload.get("qty") or 0) > 0
                and payload.get("entry_limit_policy") in EXECUTABLE_ENTRY_POLICY_VERSIONS
                and payload.get("executable") is True
            )
            or (
                event == "POSITION_OPENED"
                and isinstance(payload.get("fill_price"), (int, float))
            )
            or (
                event == "POSITION_CLOSED"
                and isinstance(payload.get("exit_price"), (int, float))
            )
            or (
                event == "ORDER_EXPIRED"
                and isinstance(payload.get("source_expires_at"), str)
            )
            or (
                event == "POSITION_REDUCED"
                and isinstance(payload.get("event_id"), str)
                and isinstance(payload.get("reduction_id"), str)
                and isinstance(payload.get("event_seq"), int)
                and int(payload.get("event_seq") or 0) > 0
                and isinstance(payload.get("prior_qty"), (int, float))
                and isinstance(payload.get("reduced_qty"), (int, float))
                and isinstance(payload.get("remaining_qty"), (int, float))
                and isinstance(payload.get("fill_price"), (int, float))
                and float(payload.get("prior_qty") or 0) > 0
                and float(payload.get("reduced_qty") or 0) > 0
                and float(payload.get("remaining_qty") or 0) > 0
                and float(payload.get("fill_price") or 0) > 0
                and abs(float(payload.get("prior_qty")) - float(payload.get("reduced_qty")) - float(payload.get("remaining_qty"))) <= 0.00000001
            )
        )
    ):
        payload["schema"] = "dcf-showcase-intent-v1"
    body = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")

    def _post() -> bool:
        started = time.perf_counter()
        # POSITION_CLOSED must not drop on a 2.5s Railway blip — exits are
        # latency-critical and the poll backstop is slower. Allow a longer
        # client timeout plus a couple of tight retries for that event only.
        durable_events = ("POSITION_CLOSED", "ORDER_EXPIRED", "POSITION_REDUCED")
        post_timeout = 8.0 if event in durable_events else 2.5
        attempts = 3 if event in durable_events else 1
        last_exc: Exception | None = None
        for attempt in range(attempts):
            try:
                headers = {"Content-Type": "application/json", "Accept": "application/json"}
                if secret:
                    headers["X-Bot-Control-Secret"] = secret
                if webhook_secret:
                    signature = hmac.new(
                        webhook_secret.encode("utf-8"),
                        body,
                        hashlib.sha256,
                    ).hexdigest()
                    headers["X-Showcase-Signature"] = f"sha256={signature}"
                response = _relay_http_session.post(
                    url, data=body, headers=headers, timeout=post_timeout
                )
                response.raise_for_status()
                response_payload = response.json() if response.content else {}
                if wait_for_durable_receipt and not _relay_response_has_durable_receipt(
                    response_payload, payload
                ):
                    raise RuntimeError("relay event was not durably acknowledged")
                _relay_push_state["seq"] += 1
                _relay_push_state["last_ts"] = time.time()
                _relay_push_state["last_event"] = event
                _relay_push_state["last_ok"] = True
                _relay_push_state["last_error"] = None
                _relay_push_state["last_latency_ms"] = round(
                    (time.perf_counter() - started) * 1000, 1
                )
                _relay_push_state["last_platform_received_at"] = (
                    response_payload.get("platform_received_at")
                    if isinstance(response_payload, dict)
                    else None
                )
                _record_relay_delivery(
                    event,
                    trade_id,
                    payload.get("ts"),
                    ok=True,
                    http_latency_ms=_relay_push_state["last_latency_ms"],
                    platform_received_at=_relay_push_state["last_platform_received_at"],
                )
                return True
            except Exception as exc:
                last_exc = exc
                if attempt + 1 < attempts:
                    time.sleep(0.35 * (attempt + 1))
                    continue
        _relay_push_state["last_ts"] = time.time()
        _relay_push_state["last_event"] = event
        _relay_push_state["last_ok"] = False
        _relay_push_state["last_error"] = str(last_exc)[:240] if last_exc else "unknown"
        _relay_push_state["last_latency_ms"] = round(
            (time.perf_counter() - started) * 1000, 1
        )
        _record_relay_delivery(
            event,
            trade_id,
            payload.get("ts"),
            ok=False,
            http_latency_ms=_relay_push_state["last_latency_ms"],
            error=last_exc,
        )
        logger.warning(f"[RELAY PUSH] {event} trade={trade_id} failed: {last_exc}")
        return False

    if wait_for_durable_receipt:
        return _post()
    threading.Thread(target=_post, daemon=True).start()
    return True


def _ack_partial_reduction_outbox(trade_id: str, event_id: str) -> bool:
    """Remove one durably acknowledged event while retaining its audit receipt."""
    removed = None
    with trade_lock:
        pos = next(
            (row for row in open_positions if row.get("trade_id") == trade_id),
            None,
        )
        if not pos:
            return False
        outbox = pos.get("partial_reduction_outbox") or []
        for index, receipt in enumerate(outbox):
            if isinstance(receipt, dict) and receipt.get("event_id") == event_id:
                removed = (index, copy.deepcopy(receipt))
                del outbox[index]
                pos["partial_reduction_outbox"] = outbox
                break
    if removed is None:
        return False
    if save_paper_lifecycle(reason=f"partial_reduction_ack:{event_id}"):
        return True
    with trade_lock:
        pos = next(
            (row for row in open_positions if row.get("trade_id") == trade_id),
            None,
        )
        if pos is not None:
            outbox = pos.setdefault("partial_reduction_outbox", [])
            if not any(
                isinstance(row, dict) and row.get("event_id") == event_id
                for row in outbox
            ):
                outbox.insert(min(removed[0], len(outbox)), removed[1])
    return False


def _drain_partial_reduction_outbox_once() -> dict:
    """Replay persisted reductions after restart and ACK only durable receipts."""
    if not _partial_reduction_drain_lock.acquire(blocking=False):
        return {"attempted": 0, "acked": 0, "busy": True}
    try:
        with trade_lock:
            pending = [
                (str(pos.get("trade_id") or ""), copy.deepcopy(receipt))
                for pos in open_positions
                for receipt in (pos.get("partial_reduction_outbox") or [])
                if isinstance(receipt, dict) and receipt.get("event_id")
            ]
        acked = 0
        for trade_id, receipt in pending:
            if _push_showcase_relay_event(
                "POSITION_REDUCED",
                trade_id,
                receipt,
                wait_for_durable_receipt=True,
            ) and _ack_partial_reduction_outbox(trade_id, receipt["event_id"]):
                acked += 1
        return {"attempted": len(pending), "acked": acked, "busy": False}
    finally:
        _partial_reduction_drain_lock.release()


def emit_signal_webhook(event: str, signal: dict = None, ai: dict = None):
    """Push a signed exact-limit lifecycle event to the platform relay.

    ``APPROVE_PENDING`` is visibility-only: it describes a structurally priced
    virtual-chase candidate and is never executable. ``ORDER_PLACED`` is the
    first executable entry event and must carry the exact canonical limit.
    Paper provenance is retained because the platform relay deliberately copies
    the canonical paper strategy only after its own NEXT_FRESH_ONLY arm gate.

    HMAC-SHA256 signs the canonical JSON with SHOWCASE_WEBHOOK_SECRET (distinct
    from BOT_CONTROL_SECRET). Fire-and-forget daemon thread — matches the
    existing _push_showcase_relay_event pattern. No-op when the secret or URL
    is unset (don't crash the bot on misconfig). The ~2s pollBotForIntents
    backstop remains; this webhook is a latency optimization, not the only path.
    """
    if not is_active_dashboard_owner():
        logger.warning(f"[INTENT WEBHOOK] blocked non-owner process event={event}")
        return
    url = (os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip()
    secret = (os.getenv("SHOWCASE_WEBHOOK_SECRET") or "").strip()
    if not url:
        return
    if not secret:
        _relay_push_state["last_ts"] = time.time()
        _relay_push_state["last_event"] = f"INTENT_{event}"
        _relay_push_state["last_ok"] = False
        _relay_push_state["last_error"] = "SHOWCASE_WEBHOOK_SECRET_MISSING"
        return

    sig = signal or {}
    ai_dict = ai or {}
    with state_lock:
        live_armed = bool(state.get("live_armed"))
        strategy_mode = str(state.get("strategy_mode") or "RESEARCH").upper()
        leverage = int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE))

    # N2 — paper/live provenance. Default showcase is RESEARCH + live_armed=False = paper.
    intent_source = "live" if live_armed else "paper"
    trade_id = sig.get("trade_id") or ai_dict.get("trade_id")
    if not trade_id:
        return

    direction = (sig.get("final_direction") or ai_dict.get("direction") or "").upper()
    signal_price = float(
        sig.get("signal_price")
        or ai_dict.get("signal_price")
        or state.get("price")
        or 0
    )
    raw_margin_usdt = sig.get("margin_usdt")
    margin_usdt = float(FIXED_MARGIN_USDT if raw_margin_usdt is None else raw_margin_usdt)
    try:
        exact_qty = float(sig.get("qty"))
    except (TypeError, ValueError):
        exact_qty = 0.0
    win_prob = ai_dict.get("win_prob") if isinstance(ai_dict.get("win_prob"), (int, float)) else None
    edge_score = sig.get("edge_score_at_entry")
    eff_thr = sig.get("effective_threshold_at_entry")
    research_lane = str(sig.get("research_lane") or "").upper()
    relay_lane = _platform_relay_lane_for_event(trade_id, research_lane)
    if (
        event in ("APPROVE_PENDING", "ORDER_PLACED")
        and relay_lane not in PLATFORM_RELAY_ELIGIBLE_LANES
    ):
        logger.warning(
            f"[INTENT WEBHOOK] blocked non-relay lane={research_lane} "
            f"event={event} trade={trade_id}"
        )
        return
    if relay_lane:
        research_lane = relay_lane
    limit_price = sig.get("limit_price") or sig.get("planned_limit_price")
    try:
        limit_price = float(limit_price) if limit_price is not None else None
    except (TypeError, ValueError):
        limit_price = None
    entry_limit_policy = str(sig.get("entry_limit_policy") or "")
    if event in ("APPROVE_PENDING", "ORDER_PLACED") and (
        direction not in ("LONG", "SHORT")
        or not limit_price
        or limit_price <= 0
        or (event == "ORDER_PLACED" and exact_qty <= 0)
        or not is_executable_entry_policy(entry_limit_policy)
    ):
        logger.warning(
            f"[INTENT WEBHOOK] blocked inexact lifecycle event={event} "
            f"trade={trade_id} direction={direction or 'MISSING'} "
            f"limit={limit_price} qty={exact_qty} policy={entry_limit_policy or 'MISSING'}"
        )
        return

    if event == "ORDER_PLACED":
        blocked, block_reason, coord = executable_live_copy_entries_blocked()
        if blocked and research_lane in ("", "CONTINUOUS"):
            logger.warning(
                f"[LIVE-COPY-COORD] suppressing executable ORDER_PLACED "
                f"trade={trade_id} state={coord} reason={block_reason} "
                "[PIPELINE ENFORCEMENT]"
            )
            # Downgrade to labelled non-executable research visibility only.
            event = "APPROVE_PENDING"
            sig = dict(sig)
            sig["executable"] = False
            sig["coordination_shadow"] = True
            sig["coordination_state"] = coord
            sig["coordination_reason"] = block_reason
            signal = sig

    try:
        event_seq = int(
            sig.get("limit_chase_count")
            if sig.get("limit_chase_count") is not None
            else (sig.get("dashboard_chase_activation_count") or 0)
        )
    except (TypeError, ValueError):
        event_seq = 0
    source_event_ts = utc_iso()
    payload = {
        "schema": "dcf-showcase-intent-v1",
        "event": event,
        "trade_id": trade_id,
        "ts": source_event_ts,
        "event_seq": max(0, event_seq),
        "event_id": f"{trade_id}:{event}:{max(0, event_seq)}:{source_event_ts}",
        "intent_source": intent_source,
        "direction": direction or None,
        "signal_price": signal_price if signal_price > 0 else None,
        "limit_price": limit_price if limit_price and limit_price > 0 else None,
        "qty": exact_qty if exact_qty > 0 else None,
        "margin_usdt": margin_usdt,
        "leverage": leverage,
        "win_prob": win_prob,
        "edge_score": edge_score if isinstance(edge_score, (int, float)) else None,
        "effective_threshold": eff_thr if isinstance(eff_thr, (int, float)) else None,
        "research_lane": research_lane,
        "entry_limit_policy": entry_limit_policy,
        "entry_reason": sig.get("entry_reason"),
        "executable": event == "ORDER_PLACED",
        "bot_version": EXECUTION_FIX_VERSION,
        "strategy_mode": strategy_mode,
        **_dashboard_owner_metadata(),
    }

    try:
        body = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
        signature = hmac.new(secret.encode("utf-8"), body, hashlib.sha256).hexdigest()
    except Exception as exc:
        logger.debug(f"[INTENT WEBHOOK] sign failed trade={trade_id}: {exc}")
        return

    def _post():
        started = time.perf_counter()
        try:
            headers = {
                "Content-Type": "application/json",
                "Accept": "application/json",
                "X-Showcase-Signature": f"sha256={signature}",
            }
            # Legacy bearer secret stays (G13) for backward compat during rollout.
            legacy_secret = (os.getenv("BOT_CONTROL_SECRET") or "").strip()
            if legacy_secret:
                headers["X-Bot-Control-Secret"] = legacy_secret
            response = _relay_http_session.post(
                url, data=body, headers=headers, timeout=2.5
            )
            response.raise_for_status()
            response_payload = response.json() if response.content else {}
            _relay_push_state["seq"] += 1
            _relay_push_state["last_ts"] = time.time()
            _relay_push_state["last_event"] = f"INTENT_{event}"
            _relay_push_state["last_ok"] = True
            _relay_push_state["last_error"] = None
            _relay_push_state["last_latency_ms"] = round(
                (time.perf_counter() - started) * 1000, 1
            )
            _relay_push_state["last_platform_received_at"] = (
                response_payload.get("platform_received_at")
                if isinstance(response_payload, dict)
                else None
            )
            _record_relay_delivery(
                f"INTENT_{event}",
                trade_id,
                payload.get("ts"),
                ok=True,
                http_latency_ms=_relay_push_state["last_latency_ms"],
                platform_received_at=_relay_push_state["last_platform_received_at"],
            )
        except Exception as exc:
            _relay_push_state["last_ts"] = time.time()
            _relay_push_state["last_event"] = f"INTENT_{event}"
            _relay_push_state["last_ok"] = False
            _relay_push_state["last_error"] = str(exc)[:240]
            _relay_push_state["last_latency_ms"] = round(
                (time.perf_counter() - started) * 1000, 1
            )
            _record_relay_delivery(
                f"INTENT_{event}",
                trade_id,
                payload.get("ts"),
                ok=False,
                http_latency_ms=_relay_push_state["last_latency_ms"],
                error=exc,
            )
            logger.warning(f"[INTENT WEBHOOK] {event} trade={trade_id} failed: {exc}")

    threading.Thread(target=_post, daemon=True).start()


def record_approve_outcome(status: str, reason: str = None, eff_thr: float = None, trade_id: str = None, edge: float = None, ai: dict = None, signal: dict = None):
    with state_lock:
        state["last_approve_outcome"] = {
            "status": status,
            "reason": reason,
            "effective_threshold": eff_thr,
            "edge_at_approve": edge,
            "trade_id": trade_id,
            "ts": utc_iso(),
            "win_prob": (ai or {}).get("win_prob") or state.get("last_ai", {}).get("win_prob"),
            "direction": (ai or {}).get("direction") or state.get("last_ai", {}).get("direction"),
        }
    if status == "PENDING" and trade_id:
        # Visibility-only, signed exact-limit intent. It cannot authorize an
        # exchange order; the relay waits for ORDER_PLACED.
        emit_signal_webhook("APPROVE_PENDING", signal, ai)
    elif status == "EXECUTED" and trade_id:
        # Fail closed when signing is unavailable; never fall back to the old
        # percentage-derived unsigned money contract.
        emit_signal_webhook("ORDER_PLACED", signal, ai)

def resolve_pending_approve_blocked(signal: dict, ai: dict, reason: str):
    """After record_approve_outcome(PENDING), upgrade to BLOCKED if pipeline exits early."""
    if not signal or not ai or ai.get("decision") != "APPROVE":
        return
    tid = signal.get("trade_id")
    with state_lock:
        lao = state.get("last_approve_outcome") or {}
    if lao.get("status") == "PENDING" and lao.get("trade_id") == tid:
        record_approve_outcome(
            "BLOCKED",
            reason,
            signal.get("effective_threshold_at_entry") or lao.get("effective_threshold") or get_effective_edge_threshold(),
            tid,
            signal.get("edge_score_at_entry") or lao.get("edge_at_approve"),
            ai,
        )

def enforce_edge_threshold_options():
    with state_lock:
        current = round(state["edge_threshold"], 1)
        research_collect = state.get("strategy_mode") == "RESEARCH" and not state.get("live_armed")
        if research_collect and RESEARCH_AI_SOLE_AUTHORITY:
            fallback = 0.0
        else:
            fallback = RESEARCH_EDGE_THRESHOLD_DEFAULT if research_collect else 3.0
        if current not in [round(x, 1) for x in EDGE_OPTIONS]:
            logger.warning(
                f"[EDGE ENFORCEMENT] Invalid threshold {current} - resetting to {fallback} "
                f"[PIPELINE ENFORCEMENT]"
            )
            state["edge_threshold"] = fallback
            state["debug_state"]["edge_reason"] = "RESET_TO_DEFAULT"
    logger.info(f"[EDGE ENFORCEMENT] threshold validated at {get_edge_threshold()} [PIPELINE ENFORCEMENT]")

def get_effective_edge_threshold() -> float:
    """Regime-aware edge bar in live mode; dashboard-only in research data collection."""
    base = get_edge_threshold()
    if is_research_data_collection():
        with state_lock:
            comps = state.get("debug_state", {}).get("edge_components") or {}
            comps["base_threshold"] = base
            comps["effective_threshold"] = round(base, 1)
            comps["research_mode"] = True
            state["debug_state"]["edge_components"] = comps
        return round(base, 1)
    with state_lock:
        regime = str(state.get("regime", "RANGE")).upper()
        sr_state = str((state.get("support_resistance") or {}).get("sr_state", "")).upper()
        fs = state.get("feature_snapshot") or {}
    eff = round(base + EDGE_RANGE_THRESHOLD_BUMP, 1) if (regime == "RANGE" or "COMPRESSION" in sr_state) else base
    flat_floor = get_dynamic_flat_momentum_floor(base)
    momentum_flat = _compute_momentum_metric(fs) < MOMENTUM_FLAT_MAX
    if momentum_flat:
        eff = max(eff, flat_floor)
    with state_lock:
        comps = state.get("debug_state", {}).get("edge_components") or {}
        comps["base_threshold"] = base
        comps["flat_momentum_floor"] = flat_floor
        comps["momentum_flat"] = momentum_flat
        comps["effective_threshold"] = round(eff, 1)
        state["debug_state"]["edge_components"] = comps
    return round(eff, 1)

def is_profit_gates_lane(research_lane) -> bool:
    return str(research_lane or "") == RESEARCH_LANE_PROFIT_GATES


def profit_gates_lane_enabled() -> bool:
    """Spawn lane toggle — PROFIT_GATES lane with hard post-AI filters (not global pipeline mode)."""
    with state_lock:
        if "profit_gates_lane_enabled" in state:
            return bool(state.get("profit_gates_lane_enabled"))
        if "profit_gates_enforced" in state:
            return bool(state.get("profit_gates_enforced"))
    return PROFIT_GATES_LANE_DEFAULT_ENABLED


def profit_gates_enforced() -> bool:
    """API compat — reflects PROFIT_GATES spawn lane toggle only (not global pipeline mode)."""
    return profit_gates_lane_enabled()


def _post_ai_gate_blocks(sole: bool, research_lane=None) -> bool:
    if is_research_data_collection():
        return is_profit_gates_lane(research_lane)
    return not sole


def _research_execute_log_only(research_lane=None) -> bool:
    """Research sim: WOULD_FAIL/CLUSTER log-only on benchmark lanes; hard enforce on PROFIT_GATES."""
    if not is_research_data_collection():
        return False
    if is_profit_gates_lane(research_lane):
        return False
    return not state.get("live_armed")


def evaluate_profitability_entry_gates(
    signal: dict, ai: dict, edge_score: float, research_lane=None
) -> tuple:
    """Non-Edge profitability gates; Edge is descriptive evidence only."""
    prob = float(ai.get("win_prob") or signal.get("ai_win_prob") or 0)
    if dashboard_ai_band_blocks(prob):
        reason = "PROFIT_GATE_AI_BAND"
        if is_research_data_collection():
            return is_profit_gates_lane(research_lane), reason
        return True, reason
    return False, None


def _exit_post_ai_profit_gate(signal, ai, reason: str, edge_score: float, sole: bool) -> bool:
    """Block APPROVE on profitability gate; return True if pipeline should stop."""
    logger.info(f"[PROFIT GATE] BLOCK {reason} trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
    log_blocked_signal(signal, ai, reason)
    log_pipeline_event("POST_AI", "BLOCKED", reason, signal.get("trade_id"), edge_score, force=True)
    exit_pipeline(signal, ai, reason)
    with state_lock:
        state["debug_state"]["last_block_reason"] = reason
        state["debug_state"]["last_pipeline_stage"] = "BLOCKED"
        state["debug_state"]["skip_reason"] = reason
    update_debug_state_always(reason, {"edge": edge_score})
    state["last_pipeline_stage"] = "IDLE"
    return True


def _sole_ai_research_mode() -> bool:
    """Independent research lanes — CONTINUOUS benchmark frozen; post-AI gates log-only except PROFIT_GATES spawn."""
    return RESEARCH_AI_SOLE_AUTHORITY and is_research_data_collection()


def research_lanes_independent() -> bool:
    """True when research lanes use per-lane cooldown/rearm (capacity is still global)."""
    return research_isolation_enabled() or _sole_ai_research_mode()


def get_research_ai_cooldown_sec(lane: str = None) -> int:
    """Continuous-lane AI interval (seconds). CONTINUOUS benchmark frozen at 180s."""
    if is_continuous_benchmark_lane(lane):
        return CONTINUOUS_BENCHMARK_AI_COOLDOWN_SEC
    with state_lock:
        raw = state.get("research_ai_cooldown_sec")
    if raw is not None:
        try:
            return max(60, min(600, int(raw)))
        except (TypeError, ValueError):
            pass
    return RESEARCH_AI_COOLDOWN_SEC


def _limit_chase_config_value(state_key: str, env_key: str, default, cast):
    with state_lock:
        raw = state.get(state_key)
    if raw is not None:
        try:
            return cast(raw)
        except (TypeError, ValueError):
            pass
    try:
        return cast(os.getenv(env_key, str(default)))
    except (TypeError, ValueError):
        return cast(default)


def limit_chase_enabled() -> bool:
    if not is_research_data_collection():
        return False
    if os.getenv("LIMIT_CHASE_ENABLED", "1").lower() in ("0", "false", "no"):
        return False
    return True


def get_limit_chase_start_sec() -> int:
    return max(0, _limit_chase_config_value(
        "limit_chase_start_sec", "LIMIT_CHASE_START_SEC", LIMIT_CHASE_START_SEC_DEFAULT, int
    ))


def get_limit_chase_interval_sec() -> int:
    return max(CHASE_INTRA_WINDOW_REPRICE_SEC, _limit_chase_config_value(
        "limit_chase_interval_sec", "LIMIT_CHASE_INTERVAL_SEC", LIMIT_CHASE_INTERVAL_SEC_DEFAULT, int
    ))


def get_limit_chase_step_pct() -> float:
    return max(0.05, min(1.0, _limit_chase_config_value(
        "limit_chase_step_pct", "LIMIT_CHASE_STEP_PCT", LIMIT_CHASE_STEP_PCT_DEFAULT, float
    )))


URGENT_CHASE_VELOCITY_MED = float(os.getenv("URGENT_CHASE_VEL_MED", "0.00003"))
URGENT_CHASE_VELOCITY_HIGH = float(os.getenv("URGENT_CHASE_VEL_HIGH", "0.00006"))
URGENT_CHASE_VELOCITY_EXTREME = float(os.getenv("URGENT_CHASE_VEL_EXTREME", "0.00012"))


def _urgent_chase_step_for_order(order: dict, signal: dict = None):
    """Velocity-aware chase step for URGENT_CHASE_ALPHA; None → benchmark 25% step."""
    lane = order.get("research_lane") or (signal or {}).get("research_lane")
    if lane != RESEARCH_LANE_URGENT_CHASE_ALPHA:
        return None, None, False
    vel = abs(float(order.get("entry_velocity") or (signal or {}).get("entry_velocity") or 0))
    if vel >= URGENT_CHASE_VELOCITY_EXTREME:
        return 1.0, "extreme", True
    if vel >= URGENT_CHASE_VELOCITY_HIGH:
        return 0.75, "high", False
    if vel >= URGENT_CHASE_VELOCITY_MED:
        return 0.50, "medium", False
    return 0.25, "normal", False


def min_signal_age_enabled() -> bool:
    if not is_research_data_collection():
        return False
    with state_lock:
        raw = state.get("min_signal_age_enabled")
    if raw is not None:
        return bool(raw)
    return MIN_SIGNAL_AGE_ENABLED_DEFAULT


def get_min_signal_age_sec() -> int:
    return max(0, _limit_chase_config_value(
        "min_signal_age_sec", "MIN_SIGNAL_AGE_SEC", MIN_SIGNAL_AGE_SEC_DEFAULT, int
    ))


def smart_submit_enabled() -> bool:
    if not is_research_data_collection():
        return False
    with state_lock:
        raw = state.get("smart_submit_enabled")
    if raw is not None:
        return bool(raw)
    return SMART_SUBMIT_ENABLED_DEFAULT


def get_smart_submit_reanchor_pct() -> float:
    return max(0.0001, min(0.02, _limit_chase_config_value(
        "smart_submit_reanchor_pct", "SMART_SUBMIT_REANCHOR_PCT", SMART_SUBMIT_REANCHOR_PCT_DEFAULT, float
    )))


def duplicate_limit_block_enabled() -> bool:
    with state_lock:
        if "duplicate_limit_block_enabled" in state:
            return bool(state.get("duplicate_limit_block_enabled"))
    return DUPLICATE_LIMIT_BLOCK_ENABLED_DEFAULT


def _signal_age_sec(signal: dict, now: float = None) -> float:
    now = float(time.time() if now is None else now)
    if not isinstance(signal, dict):
        return 0.0
    signal_ts = (signal.get("timing") or {}).get("signal_ts") or signal.get("created_ts_ts")
    if signal_ts:
        try:
            return max(0.0, now - float(signal_ts))
        except (TypeError, ValueError):
            pass
    return 0.0


def _chase_lifecycle_age_sec(order: dict = None, signal: dict = None, now: float = None) -> float:
    """Signal-age for chase windows (not order-age, not chase-count ticks)."""
    now = float(time.time() if now is None else now)
    if isinstance(signal, dict):
        signal_ts = (signal.get("timing") or {}).get("signal_ts") or signal.get("created_ts_ts")
        if signal_ts:
            try:
                return max(0.0, now - float(signal_ts))
            except (TypeError, ValueError):
                pass
        age = _signal_age_sec(signal, now=now)
        if age > 0:
            return age
    if isinstance(order, dict):
        for key in ("signal_created_ts", "signal_ts", "created_ts"):
            ts = order.get(key)
            if ts:
                try:
                    return max(0.0, now - float(ts))
                except (TypeError, ValueError):
                    continue
    return 0.0


def _refresh_signal_price_for_submit(signal: dict) -> float:
    """Use current market at submit time (not stale APPROVE-time price)."""
    now = time.time()
    with state_lock:
        ws_price = float(state.get("price") or 0)
        bid = float(state.get("bid") or 0)
        ask = float(state.get("ask") or 0)
        rest_price = (bid + ask) / 2.0 if bid > 0 and ask >= bid else 0.0
    price = rest_price if _fresh_rest_entry_quote_ready(now) else ws_price
    if price and float(price) > 0:
        signal["signal_price"] = float(price)
        signal["signal_price_submit"] = float(price)
        signal["signal_price_submit_source"] = (
            "REST_BBO" if price == rest_price and rest_price > 0 else "WS"
        )
        return float(price)
    return float(signal.get("signal_price") or 0)


def _entry_limit_would_fill_immediately(direction: str, market_price: float, limit_price: float) -> bool:
    """True when a resting maker limit at limit_price would take immediately vs market."""
    direction = str(direction or "").upper()
    if limit_price <= 0 or market_price <= 0:
        return False
    if direction == "LONG":
        return market_price <= limit_price
    if direction == "SHORT":
        return market_price >= limit_price
    return False


def _apply_smart_submit_limit(
    signal: dict, planned_limit: float, entry_mode: str, market_price: float
) -> tuple:
    """Re-anchor below/above market when price crossed planned limit; enable immediate chase.

    Danish decision 5 (2026-08-01): under the deterministic 0.1% anchor a
    crossed virtual limit before the first selected entry stage is recorded as
    ``VIRTUAL_TOUCH_BEFORE_SELECTED_ENTRY`` by ``_expire_skipped_virtual_fill``
    (handled in ``process_awaiting_dashboard_virtual_chase_entries`` before this
    function is reached). When the candidate survives to a selected stage and
    the planned limit is already marketable, smart-submit re-anchors to a fresh
    maker offset under the documented rule — it does NOT invent a fill and does
    NOT reset the chase counter. Only the legacy ``micro_sr_structural_limit_v1``
    policy preserves its observed pivot (kept for back-compat with old snapshots).
    """
    direction = _signal_direction(signal)
    original = float(planned_limit)
    # Legacy structural-limit snapshots preserve their observed pivot anchor.
    # The deterministic policy intentionally falls through to the re-anchor path
    # below so a touched limit at a selected stage becomes a fresh maker offset.
    if signal.get("entry_limit_policy") == STRUCTURAL_ENTRY_POLICY_VERSION:
        signal["smart_submit_reanchored"] = False
        return original, entry_mode, {
            "reanchored": False,
            "immediate_chase": False,
            "original_planned": original,
            "structural_anchor_preserved": True,
        }
    if not _entry_limit_would_fill_immediately(direction, market_price, original):
        signal["smart_submit_reanchored"] = False
        return original, entry_mode, {
            "reanchored": False,
            "immediate_chase": False,
            "original_planned": original,
        }
    reanchor_pct = get_smart_submit_reanchor_pct()
    if direction == "LONG":
        new_limit = round(market_price * (1 - reanchor_pct), 2)
    elif direction == "SHORT":
        new_limit = round(market_price * (1 + reanchor_pct), 2)
    else:
        return original, entry_mode, {"reanchored": False, "immediate_chase": False, "original_planned": original}
    signal["smart_submit_reanchored"] = True
    signal["smart_submit_original_planned"] = original
    signal["planned_limit_price"] = original
    logger.info(
        f"[SMART_SUBMIT] re-anchor trade_id={signal.get('trade_id')} dir={direction} "
        f"market={fmt(market_price)} planned={fmt(original)} new_limit={fmt(new_limit)} "
        f"reanchor_pct={reanchor_pct*100:.2f}% immediate_chase=ON [PIPELINE ENFORCEMENT]"
    )
    return new_limit, entry_mode, {
        "reanchored": True,
        "immediate_chase": True,
        "original_planned": original,
    }


def _resolve_submit_limit_price(signal: dict) -> tuple:
    """Refresh market, resolve entry limit, apply smart-submit re-anchor when needed."""
    if str(signal.get("research_lane") or "").upper() == RESEARCH_LANE_OFFSET_029_ATR_TP_25:
        planned, entry_mode = resolve_entry_limit_price(signal)
        return planned, entry_mode, {
            "reanchored": False,
            "immediate_chase": False,
            "original_planned": planned,
            "policy_id": offset029_policy.POLICY_ID,
        }, planned
    if smart_submit_enabled():
        _refresh_signal_price_for_submit(signal)
    planned, entry_mode = resolve_entry_limit_price(signal)
    market = float(state.get("price") or signal.get("signal_price") or 0)
    if smart_submit_enabled() and market > 0:
        return _apply_smart_submit_limit(signal, planned, entry_mode, market) + (planned,)
    return planned, entry_mode, {"reanchored": False, "immediate_chase": False, "original_planned": planned}, planned


def _instant_entry_path(signal: dict) -> bool:
    pullback_pct = float(signal.get("pullback_pct", state.get("pullback_threshold", 0.001)))
    return pullback_pct <= 0.0


def _should_defer_min_signal_age(signal: dict) -> bool:
    if fills_first_continuous_enabled(signal):
        return False
    if not min_signal_age_enabled():
        return False
    if _instant_entry_path(signal):
        return False
    return _signal_age_sec(signal) < get_min_signal_age_sec()


def _defer_signal_min_age(signal: dict) -> bool:
    signal["status"] = SIGNAL_STATUS_AWAITING_MIN_AGE
    signal["awaiting_min_age_since"] = time.time()
    signal["order_placed"] = False
    logger.info(
        f"[SIM] awaiting_min_age trade_id={signal.get('trade_id')} "
        f"age_sec={round(_signal_age_sec(signal), 1)} need={get_min_signal_age_sec()}s "
        f"[PIPELINE ENFORCEMENT]"
    )
    pipeline_state_sync()
    return True


def is_chase_3plus_alpha_lane(signal: dict) -> bool:
    lane = str((signal or {}).get("research_lane") or "").upper()
    if lane == RESEARCH_LANE_CHASE_3PLUS_ALPHA:
        return True
    return is_chase_3plus_entry_lane(lane)


def _chase_3plus_signal_distance_pct(signal: dict, market_price: float) -> float:
    ref = float(signal.get("chase_3plus_signal_price") or signal.get("signal_price") or 0)
    if ref <= 0 or market_price <= 0:
        return 0.0
    return abs(market_price - ref) / ref


def _init_chase_3plus_virtual_state(signal: dict, market_price: float) -> None:
    """Seed virtual chase from benchmark-equivalent planned limit (CONTINUOUS chase step)."""
    if not signal.get("entry_path"):
        compute_continuous_ai_direct_entry(signal)
    planned, entry_mode, smart_meta, _planned_raw = _resolve_submit_limit_price(signal)
    if smart_submit_enabled() and market_price > 0:
        planned, entry_mode, smart_meta = _apply_smart_submit_limit(
            signal, planned, entry_mode, market_price,
        )
    original = float((smart_meta or {}).get("original_planned") or planned)
    ref_price = float(signal.get("signal_price") or market_price or 0)
    signal["chase_3plus_signal_price"] = ref_price
    signal["chase_3plus_planned_limit"] = float(planned)
    signal["chase_3plus_virtual_limit"] = float(planned)
    signal["chase_3plus_original_limit"] = original
    signal["chase_3plus_virtual_chase_count"] = 0
    signal["chase_3plus_virtual_started_ts"] = time.time()
    signal["chase_3plus_last_virtual_chase_ts"] = None
    signal["planned_limit_price"] = float(planned)
    signal["limit_price"] = float(planned)
    signal["entry_mode"] = entry_mode


def _virtual_chase_eligible(signal: dict, market_price: float, now: float) -> bool:
    direction = _signal_direction(signal)
    virtual_limit = float(signal.get("chase_3plus_virtual_limit") or 0)
    original = float(signal.get("chase_3plus_original_limit") or virtual_limit)
    started = float(signal.get("chase_3plus_virtual_started_ts") or now)
    age_sec = now - started
    if age_sec < LIMIT_CHASE_HOLD_SEC:
        return False
    if age_sec >= LIMIT_ORDER_MAX_AGE_SEC:
        return False
    last_chase = signal.get("chase_3plus_last_virtual_chase_ts")
    if last_chase and (now - float(last_chase)) < get_limit_chase_interval_sec():
        return False
    if virtual_limit <= 0 or market_price <= 0:
        return False
    if _limit_chase_near_fill_zone(direction, virtual_limit, market_price):
        return False
    orig_gap = _limit_chase_market_gap(direction, original, market_price)
    if orig_gap <= LIMIT_CHASE_NEAR_FILL_USD:
        return False
    cur_gap = _limit_chase_market_gap(direction, virtual_limit, market_price)
    if cur_gap <= 0:
        return False
    if orig_gap > 0:
        closed_pct = 1.0 - (cur_gap / orig_gap)
        if closed_pct >= LIMIT_CHASE_MAX_GAP_CLOSE_PCT:
            return False
    return True


def _tick_chase_3plus_virtual_chase(signal: dict, market_price: float, now: float) -> int:
    age = _signal_age_sec(signal)
    idx = chase_age_window_index(age)
    current = int(signal.get("chase_3plus_virtual_chase_count") or 0)
    # Count follows the 5-minute age window, never 60s tick burns.
    target = idx
    if target != current:
        signal["chase_3plus_virtual_chase_count"] = target
    if not chase_age_window_may_reprice(age):
        return int(signal.get("chase_3plus_virtual_chase_count") or 0)
    if not _virtual_chase_eligible(signal, market_price, now):
        return int(signal.get("chase_3plus_virtual_chase_count") or 0)
    direction = _signal_direction(signal)
    virtual_limit = float(signal.get("chase_3plus_virtual_limit") or 0)
    original = float(signal.get("chase_3plus_original_limit") or virtual_limit)
    new_limit, reason = _compute_limit_chase_target(
        direction, virtual_limit, market_price, original, step_pct=get_limit_chase_step_pct(),
    )
    if reason != "LIMIT_CHASE" or abs(new_limit - virtual_limit) < 0.01:
        return int(signal.get("chase_3plus_virtual_chase_count") or 0)
    signal["chase_3plus_virtual_limit"] = new_limit
    signal["limit_price"] = new_limit
    signal["chase_3plus_virtual_chase_count"] = target
    signal["chase_3plus_last_virtual_chase_ts"] = now
    return target


def _chase_3plus_activation_reason(signal: dict, market_price: float) -> str:
    vcount = int(signal.get("chase_3plus_virtual_chase_count") or 0)
    if vcount >= CHASE_3PLUS_VIRTUAL_MIN:
        return f"VIRTUAL_CHASE_{vcount}"
    age = _signal_age_sec(signal)
    if age >= CHASE_3PLUS_MAX_WAIT_SEC:
        return f"SIGNAL_AGE_{int(age)}s"
    dist_pct = _chase_3plus_signal_distance_pct(signal, market_price)
    if dist_pct >= CHASE_3PLUS_DISTANCE_PCT:
        return f"SIGNAL_DISTANCE_{dist_pct * 100:.3f}pct"
    return ""


def _defer_signal_chase_3plus(signal: dict) -> bool:
    return _defer_dashboard_virtual_chase(signal)


def _defer_dashboard_virtual_chase(signal: dict) -> bool:
    """Remember APPROVE; tick virtual chase until dashboard bucket allows limit submit."""
    price = float(state.get("price") or signal.get("signal_price") or 0)
    if price <= 0:
        return False
    with trade_lock:
        if signal.get("status") not in VIRTUAL_CHASE_AWAITING_STATUSES:
            _init_chase_3plus_virtual_state(signal, price)
            signal["dashboard_virtual_chase_count"] = 0
            signal["dashboard_virtual_started_ts"] = time.time()
            signal["dashboard_virtual_limit"] = signal.get("chase_3plus_virtual_limit")
            signal["promotion_lifecycle_generation"] = int(
                signal.get("promotion_lifecycle_generation") or 0
            ) + 1
        signal["status"] = SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE
        signal["awaiting_dashboard_chase_since"] = time.time()
        signal["order_placed"] = False
    mn = min_enabled_chase_count()
    logger.info(
        f"[DASHBOARD GATE] virtual defer trade_id={signal.get('trade_id')} "
        f"lane={signal.get('research_lane')} need_chase_count>={mn} "
        f"enabled={get_chase_execution_buckets()} [PIPELINE ENFORCEMENT]"
    )
    pipeline_state_sync()
    return True


def _tick_dashboard_virtual_chase(signal: dict, market_price: float, now: float) -> int:
    count = _tick_chase_3plus_virtual_chase(signal, market_price, now)
    signal["dashboard_virtual_chase_count"] = count
    return count


def _claim_signal_promotion(signal: dict) -> dict | None:
    """Atomically claim one canonical signal generation for order promotion."""
    if not isinstance(signal, dict):
        return None
    tid = str(signal.get("trade_id") or "")
    if not tid:
        return None
    now = time.time()
    with trade_lock:
        master = trades_map.get(tid, {}).get("signal_ref")
        generation = int(signal.get("promotion_lifecycle_generation") or 0)
        if (
            master is not signal
            or is_terminal_signal(signal)
            or signal.get("status") not in VIRTUAL_CHASE_AWAITING_STATUSES
            or signal.get("order_placed")
            or any(
                str(order.get("trade_id") or "") == tid
                and str(order.get("status") or "").upper()
                in ("PENDING", "CANCEL_PENDING_LIVE")
                for order in pending_orders
            )
            or any(
                str(position.get("trade_id") or "") == tid
                and str(position.get("status") or "").upper() not in ("CLOSED", "EXPIRED")
                for position in open_positions
            )
        ):
            return None
        active_token = signal.get("promotion_claim_token")
        active_at = float(signal.get("promotion_in_progress_at") or 0)
        if active_token and now - active_at <= PROMOTION_IN_PROGRESS_GRACE_SEC:
            return None
        token = uuid.uuid4().hex
        signal["promotion_claim_token"] = token
        signal["promotion_claim_generation"] = generation
        signal["promotion_in_progress_at"] = now
        return {"trade_id": tid, "token": token, "generation": generation}


def _signal_promotion_claim_valid(signal: dict, claim: dict) -> bool:
    """Revalidate identity, generation and no-exposure immediately before creation."""
    if not isinstance(signal, dict) or not isinstance(claim, dict):
        return False
    tid = str(claim.get("trade_id") or "")
    with trade_lock:
        return bool(
            tid
            and trades_map.get(tid, {}).get("signal_ref") is signal
            and signal.get("promotion_claim_token") == claim.get("token")
            and int(signal.get("promotion_lifecycle_generation") or 0)
            == int(claim.get("generation") or 0)
            and int(signal.get("promotion_claim_generation") or 0)
            == int(claim.get("generation") or 0)
            and not is_terminal_signal(signal)
            and signal.get("status") in VIRTUAL_CHASE_AWAITING_STATUSES
            and not signal.get("order_placed")
            and not any(
                str(order.get("trade_id") or "") == tid
                and str(order.get("status") or "").upper()
                in ("PENDING", "CANCEL_PENDING_LIVE")
                for order in pending_orders
            )
            and not any(
                str(position.get("trade_id") or "") == tid
                and str(position.get("status") or "").upper() not in ("CLOSED", "EXPIRED")
                for position in open_positions
            )
        )


def _release_signal_promotion_claim(signal: dict, claim: dict) -> None:
    if not isinstance(signal, dict) or not isinstance(claim, dict):
        return
    with trade_lock:
        if signal.get("promotion_claim_token") != claim.get("token"):
            return
        signal.pop("promotion_claim_token", None)
        signal.pop("promotion_claim_generation", None)
        signal.pop("promotion_in_progress_at", None)


def _virtual_limit_would_fill(signal: dict, market_price: float) -> bool:
    """Whether the unplaced virtual limit would have filled at its current count."""
    direction = _signal_direction(signal)
    virtual_limit = float(
        signal.get("chase_3plus_virtual_limit")
        or signal.get("dashboard_virtual_limit")
        or signal.get("limit_price")
        or 0
    )
    if virtual_limit <= 0 or market_price <= 0:
        return False
    if direction == "LONG":
        return float(market_price) <= virtual_limit
    if direction == "SHORT":
        return float(market_price) >= virtual_limit
    return False


def _expire_skipped_virtual_fill(signal: dict) -> None:
    """Close a virtual-only path when an unchecked chase count would have filled.

    Danish decision 5 (2026-08-01): when market crosses a virtual limit before
    the first selected entry stage, record ``VIRTUAL_TOUCH_BEFORE_SELECTED_ENTRY``
    — never invent an exchange fill, never submit a marketable order at the old
    price. At later unchecked stages the legacy ``VIRTUAL_FILL_SKIPPED_CHASE_n``
    reason is retained for cohort fidelity.
    """
    chase_n = _signal_virtual_chase_count(signal)
    min_enabled = min_enabled_chase_count()
    if min_enabled is None or chase_n < min_enabled:
        reason = "VIRTUAL_TOUCH_BEFORE_SELECTED_ENTRY"
    else:
        reason = f"VIRTUAL_FILL_SKIPPED_CHASE_{chase_n}"
    signal["status"] = "EXPIRED"
    signal["outcome"] = reason
    signal["exit_reason"] = reason
    signal["virtual_touch_before_selected_entry"] = (
        reason == "VIRTUAL_TOUCH_BEFORE_SELECTED_ENTRY"
    )
    signal["order_placed"] = False
    _record_expired_order(signal, reason)
    _funnel_signal_expired(signal, reason)
    logger.info(
        f"[DASHBOARD GATE] skipped virtual fill trade_id={signal.get('trade_id')} "
        f"chase_count={chase_n} min_enabled={min_enabled} "
        f"limit={fmt(signal.get('limit_price'))} reason={reason} [PIPELINE ENFORCEMENT]"
    )


def process_awaiting_dashboard_virtual_chase_entries(
    *, allow_submit: bool = True, promotion_block_reason: str = ""
):
    """Advance virtual evidence; submit only behind the full readiness gate."""
    if allow_submit and not can_progress_new_entry()[0]:
        logger.debug(
            "[WS ENTRY FREEZE] virtual chase approvals retained while genuine WS is unavailable "
            "[PIPELINE ENFORCEMENT]"
        )
        return
    price = state.get("price")
    if price is None or price <= 0:
        return
    now = time.time()
    market = float(price)
    with trade_lock:
        awaiting = [
            (entry.get("signal_ref") or {})
            for entry in trades_map.values()
            if isinstance(entry.get("signal_ref"), dict)
            and entry["signal_ref"].get("status") in VIRTUAL_CHASE_AWAITING_STATUSES
            and not is_terminal_signal(entry["signal_ref"])
        ]
    for signal in awaiting:
        tid = signal.get("trade_id")
        if not tid:
            continue
        if not lane_orders_allowed(signal.get("research_lane")):
            continue
        meta = trades_map.get(tid, {})
        ai = meta.get("ai") or signal.get("ai") or {}
        allowed, reason, _defer = evaluate_dashboard_execution_gate(signal, ai, stage="promote")
        if reason in ("AI_BAND_BLOCKED", "AI_REVIEWER_OFF", "LANE_DISABLED", "CHASE_BUCKETS_ALL_OFF", "LEVERAGE_OUT_OF_RANGE"):
            signal["status"] = "BLOCKED"
            signal["outcome"] = reason
            signal["exit_reason"] = reason
            logger.info(
                f"[DASHBOARD GATE] blocked while waiting trade_id={tid} reason={reason} "
                f"[PIPELINE ENFORCEMENT]"
            )
            continue
        expires_ts = signal.get("expires_ts") or (signal.get("created_ts_ts", 0) + SIGNAL_TTL_SEC)
        if expires_ts and now > expires_ts:
            with trade_lock:
                master = trades_map.get(tid, {}).get("signal_ref", signal)
                master["status"] = "EXPIRED"
                master["outcome"] = "SIGNAL_TTL_EXPIRED"
                master["exit_reason"] = "SIGNAL_TTL_EXPIRED"
            _record_expired_order(signal, "SIGNAL_TTL_EXPIRED")
            _funnel_signal_expired(signal, "SIGNAL_EXPIRED")
            logger.info(
                f"[DASHBOARD GATE] virtual defer expired trade_id={tid} "
                f"virtual_chase={_signal_virtual_chase_count(signal)} [PIPELINE ENFORCEMENT]"
            )
            continue
        # Faithful cohort isolation: if the unplaced limit would have filled at
        # an unchecked count, this signal belongs to that skipped bucket. It
        # must not survive and later masquerade as a chase-3/4/5 entry.
        if _virtual_limit_would_fill(signal, market):
            _expire_skipped_virtual_fill(signal)
            continue
        _tick_dashboard_virtual_chase(signal, market, now)
        vcount = _signal_virtual_chase_count(signal)
        signal["current_age_bucket"] = chase_age_window_index(_signal_age_sec(signal))
        signal["next_enabled_bucket"] = _next_enabled_chase_after(vcount)
        if not dashboard_virtual_chase_submit_ready(signal):
            continue
        if not allow_submit:
            signal["promotion_block_reason"] = (
                promotion_block_reason or "NEW_ENTRY_NOT_READY"
            )
            continue
        if not ensure_signal_capacity():
            continue
        allowed, reason, _ = evaluate_dashboard_execution_gate(signal, ai, stage="submit")
        if not allowed:
            signal["promotion_block_reason"] = reason
            continue
        signal["promotion_block_reason"] = None
        logger.info(
            f"[DASHBOARD GATE] virtual chase ready trade_id={tid} "
            f"virtual_chase={vcount} bucket={chase_count_bucket(vcount)} "
            f"submitting limit [PIPELINE ENFORCEMENT]"
        )
        signal["dashboard_chase_activation_count"] = vcount
        _promote_signal_to_limit_order(signal, skip_virtual_defer=True)


def process_awaiting_chase_3plus_entries():
    """Legacy alias — dashboard virtual defer is the global path."""
    process_awaiting_dashboard_virtual_chase_entries()


def _virtual_chase_fill_phase(chase_count: int, *, virtual: bool = False, waiting: bool = False, market: bool = False) -> str:
    if market:
        return "CHASE6_MARKET"
    if waiting:
        return "CHASE6_WAIT"
    if chase_count <= 0:
        return "CHASE0"
    if chase_count == 3 and not virtual:
        return "CHASE3"
    if chase_count == 4:
        return "CHASE4"
    if chase_count == 5:
        return "CHASE5"
    if virtual and chase_count in (1, 2):
        return f"VIRTUAL_CHASE_{chase_count}"
    return f"CHASE{chase_count}"


def _record_virtual_chase_execution_metrics(signal: dict, order: dict = None) -> None:
    if not isinstance(signal, dict):
        return
    now = time.time()
    virtual_since = float(signal.get("virtual_chase_since_ts") or 0)
    visible_since = float(signal.get("visible_chase_since_ts") or 0)
    if signal.get("virtual_chase_state") and virtual_since > 0:
        signal["virtual_time_sec"] = round(now - virtual_since, 2)
    elif virtual_since > 0 and visible_since > 0:
        signal["virtual_time_sec"] = round(max(0.0, visible_since - virtual_since), 2)
    if visible_since > 0 and not signal.get("virtual_chase_state"):
        signal["visible_time_sec"] = round(now - visible_since, 2)
    payload = {
        "trade_id": signal.get("trade_id"),
        "research_lane": signal.get("research_lane"),
        "fill_phase": signal.get("fill_phase"),
        "virtual_time_sec": signal.get("virtual_time_sec"),
        "visible_time_sec": signal.get("visible_time_sec"),
        "market_conversion": bool(signal.get("market_conversion")),
        "market_conversion_delay": signal.get("market_conversion_delay"),
        "conversion_slippage": signal.get("conversion_slippage"),
        "conversion_success": signal.get("conversion_success"),
        "limit_chase_count": signal.get("limit_chase_count"),
    }
    if order:
        payload["order_id"] = order.get("order_id") or order.get("id")
    _emit_genome_execution_event("VIRTUAL_CHASE_METRICS", payload)


def _sync_virtual_chase_signal_order(signal: dict, order: dict = None, **fields) -> None:
    if not isinstance(signal, dict):
        return
    for k, v in fields.items():
        signal[k] = v
    if order:
        for k, v in fields.items():
            if k in ("limit_price", "limit_chase_count", "last_chase_ts", "fill_phase",
                     "virtual_chase_state", "virtual_chase_6_wait_until", "market_conversion"):
                order[k] = v


def _pull_order_to_virtual_chase(signal: dict, order: dict, new_limit: float, chase_count: int, now: float) -> bool:
    tid = order.get("trade_id") or signal.get("trade_id")
    cancel_result = _cancel_pending_order_confirmed(
        order,
        "VIRTUAL_CHASE_HIDE",
        record_expired=False,
        expire_signal=False,
    )
    if not cancel_result.get("finalized"):
        logger.critical(
            f"[VIRTUAL_CHASE] unable to hide unconfirmed live order "
            f"trade_id={tid} oid={cancel_result.get('exchange_order_id') or '-'} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return False
    if not signal.get("virtual_chase_since_ts"):
        signal["virtual_chase_since_ts"] = now
    signal["virtual_chase_state"] = True
    signal["order_placed"] = False
    signal["status"] = SIGNAL_STATUS_VIRTUAL_CHASE
    signal["limit_price"] = round(float(new_limit), 2)
    signal["planned_limit_price"] = signal["limit_price"]
    signal["limit_chase_count"] = chase_count
    signal["last_chase_ts"] = now
    signal["fill_phase"] = _virtual_chase_fill_phase(chase_count, virtual=True)
    _emit_genome_execution_event("ORDER_CANCELLED", {
        "trade_id": tid,
        "reason": "VIRTUAL_CHASE_HIDE",
        "chase_count": chase_count,
        "research_lane": signal.get("research_lane"),
    })
    _record_virtual_chase_execution_metrics(signal)
    logger.info(
        f"[VIRTUAL_CHASE] chase={chase_count} trade_id={tid} hidden from exchange "
        f"limit={fmt(signal['limit_price'])} [PIPELINE ENFORCEMENT]"
    )
    pipeline_state_sync()
    return True


def _virtual_chase_signal_eligible(signal: dict, price: float, now: float) -> bool:
    if not limit_chase_enabled():
        return False
    if not signal.get("virtual_chase_state"):
        return False
    lane = signal.get("research_lane")
    if not is_virtual_chase_entry_lane(lane):
        return False
    direction = str(signal.get("final_direction") or "").upper()
    if direction not in ("LONG", "SHORT"):
        return False
    created = float(signal.get("order_created_ts") or signal.get("created_ts_ts") or 0)
    if not created:
        return False
    age_sec = now - created
    if age_sec < LIMIT_CHASE_HOLD_SEC:
        return False
    chase_start = float(signal.get("chase_start_sec") or get_limit_chase_start_sec())
    if age_sec < chase_start:
        return False
    if not _chase_structure_valid(direction):
        return False
    if age_sec > LIMIT_ORDER_MAX_AGE_SEC:
        return False
    last_chase = signal.get("last_chase_ts")
    if last_chase and (now - float(last_chase)) < get_limit_chase_interval_sec():
        return False
    limit_price = float(signal.get("limit_price") or signal.get("planned_limit_price") or 0)
    if limit_price <= 0 or price <= 0:
        return False
    if _limit_chase_near_fill_zone(direction, limit_price, price):
        return False
    return True


def _virtual_chase_lane_chase_on_order(order: dict, signal: dict, price: float, now: float) -> bool:
    """Virtual Chase lane — intercept global chase counter on resting limits."""
    lane = order.get("research_lane") or (signal or {}).get("research_lane")
    if not is_virtual_chase_entry_lane(lane):
        return False
    if order.get("virtual_chase_6_wait_until"):
        return True
    current = int(order.get("limit_chase_count") or (signal or {}).get("limit_chase_count") or 0)
    age_sec = _order_signal_age_sec(order, signal or {}, now)
    next_count = chase_age_window_index(age_sec)
    if next_count < current:
        next_count = current
    if chase_age_window_should_cancel(age_sec):
        _cancel_pending_for_chase_gate(order, f"CHASE_BUCKET_{chase_count_bucket(next_count)}")
        return True
    if not chase_age_window_may_reprice(age_sec):
        return True
    direction = _normalize_order_side_to_dir(order.get("signal_dir") or order.get("side"))
    old_limit = float(order.get("limit_price") or 0)
    original = float(order.get("original_limit_price") or order.get("planned_limit_price") or old_limit)
    new_limit, reason = _compute_limit_chase_target(direction, old_limit, float(price), original)
    if next_count == 1:
        if reason != "LIMIT_CHASE" or abs(new_limit - old_limit) < 0.01:
            return False
        return _pull_order_to_virtual_chase(signal, order, new_limit, next_count, now)
    if next_count in (4, 5):
        return _apply_limit_chase(order, signal, price, now)
    if next_count == 6:
        order["limit_chase_count"] = 6
        order["last_chase_ts"] = now
        order["virtual_chase_6_wait_until"] = now + VIRTUAL_CHASE_LANE_CHASE6_WAIT_SEC
        order["virtual_chase_6_wait_started"] = now
        if signal:
            signal["limit_chase_count"] = 6
            signal["last_chase_ts"] = now
            signal["virtual_chase_6_wait_until"] = order["virtual_chase_6_wait_until"]
            signal["market_conversion_delay"] = VIRTUAL_CHASE_LANE_CHASE6_WAIT_SEC
            signal["fill_phase"] = _virtual_chase_fill_phase(6, waiting=True)
            _record_virtual_chase_execution_metrics(signal, order)
        logger.info(
            f"[VIRTUAL_CHASE] chase=6 trade_id={order.get('trade_id')} "
            f"60s wait before market conversion [PIPELINE ENFORCEMENT]"
        )
        return True
    if next_count > 6:
        return False
    return _apply_limit_chase(order, signal, price, now)


def process_virtual_chase_lane_virtual_signals(price: float):
    """Chase 2 (and virtual ticks) — update hidden limit, relive at chase 3."""
    if not limit_chase_enabled() or price is None or price <= 0:
        return
    now = time.time()
    with trade_lock:
        virtual_signals = [
            (entry.get("signal_ref") or {})
            for entry in trades_map.values()
            if isinstance(entry.get("signal_ref"), dict)
            and entry["signal_ref"].get("status") == SIGNAL_STATUS_VIRTUAL_CHASE
            and entry["signal_ref"].get("virtual_chase_state")
            and is_virtual_chase_entry_lane(entry["signal_ref"].get("research_lane"))
            and not is_terminal_signal(entry["signal_ref"])
        ]
    for signal in virtual_signals:
        tid = signal.get("trade_id")
        if not tid or not _virtual_chase_signal_eligible(signal, float(price), now):
            continue
        current = int(signal.get("limit_chase_count") or 0)
        age_sec = _signal_age_sec(signal)
        next_count = chase_age_window_index(age_sec)
        if next_count < current:
            next_count = current
        if not chase_age_window_may_reprice(age_sec):
            continue
        direction = str(signal.get("final_direction") or "").upper()
        old_limit = float(signal.get("limit_price") or signal.get("planned_limit_price") or 0)
        original = float(signal.get("original_limit_price") or signal.get("planned_limit_price") or old_limit)
        new_limit, reason = _compute_limit_chase_target(direction, old_limit, float(price), original)
        if reason != "LIMIT_CHASE" or abs(new_limit - old_limit) < 0.01:
            continue
        signal["limit_price"] = round(float(new_limit), 2)
        signal["planned_limit_price"] = signal["limit_price"]
        signal["limit_chase_count"] = next_count
        signal["last_chase_ts"] = now
        if next_count == 2:
            signal["fill_phase"] = _virtual_chase_fill_phase(2, virtual=True)
            _record_virtual_chase_execution_metrics(signal)
            logger.info(
                f"[VIRTUAL_CHASE] chase=2 trade_id={tid} still hidden limit={fmt(new_limit)} "
                f"[PIPELINE ENFORCEMENT]"
            )
            continue
        if next_count == 3:
            signal["virtual_chase_state"] = False
            signal["visible_chase_since_ts"] = now
            signal["status"] = "PENDING"
            signal["fill_phase"] = _virtual_chase_fill_phase(3)
            _record_virtual_chase_execution_metrics(signal)
            logger.info(
                f"[VIRTUAL_CHASE] chase=3 trade_id={tid} relive limit={fmt(new_limit)} "
                f"[PIPELINE ENFORCEMENT]"
            )
            _place_simulated_limit_order(signal, signal["limit_price"], signal.get("entry_mode") or ENTRY_MODE_AI_DIRECT)
            pipeline_state_sync()


def process_virtual_chase_chase6_market_conversions(price: float):
    """Chase 6 — after 60s unfilled, cancel limit and market in."""
    if price is None or price <= 0:
        return
    now = time.time()
    with trade_lock:
        waiting = [
            o for o in list(pending_orders)
            if isinstance(o, dict)
            and o.get("status") == "PENDING"
            and o.get("virtual_chase_6_wait_until")
            and is_virtual_chase_entry_lane(o.get("research_lane"))
        ]
    for order in waiting:
        until = float(order.get("virtual_chase_6_wait_until") or 0)
        if until <= 0 or now < until:
            continue
        tid = order.get("trade_id")
        meta = trades_map.get(tid, {})
        signal = meta.get("signal_ref") or {}
        limit_price = float(order.get("limit_price") or 0)
        fill_px = resolve_sim_fill_price(order)
        slippage = None
        if limit_price > 0 and fill_px:
            direction = _normalize_order_side_to_dir(order.get("signal_dir") or order.get("side"))
            if direction == "LONG":
                slippage = round(float(fill_px) - limit_price, 4)
            elif direction == "SHORT":
                slippage = round(limit_price - float(fill_px), 4)
        order["entry_type"] = "SIM_MARKET"
        order["fee_type"] = "TAKER"
        order["fill_price"] = fill_px
        order["limit_price"] = fill_px
        order["market_conversion"] = True
        if signal:
            signal["market_conversion"] = True
            signal["conversion_slippage"] = slippage
            signal["market_conversion_delay"] = VIRTUAL_CHASE_LANE_CHASE6_WAIT_SEC
            signal["fill_phase"] = _virtual_chase_fill_phase(6, market=True)
            _record_virtual_chase_execution_metrics(signal, order)
        logger.info(
            f"[VIRTUAL_CHASE] chase=6 market conversion trade_id={tid} "
            f"limit={fmt(limit_price)} fill={fmt(fill_px)} slip={slippage} [PIPELINE ENFORCEMENT]"
        )
        fill_order(order)


def get_effective_ai_cooldown_sec(lane: str = None) -> int:
    """Research collection uses shorter periodic interval; live keeps AI_COOLDOWN_SECONDS."""
    if _sole_ai_research_mode() and is_research_data_collection():
        return get_research_ai_cooldown_sec(lane or RESEARCH_LANE_CONTINUOUS)
    return AI_COOLDOWN_SECONDS


def ai_cooldown_remaining_sec(lane: str = None) -> int:
    cd = get_effective_ai_cooldown_sec(lane)
    with state_lock:
        if research_isolation_enabled() and lane:
            last_map = state.get("lane_last_ai_call_ts") or {}
            last = float(last_map.get(str(lane).upper(), 0) or 0)
        else:
            last = float(state.get("last_ai_call_ts") or 0)
    return max(0, int(cd - (time.time() - last)))


def reserve_ai_cooldown_slot(lane: str = RESEARCH_LANE_CONTINUOUS) -> tuple:
    """Atomically claim DeepSeek slot immediately before any API call."""
    lane = str(lane or RESEARCH_LANE_CONTINUOUS).upper()
    cd = get_effective_ai_cooldown_sec(lane)
    with state_lock:
        now = time.time()
        if research_isolation_enabled():
            last_map = state.setdefault("lane_last_ai_call_ts", {})
            last = float(last_map.get(lane, state.get("last_ai_call_ts", 0)) or 0)
        else:
            last = float(state.get("last_ai_call_ts") or 0)
        if now - last < cd:
            rem = int(cd - (now - last))
            return False, f"AI_COOLDOWN_{rem}s"
        if research_isolation_enabled():
            state.setdefault("lane_last_ai_call_ts", {})[lane] = now
        state["last_ai_call_ts"] = now
        state["debug_state"]["ai_cooldown_active"] = True
        state["debug_state"]["cooldown_remaining_ai"] = cd
    return True, "RESERVED"

def should_invoke_ai(ctx: dict, edge_score: float, event_trigger: bool) -> tuple:
    """Final non-Edge gate before the single direction AI call."""
    if state.get("force_ai_every_signal"):
        return True, "FORCE_AI"
    if _sole_ai_research_mode():
        if not shared_research_ai_observation_enabled():
            return False, "RESEARCH_OBSERVATION_DISABLED"
        if ai_cooldown_remaining_sec() > 0:
            return False, f"AI_COOLDOWN_{ai_cooldown_remaining_sec(RESEARCH_LANE_AI_SCAN)}s"
        rq = compute_research_quality_score(ctx)
        if rq < RESEARCH_QUALITY_MIN:
            return False, f"RESEARCH_QUALITY_{rq:.0f}"
        with state_lock:
            state["debug_state"]["research_quality_score"] = rq
        return True, "PERIODIC_RESEARCH_AI"
    if ai_cooldown_remaining_sec() > 0:
        return False, f"AI_COOLDOWN_{ai_cooldown_remaining_sec()}s"
    if not event_trigger:
        return False, "NO_PERIODIC_TRIGGER"
    return True, "PERIODIC_DIRECTION_AI"

def compute_ret_1m():
    if len(price_buffer) < 2:
        return 0.0
    return (price_buffer[-1] - price_buffer[-2]) / price_buffer[-2] if price_buffer[-2] != 0 else 0.0

def compute_ret_5m():
    if len(price_buffer) < 20:
        return 0.0
    return (price_buffer[-1] - price_buffer[-20]) / price_buffer[-20] if price_buffer[-20] != 0 else 0.0

def populate_candle_buffers_from_candles(candles, *, force=False):
    if not force and len(candle_range_buffer) >= WINDOW_SIZE:
        return 0
    populated = 0
    for candle in candles:
        try:
            o = candle[1]
            h = candle[2]
            l = candle[3]
            c = candle[4]
            candle_range = h - l
            if candle_range <= 0:
                continue
            body = abs(c - o)
            wick = candle_range - body
            body_ratio = body / candle_range
            wick_ratio = wick / candle_range
            candle_range_buffer.append(candle_range)
            body_ratio_buffer.append(body_ratio)
            wick_ratio_buffer.append(wick_ratio)
            populated += 1
        except Exception as e:
            logger.error(f"[CANDLE BUFFER PRELOAD ERROR] {e} [PIPELINE ENFORCEMENT]")
    logger.info(f"[CANDLE BUFFER PRELOAD] populated {populated} candles into buffers [PIPELINE ENFORCEMENT]")
    return populated

def compute_volume_ratio():
    if len(volume_buffer) < 1:
        return 0.0
    vol_mean = np.mean(list(volume_buffer)[-50:]) if len(volume_buffer) > 50 else np.mean(list(volume_buffer))
    if vol_mean <= 0:
        return 0.0
    current = volume_buffer[-1]
    return float(current / vol_mean)

def update_candle_features():
    global last_processed_candle_ts
    try:
        if len(latest_candles) < 1:
            logger.debug("[CANDLE] No candles yet - skipping buffer fill [PIPELINE ENFORCEMENT]")
            return
        candle = latest_candles[-1]
        candle_ts = candle[0]
        if candle_ts == last_processed_candle_ts:
            _agent_dbg("H5", "update_candle_features", "dedupe_skip", {"candle_ts": candle_ts})
            return
        last_processed_candle_ts = candle_ts
        high = candle[2]
        low = candle[3]
        open_p = candle[1]
        close = candle[4]
        candle_range = high - low
        body = abs(close - open_p)
        wick = candle_range - body
        body_ratio = body / candle_range if candle_range > 0 else 0.0
        wick_ratio = wick / candle_range if candle_range > 0 else 0.0
        candle_range_buffer.append(candle_range)
        body_ratio_buffer.append(body_ratio)
        wick_ratio_buffer.append(wick_ratio)
        logger.info(f"[CANDLE BUFFER LIVE UPDATE] range={candle_range:.4f} body_ratio={body_ratio:.4f} wick_ratio={wick_ratio:.4f} [PIPELINE ENFORCEMENT]")
    except Exception as e:
        logger.error(f"[CANDLE BUFFER ERROR] {e} [PIPELINE ENFORCEMENT]")

def build_full_feature_snapshot():
    if not is_buffer_ready():
        logger.warning("[BUFFER] Not enough data for stable features - skipping [PIPELINE ENFORCEMENT]")
        return None
    try:
        logger.info("[FEATURE BUILD] Starting aggregated feature construction with WINDOW=10 [PIPELINE ENFORCEMENT]")
        update_candle_features()
        # A WS snapshot can legitimately warm every analytical buffer before
        # the first genuine live trade tick authorizes a strategy price. Keep
        # that fail-closed state quiet and explicit instead of comparing None
        # with zero and emitting a misleading FEATURE BUILD ERROR on every
        # periodic pass.
        price = nz(state.get("price"), 0.0)
        if price <= 0:
            logger.warning("[FEATURE BUILD] price <=0 [PIPELINE ENFORCEMENT]")
            return None
        ema_status = state.get("ema_status", {})
        sr = state.get("support_resistance", {})
        volume_ratio = compute_volume_ratio()
        velocity = (price_buffer[-1] - price_buffer[-10]) / price_buffer[-10] if len(price_buffer) > 10 else 0.0
        delta = get_sum(delta_buffer)
        imbalance = get_aggregated(imbalance_buffer)
        candle = latest_candles[-1] if len(latest_candles) > 0 else None
        if candle:
            candle_range = candle[2] - candle[3]
            body_ratio = abs(candle[4] - candle[1]) / candle_range if candle_range > 0 else 0.0
            wick_ratio = (candle[2] - max(candle[1], candle[4])) / candle_range if candle_range > 0 else 0.0
        else:
            candle_range = 0.0
            body_ratio = 0.0
            wick_ratio = 0.0
        vol_agg = nz(get_aggregated(volume_buffer), 0.0)
        delta_agg = nz(get_aggregated(delta_buffer), 0.0)
        velocity_agg = nz(get_aggregated(velocity_buffer), 0.0)
        imbalance_agg = nz(get_aggregated(imbalance_buffer), 0.0)
        candle_range_agg = nz(get_aggregated(candle_range_buffer), 0.0)
        body_ratio_agg = nz(get_aggregated(body_ratio_buffer), 0.0)
        wick_ratio_agg = nz(get_aggregated(wick_ratio_buffer), 0.0)
        features = {
            "price": price,
            "ret_1m": compute_ret_1m(),
            "ret_5m": compute_ret_5m(),
            "ema9": nz(ema_status.get("ema9")),
            "ema21": nz(ema_status.get("ema21")),
            "ema200": nz(ema_status.get("ema200")),
            "dist_to_support": nz(sr.get("dist_to_support")),
            "dist_to_resistance": nz(sr.get("dist_to_resistance")),
            "volume": vol_agg,
            "volume_ratio": volume_ratio,
            "delta": delta_agg,
            "velocity": velocity_agg,
            "imbalance": imbalance_agg,
            "candle_range": candle_range_agg,
            "body_ratio": body_ratio_agg,
            "wick_ratio": wick_ratio_agg
        }
        with state_lock:
            market_context = copy.deepcopy(state.get("market_context") or {})
        indicators = normalize_market_indicators(
            features=features,
            market_context=market_context,
            candles=copy.deepcopy(latest_candles),
        )
        features.update({
            "ema_slope": (
                (float(features.get("ema9")) - float(features.get("ema21"))) / float(features.get("ema21"))
                if features.get("ema21") not in (None, 0) else None
            ),
            "adx": indicators.get("adx"),
            "adx_normalized": indicators.get("adx"),
            "adx_source": indicators.get("adx_source"),
            "adx_derived": indicators.get("adx_derived"),
            "adx_slope_3": indicators.get("adx_slope_3"),
            "plus_di": indicators.get("plus_di"),
            "minus_di": indicators.get("minus_di"),
            "di_separation": indicators.get("di_separation"),
            "dmi_source": indicators.get("dmi_source"),
            "dmi_period": indicators.get("dmi_period"),
            "volatility_percentile": indicators.get("volatility_percentile"),
            "volatility_atr": indicators.get("atr"),
            "volatility_source": indicators.get("volatility_source"),
            "volume_percentile": indicators.get("volume_percentile"),
            "volume_percentile_source": indicators.get("volume_percentile_source"),
            "indicator_normalization_version": indicators.get("indicator_normalization_version"),
            "research_feature_schema_version": indicators.get("research_feature_schema_version"),
        })
        with state_lock:
            state["feature_snapshot"] = features
        logger.info(f"[FEATURE BUILD] complete - keys: {list(features.keys())} price={price:.2f} volume={vol_agg:.4f} velocity={velocity_agg:.6f} volume_ratio={features['volume_ratio']:.4f} candle_range={candle_range_agg:.4f} body_ratio={body_ratio_agg:.4f} wick_ratio={wick_ratio_agg:.4f} [PIPELINE ENFORCEMENT]")
        return features
    except Exception as e:
        logger.error(f"[FEATURE BUILD ERROR] {e} [PIPELINE ENFORCEMENT]")
        return None

def validate_feature_completeness(features):
    if features is None:
        return False
    required = ["ret_1m", "ema9", "dist_to_support"]
    missing = [k for k in required if features.get(k) is None]
    if missing:
        logger.info(f"[EDGE BLOCK SOFT] incomplete features: {missing} - continuing with partial [PIPELINE ENFORCEMENT]")
        return False
    return True

def is_valid_feature_set(features):
    if features is None:
        logger.info("[FEATURE VALIDATION] BAD_FEATURE_QUALITY features=None [PIPELINE ENFORCEMENT]")
        return False
    required_values = (
        "price", "ret_1m", "ret_5m", "ema9", "ema21", "ema200",
        "dist_to_support", "dist_to_resistance", "volume", "volume_ratio",
        "delta", "velocity", "imbalance", "candle_range", "body_ratio", "wick_ratio",
    )
    if any(features.get(key) is None for key in required_values):
        logger.info("[FEATURE VALIDATION] BAD_FEATURE_QUALITY required None values present [PIPELINE ENFORCEMENT]")
        return False
    if features.get("volume", 0) < 0.01:
        logger.warning("[FEATURE VALIDATION] LOW_VOLUME_ENV - continuing for research [PIPELINE ENFORCEMENT]")
        return True
    if abs(features.get("velocity", 0)) < 1e-5:
        logger.warning("[FEATURE VALIDATION] LOW_VELOCITY_ENV - continuing for research [PIPELINE ENFORCEMENT]")
        return True
    return True

def compute_edge_score(features: dict = None) -> float:
    try:
        global last_edge_compute
        now = time.time()
        if now - last_edge_compute < EDGE_INTERVAL_SEC:
            logger.debug(f"[EDGE CLOCK] skipped compute - {now - last_edge_compute:.1f}s since last - reusing last_edge [PIPELINE ENFORCEMENT]")
            return round(state.get("last_edge", 0.1), 1)
        last_edge_compute = now
        logger.info("[EDGE] compute_edge_score started with explicit features (30s enforced) [PIPELINE ENFORCEMENT]")
        if features is None:
            features = build_full_feature_snapshot()
        if features is None or not validate_feature_completeness(features):
            logger.info("[FEATURE VALIDATION] partial - proceeding with penalties [PIPELINE ENFORCEMENT]")
            return 0.1
        with state_lock:
            dq = state.get("data_quality", 0.0)
        if dq < MIN_DATA_QUALITY_FOR_EDGE:
            logger.info(f"[EDGE] data_quality={dq:.2f} < {MIN_DATA_QUALITY_FOR_EDGE} - no edge score [PIPELINE ENFORCEMENT]")
            return 0.1
        price = nz(state.get("price"))
        if price <= 0:
            logger.warning("[EDGE] price <=0 - returning floor 0.1 [PIPELINE ENFORCEMENT]")
            return 0.1
        dist_to_support = nz(features.get("dist_to_support", 1))
        dist_to_resistance = nz(features.get("dist_to_resistance", 1))
        ema9 = nz(features.get("ema9", 0))
        ema21 = nz(features.get("ema21", 0))
        ema200 = nz(features.get("ema200", 0))
        ret_1m_raw, ret_5m_raw, velocity_raw = _signed_momentum_components(features)
        volume = nz(features.get("volume", 0))
        volume_ratio = nz(features.get("volume_ratio", 0))
        delta = abs(nz(features.get("delta", 0)))
        if volume < 0.01:
            logger.info("[EDGE] low volume - soft penalty [PIPELINE ENFORCEMENT]")
            volume_ratio *= 0.3
        update_market_context()
        with state_lock:
            mc = copy.deepcopy(state.get("market_context", {}))
        ms = mc.get("market_structure", {})
        mtf = mc.get("multi_tf", {})
        ts = mc.get("trend_strength", {})
        struct_score = abs(ms.get("structure_score", 0))
        structure_component = min(1.0, struct_score / 6.0) * 1.5
        mtf_aligned = max(mtf.get("bull_tf_count", 0), mtf.get("bear_tf_count", 0))
        mtf_component = (mtf_aligned / 3.0) * 1.2
        if mtf.get("agreement") == "CONFLICTED":
            mtf_component *= 0.35
        adx = ts.get("adx") or 0
        if ema9 > ema21 > ema200 or ema9 < ema21 < ema200:
            ema_trend_component = 1.0
        else:
            ema_trend_component = 0.35
        trend_component = ema_trend_component + (0.25 if adx >= 25 else 0.0)
        agreement = str(mtf.get("agreement", ""))
        struct_score_raw = float(ms.get("structure_score") or 0)
        pref_dir = None
        if agreement == "BEAR_ALIGNED" or struct_score_raw <= -3:
            pref_dir = "SHORT"
        elif agreement == "BULL_ALIGNED" or struct_score_raw >= 3:
            pref_dir = "LONG"

        def _aligned_momentum(val, scale):
            if pref_dir == "SHORT":
                return max(0.0, -val) * scale
            if pref_dir == "LONG":
                return max(0.0, val) * scale
            return abs(val) * scale

        momentum_raw = max(
            _aligned_momentum(ret_1m_raw, 5000),
            _aligned_momentum(ret_5m_raw, 2000),
            _aligned_momentum(velocity_raw, 8000),
        )
        momentum_component = min(momentum_raw, 1.0) * 1.0
        momentum_misalign_penalty = 0.0
        if pref_dir == "SHORT" and _tape_bounce_against("SHORT", features):
            momentum_misalign_penalty = min(0.6, ret_1m_raw * 8000 + max(0.0, ret_5m_raw) * 3000)
        elif pref_dir == "LONG" and _tape_bounce_against("LONG", features):
            momentum_misalign_penalty = min(0.6, abs(ret_1m_raw) * 8000 + max(0.0, -ret_5m_raw) * 3000)
        flow_component = min(volume_ratio, 1.0) * min(delta / 50, 1.0) * 1.0
        sr_near = dist_to_support < 0.02 or dist_to_resistance < 0.02
        sr_component = 0.6 if sr_near else 0.15
        edge_score = (
            structure_component +
            mtf_component +
            trend_component +
            momentum_component +
            flow_component +
            sr_component
        )
        chop_penalty = 0.0
        if mtf.get("agreement") == "CONFLICTED":
            chop_penalty += EDGE_CHOP_CONFLICTED_PENALTY
        sr_state = str((state.get("support_resistance") or {}).get("sr_state", "")).upper()
        if "COMPRESSION" in sr_state:
            chop_penalty += EDGE_CHOP_COMPRESSION_PENALTY
        if adx < PRE_AI_MIN_ADX:
            chop_penalty += 0.25
        edge_score = edge_score - chop_penalty - momentum_misalign_penalty
        edge_score = max(0.1, min(edge_score, EDGE_SCORE_MAX))
        edge_score = round(edge_score, 1)
        eff_thr = get_effective_edge_threshold()
        with state_lock:
            state["last_edge"] = edge_score
            state["debug_state"]["last_edge_score"] = edge_score
            state["debug_state"]["edge_components"] = {
                "structure": round(structure_component, 2),
                "mtf": round(mtf_component, 2),
                "trend": round(trend_component, 2),
                "momentum": round(momentum_component, 2),
                "flow": round(flow_component, 2),
                "sr_context": round(sr_component, 2),
                "chop_penalty": round(chop_penalty, 2),
                "momentum_misalign_penalty": round(momentum_misalign_penalty, 2),
                "effective_threshold": eff_thr,
            }
            state["debug_state"]["edge_progress"] = (
                f"{edge_score:.1f}/{eff_thr:.1f} (max {EDGE_SCORE_MAX:.1f})"
            )
            state["debug_state"]["edge_reason"] = "OK" if edge_score > 0.5 else "LOW"
        logger.info(f"[EDGE] compute_edge_score completed edge={edge_score:.1f} reason={state['debug_state']['edge_reason']} [PIPELINE ENFORCEMENT]")
        enforce_edge_threshold_options()
        update_debug_state_always("EDGE_DONE", {"edge": edge_score})
        return edge_score
    except Exception as e:
        logger.error(f"[EDGE SCORE ERROR] {e} [PIPELINE ENFORCEMENT]")
        return 0.1

def _fresh_debug_state():
    return {
        "last_event_time": None,
        "last_edge_score": 0,
        "last_flags": {},
        "last_trigger": False,
        "last_signal_attempt": None,
        "last_block_reason": None,
        "last_ai_call": None,
        "last_ai_decision": None,
        "last_ai_score": None,
        "signal_cooldown_active": False,
        "ai_cooldown_active": False,
        "cooldown_remaining_signal": 0,
        "cooldown_remaining_ai": 0,
        "last_pipeline_stage": None,
        "system_last_tick": None,
        "engine_last_run": None,
        "last_check_time": None,
        "skip_reason": None,
        "edge_progress": None,
        "ai_gate": {"called": False, "reason": "", "edge": 0.0, "threshold": 0.0},
        "edge_reason": "UNKNOWN",
        "edge_trigger_reason": None,
        "pipeline_event_trigger": None,
        "edge_above_threshold": False,
    }

def _ai_gate_was_called(debug_state: dict) -> bool:
    return bool(((debug_state or {}).get("ai_gate") or {}).get("called"))

def _is_misleading_ai_skip_label(label) -> bool:
    """Labels that imply DeepSeek ran when ai_gate.called is false."""
    if label is None:
        return False
    s = str(label).strip().upper()
    if not s or s in ("-", "OK", "UNKNOWN"):
        return False
    if s.startswith("EDGE_") or s.startswith("PRE_AI_"):
        return False
    if s in (
        "EDGE_FAIL", "DUPLICATE", "DUPLICATE_KEY", "CTX_FAIL", "NO_PRICE",
        "CLUSTER_ENTRY", "MAX_ACTIVE_SIGNALS", "GLOBAL_COOLDOWN",
    ):
        return False
    if s.startswith("AI_"):
        return True
    return s in {"REJECT", "AI_REJECT", "AI_REJECTED", "BELOW_THRESHOLD", "AI_FAIL"}

def _dashboard_idle_gate_reason(debug_state: dict) -> str:
    dbg = debug_state or {}
    if _sole_ai_research_mode():
        reason = (
            dbg.get("pipeline_idle_reason")
            or dbg.get("skip_reason")
            or dbg.get("last_block_reason")
        )
        if reason and not str(reason).startswith(("EDGE_", "NO_EDGE")):
            return str(reason)
        return "WAITING_FOR_PERIODIC_DIRECTION_SCAN"
    reason = dbg.get("edge_trigger_reason") or dbg.get("edge_reason")
    if reason and str(reason) not in ("OK", "UNKNOWN", ""):
        return str(reason)
    edge = dbg.get("last_edge_score")
    try:
        eff = (dbg.get("edge_components") or {}).get("effective_threshold")
        if eff is None:
            eff = get_effective_edge_threshold()
    except Exception:
        eff = get_edge_threshold()
    if edge is not None and eff is not None:
        return f"EDGE_WAIT ({float(edge):.1f} / {float(eff):.1f})"
    return "WAITING_FOR_EDGE"

def _dashboard_skip_block(debug_state: dict, last_ai: dict = None) -> tuple:
    """Map skip/block to the real gate when DeepSeek was not invoked this cycle."""
    dbg = debug_state or {}
    la = last_ai or {}
    idle = dbg.get("pipeline_idle_reason") or dbg.get("edge_trigger_reason")
    skip = dbg.get("skip_reason")
    block = dbg.get("last_block_reason")
    if _ai_gate_was_called(dbg):
        la_dec = la.get("decision")
        idle_label = idle or skip or "PIPELINE_IDLE"
        if la_dec in ("APPROVE", "STRONG_APPROVE", "SOFT_APPROVE") and str(idle_label).startswith("AI_COOLDOWN"):
            return idle_label, f"AI_{la_dec} — waiting next slot (not rejected)"
        if la_dec == "REJECT" and str(idle_label).startswith("AI_COOLDOWN"):
            return idle_label, f"AI_REJECTED — waiting next slot"
        return idle_label or skip or "-", block or idle_label or "-"
    if skip and not _is_misleading_ai_skip_label(skip):
        return skip, block or skip
    if block and not _is_misleading_ai_skip_label(block):
        return skip or block, block
    idle_reason = _dashboard_idle_gate_reason(dbg)
    return idle_reason, idle_reason

def build_dashboard_display(snapshot: dict) -> dict:
    """Server-side labels for dashboard (avoids stale AI_REJECT / Bybit-era copy)."""
    dbg = snapshot.get("debug_state") or {}
    ag = dbg.get("ai_gate") or {}
    la = snapshot.get("last_ai") or {}
    sk, bl = _dashboard_skip_block(dbg, la)
    current_pause = bool(
        snapshot.get("manual_admin_pause")
        or snapshot.get("execution_paused")
    )
    stale_pause_labels = {
        "MANUAL_PAUSE",
        "ADMIN_MANUAL_PAUSE",
        "ADMIN_MANUAL_PAUSED_SHADOW",
    }
    # debug_state is a last-cycle receipt and may legitimately retain the
    # reason from a cycle that ran while paused. It must not be presented as
    # current control authority after /api/resume has cleared the pause.
    if not current_pause and (
        str(sk or "").upper() in stale_pause_labels
        or str(bl or "").upper() in stale_pause_labels
    ):
        sk = "WAITING_FOR_PERIODIC_DIRECTION_SCAN"
        bl = "ALLOWED — prior manual-pause receipt is historical"
    symbol = BITFINEX_WS_SYMBOL
    if _ai_gate_was_called(dbg):
        dec = la.get("decision") or snapshot.get("ai_outcome") or "UNKNOWN"
        if dec == "AI_ERROR":
            ai_status = "AI_ERROR"
            err_note = (la.get("error_detail") or la.get("reason") or la.get("comment") or "DeepSeek API/parse failure")[:400]
            if "MISSING_API_KEY" in err_note or "MISSING_API_KEY" in str(la.get("error_type") or ""):
                err_note = "MISSING_API_KEY — add DEEPSEEK_API_KEY to Final Bots\\.env and restart"
            good = snapshot.get("last_ai_best") or _pick_dashboard_last_ai({"last_ai": {}}, snapshot.get("ai_history") or [])
            if good.get("decision") not in (None, "", "AI_ERROR", "UNKNOWN"):
                ai_note = f"{err_note} | Last OK: {good.get('decision')} {good.get('win_prob')}% ({good.get('direction')})"
            else:
                ai_note = err_note
        else:
            ai_status = dec
            ai_note = "DeepSeek evaluated this pipeline cycle"
        ai_prob = la.get("win_prob") if dec != "AI_ERROR" else None
    else:
        ai_status = "NO_AI_CALL"
        ai_note = f"No DeepSeek call — {sk}"
        ai_prob = None
        if la.get("decision") and la.get("source") in ("CSV", "FRESH", "AI"):
            ai_note += f" (table below may show prior call: {la.get('decision')})"
    pipeline_idle = dbg.get("pipeline_idle_reason") or dbg.get("edge_trigger_reason")
    funnel = dict(snapshot.get("pipeline_funnel_counters") or {})
    edge_thr_ui = snapshot.get("edge_threshold")
    edge_eff = (dbg.get("edge_components") or {}).get("effective_threshold")
    if _sole_ai_research_mode():
        edge_gate_note = "sole-AI research: edge gate = >0 (dashboard threshold is telemetry only)"
    else:
        edge_gate_note = f"edge gate min = {edge_eff if edge_eff is not None else edge_thr_ui}"
    return {
        "display_skip_block": {"skip": sk, "block": bl},
        "display_ai": {
            "status": ai_status,
            "win_prob": ai_prob,
            "note": ai_note,
            "gate_called": bool(ag.get("called")),
            "last_decision": la.get("decision"),
            "last_direction": la.get("direction"),
            "pipeline_idle": pipeline_idle,
            "research_lane": la.get("research_lane"),
            "research_model": la.get("research_model") or research_lane_label(la.get("research_lane")),
        },
        "display_pipeline": {
            "idle_reason": pipeline_idle,
            "edge_gate_note": edge_gate_note,
            "funnel": funnel,
            "isolation_mode": research_isolation_enabled(),
            "lane_opportunity": dict(snapshot.get("lane_opportunity_counters") or {}),
        },
        "exchange_label": "Bitfinex",
        "market_symbol": symbol,
        "data_banner_ws": f"REAL BITFINEX MARKET DATA (WS) · {symbol}",
        "data_banner_rest": f"BITFINEX REST FALLBACK · {symbol}",
        "data_banner_boot": f"BITFINEX CONNECTING · {symbol}",
    }

def sync_dashboard_branding():
    """Keep exchange/banner fields on state so /api/state is never Bybit-stale."""
    try:
        with state_lock:
            snap = {
                "debug_state": copy.deepcopy(state.get("debug_state") or {}),
                "last_ai": copy.deepcopy(state.get("last_ai") or {}),
                "ai_outcome": state.get("ai_outcome"),
            }
        branding = build_dashboard_display(snap)
        with state_lock:
            state.update(branding)
    except Exception as e:
        logger.debug(f"[DASHBOARD BRANDING] {e}")

def update_debug_state_always(stage=None, extra=None, *args, **kwargs):
    try:
        with state_lock:
            if stage:
                state["debug_state"]["last_pipeline_stage"] = stage
            state["debug_state"]["last_event_time"] = utc_iso()
            if extra:
                state["debug_state"].update(extra)
            if args or kwargs:
                logger.debug(f"[DEBUG STATE] extra args absorbed: args={len(args)} kwargs={len(kwargs)} [PIPELINE ENFORCEMENT]")
            logger.info(f"[DEBUG STATE UPDATE] stage={stage} edge={state['debug_state'].get('last_edge_score',0)} pipeline={state['last_pipeline_stage']} [PIPELINE ENFORCEMENT]")
    except Exception as e:
        logger.error(f"[DEBUG STATE ERROR] {e} [PIPELINE ENFORCEMENT]")

def reset_all_csv():
    logger.warning("[RESET] Deleting all CSV files for fresh session [PIPELINE ENFORCEMENT]")
    files = [
        CSV_DECISIONS, CSV_TRADES, CSV_EXPIRED, CSV_BLOCKS, CSV_AI_TRANCHE, CSV_SETUP_LOG, CSV_CANDLES,
        CSV_PIPELINE_EVENTS, CSV_AI_ERRORS,
    ]
    for f in files:
        try:
            if os.path.exists(f):
                os.remove(f)
                logger.info(f"[RESET] Deleted {f} [PIPELINE ENFORCEMENT]")
        except Exception as e:
            logger.error(f"[RESET ERROR] Failed to delete {f}: {e} [PIPELINE ENFORCEMENT]")

def update_logger_level():
    try:
        console_level = logging.DEBUG if state.get("debug_enabled") else logging.INFO
        logger.setLevel(console_level)
        for h in logger.handlers:
            if isinstance(h, RotatingFileHandler):
                h.setLevel(logging.INFO)
            else:
                h.setLevel(console_level)
        logger.info(
            f"[LOGGER] console={logging.getLevelName(console_level)} "
            f"file=INFO rotate={LOG_MAX_BYTES // (1024*1024)}MB x{LOG_BACKUP_COUNT} [PIPELINE ENFORCEMENT]"
        )
    except Exception as e:
        logger.error(f"[LOGGER ERROR] {e} [PIPELINE ENFORCEMENT]")

CSV_WRITE_RETRIES = 8
CSV_WRITE_RETRY_BASE_SEC = 0.05
CSV_FALLBACK_JSONL = "csv_write_fallback.jsonl"


def _transient_csv_lock_error(exc: BaseException) -> bool:
    if isinstance(exc, PermissionError):
        return True
    if isinstance(exc, OSError):
        if getattr(exc, "errno", None) in (11, 13):
            return True
        if getattr(exc, "winerror", None) in (32, 33):
            return True
    return False


def _dynamic_csv_writer_once(filename, row):
    file_exists = os.path.exists(filename)
    if not file_exists:
        _atomic_write_csv_rows(filename, list(row.keys()), [safe_csv_row(row)])
        return
    with open(filename, "r", encoding="utf-8", errors="replace") as f:
        reader = csv.DictReader(f)
        existing = reader.fieldnames or []
    new_fields = list(set(existing) | set(row.keys()))
    if set(new_fields) != set(existing):
        with open(filename, "r", encoding="utf-8", errors="replace") as f:
            old_rows = list(csv.DictReader(f))
        _atomic_write_csv_rows(
            filename, new_fields, [*old_rows, safe_csv_row(row)],
        )
    else:
        with open(filename, "a", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=existing)
            writer.writerow(safe_csv_row(row))


def _atomic_write_csv_rows(filename, fieldnames, rows):
    """Publish CSV creation/schema expansion with an inode-changing replace."""
    target = os.path.abspath(filename)
    candidate = f"{target}.{os.getpid()}.{threading.get_ident()}.tmp"
    try:
        with open(candidate, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=list(fieldnames))
            writer.writeheader()
            writer.writerows(rows)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(candidate, target)
    finally:
        try:
            if os.path.exists(candidate):
                os.remove(candidate)
        except OSError:
            pass


def _csv_write_fallback(filename, row, err: BaseException) -> None:
    try:
        payload = {
            "ts": utc_iso(),
            "target": filename,
            "row": safe_csv_row(row),
            "error": str(err),
            "bot_version": EXECUTION_FIX_VERSION,
        }
        _safe_append_jsonl(
            CSV_FALLBACK_JSONL, payload, label="CSV_FALLBACK", fallback_on_error=False,
        )
    except Exception as fe:
        logger.error(f"[CSV FALLBACK FAILED] {fe} [PIPELINE ENFORCEMENT]")


def dynamic_csv_writer(filename, row):
    last_err = None
    with csv_lock:
        for attempt in range(CSV_WRITE_RETRIES):
            try:
                _dynamic_csv_writer_once(filename, row)
                if state.get("execution_reason") == "CSV_FAILURE":
                    set_execution_paused("")
                logger.info(
                    f"[CSV WRITE] {filename} row added - edge={row.get('edge_score', 'N/A')} "
                    f"experiment={row.get('experiment_tag', 'NONE')} stage={row.get('stage', 'N/A')} "
                    f"[PIPELINE ENFORCEMENT]"
                )
                return
            except Exception as e:
                last_err = e
                if attempt < CSV_WRITE_RETRIES - 1 and _transient_csv_lock_error(e):
                    time.sleep(CSV_WRITE_RETRY_BASE_SEC * (attempt + 1))
                    continue
                break
    logger.critical(
        f"[CSV WRITE FAILED] {filename} after {CSV_WRITE_RETRIES} tries: {last_err} "
        f"(fallback={CSV_FALLBACK_JSONL}) [PIPELINE ENFORCEMENT]"
    )
    _csv_write_fallback(filename, row, last_err)

def prune_signals():
    now = time.time()
    removed = 0
    with trade_lock:
        for t in list(trades_map.keys()):
            signal = trades_map[t].get("signal_ref", {})
            ts = signal.get("created_ts_ts", 0)
            if ts and now - ts > MAX_SIGNAL_RETENTION_SEC:
                trades_map.pop(t, None)
                removed += 1
    if removed > 0:
        logger.info(f"[PRUNE] Removed {removed} old signals [PIPELINE ENFORCEMENT]")

def _remove_pending_for_trade(trade_id: str, reason: str = "ORPHAN_CLEANUP"):
    if not trade_id:
        return False
    with trade_lock:
        matches = [
            order for order in list(pending_orders)
            if order.get("trade_id") == trade_id
            and str(order.get("status") or "").upper()
            in ("PENDING", "CANCEL_PENDING_LIVE")
        ]
    removed = 0
    for order in matches:
        outcome = _cancel_pending_order_confirmed(
            order,
            reason,
            record_expired=False,
            expire_signal=False,
        )
        if outcome.get("finalized"):
            removed += 1
            logger.info(
                f"[ORDER CLEANUP] Removed confirmed pending order "
                f"trade_id={trade_id} reason={reason} [PIPELINE ENFORCEMENT]"
            )
    return bool(removed)

def _funnel_signal_expired(signal_or_order: dict, reason: str = "SIGNAL_EXPIRED") -> None:
    try:
        from execution_funnel import funnel_on_signal_expire
        funnel_on_signal_expire(signal_or_order, reason)
    except Exception:
        pass


def reconcile_stale_signals():
    pending_ids = _pending_trade_ids()
    open_ids = _open_trade_ids()
    fixed = 0
    orphans_removed = 0
    now = time.time()
    expiry_records = []
    pending_removals = []
    pending_cancellations = []
    with trade_lock:
        for tid in open_ids:
            sig = trades_map.get(tid, {}).get("signal_ref", {}) or {}
            if not sig or is_terminal_signal(sig):
                continue
            if sig.get("outcome") != "OPEN":
                sig["outcome"] = "OPEN"
                fixed += 1
            if sig.get("status") in ("ORDERED", "ACTIVE", "PENDING", SIGNAL_STATUS_AWAITING_MICRO, SIGNAL_STATUS_AWAITING_5M, SIGNAL_STATUS_AWAITING_MIN_AGE, SIGNAL_STATUS_AWAITING_CHASE_3PLUS, SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE):
                sig["status"] = "FILLED"
                fixed += 1
        for s in trades_map.values():
            sig = s.get("signal_ref", {}) or {}
            tid = sig.get("trade_id")
            if not tid:
                continue
            st = sig.get("status")
            outcome = sig.get("outcome") or sig.get("exit_reason")
            if outcome in TERMINAL_SIGNAL_OUTCOMES and st not in TERMINAL_SIGNAL_STATUSES:
                sig["status"] = "EXPIRED"
                fixed += 1
                expiry_records.append((sig, outcome, False))
                pending_removals.append((tid, "OUTCOME_TERMINAL_SYNC"))
                continue
            created_ts = sig.get("created_ts_ts", 0)
            if created_ts and now - created_ts < ORDER_PLACEMENT_GRACE_SEC:
                continue
            expires_ts = sig.get("expires_ts") or (sig.get("created_ts_ts", 0) + SIGNAL_TTL_SEC)
            ttl_expired = expires_ts and now > expires_ts
            missing_exposure = tid not in pending_ids and tid not in open_ids
            promotion_at = float(sig.get("promotion_in_progress_at") or 0)
            promotion_in_progress = bool(
                sig.get("promotion_claim_token")
                and promotion_at > 0
                and now - promotion_at <= PROMOTION_IN_PROGRESS_GRACE_SEC
            )
            if st in ("ORDERED", "ACTIVE", "PENDING") and (missing_exposure or ttl_expired):
                if ttl_expired:
                    sig["status"] = "EXPIRED"
                    sig["outcome"] = "SIGNAL_TTL_EXPIRED"
                    sig["exit_reason"] = sig["outcome"]
                    fixed += 1
                    expiry_records.append((sig, sig["outcome"], True))
                    pending_removals.append((tid, sig["outcome"]))
                elif sig.get("order_placed") and missing_exposure and not promotion_in_progress:
                    sig["status"] = "EXPIRED"
                    sig["outcome"] = "STALE_NO_EXPOSURE"
                    sig["exit_reason"] = sig["outcome"]
                    fixed += 1
                    expiry_records.append((sig, sig["outcome"], False))
                    pending_removals.append((tid, sig["outcome"]))
                continue
            elif st in (SIGNAL_STATUS_AWAITING_MICRO, SIGNAL_STATUS_AWAITING_5M, SIGNAL_STATUS_AWAITING_MIN_AGE, SIGNAL_STATUS_AWAITING_CHASE_3PLUS, SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE) and ttl_expired:
                sig["status"] = "EXPIRED"
                sig["outcome"] = "SIGNAL_TTL_EXPIRED"
                sig["exit_reason"] = sig["outcome"]
                fixed += 1
                expiry_records.append((sig, "SIGNAL_TTL_EXPIRED", True))
        for order in list(pending_orders):
            tid = order.get("trade_id")
            if order.get("status") != "PENDING" or not tid:
                continue
            master = trades_map.get(tid, {}).get("signal_ref", {}) or {}
            if is_terminal_signal(master) or (master.get("created_ts_ts", 0) and now - master.get("created_ts_ts", 0) > SIGNAL_TTL_SEC):
                expire_reason = master.get("outcome") or master.get("exit_reason") or "TTL_EXPIRED"
                pending_cancellations.append((order, expire_reason, tid, master))

    # Expiry persistence, relay publication, collector writes, and private
    # cancellation can block on network or disk.  They must never run while
    # the global execution lock is held; the status mutations above are the
    # atomic boundary and these idempotent side effects follow it.
    for sig, reason, funnel_expired in expiry_records:
        _record_expired_order(sig, reason)
        if funnel_expired:
            _funnel_signal_expired(sig, "SIGNAL_EXPIRED")
    for tid, reason in pending_removals:
        if _remove_pending_for_trade(tid, reason):
            orphans_removed += 1
    for order, expire_reason, tid, master in pending_cancellations:
        outcome = _cancel_pending_order_confirmed(
            order,
            expire_reason,
            record_expired=True,
            expire_signal=False,
        )
        if outcome.get("finalized"):
            orphans_removed += 1
            logger.info(
                f"[ORDER CLEANUP] Dropped confirmed orphan pending "
                f"trade_id={tid} signal_status={master.get('status')} "
                f"outcome={master.get('outcome')} [PIPELINE ENFORCEMENT]"
            )
    if fixed or orphans_removed:
        logger.info(f"[EXECUTION FIX {EXECUTION_FIX_VERSION}] reconciled {fixed} stale signals, removed {orphans_removed} orphan pending orders")
        _agent_dbg("H1", "reconcile_stale_signals", "reconciled", {"count": fixed, "orphans_removed": orphans_removed, "pending_ids": len(_pending_trade_ids()), "open_ids": len(_open_trade_ids())})
    return fixed

def sync_signal_info_registry():
    pending_ids = _pending_trade_ids()
    open_ids = _open_trade_ids()
    awaiting_micro_ids = set()
    awaiting_5m_ids = set()
    awaiting_min_age_ids = set()
    awaiting_chase_3plus_ids = set()
    with trade_lock:
        for entry in trades_map.values():
            sig = entry.get("signal_ref")
            if not isinstance(sig, dict):
                continue
            tid = sig.get("trade_id")
            if tid and sig.get("status") == SIGNAL_STATUS_AWAITING_MICRO and not is_terminal_signal(sig):
                awaiting_micro_ids.add(tid)
            if tid and sig.get("status") == SIGNAL_STATUS_AWAITING_5M and not is_terminal_signal(sig):
                awaiting_5m_ids.add(tid)
            if tid and sig.get("status") == SIGNAL_STATUS_AWAITING_MIN_AGE and not is_terminal_signal(sig):
                awaiting_min_age_ids.add(tid)
            if tid and sig.get("status") in VIRTUAL_CHASE_AWAITING_STATUSES and not is_terminal_signal(sig):
                awaiting_chase_3plus_ids.add(tid)
    live_ids = pending_ids | open_ids | awaiting_micro_ids | awaiting_5m_ids | awaiting_min_age_ids | awaiting_chase_3plus_ids
    live_signals = []
    with trade_lock:
        for entry in trades_map.values():
            sig = entry.get("signal_ref")
            if not isinstance(sig, dict):
                continue
            tid = sig.get("trade_id")
            if not tid or tid not in live_ids or is_terminal_signal(sig):
                continue
            live_signals.append(sig)
    exposure = get_active_signal_count()
    with state_lock:
        state["signal_info"]["signals"] = live_signals[-MAX_ACTIVE_SIGNALS:]
        state["signal_info"]["count"] = exposure
        state["signal_info"]["active"] = exposure > 0

def pipeline_state_sync():
    reconcile_stale_signals()
    reconcile_lane_position_registry()
    sync_signal_info_registry()
    sync_cooldown_debug_state()
    logger.debug("[STATE SYNC] Pipeline state synchronized [PIPELINE ENFORCEMENT]")

def persist_signal(signal, stage="UNKNOWN"):
    try:
        if stage not in PERSIST_SIGNAL_STAGES:
            return
        if not signal or not signal.get("trade_id"):
            return
        row = {
            "ts": signal.get("_persist_ts") or utc_iso(),
            "trade_id": signal.get("trade_id"),
            "stage": stage,
            "direction": signal.get("final_direction"),
            "price": signal.get("signal_price"),
            "status": signal.get("status"),
            "ai_win_prob": signal.get("ai_win_prob"),
            "ai_decision": signal.get("ai_decision"),
            "edge_score": signal.get("edge_score_at_entry"),
            "setup_type": signal.get("setup_type")
        }
        logger.info(f"[PERSIST] {stage} for trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
        dynamic_csv_writer("signal_persist.log", row)
    except Exception as e:
        logger.error(f"[PERSIST ERROR] {e} [PIPELINE ENFORCEMENT]")

def persist_signal_close(trade_id, status):
    logger.info(f"[PERSIST CLOSE] trade_id={trade_id} status={status} [PIPELINE ENFORCEMENT]")


def _position_open_relay_allowed(pos, master=None):
    """Refuse to publish or re-persist an OPEN after terminal close won.

    ``fill_order`` performs persistence and analytics after registering the
    in-memory position. A strategy/admin close may legitimately win during
    those slower steps. Terminal state must dominate that late fill thread.
    """
    if not isinstance(pos, dict):
        return False
    if (
        pos.get("status") == "CLOSED"
        or pos.get("_close_in_progress")
        or pos.get("exit_reason")
    ):
        return False
    if isinstance(master, dict) and is_terminal_signal(master):
        return False
    return True


def _commit_position_open_lifecycle(pos, master, signal, order, fill_px, opened_ts):
    """Atomically commit OPEN or yield to a concurrent terminal close."""
    with position_close_lock:
        if not _position_open_relay_allowed(pos, master):
            return None
        if isinstance(master, dict):
            master.update({
                "status": "FILLED",
                "filled_ts": time.time(),
                "fill_price": fill_px,
                "planned_limit_price": order.get("planned_limit_price"),
                "outcome": "OPEN",
            })
        snapshot = copy.deepcopy(master or signal or {})
        snapshot["_persist_ts"] = opened_ts
        return snapshot


def _finalize_position_open_lifecycle(pos, master, signal, order, fill_px, opened_ts):
    """Publish only after OPEN won the terminal-state commit race.

    External/local callbacks remain outside ``position_close_lock`` so a slow
    analytics bridge cannot delay a risk-reducing close. Their immutable
    source timestamp still records the causal OPEN commit before that close.
    """
    snapshot = _commit_position_open_lifecycle(
        pos, master, signal, order, fill_px, opened_ts
    )
    if snapshot is None:
        return None
    _emit_genome_execution_event("ORDER_FILLED", {
        "trade_id": order.get("trade_id"),
        "fill_price": fill_px,
        "direction": order.get("signal_dir"),
        "research_lane": (signal or {}).get("research_lane") or order.get("research_lane"),
        "chase_count": int(order.get("limit_chase_count") or 0),
    })
    _emit_genome_execution_event("POSITION_OPENED", {
        "trade_id": pos.get("trade_id"),
        "entry_price": fill_px,
        "direction": pos.get("dir"),
        "qty": pos.get("qty"),
        "research_lane": pos.get("research_lane"),
        "stop_loss": pos.get("sl"),
    })
    _push_showcase_relay_event(
        "POSITION_OPENED",
        order.get("trade_id"),
        {
            "ts": opened_ts,
            "direction": order.get("signal_dir"),
            "fill_price": fill_px,
            "qty": order.get("qty"),
            "research_lane": (signal or {}).get("research_lane")
            or order.get("research_lane"),
        },
    )
    _relay_mirror(
        "FILLED",
        {
            "trade_id": order.get("trade_id"),
            "direction": order.get("signal_dir"),
            "qty": order.get("qty"),
            "fill_price": fill_px,
            "entry": fill_px,
            "research_lane": (signal or {}).get("research_lane"),
        },
        source_ts=time.time(),
    )
    return snapshot


def validate_startup():
    required = ["reset_all_csv","update_logger_level","prune_signals","process_signal","evaluate_signal_with_ai","execute_order","pipeline_state_sync","persist_signal","compute_edge_score","update_debug_state_always"]
    for fn in required:
        if fn not in globals():
            raise Exception(f"[STARTUP ERROR] Missing function: {fn}")
    logger.info("[STARTUP] All critical functions verified [PIPELINE ENFORCEMENT]")

def track_event(trade_id, stage):
    if trade_id in trades_map:
        if "timeline" not in trades_map[trade_id]:
            trades_map[trade_id]["timeline"] = []
        trades_map[trade_id]["timeline"].append({"ts": utc_iso(), "stage": stage})
        logger.info(f"[LIFECYCLE] trade_id={trade_id} stage={stage} [PIPELINE ENFORCEMENT]")

def sanitize_ai_inputs(ctx: dict) -> dict:
    if not isinstance(ctx, dict):
        return {}
    clean = {}
    for k, v in ctx.items():
        if isinstance(v, (int, float)):
            if math.isnan(v) or math.isinf(v):
                clean[k] = 0
            else:
                clean[k] = float(v)
        elif v is None:
            clean[k] = 0
        else:
            clean[k] = v
    return clean

def enforce_log(signal: dict, stage: str, extra: str = None, skip_stage: str = None):
    if not signal or not isinstance(signal, dict) or not signal.get("trade_id"):
        logger.error(f"[LOG ENFORCEMENT FAIL] Missing trade_id for stage={stage} [PIPELINE ENFORCEMENT]")
        return
    logged_key = f"_logged_{stage}"
    if signal.get(logged_key):
        return
    signal[logged_key] = True
    signal["_logged"] = True
    log_decision(signal, stage, extra or stage, skip_stage=skip_stage or stage, ai_extra=extra)
    persist_signal(signal, stage)
    logger.info(f"[ENFORCE_LOG] {stage} trade_id={signal.get('trade_id')} extra={extra} [PIPELINE ENFORCEMENT]")

def enforce_immutable(signal: dict):
    IMMUTABLE_FIELDS = ["features", "controls", "indicators", "edge_score_at_entry", "edge_threshold_at_entry", "counterfactuals"]
    for f in IMMUTABLE_FIELDS:
        if f in signal and isinstance(signal[f], (dict, list)):
            signal[f] = copy.deepcopy(signal[f])
    signal["_frozen"] = True
    logger.debug(f"[IMMUTABILITY GUARD] Applied to trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")

def assert_not_mutated(signal: dict, field: str, new_value=None):
    if signal.get("_frozen") and field in ["features", "controls", "indicators", "edge_score_at_entry", "edge_threshold_at_entry", "counterfactuals"]:
        logger.critical(f"IMMUTATION VIOLATION: {field} on frozen trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
        raise RuntimeError(f"IMMUTATION VIOLATION: {field} on frozen trade_id={signal.get('trade_id')}")

def finalize_signal(signal: dict, ai: dict = None, status: str = None):
    if signal.get("_finalized"):
        current = signal.get("status")
        if status and current != status:
            if current in TERMINAL_SIGNAL_STATUSES or is_terminal_signal(signal):
                logger.debug(f"[FINALIZE SKIP] trade_id={signal.get('trade_id')} terminal status={current} - not downgrading to {status} [PIPELINE ENFORCEMENT]")
            else:
                signal["status"] = status
                logger.info(f"[FINALIZE UPDATE] trade_id={signal.get('trade_id')} status={status} [PIPELINE ENFORCEMENT]")
                pipeline_state_sync()
        else:
            logger.debug(f"[FINALIZE SKIP] trade_id={signal.get('trade_id')} already finalized status={signal.get('status')} [PIPELINE ENFORCEMENT]")
        return
    if ai is None:
        raise RuntimeError("FINALIZE WITHOUT AI — PIPELINE VIOLATION")
    if status:
        signal["status"] = status
    if ai:
        signal["ai"] = ai
        signal["ai_win_prob"] = ai.get("win_prob")
        signal["ai_decision"] = ai.get("decision")
        signal["ai_source"] = ai.get("source")
        ai_direction = ai.get("direction")
        invert_on = invert_signal_active()
        final_direction, inverted = apply_invert_direction(ai_direction, invert_on)
        if inverted:
            logger.info(f"[DIRECTION CONSISTENCY] INVERSION APPLIED raw_ai={ai_direction} -> final_direction={final_direction} inverted={inverted} trade_id={signal.get('trade_id')} [PIPELINE ENFORCEMENT]")
        stamp_signal_policy_identity(
            signal, raw_direction=ai_direction, executed_direction=final_direction, invert_on=invert_on,
        )
        signal["inverted"] = inverted
    if ai and not signal.get("_ai_logged"):
        log_ai(signal, ai)
    signal["_completed"] = True
    signal["_finalized"] = True
    trades_map[signal.get("trade_id")] = {"signal_ref": signal, "ai": ai}
    pipeline_state_sync()
    enforce_log(signal, "COMPLETE")
    logger.info(f"[FINALIZE] trade_id={signal.get('trade_id')} status={signal.get('status')} ai_source={ai.get('source') if ai else 'NONE'} final_direction={signal.get('final_direction')} raw_ai={signal.get('ai_direction_raw')} inverted={signal.get('inverted')} [PIPELINE ENFORCEMENT]")
    assert signal.get("_logged"), "[CRITICAL] Signal not logged"
    assert signal.get("trade_id"), "[CRITICAL] Missing trade_id"
    validate_pipeline_completion(signal)

def exit_pipeline(signal: dict, ai: dict = None, reason: str = "UNKNOWN"):
    signal["status"] = "BLOCKED"
    signal["block_reason"] = reason
    if ai is None:
        ai = {"win_prob":0,"direction":"NO_TRADE","decision":"REJECT","source":"SYSTEM","approved":False}
    if ai.get("decision") == "APPROVE":
        record_approve_outcome(
            "BLOCKED",
            reason,
            signal.get("effective_threshold_at_entry") or get_effective_edge_threshold(),
            signal.get("trade_id"),
            signal.get("edge_score_at_entry"),
            ai,
        )
        defer_shadow_research(signal.get("trade_id"), reason)
        if not signal.get("_logged_BLOCKED"):
            enforce_log(signal, "BLOCKED", reason, skip_stage="POST_AI")
    log_blocked_signal(signal, ai, reason)
    persist_rejected_opportunity(signal, ai, reason, would_block_only=False)
    finalize_signal(signal, ai, "BLOCKED")
    full_pipeline_trace("BLOCKED", reason, signal.get("trade_id"))
    clear_pending_trade()
    return

def full_pipeline_trace(stage: str, reason: str = "", trade_id=None):
    msg = f"[PIPELINE] {stage} | REASON={reason}"
    if trade_id:
        msg += f" | trade_id={trade_id}"
    logger.info(msg + " [PIPELINE ENFORCEMENT]")

def trace(stage: str, msg: str, trade_id: str = None):
    ts = utc_iso()
    tid = f" | trade_id={trade_id}" if trade_id else ""
    logger.info(f"[{ts}] [{stage}] {msg}{tid} [PIPELINE ENFORCEMENT]")

