def allocate_lane_trade_id(research_lane: str) -> str:
    """Stable lane-prefixed trade_id — relay + CSV must never see bare UUIDs."""
    lane = str(research_lane or RESEARCH_LANE_AI_SCAN).upper()
    if lane == RESEARCH_LANE_CONTINUOUS:
        prefix = "cont"
    elif is_ai_scan_lane(lane):
        prefix = "scan"
    else:
        prefix = (
            COMBO_LANE_SPECS.get(lane, {}).get("id_prefix")
            or _SPAWN_LANE_ID_PREFIX.get(lane)
            or "lane"
        )
    return f"{prefix}-{uuid.uuid4().hex[:12]}"


def relay_publishes_approve_outcome(research_lane: str) -> bool:
    """Publish entry intent only for explicitly platform-relay-eligible lanes."""
    return str(research_lane or "").upper() in PLATFORM_RELAY_ELIGIBLE_LANES


SHADOW_RUNNER_HORIZON_SECS = {
    "15m": 900,
    "30m": 1800,
    "60m": 3600,
    "90m": 5400,
}


def _spawn_ai_prob_ge(ai, lo: int) -> bool:
    try:
        return int(ai.get("win_prob") or 0) >= int(lo)
    except (TypeError, ValueError):
        return False


def _spawn_structure_score(ctx, features=None) -> float:
    mc = ctx or {}
    ms = mc.get("market_structure") or {}
    if ms.get("structure_score") is None and isinstance(features, dict):
        ms = features.get("market_structure") or ms
    try:
        return float(ms.get("structure_score") or mc.get("structure_score") or 0)
    except (TypeError, ValueError):
        return 0.0


def _spawn_near_support(ctx, features) -> bool:
    sr = (
        (features or {}).get("sr_state")
        or (ctx or {}).get("sr_state")
        or (state.get("support_resistance") or {}).get("sr_state")
    )
    return _sr_location_bucket(sr) == "NEAR_SUPPORT"


def _spawn_ai_prob_in_band(ai, lo: int = 50, hi: int = 55) -> bool:
    try:
        prob = int(ai.get("win_prob") or 0)
    except (TypeError, ValueError):
        return False
    return lo <= prob <= hi


def compute_binance_fee_stress(trades: list) -> dict:
    """Reference PnL after Binance USDT-M VIP0 taker round-trip (not live exchange)."""
    lev = int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE))
    margin = float(FIXED_MARGIN_USDT)
    notional = margin * lev
    fee_per_trade = round(notional * BINANCE_USDT_M_TAKER_FEE * 2, 4)
    lanes_out = {}
    for lane_key, lane_label in RESEARCH_LANE_LABELS.items():
        if lane_key == RESEARCH_LANE_PROFIT_GATES:
            continue
        lt = [t for t in (trades or []) if str(t.get("research_lane") or "") == lane_key]
        n = len(lt)
        gross = round(sum(float(t.get("net_pnl_usd") or t.get("net") or 0) for t in lt), 2)
        fees = round(n * fee_per_trade, 2)
        net = round(gross - fees, 2)
        lanes_out[lane_key] = {
            "label": lane_label,
            "trades": n,
            "gross_pnl_usd": gross,
            "est_fees_usd": fees,
            "net_after_fees_usd": net,
            "profitable": net > 0,
            "fee_per_trade_usd": fee_per_trade,
        }
    return {
        "exchange": "binance_usdt_m",
        "fee_model": "VIP0 taker 0.05% entry + 0.05% exit (reference)",
        "maker_fee_pct": BINANCE_USDT_M_MAKER_FEE * 100,
        "taker_fee_pct": BINANCE_USDT_M_TAKER_FEE * 100,
        "margin_usd": margin,
        "leverage": lev,
        "notional_usd": round(notional, 2),
        "fee_per_round_trip_usd": fee_per_trade,
        "lanes": lanes_out,
    }


def _golden_stack_pass_for_spawn(final_direction, ctx, ai, features, edge_score, signal_stub=None) -> tuple:
    probe = signal_stub or {
        "final_direction": final_direction,
        "signal_price": nz(state.get("price")),
        "trade_id": f"gs-probe-{uuid.uuid4().hex[:8]}",
        "features": features or {},
        "context": ctx,
        "trade_planner": copy.deepcopy((ai or {}).get("trade_planner") or {}),
    }
    if not probe.get("entry_mode"):
        compute_continuous_ai_direct_entry(probe)
    blocked, reason = evaluate_golden_stack_filter(
        final_direction, ctx, ai, features, edge_score, probe,
    )
    return not blocked, reason


def _enrich_combo_lane_features(features: dict = None, ctx: dict = None) -> dict:
    """Ensure ADX / session / structure fields exist for combo extra_filters + sizing.

    AI_SCAN feature snapshots often omit ADX/session; pull from live market_context /
    research session bucket so SL_AVOIDANCE and SIZED_CONTINUOUS can diverge.
    """
    out = dict(features or {})
    ctx = ctx or {}
    mc = (
        out.get("market_context")
        or ctx.get("market_context")
        or state.get("market_context")
        or {}
    )
    if mc and "market_context" not in out:
        out["market_context"] = mc
    ts_mc = (mc.get("trend_strength") or {}) if isinstance(mc, dict) else {}
    adx = (
        out.get("adx_at_entry")
        or out.get("adx")
        or out.get("mom_adx")
        or ts_mc.get("adx")
    )
    if adx is not None:
        out.setdefault("adx", adx)
        out.setdefault("adx_at_entry", adx)
    ms = (mc.get("market_structure") or {}) if isinstance(mc, dict) else {}
    struct = (
        out.get("structure_bias_at_entry")
        or out.get("structure_bias")
        or out.get("mtf_structure")
        or ms.get("structure_bias")
    )
    if struct:
        out.setdefault("structure_bias", struct)
        out.setdefault("structure_bias_at_entry", struct)
    if not out.get("session_bucket"):
        out["session_bucket"] = _research_session_bucket()
    out.setdefault("ts_utc", utc_iso())
    return out


def _prepare_shared_lane_spawn_features(event: dict = None, features: dict = None, ctx: dict = None) -> dict:
    """Build inherited-lane features before the downstream signal object exists."""
    event_features = (event or {}).get("features") if isinstance(event, dict) else None
    return _enrich_combo_lane_features(event_features or features, ctx)


def _lane_sized_margin_usdt(lane: str, features: dict = None) -> tuple:
    """Apply per-lane session size_multipliers on top of FIXED_MARGIN_USDT."""
    size_mult = float(resolve_lane_size_multiplier(lane, features or {}))
    margin = round(float(FIXED_MARGIN_USDT) * size_mult, 4)
    margin = max(float(FIXED_MARGIN_USDT) * SIZE_MULT_MIN, min(margin, float(FIXED_MARGIN_USDT) * SIZE_MULT_MAX))
    return margin, size_mult


def _spawn_combo_lane(ctx, ai, edge_score, features, target_lane: str, trigger_reason: str):
    if ai.get("decision") != "APPROVE":
        log_lane_opportunity_event(
            target_lane, "SPAWN_SKIPPED", (ctx or {}).get("trade_id"),
            (ai or {}).get("direction"), (ai or {}).get("win_prob"), edge_score,
            block_reason=f"DECISION_NOT_APPROVE ({(ai or {}).get('decision')})",
        )
        return
    if not is_research_data_collection():
        log_lane_opportunity_event(
            target_lane, "SPAWN_SKIPPED", (ctx or {}).get("trade_id"),
            (ai or {}).get("direction"), (ai or {}).get("win_prob"), edge_score,
            block_reason="RESEARCH_DATA_COLLECTION_OFF",
        )
        return
    if not guard_retired_lane_execution(target_lane, "spawn_combo_lane", (ctx or {}).get("trade_id")):
        log_lane_opportunity_event(
            target_lane, "SPAWN_FILTERED", (ctx or {}).get("trade_id"),
            (ai or {}).get("direction"), (ai or {}).get("win_prob"), edge_score,
            block_reason="RETIRED_LANE_GUARD",
        )
        return
    enriched = _enrich_combo_lane_features(features, ctx)
    if not is_research_lane_enabled(target_lane):
        if is_patient_chase_lane(target_lane):
            log_lane_opportunity_event(
                target_lane, "SPAWN_SHADOW", (ctx or {}).get("trade_id"),
                (ai or {}).get("direction"), (ai or {}).get("win_prob"), edge_score,
                block_reason="TILE_OFF_SHADOW_ONLY",
            )
            _spawn_lab_combo_shadow(ctx, ai, edge_score, target_lane, enriched)
            return
        logger.info(f"[{target_lane}] spawn LAB mode - lane OFF [PIPELINE ENFORCEMENT]")
        log_lane_opportunity_event(
            target_lane, "SPAWN_LAB", (ctx or {}).get("trade_id"),
            (ai or {}).get("direction"), (ai or {}).get("win_prob"), edge_score,
            block_reason="LANE_TOGGLE_OFF_LAB",
        )
        _spawn_lab_combo_shadow(ctx, ai, edge_score, target_lane, enriched)
        return
    # The child gets its own trade id, but retains the canonical parent scan.
    # Thread it through both inputs because process_signal can normalize them
    # independently before creating the signal and order records.
    call_id = _shared_ai_call_id(ai_result=ai, ctx=ctx)
    call_ts = (ai or {}).get("shared_ai_call_ts") or (ctx or {}).get("shared_ai_call_ts")
    spawn_ctx = copy.deepcopy(ctx)
    spawn_ctx["trade_id"] = allocate_lane_trade_id(target_lane)
    spawn_ctx["shared_ai_call_id"] = call_id
    spawn_ctx["shared_ai_call_ts"] = call_ts
    spawn_ctx["exit_config"] = get_exit_config_for_lane(target_lane)
    spawn_ai = copy.deepcopy(ai)
    spawn_ai["shared_ai_call_id"] = call_id
    spawn_ai["shared_ai_call_ts"] = call_ts
    logger.info(
        f"[{target_lane}] combo spawn trade_id={spawn_ctx['trade_id']} reason={trigger_reason} "
        f"[PIPELINE ENFORCEMENT]"
    )
    result = process_signal({
        "event_trigger": True,
        "research_lane": target_lane,
        "edge_trigger_reason": trigger_reason,
        "edge_score": round(float(edge_score), 1),
        "price": nz(state.get("price")),
        "timestamp": utc_iso(),
        "features": enriched,
        "skip_ai": True,
        "pre_ai": spawn_ai,
        "pre_ctx": spawn_ctx,
    })
    if isinstance(result, dict):
        resolution = str(result.get("entry_resolution") or "").upper()
        if resolution in {"AWAITING", "NO_ORDER"}:
            resolution_source = {
                **spawn_ctx,
                "shared_ai_call_id": call_id,
                "raw_direction": spawn_ai.get("raw_direction") or spawn_ai.get("direction"),
                "executed_direction": spawn_ai.get("direction"),
                "research_lane": target_lane,
            }
            _append_v3_lane_entry_resolution(
                resolution_source, target_lane, resolution,
                str(result.get("exact_reason") or "UNSPECIFIED"),
            )


def _spawn_lab_combo_shadow(
    ctx,
    ai,
    edge_score,
    target_lane: str,
    features: dict = None,
    collection_mode: str = "LAB",
    is_counterfactual: bool = False,
):
    """LAB mode for an OFF combo tile — run the FULL strategy pipeline in telemetry/simulation:
    virtual chase fill + Scenario C exit ladder (thesis stop / early-fail / SL / TP / profit-lock),
    WITHOUT placing any real exchange order. Reuses the shadow-collecting replay engine
    (`start_replay_buffer` + `tick_all_replay_buffers` + `simulate_replay_outcome` +
    `finalize_shadow_lane_collecting`). Simulated PnL is recorded into `lane_lab_pnl_ledger`
    on buffer finalization, tagged `mode: "lab"` so it never contaminates the real
    `lane_pnl_ledger` used for live decisions.

    Safety: this path never calls submit_limit / submit_stop / any order API. The existing
    `lane_orders_allowed` gate (False for OFF combo tiles) is the secondary defense at every
    order-submission site.
    """
    if not is_research_data_collection():
        return
    if not (
        is_combo_execution_lane(target_lane)
        or str(target_lane or "").upper() == RESEARCH_LANE_CONTINUOUS
    ):
        return
    study_id = f"lab-{str(target_lane).lower()}-{uuid.uuid4().hex[:12]}"
    ai_dir = str((ai or {}).get("direction") or "LONG").upper()
    invert_on = invert_signal_active()
    direction = ai_dir
    if invert_on:
        if direction == "LONG":
            direction = "SHORT"
        elif direction == "SHORT":
            direction = "LONG"
    price = float(nz(state.get("price")) or 0)
    if price <= 0:
        return
    exit_cfg = get_exit_config_for_lane(target_lane)
    # Belt-and-braces no-real-order guard: LAB mode must NEVER place a real order.
    # This branch only starts a replay buffer; the real order path (process_signal →
    # submit_limit/submit_stop) is never entered for OFF tiles. Assert defensively.
    # Rejected Type B controls are replay buffers only and must continue while
    # the tile is ON; they never call an order API. The old blanket toggle
    # guard aborted every calibration counterfactual whenever Type B was ON.
    # Keep the fail-closed guard for ordinary OFF-tile LAB studies and allow
    # only this explicitly tagged counterfactual path through.
    safe_counterfactual = (
        bool(is_counterfactual)
        and str(collection_mode or "").upper() == "CALIBRATION_COUNTERFACTUAL"
    )
    if lane_orders_allowed(target_lane) and not safe_counterfactual:
        logger.error(
            f"[LAB_GUARD] lane={target_lane} unexpectedly orders-allowed in LAB spawn "
            f"— aborting LAB shadow to avoid real orders [PIPELINE ENFORCEMENT]"
        )
        return
    enriched = _enrich_combo_lane_features(features, ctx)
    margin_usdt, size_mult = _lane_sized_margin_usdt(target_lane, enriched)
    paused_shadow = manual_admin_pause_active()
    patient_shadow = is_patient_chase_lane(target_lane)
    if patient_shadow:
        lane_spec = COMBO_LANE_SPECS.get(target_lane) or {}
        margin_usdt = min(float(margin_usdt), float(lane_spec.get("margin_usd") or 2.0))
    # Patient Chase OFF shadows retain the real 0.29% entry anchor. Other
    # legacy LAB studies retain their established instant-fill behavior.
    start_replay_buffer(
        study_id,
        price,
        lane=f"shadow_collect_{target_lane}",  # reuse prefix so finalize_shadow_lane_collecting handles TTL
        direction=direction,
        leverage=int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)),
        margin_usdt=float(margin_usdt),
        pullback_pct=offset029_policy.ENTRY_OFFSET if patient_shadow else 0.0,
        virtual_entry=None if patient_shadow else price,
        virtual_fill_t=None if patient_shadow else 0.0,
        early_fail_enabled=bool(state.get("early_fail_enabled", True)),
        exit_config=exit_cfg,
        ai_win_prob=(ai or {}).get("win_prob"),
        edge_score=round(float(edge_score), 1),
        research_lane=target_lane,
        source_trade_id=(ai or {}).get("shared_ai_call_id") or (ctx or {}).get("shared_ai_call_id") or (ctx or {}).get("trade_id"),
        shared_ai_call_id=(ai or {}).get("shared_ai_call_id") or (ctx or {}).get("shared_ai_call_id") or (ctx or {}).get("trade_id"),
        shared_ai_call_ts=(ai or {}).get("shared_ai_call_ts") or (ctx or {}).get("shared_ai_call_ts"),
        collection_mode=collection_mode,
        paused_shadow=paused_shadow,
        is_counterfactual=bool(is_counterfactual),
        policy_version=(
            (COMBO_LANE_SPECS.get(target_lane) or {}).get("raw_policy_id")
            if patient_shadow else
            _type_b_policy_version()
            if str(target_lane).upper() == RESEARCH_LANE_TYPE_B_HUNTER_V1
            else "continuous_shared_direction_gap_v1"
            if str(target_lane).upper() == RESEARCH_LANE_CONTINUOUS
            else None
        ),
        invert_on=invert_on,
        size_mult=size_mult,
        session_bucket=enriched.get("session_bucket"),
        prompt_id=(ai or {}).get("prompt_id") or SHARED_DIRECTION_PROMPT_ID,
        adx_at_signal=enriched.get("adx_normalized") or enriched.get("adx"),
        entry_features=copy.deepcopy(enriched),
        ai_snapshot={
            "direction": (ai or {}).get("direction"),
            "win_prob": (ai or {}).get("win_prob"),
            "decision": (ai or {}).get("decision"),
        },
    )
    append_replay_tick(study_id, price, None)
    logger.info(
        f"[{target_lane}] LAB shadow study_id={study_id} dir={direction} edge={float(edge_score):.1f} "
        f"margin=${margin_usdt:.2f} size_mult={size_mult:.2f} session={enriched.get('session_bucket')} "
        f"— simulating policy shadow path, no paper or real orders [PIPELINE ENFORCEMENT]"
    )


def _open_bracket_lab_shadow_for_side(target_lane: str, side: str):
    """Return (trade_id, buf) for an open unfilled LAB shadow on lane+side, else None."""
    lane_u = str(target_lane or "").upper()
    side_u = str(side or "").upper()
    with replay_lock:
        for tid, buf in replay_buffers.items():
            if buf.get("closed"):
                continue
            if str(buf.get("research_lane") or "").upper() != lane_u:
                continue
            if str(buf.get("collection_mode") or "") not in ("LAB", "ADMIN_PAUSED_SHADOW"):
                continue
            if buf.get("virtual_entry"):
                continue
            if str(buf.get("direction") or "").upper() != side_u:
                continue
            return tid, buf
    return None


def _cancel_open_bracket_lab_shadows(
    target_lane: str,
    side: str = None,
    reason: str = "CANCELLED",
):
    """Finalize open LAB bracket shadows for a lane (optionally one side) as CANCELLED."""
    lane_u = str(target_lane or "").upper()
    side_u = str(side or "").upper() or None
    to_finalize = []
    with replay_lock:
        for tid, buf in list(replay_buffers.items()):
            if buf.get("closed"):
                continue
            if str(buf.get("research_lane") or "").upper() != lane_u:
                continue
            if str(buf.get("collection_mode") or "") not in ("LAB", "ADMIN_PAUSED_SHADOW"):
                continue
            if buf.get("virtual_entry"):
                continue  # already filled — leave Scenario C exit alone
            if side_u and str(buf.get("direction") or "").upper() != side_u:
                continue
            buf["exit_outcome"] = reason
            buf["block_reason"] = reason
            to_finalize.append((tid, {**buf, "ticks": list(buf.get("ticks", []))}))
    for tid, buf_copy in to_finalize:
        try:
            finalize_shadow_lane_collecting(tid, buf_copy)
            logger.info(
                f"[{lane_u}] cancelled open LAB shadow study_id={tid} "
                f"reason={reason} [PIPELINE ENFORCEMENT]"
            )
        except Exception as e:
            logger.error(f"[{lane_u}] cancel shadow failed study_id={tid}: {e}")


def _spawn_lab_bracket_shadow(
    ctx,
    side: str,
    limit_price: float,
    edge_score: float,
    target_lane: str,
    features: dict = None,
    bracket_eval: dict = None,
    chase_mode: str = None,
    id_prefix: str = None,
    max_chases: int = None,
    fill_at_limit: bool = None,
    force_paused_shadow: bool = False,
):
    """LAB shadow at a bracket limit (micro S/R level) — real tick replay fill + Scenario C exit.

    chase_mode:
      FULL_CHASE (default / V2) — unchanged fill-on-cross at market price.
      STATIC — resting limit at exact S/R; never reprice; fill AT limit or TTL_EXPIRED.
    """
    if not is_research_data_collection():
        return
    if not is_combo_execution_lane(target_lane):
        return
    try:
        from sr_micro_tile_v2 import (
            bracket_limit_pullback,
            chase_mode_for_lane,
            max_chases_for_mode,
            trade_id_prefix_for_lane,
            CHASE_MODE_STATIC,
        )
    except Exception:
        bracket_limit_pullback = None
        chase_mode_for_lane = None
        max_chases_for_mode = None
        trade_id_prefix_for_lane = None
        CHASE_MODE_STATIC = "STATIC"

    direction = str(side or "LONG").upper()
    if direction not in ("LONG", "SHORT"):
        return
    if state.get("invert_signal", False):
        direction = "SHORT" if direction == "LONG" else "LONG"

    market_price = float(nz(state.get("price")) or 0)
    limit_price = float(limit_price or 0)
    if market_price <= 0 or limit_price <= 0:
        return

    mode = str(chase_mode or "").upper()
    if not mode and chase_mode_for_lane:
        mode = chase_mode_for_lane(target_lane)
    if not mode:
        mode = "FULL_CHASE"
    is_static = mode == CHASE_MODE_STATIC or bool(fill_at_limit) or is_static_bracket_lane(target_lane)
    if max_chases is None and max_chases_for_mode:
        max_chases = max_chases_for_mode(mode)
    if max_chases is None and is_static:
        max_chases = 0

    prefix = id_prefix or (trade_id_prefix_for_lane(target_lane) if trade_id_prefix_for_lane else "srmv2")

    if is_static:
        # Resting-order model: keep one working limit per side.
        # Same limit → leave open (do not cancel/respawn). Changed limit → cancel + replace.
        existing = _open_bracket_lab_shadow_for_side(target_lane, direction)
        if existing:
            _tid, _buf = existing
            cur_lim = float(_buf.get("limit_price") or _buf.get("original_limit_price") or 0)
            if cur_lim > 0 and abs(cur_lim - limit_price) < 0.01:
                logger.info(
                    f"[{target_lane}] STATIC resting limit already working "
                    f"study_id={_tid} dir={direction} limit={cur_lim:.2f} — skip respawn "
                    f"[PIPELINE ENFORCEMENT]"
                )
                return "RESTING"
            _cancel_open_bracket_lab_shadows(target_lane, direction, reason="CANCELLED")

    if bracket_limit_pullback:
        start_price, pullback_pct = bracket_limit_pullback(direction, market_price, limit_price)
    else:
        start_price = market_price
        if direction == "LONG" and limit_price < market_price:
            pullback_pct = (market_price - limit_price) / market_price
        elif direction == "SHORT" and limit_price > market_price:
            pullback_pct = (limit_price - market_price) / market_price
        else:
            pullback_pct = 0.0

    if start_price <= 0:
        return

    study_id = f"{prefix}-{direction.lower()}-{uuid.uuid4().hex[:12]}"
    exit_cfg = get_exit_config_for_lane(target_lane)
    if lane_orders_allowed(target_lane) and not force_paused_shadow:
        logger.error(
            f"[LAB_GUARD] lane={target_lane} unexpectedly orders-allowed in bracket LAB spawn "
            f"— aborting to avoid real orders [PIPELINE ENFORCEMENT]"
        )
        return

    enriched = _enrich_combo_lane_features(features, ctx)
    margin_usdt, size_mult = _lane_sized_margin_usdt(target_lane, enriched)
    # Section 8: carry the policy/episode identifiers into the buffer so the
    # finalized outcome row can stamp them on every record. For non-Tile 2
    # lanes these are None and the schema fields are skipped on finalize.
    _ctx_src = ctx or {}
    _tile2_policy = _ctx_src.get("policy_id") if target_lane == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC else None
    _tile2_exit = _ctx_src.get("exit_profile_id") if target_lane == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC else None
    _tile2_episode = _ctx_src.get("sr_episode_id") if target_lane == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC else None
    start_replay_buffer(
        study_id,
        start_price,
        lane=f"shadow_collect_{target_lane}",
        direction=direction,
        leverage=int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE)),
        margin_usdt=float(margin_usdt),
        pullback_pct=float(pullback_pct),
        early_fail_enabled=bool(state.get("early_fail_enabled", True)),
        exit_config=exit_cfg,
        edge_score=round(float(edge_score), 1),
        research_lane=target_lane,
        source_trade_id=(ctx or {}).get("trade_id"),
        collection_mode="ADMIN_PAUSED_SHADOW" if force_paused_shadow else "LAB",
        paused_shadow=bool(force_paused_shadow),
        size_mult=size_mult,
        session_bucket=enriched.get("session_bucket"),
        entry_features=copy.deepcopy(enriched),
        limit_price=float(limit_price),
        original_limit_price=float(limit_price),
        chase_mode=mode,
        max_chases=0 if is_static else max_chases,
        fill_at_limit=bool(is_static),
        limit_chase_count=0,
        policy_version=_tile2_policy,
        prompt_id=(ctx or {}).get("prompt_id"),
        adx_at_signal=(features or {}).get("adx_normalized") or (features or {}).get("adx"),
        sr_episode_id=_tile2_episode,
        exit_profile_id=_tile2_exit,
    )
    append_replay_tick(study_id, market_price, None)
    log_lane_opportunity_event(
        target_lane,
        "SPAWN_LAB",
        study_id,
        direction,
        None,
        edge_score,
        block_reason="BRACKET_LEG_STATIC" if is_static else "BRACKET_LEG",
    )
    logger.info(
        f"[{target_lane}] LAB bracket shadow study_id={study_id} dir={direction} "
        f"limit={limit_price:.2f} market={market_price:.2f} pullback={pullback_pct:.6f} "
        f"chase_mode={mode} fill_at_limit={is_static} "
        f"zone={(bracket_eval or {}).get('zone')} armed={(bracket_eval or {}).get('armed')} "
        f"— limit replay + Scenario C, no real orders [PIPELINE ENFORCEMENT]"
    )
    return "SPAWNED"


# ---------------------------------------------------------------------------
# Section 3 of Tile 2 static integrity repair.
#
# Replace the contradictory Tile 2 ON path. Previously the ON path called
# _spawn_lab_bracket_shadow, but the LAB guard aborted when
# lane_orders_allowed(target_lane) was true. The result was: tile ON did
# nothing (silently swallowed by the LAB guard error log).
#
# The fix routes Tile 2 explicitly via execution_mode_for_lane():
#   LAB_SHADOW  -> _spawn_lab_bracket_shadow (LAB shadow + counterfactual, no order)
#   PAPER       -> _submit_tile2_paper_resting_limit (local paper pending order)
#   LIVE        -> BLOCKED while PROBATION; never submit Bitfinex orders
#                  until the operator explicitly promotes the lane.
#   EXIT_ONLY   -> no new entries; existing filled positions still managed
# ---------------------------------------------------------------------------
TILE2_ENTRY_TTL_SEC = int(os.getenv("TILE2_ENTRY_TTL_SEC", str(30 * 60)))


def _tile2_paper_resting_limit_for_lane(side: str = None) -> dict | None:
    """Return a Tile 2 paper resting limit, optionally restricted by side.

    A Tile 2 paper limit is uniquely keyed by research_lane == SR_MICRO_TILE_V2_STATIC
    AND status == PENDING. The operational dual-leg policy permits at most one
    LONG and one SHORT, so callers that enforce occupancy must pass a side.
    """
    side_u = str(side or "").upper() or None
    with trade_lock:
        for o in pending_orders:
            if (
                isinstance(o, dict)
                and o.get("research_lane") == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC
                and o.get("status") == "PENDING"
                and (
                    side_u is None
                    or _normalize_order_side_to_dir(
                        o.get("signal_dir") or o.get("direction") or o.get("dir") or o.get("side")
                    ) == side_u
                )
            ):
                return o
    return None


def _tile2_active_trade_for_side(side: str) -> dict | None:
    """Return the pending/open Tile 2 trade occupying one direction slot."""
    side_u = str(side or "").upper()
    if side_u not in ("LONG", "SHORT"):
        return None
    with trade_lock:
        for collection in (pending_orders, open_positions):
            for item in collection:
                if not isinstance(item, dict):
                    continue
                if item.get("research_lane") != RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC:
                    continue
                status = str(item.get("status") or "").upper()
                if collection is pending_orders and status != "PENDING":
                    continue
                if collection is open_positions and status not in ("OPEN", "FILLED", "ACTIVE"):
                    continue
                item_side = _normalize_order_side_to_dir(
                    item.get("signal_dir")
                    or item.get("direction")
                    or item.get("dir")
                    or item.get("side")
                )
                if item_side == side_u:
                    return item
    return None


def _tile2_open_episode_ids(side: str = None) -> set:
    """Section 4: episode IDs currently attached to open/pending Tile 2 trades.

    Includes both pending paper limits and open positions. The bracket tick
    consults this before submitting a new paper limit so we never have two
    Tile 2 trades running on the same S/R episode.
    """
    seen = set()
    side_u = str(side or "").upper() or None
    with trade_lock:
        for o in pending_orders:
            if (
                isinstance(o, dict)
                and o.get("research_lane") == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC
                and o.get("status") == "PENDING"
                and o.get("sr_episode_id")
                and (
                    side_u is None
                    or _normalize_order_side_to_dir(
                        o.get("signal_dir") or o.get("direction") or o.get("dir") or o.get("side")
                    ) == side_u
                )
            ):
                seen.add(str(o.get("sr_episode_id")))
        for p in open_positions:
            if (
                isinstance(p, dict)
                and p.get("research_lane") == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC
                and str(p.get("status") or "").upper() in ("OPEN", "FILLED", "ACTIVE")
                and p.get("sr_episode_id")
                and (
                    side_u is None
                    or _normalize_order_side_to_dir(
                        p.get("signal_dir") or p.get("direction") or p.get("dir") or p.get("side")
                    ) == side_u
                )
            ):
                seen.add(str(p.get("sr_episode_id")))
    return seen


def _tile2_submitted_episode_ids() -> set:
    """Episodes already admitted to the running clean cohort."""
    with state_lock:
        return set(_tile2_counters_bucket().get("submitted_episode_ids") or [])


def _mark_tile2_episode_submitted(episode_id: str) -> None:
    if not episode_id:
        return
    with state_lock:
        bucket = _tile2_counters_bucket()
        seen = bucket.setdefault("submitted_episode_ids", [])
        if episode_id not in seen:
            seen.append(str(episode_id))
            if len(seen) > 500:
                del seen[: len(seen) - 500]
    _persist_tile2_counters(bucket)


def _register_tile2_active_signal(order: dict, ctx: dict = None, features: dict = None) -> dict:
    """Give a deterministic Tile 2 order the same visible signal lifecycle as AI lanes."""
    order = order or {}
    ctx = ctx or {}
    trade_id = str(order.get("trade_id") or "")
    direction = _normalize_order_side_to_dir(
        order.get("signal_dir") or order.get("dir") or order.get("side")
    )
    if not trade_id or direction not in ("LONG", "SHORT"):
        return {}
    created_ts = float(order.get("created_ts") or time.time())
    signal = {
        "trade_id": trade_id,
        "status": "ORDERED",
        "outcome": "PENDING",
        "order_placed": True,
        "research_lane": RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC,
        "research_model": RESEARCH_LANE_LABELS.get(
            RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC,
            "S/R Micro Tile V2 Static",
        ),
        "final_direction": direction,
        "dir": direction,
        "signal_price": float(order.get("signal_price") or state.get("price") or 0),
        "planned_limit_price": float(order.get("planned_limit_price") or order.get("limit_price") or 0),
        "original_limit_price": float(order.get("original_limit_price") or order.get("limit_price") or 0),
        "limit_price": float(order.get("limit_price") or 0),
        "created_ts": utc_iso(datetime.fromtimestamp(created_ts, tz=timezone.utc)),
        "created_ts_ts": created_ts,
        "expires_ts": float(order.get("entry_expires_ts") or 0),
        "order_created_ts": created_ts,
        "entry_mode": "BRACKET_LIMIT_STATIC",
        "entry_path": (
            "STATIC_MICRO_SUPPORT" if direction == "LONG" else "STATIC_MICRO_RESISTANCE"
        ),
        "trigger": "MICRO_SUPPORT" if direction == "LONG" else "MICRO_RESISTANCE",
        "strategy": "SR_MICRO_STATIC",
        "regime": state.get("regime", "UNKNOWN"),
        "ai_win_prob": None,
        "ai_decision": "NOT_USED",
        "limit_chase_count": 0,
        "chase_mode": "STATIC",
        "margin_usdt": float(order.get("margin_usdt") or FIXED_MARGIN_USDT),
        "edge_score_at_entry": order.get("edge_score"),
        "features": copy.deepcopy(features or {}),
        "context": copy.deepcopy(ctx),
        "policy_version": TILE2_POLICY_ID,
        "exit_config": copy.deepcopy(order.get("exit_config") or {}),
        "sr_episode_id": order.get("sr_episode_id"),
    }
    with trade_lock:
        existing = trades_map.get(trade_id)
        if isinstance(existing, dict) and isinstance(existing.get("signal_ref"), dict):
            existing["signal_ref"].update(signal)
            existing.setdefault("ai", {})
            return existing["signal_ref"]
        trades_map[trade_id] = {"signal_ref": signal, "ai": {}}
    return signal


def _cancel_tile2_paper_resting_limit(
    reason: str = "CANCELLED",
    side: str = None,
) -> bool:
    """Cancel Tile 2 resting limits, optionally only one direction."""
    side_u = str(side or "").upper() or None
    with trade_lock:
        matches = [
            o for o in list(pending_orders)
            if (
                isinstance(o, dict)
                and o.get("research_lane") == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC
                and o.get("status") == "PENDING"
                and (
                    side_u is None
                    or _normalize_order_side_to_dir(
                        o.get("signal_dir") or o.get("direction") or o.get("dir") or o.get("side")
                    ) == side_u
                )
            )
        ]
    cancelled = False
    for existing in matches:
        try:
            outcome = _cancel_pending_order_confirmed(
                existing,
                reason,
                record_expired=False,
                expire_signal=True,
            )
            if not outcome.get("finalized"):
                logger.warning(
                    f"[TILE2] cancel unconfirmed trade_id={existing.get('trade_id')} "
                    f"reason={reason} [PIPELINE ENFORCEMENT]"
                )
                continue
            existing["exit_reason"] = reason
            existing["cancelled_ts"] = time.time()
            log_lane_opportunity_event(
                RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC,
                "CANCELLED",
                existing.get("trade_id"),
                existing.get("signal_dir") or existing.get("dir"),
                None,
                float(existing.get("edge_score") or 0),
                block_reason=reason,
            )
            logger.info(
                f"[{RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC}] paper resting limit CANCELLED "
                f"trade_id={existing.get('trade_id')} reason={reason} [PIPELINE ENFORCEMENT]"
            )
            cancelled = True
        except Exception as e:
            logger.error(f"[TILE2] cancel paper limit failed: {e}")
    return cancelled


def _submit_tile2_paper_resting_limit(
    ctx: dict,
    side: str,
    limit_price: float,
    edge_score: float,
    features: dict = None,
    bracket_eval: dict = None,
    sr_episode_id: str = "",
) -> str:
    """Submit one local paper resting limit for a Tile 2 direction slot.

    This is the PAPER-mode replacement for _spawn_lab_bracket_shadow when the
    tile is ON. The limit is a *real pending_orders* entry (so the existing
    fill/exit machinery manages it) and is marked paper_only=True so the bot
    never submits it directly to Bitfinex. The separate platform relay may
    copy it only when that relay is ON.

    Tile 2 may hold one LONG slot at support and one SHORT slot at resistance
    simultaneously. A pending order or open position blocks only its own
    direction until that lifecycle expires or closes.
    """
    if _manual_pause_block_entry(ctx, "TILE2_PAPER_LIMIT"):
        return "REFUSED_ADMIN_PAUSE"
    if not can_progress_new_entry()[0]:
        logger.warning(
            "[WS ENTRY FREEZE] Tile 2 resting limit not created until a genuine "
            "WS tick is fresh [PIPELINE ENFORCEMENT]"
        )
        return "REFUSED_WS_NOT_READY"
    direction = str(side or "LONG").upper()
    if direction not in ("LONG", "SHORT"):
        return "REFUSED_BAD_SIDE"

    active_same_side = _tile2_active_trade_for_side(direction)
    if active_same_side:
        existing_limit = float(active_same_side.get("limit_price") or 0)
        requested_limit = float(limit_price or 0)
        if (
            str(active_same_side.get("status") or "").upper() == "PENDING"
            and existing_limit > 0
            and requested_limit > 0
            and abs(existing_limit - requested_limit) < 0.01
        ):
            return "RESTING"
        logger.info(
            f"[TILE2] {direction} paper limit refused — direction slot occupied "
            f"trade_id={active_same_side.get('trade_id')} "
            f"status={active_same_side.get('status')} [PIPELINE ENFORCEMENT]"
        )
        return "REFUSED_DIRECTION_ACTIVE"

    market_price = float(nz(state.get("price")) or 0)
    limit_price = float(limit_price or 0)
    if market_price <= 0 or limit_price <= 0:
        return "REFUSED_BAD_PRICE"
    if direction == "LONG" and limit_price >= market_price:
        logger.warning(
            f"[TILE2] LONG paper limit refused — limit {limit_price:.2f} >= market "
            f"{market_price:.2f} (would cross, not resting at support) "
            f"[PIPELINE ENFORCEMENT]"
        )
        return "REFUSED_WOULD_CROSS"
    if direction == "SHORT" and limit_price <= market_price:
        logger.warning(
            f"[TILE2] SHORT paper limit refused — limit {limit_price:.2f} <= market "
            f"{market_price:.2f} (would cross, not resting at resistance) "
            f"[PIPELINE ENFORCEMENT]"
        )
        return "REFUSED_WOULD_CROSS"

    # This function owns only the local showcase paper book. Direct Bitfinex
    # submission is always forbidden; platform relay eligibility is separate.
    mode = execution_mode_for_lane(RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC)
    if mode == EXEC_MODE_LIVE:
        logger.error(
            f"[TILE2] unexpected direct LIVE mode; retaining local-paper lifecycle "
            f"[PIPELINE ENFORCEMENT]"
        )
    if mode not in (EXEC_MODE_PAPER, EXEC_MODE_LIVE):
        logger.info(
            f"[TILE2] paper limit not submitted — execution_mode={mode} "
            f"[PIPELINE ENFORCEMENT]"
        )
        return f"REFUSED_MODE_{mode}"

    enriched = _enrich_combo_lane_features(features, ctx)
    # Operator policy: exactly $20 margin per direction ($40 only when both
    # independent slots are concurrently working).
    margin_usdt, size_mult = float(FIXED_MARGIN_USDT), 1.0
    leverage = int(state.get("leverage", DEFAULT_RESEARCH_LEVERAGE))
    qty = (float(margin_usdt) * leverage) / limit_price if limit_price > 0 else 0.0
    trade_id = allocate_lane_trade_id(RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC)
    exit_cfg = get_exit_config_for_lane(RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC)
    now_ts = time.time()
    # Section 6: the entry TTL is for the UNFILLED resting limit only. Once
    # filled, the resulting open position must continue until a genuine
    # strategy exit (Scenario C / thesis / stop / TIME_EXIT). We stamp
    # entry_expires_ts so the chase loop can expire the unfilled limit
    # without finalizing any filled position as MARK_TO_MARKET.
    entry_expires_ts = now_ts + TILE2_ENTRY_TTL_SEC
    order = {
        "trade_id": trade_id,
        "bitfinex_order_id": "",  # paper-only: never has a real exchange id
        # Internal direction is always LONG/SHORT. Exchange side stays buy/sell.
        # The old "buy" value crashed fill_order before Tile 2 could open a
        # position or receive ledger credit.
        "signal_dir": direction,
        "side": "buy" if direction == "LONG" else "sell",
        "dir": direction,
        "direction": direction,
        "signal_price": market_price,
        "limit_price": float(limit_price),
        "original_limit_price": float(limit_price),
        "planned_limit_price": float(limit_price),
        "qty": float(qty),
        "created_ts": now_ts,
        "entry_submitted_ts": now_ts,
        "entry_expires_ts": entry_expires_ts,
        "limit_chase_count": 0,
        "max_chase_count": 0,  # STATIC: never chase/reprice/slide
        "last_chase_ts": 0,
        "status": "PENDING",
        "entry_type": "TILE2_STATIC_PAPER",
        "research_lane": RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC,
        "edge_score": round(float(edge_score), 1),
        "size_mult": size_mult,
        "margin_usdt": float(margin_usdt),
        "leverage": leverage,
        "paper_only": True,
        "exchange_submission_blocked": True,  # PROBATION marker
        "policy_id": TILE2_POLICY_ID,
        "exit_profile_id": TILE2_EXIT_PROFILE_ID,
        "sr_episode_id": str(sr_episode_id or ""),  # Section 4 dedup key
        "exit_config": exit_cfg,
        "chase_mode": "STATIC",
        "fill_at_limit": True,
        # Audit fields (Section 8 outcome schema).
        "micro_support": float((bracket_eval or {}).get("micro_support") or 0),
        "micro_resistance": float((bracket_eval or {}).get("micro_resistance") or 0),
        "adx_at_entry": float((bracket_eval or {}).get("adx") or 0) or None,
        "session_bucket_at_entry": str((bracket_eval or {}).get("session_bucket") or ""),
        "bracket_eval_zone": str((bracket_eval or {}).get("zone") or ""),
    }
    active_signal = _register_tile2_active_signal(order, ctx=ctx, features=enriched)
    lane_register_pending_order(order)
    # Tile 2 publishes the same signed pending/order lifecycle as Continuous
    # and Type B. It remains a local paper book; only the separate platform
    # relay switch can turn this intent into a Bitfinex copy.
    if active_signal and relay_publishes_approve_outcome(
        RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC
    ):
        relay_ai = {"direction": direction}
        record_approve_outcome(
            "PENDING", None, None, trade_id, edge_score, relay_ai, active_signal
        )
        record_approve_outcome(
            "EXECUTED",
            "ORDER_PLACED",
            None,
            trade_id,
            edge_score,
            relay_ai,
            active_signal,
        )
    _record_tile2_order_lifecycle(
        trade_id,
        "PENDING",
        "BRACKET_LEG_STATIC_PAPER",
        order=order,
    )
    _mark_tile2_episode_submitted(str(sr_episode_id or ""))
    log_lane_opportunity_event(
        RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC,
        "ORDER_SUBMITTED",
        trade_id,
        direction,
        None,
        edge_score,
        block_reason="BRACKET_LEG_STATIC_PAPER",
    )
    logger.info(
        f"[TILE2] paper resting limit submitted trade_id={trade_id} dir={direction} "
        f"limit={limit_price:.2f} market={market_price:.2f} qty={qty:.6f} "
        f"entry_ttl={TILE2_ENTRY_TTL_SEC}s mode={mode} policy={TILE2_POLICY_ID} "
        f"— local paper; platform live copy remains RELAY-GATED [PIPELINE ENFORCEMENT]"
    )
    return "SPAWNED"


def spawn_combo_lanes_from_ai_scan(ctx, ai, edge_score, features, source_lane: str):
    """Fan out APPROVE to all enabled combo tiles matching entry fingerprint (independent orders).

    Independent-AI lanes, shared-direction policy lanes, and deterministic bracket
    lanes are excluded. Shared Type B is routed explicitly from the same completed
    AI result so it keeps a separate policy and order book without a duplicate call.
    """
    if not is_ai_scan_lane(source_lane) or not ai:
        return
    if not is_research_data_collection():
        return
    ai_direction = ai.get("direction")
    final_direction = ai_direction
    if state.get("invert_signal", False):
        if ai_direction == "LONG":
            final_direction = "SHORT"
        elif ai_direction == "SHORT":
            final_direction = "LONG"
    spread = int(compute_directional_spread(final_direction, ai))
    enriched = _enrich_combo_lane_features(features, ctx)
    for lane in COMBO_EXECUTION_LANES:
        # Shared-direction policy lanes are routed explicitly so their own
        # deterministic gate remains the sole entry authority.
        if (
            is_independent_ai_lane(lane)
            or (
                is_shared_ai_direction_lane(lane)
                and not is_patient_chase_lane(lane)
            )
            or is_deterministic_bracket_lane(lane)
        ):
            continue
        detail = combo_lane_match_detail(
            lane, ai, final_direction, spread, features=enriched,
        )
        ai_accepted = str(ai.get("decision") or "").upper() == "APPROVE"
        lane_enabled = is_research_lane_enabled(lane)
        policy_accepted = ai_accepted and bool(detail.get("passes"))
        if not ai_accepted:
            disposition = "AI_REJECTED_NO_ORDER"
            decision_reason = f"AI_{str(ai.get('decision') or 'REJECT').upper()}"
        elif not detail.get("passes"):
            disposition = "POLICY_FILTERED_NO_ORDER"
            decision_reason = detail.get("block_reason") or "COMBO_FILTER"
        elif not lane_enabled:
            disposition = "LANE_DISABLED_NO_ORDER"
            decision_reason = "PAPER_LANE_TOGGLE_OFF_NO_SHADOW"
        else:
            disposition = "ORDER_ELIGIBLE"
            decision_reason = "SHARED_AI_APPROVE_AND_POLICY_PASS"
        _write_v3_shared_lane_decision(
            lane, ai, ctx, enriched,
            policy_decision="ACCEPT" if policy_accepted else "REJECT",
            execution_disposition=disposition,
            exact_reason=decision_reason,
        )
        if not ai_accepted:
            continue
        if not detail.get("passes"):
            br = detail.get("block_reason") or "COMBO_FILTER"
            log_lane_opportunity_event(
                lane, "SPAWN_FILTERED", (ctx or {}).get("trade_id"),
                (ai or {}).get("direction"), (ai or {}).get("win_prob"), edge_score,
                block_reason=br,
            )
            logger.info(
                f"[{lane}] combo filter blocked spawn reason={br} "
                f"[PIPELINE ENFORCEMENT]"
            )
            continue
        _spawn_combo_lane(
            ctx, ai, edge_score, enriched, lane,
            f"COMBO_MATCH_{COMBO_LANE_SPECS[lane]['combo_key']}",
        )


def finalize_shadow_lane_collecting(study_id: str, buf: dict):
    """Simulate virtual fill + Scenario C exit for off-dashboard shadow lanes."""
    lane = str(buf.get("research_lane") or "").upper()
    if is_patient_chase_lane(lane):
        logger.error(
            "[OFFSET029_CONTRACT] discarded forbidden shadow finalization "
            f"study_id={study_id}; genuine paper lifecycle only [PIPELINE ENFORCEMENT]"
        )
        return
    # Honour explicit cancel before simulate (CANCELLED > TTL).
    explicit = str(buf.get("exit_outcome") or buf.get("block_reason") or "").upper()
    outcome = simulate_replay_outcome(buf)
    if explicit == "CANCELLED" and not outcome.get("filled"):
        outcome["exit_reason"] = "CANCELLED"
        outcome["entry_outcome"] = "CANCELLED"
    elif (
        not outcome.get("filled")
        and str(outcome.get("exit_reason") or "") in ("NO_FILL", "TTL_EXPIRED")
        and (buf.get("fill_at_limit") or str(buf.get("chase_mode") or "").upper() == "STATIC")
    ):
        outcome["exit_reason"] = "TTL_EXPIRED"
        outcome["entry_outcome"] = "TTL_EXPIRED"
    # Section 8: stable outcome schema for the Tile 2 frozen policy cohort.
    # When this row belongs to SR_MICRO_TILE_V2_STATIC, stamp the full
    # required field set so the fresh holdout cohort can never be silently
    # confused with the archived historical 346-row training sample.
    is_tile2 = (lane == RESEARCH_LANE_SR_MICRO_TILE_V2_STATIC)
    entry_features = buf.get("entry_features") or {}
    bracket_eval = entry_features.get("bracket_eval") if isinstance(entry_features, dict) else None
    row = {
        "schema": "shadow_lane_outcome_v1",
        "ts": utc_iso(),
        "study_id": study_id,
        "trade_id": study_id,
        "research_lane": lane,
        "source_trade_id": buf.get("source_trade_id"),
        "shared_ai_call_id": buf.get("shared_ai_call_id") or buf.get("source_trade_id"),
        "shared_ai_call_ts": buf.get("shared_ai_call_ts"),
        "lane_recorded_ts": utc_iso(
            datetime.fromtimestamp(float(buf.get("start_ts") or time.time()), tz=timezone.utc)
        ),
        "collection_mode": buf.get("collection_mode") or PATHWAY_STATUS_SHADOW_COLLECTING,
        "paused_shadow": bool(buf.get("paused_shadow")),
        "prompt_id": buf.get("prompt_id"),
        "adx_at_signal": buf.get("adx_at_signal"),
        "is_counterfactual": bool(buf.get("is_counterfactual")),
        "policy_entered": not bool(buf.get("is_counterfactual")),
        "policy_version": buf.get("policy_version"),
        "collection_epoch_id": buf.get("collection_epoch_id"),
        "epoch_id": buf.get("collection_epoch_id"),
        "base_policy_id": buf.get("base_policy_id"),
        "control_policy_signature": buf.get("control_policy_signature"),
        "policy_signature": buf.get("policy_signature"),
        "policy_epoch_id": buf.get("policy_epoch_id"),
        "policy_identity": copy.deepcopy(buf.get("policy_identity") or {}),
        "executed": False,
        "direction": buf.get("direction"),
        "exit_config": buf.get("exit_config"),
        "margin_usdt": buf.get("margin_usdt"),
        "size_mult": buf.get("size_mult"),
        "session_bucket": buf.get("session_bucket"),
        "entry_features": copy.deepcopy(buf.get("entry_features") or {}),
        "ai_snapshot": copy.deepcopy(buf.get("ai_snapshot") or {}),
        "bot_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "chase_mode": buf.get("chase_mode") or outcome.get("chase_mode"),
        "limit_price": buf.get("limit_price") or outcome.get("limit_price"),
        "original_limit_price": buf.get("original_limit_price") or outcome.get("original_limit_price"),
        "start_price": buf.get("start_price") or outcome.get("start_price"),
        "max_chases": buf.get("max_chases"),
        "fill_at_limit": bool(buf.get("fill_at_limit")),
        **outcome,
    }
    if is_tile2:
        # Section 8 required fields (frozen Tile 2 policy):
        #   policy_id, entry_policy_hash, exit_profile_id, source_commit,
        #   sr_episode_id, adx, utc_session_bucket, exact support level,
        #   fill/cancel/expiry reason.
        row["policy_id"] = TILE2_POLICY_ID
        row["entry_policy_hash"] = tile2_entry_policy_hash()
        row["exit_profile_id"] = (
            buf.get("exit_profile_id") or TILE2_EXIT_PROFILE_ID_PROVISIONAL
        )
        row["source_commit"] = _runtime_git_rev()
        row["sr_episode_id"] = buf.get("sr_episode_id") or ""
        row["adx"] = (
            entry_features.get("adx")
            if isinstance(entry_features, dict)
            else None
        ) or (bracket_eval or {}).get("adx")
        row["utc_session_bucket"] = row.get("session_bucket") or ""
        row["support_level"] = float(
            (bracket_eval or {}).get("micro_support")
            or buf.get("limit_price")
            or 0
        )
        # exit_reason is already in `outcome` (merged via **outcome above);
        # this alias makes the fill/cancel/expiry reason explicit on Tile 2
        # rows for the promotion-rule filter.
        row["fill_cancel_or_expiry_reason"] = (
            row.get("exit_reason") or row.get("entry_outcome") or ""
        )
    _safe_append_jsonl(SHADOW_LANE_OUTCOME_FILE, row, label=f"SHADOW_COLLECT_{lane}")
    collection_mode = str(row.get("collection_mode") or "").upper()
    v2_mode = (
        "LAB" if collection_mode == "LAB"
        else "PAUSED_SHADOW" if row.get("paused_shadow")
        else "SHADOW"
    )
    _record_type_b_research_v2_child(
        "OUTCOME",
        str(row.get("shared_ai_call_id") or ""),
        lane=lane,
        trade_id=study_id,
        mode=v2_mode,
        payload={
            "filled": bool(outcome.get("filled")),
            "net_pnl_usd": outcome.get("net_pnl_usd"),
            "max_mfe_pct": outcome.get("max_profit_margin_pct"),
            "max_mae_pct": outcome.get("max_drawdown_margin_pct"),
            "exit_reason": outcome.get("exit_reason") or outcome.get("entry_outcome"),
            "entry_price": outcome.get("entry") if outcome.get("entry") is not None else outcome.get("fill_price"),
            "exit_price": outcome.get("exit") if outcome.get("exit") is not None else outcome.get("exit_price"),
            "tick_count": len(buf.get("ticks", [])),
            "entry_mode": outcome.get("chase_mode") or row.get("chase_mode"),
        },
    )
    logger.info(
        f"[SHADOW_COLLECT] lane={lane} study_id={study_id} filled={outcome.get('filled')} "
        f"pnl=${outcome.get('net_pnl_usd')} exit={outcome.get('exit_reason')} "
        f"entry_outcome={outcome.get('entry_outcome')} chase_mode={row.get('chase_mode')} "
        f"[PIPELINE ENFORCEMENT]"
    )
    # LAB mode (OFF combo tile): record simulated PnL into the parallel lab ledger so the
    # Pathway Lab dashboard can pre-flight a strategy without real orders. Tagged `mode: "lab"`
    # and kept strictly separate from the real `lane_pnl_ledger` used for live decisions.
    if str(buf.get("collection_mode") or "") == "LAB" and outcome.get("filled") and lane:
        try:
            update_lane_lab_pnl_ledger(
                lane, "CLOSE",
                float(outcome.get("net_pnl_usd") or 0.0),
                str(buf.get("direction") or "").upper(),
            )
            logger.info(
                f"[LAB] lane={lane} study_id={study_id} simulated close recorded "
                f"net_pnl=${outcome.get('net_pnl_usd')} exit={outcome.get('exit_reason')} "
                f"[PIPELINE ENFORCEMENT]"
            )
        except Exception as e:
            logger.error(f"[LAB] ledger update failed lane={lane} study_id={study_id}: {e}")
    close_replay_buffer(study_id)


def spawn_continuous_lane_from_ai_scan(ctx, ai, edge_score, features, source_lane: str):
    """CONTINUOUS benchmark tile — mirrors AI_SCAN AI; toggle ON places limits, OFF logs shadow data only."""
    if not is_ai_scan_lane(source_lane) or not ai:
        return
    spawn_ctx = copy.deepcopy(ctx or {})
    call_id = _shared_ai_call_id(ai_result=ai, ctx=ctx)
    spawn_ctx["shared_ai_call_id"] = call_id
    spawn_ctx["shared_ai_call_ts"] = (ai or {}).get("shared_ai_call_ts")
    spawn_ctx["trade_id"] = allocate_lane_trade_id(RESEARCH_LANE_CONTINUOUS)
    orders_on = continuous_ai_research_enabled()
    continuous_ai = copy.deepcopy(ai)
    continuous_tier = continuous_score_gap_execution_tier(continuous_ai)
    continuous_accept = continuous_tier in AI_EXECUTE_TIERS
    continuous_reason = continuous_tier
    long_score = int(continuous_ai.get("long_score", 0) or 0)
    short_score = int(continuous_ai.get("short_score", 0) or 0)
    continuous_ai["raw_decision"] = str(
        continuous_ai.get("raw_decision") or continuous_ai.get("decision") or ""
    ).upper()
    continuous_ai["direction"] = derive_candidate_direction(
        long_score,
        short_score,
        continuous_ai.get("direction")
        or continuous_ai.get("candidate_direction")
        or continuous_ai.get("raw_direction"),
    )
    continuous_ai["candidate_direction"] = continuous_ai["direction"]
    continuous_ai["execution_tier"] = continuous_tier
    continuous_ai["research_soft"] = continuous_tier
    continuous_ai["decision"] = "APPROVE" if continuous_accept else "REJECT"
    continuous_ai["approved"] = continuous_accept
    # R2 spread floor (2026-08-04): backtest on 21 realized trades showed
    # spread<4 = 28.6% win rate / -$10.61 PnL vs spread>=4 = 71.4% win / -$0.15.
    # Filter weak-edge signals before they enter the chase lifecycle. Only
    # applied when AI said execute; preserves shadow data collection when AI
    # rejected.
    #
    # Stage 1 Fix #4 (2026-08-06): the prior implementation multiplied the
    # constant by 10, making the effective threshold raw gap >= 40 (8x
    # stricter than intended). The constant is now used as a RAW score-gap
    # threshold directly (raw gap >= CONTINUOUS_MIN_SPREAD_FLOOR).
    r2_floor_blocked = False
    if continuous_accept:
        spread = abs(long_score - short_score)
        if spread < CONTINUOUS_MIN_SPREAD_FLOOR:
            r2_floor_blocked = True
            continuous_accept = False
            continuous_reason = (
                f"R2_SPREAD_FLOOR_BLOCKED spread={spread}"
                f"<{CONTINUOUS_MIN_SPREAD_FLOOR}"
            )
            logger.info(
                f"[CONTINUOUS LANE] skip trade_id={spawn_ctx.get('trade_id')} "
                f"spread={spread}<{CONTINUOUS_MIN_SPREAD_FLOOR} (R2 floor) "
                f"[CONTINUOUS_R2_FLOOR]"
            )
    _stamp_shared_ai_lane_verdict(
        call_id,
        RESEARCH_LANE_CONTINUOUS,
        continuous_accept,
        continuous_reason,
        score=abs(long_score - short_score),
        policy_version="continuous_shared_direction_gap_v1",
    )
    if continuous_accept and orders_on:
        v3_disposition = "ORDER_ELIGIBLE"
        v3_reason = continuous_reason
    elif continuous_accept:
        v3_disposition = "LANE_DISABLED_DATA_ONLY"
        v3_reason = "CONTINUOUS_TOGGLE_OFF_DATA_ONLY"
    else:
        v3_disposition = "POLICY_REJECTED_NO_ORDER"
        v3_reason = continuous_reason
    _write_v3_shared_lane_decision(
        RESEARCH_LANE_CONTINUOUS,
        continuous_ai,
        spawn_ctx,
        features or {},
        policy_decision="ACCEPT" if continuous_accept else "REJECT",
        execution_disposition=v3_disposition,
        exact_reason=v3_reason,
    )
    if r2_floor_blocked:
        return
    logger.info(
        f"[CONTINUOUS LANE] spawn from {source_lane} trade_id={spawn_ctx['trade_id']} "
        f"decision={continuous_ai.get('decision')} tier={continuous_tier} "
        f"raw_decision={continuous_ai.get('raw_decision') or '-'} "
        f"orders={'ON' if orders_on else 'OFF(data-only)'} "
        f"[PIPELINE ENFORCEMENT]"
    )
    # Apply the same toggle contract as every other execution tile. ON enters
    # the local order lifecycle; OFF opens a full LAB replay. The former direct
    # process_signal call stopped at DATA_COLLECT_ONLY and produced no shadow.
    _spawn_combo_lane(
        spawn_ctx,
        continuous_ai,
        float(edge_score or 0),
        features or {},
        RESEARCH_LANE_CONTINUOUS,
        f"CONTINUOUS_FROM_{source_lane}",
    )


