def evaluate_signal_with_ai(
    raw_context: dict,
    research_lane: str = RESEARCH_LANE_CONTINUOUS,
    shadow_only: bool = False,
    trigger_reason: str = "",
    research_entry_features: dict = None,
):
    request_ts = None
    frozen_entry_context = None
    try:
        logger.info(
            f"[AI] START lane={research_lane} shadow={shadow_only} "
            f"evaluate_signal_with_ai [PIPELINE ENFORCEMENT]"
        )
        full_pipeline_trace("[AI]", "EVALUATE_START", raw_context.get("trade_id"))
        trace("AI", "EVALUATE_START", raw_context.get("trade_id"))
        debug_snapshot(None, None, "PRE_AI_EVAL")
        with state_lock:
            price = state.get("price")
        if price is None or price <= 0:
            logger.error("[AI CRITICAL] price missing - HARD FAIL [PIPELINE ENFORCEMENT]")
            full_pipeline_trace("[AI]", "HARD_FAIL_NO_PRICE", raw_context.get("trade_id"))
            trace("AI", "HARD_FAIL_NO_PRICE", raw_context.get("trade_id"))
            debug_snapshot(None, None, "AI_NO_PRICE")
            raise RuntimeError("AI CALLED WITHOUT VALID PRICE - PIPELINE VIOLATION")
        ctx = copy.deepcopy(raw_context)
        if not ctx:
            logger.warning("[AI] Context build failed - using fallback reject [PIPELINE ENFORCEMENT]")
            return {"win_prob": 0, "direction": "NO_TRADE", "decision": "REJECT", "override": False, "comment": "CONTEXT_FALLBACK", "ai_error": True, "factors": {}, "source": "FALLBACK", "approved": False, "trade_id": raw_context.get("trade_id")}
        if not ctx.get("ai_input_upgrade"):
            ctx = enrich_ai_context_upgrade(ctx)
        ctx = sanitize_ai_inputs(ctx)
        ok, reason = validate_ai_features(ctx)
        if not ok:
            logger.warning(f"[AI] Feature validation failed: {reason} - reject without API call [PIPELINE ENFORCEMENT]")
            return {"win_prob": 0, "direction": "NO_TRADE", "decision": "REJECT", "override": False, "comment": f"FEATURE_VALIDATION:{reason}", "ai_error": True, "factors": {}, "source": "VALIDATION", "approved": False, "trade_id": raw_context.get("trade_id")}
        global LAST_AI_PAYLOAD, LAST_AI_TIMESTAMP
        if not shadow_only:
            LAST_AI_PAYLOAD = copy.deepcopy(ctx)
            LAST_AI_TIMESTAMP = utc_iso()
        logger.info(f"[AI PAYLOAD SNAPSHOT] lane={research_lane} {ctx} [PIPELINE ENFORCEMENT]")
        temperature = research_ai_temperature()
        replay_eval = compute_replay_model_eval(ctx, float(state.get("last_edge") or ctx.get("edge_score") or 0))
        with state_lock:
            state["last_replay_model_eval"] = copy.deepcopy(replay_eval)
        # One shared direction prompt is the only runtime AI layer.
        prompt = AI_PROMPT_TEMPLATE.format(context=json.dumps(ctx, indent=2))
        if is_research_data_collection() and AI_RESEARCH_MODE_ENABLED:
            prompt += RESEARCH_AI_PROMPT_ADDENDUM
        if not trigger_reason:
            trigger_reason = state.get("debug_state", {}).get("edge_trigger_reason") or ""
        request_ts = utc_iso()
        frozen_entry_context = _freeze_type_b_research_v2_entry_context(
            research_entry_features or {},
            ctx,
        )
        if os.environ.get("DEMO_MODE_ENABLED", "").lower() == "true":
            from demo_mode import cassette_lookup, cassette_record
            cassette_resp = cassette_lookup(_deepseek_model(), temperature, prompt[:256])
            if cassette_resp:
                response_data = cassette_resp.get("response", cassette_resp.get("body", {}))
                text = response_data.get("choices", [{}])[0].get("message", {}).get("content", "")
                if not text:
                    text = json.dumps(response_data) if isinstance(response_data, dict) else str(response_data)
                latency_ms = 5
                log_pipeline_event("AI", "API_OK_CASSETTE", "DEEPSEEK_CASSETTE_REPLAY", ctx.get("trade_id"), state.get("last_edge"), {"latency_ms": latency_ms}, force=True)
            else:
                text, latency_ms = call_deepseek_api(
                    [{"role": "user", "content": prompt}],
                    temperature=temperature,
                    purpose="trading_direction",
                )
                log_pipeline_event("AI", "API_OK", "DEEPSEEK_RESPONSE", ctx.get("trade_id"), state.get("last_edge"), {"latency_ms": latency_ms}, force=True)
        else:
            text, latency_ms = call_deepseek_api(
                [{"role": "user", "content": prompt}],
                temperature=temperature,
                purpose="trading_direction",
            )
            log_pipeline_event("AI", "API_OK", "DEEPSEEK_RESPONSE", ctx.get("trade_id"), state.get("last_edge"), {"latency_ms": latency_ms}, force=True)
        logger.info(f"[AI RAW RESPONSE] {text} [PIPELINE ENFORCEMENT]")
        parsed = parse_ai_response_fields(text)
        direction = parsed["direction"]
        win_prob = parsed["win_prob"]
        decision = parsed["decision"]
        factors = parsed["factors"]
        override = parsed["override"]
        trade_plan = parse_ai_trade_planner(text, json_blob=parsed.get("json_blob"))
        if parsed.get("parsed_decision_from_json"):
            logger.info(
                f"[AI PARSE] JSON-only response — derived decision={decision} dir={direction} "
                f"prob={win_prob} long={factors.get('long_score')} short={factors.get('short_score')} "
                f"[PIPELINE ENFORCEMENT]"
            )
        ai_result = {
            "win_prob": win_prob,
            "direction": direction,
            "candidate_direction": parsed.get("candidate_direction") or direction,
            "raw_direction": parsed.get("raw_direction"),
            "confidence_requested": False,
            "decision": decision,
            "override": override,
            "comment": ("[AI_RETURNED_ZERO_SCORES] " + text) if parsed.get("zero_score_reject") else text,
            "reason": ("AI_RETURNED_ZERO_SCORES" if parsed.get("zero_score_reject")
                       else str((parsed.get("json_blob") or {}).get("reason") or "")),
            "ai_error": False,
            "factors": factors,
            "bull_score": factors.get("bull_score", 0),
            "bear_score": factors.get("bear_score", 0),
            "long_score": factors.get("long_score", 0),
            "short_score": factors.get("short_score", 0),
            "preferred_direction": factors.get("preferred_direction"),
            "source": "FRESH",
            "approved": decision in AI_EXECUTE_TIERS,
            "trade_id": ctx.get("trade_id"),
            "shared_ai_call_id": ctx.get("trade_id"),
            "latency_ms": latency_ms,
            "research_lane": research_lane,
            "research_model": research_lane_label(research_lane),
            "shadow_only": shadow_only,
            "trade_planner": trade_plan,
            "prompt_id": SHARED_DIRECTION_PROMPT_ID,
            "deepseek_model": _deepseek_model(),
            "deepseek_thinking_mode": _deepseek_thinking_mode(),
            "_type_b_research_v2_request_ts": request_ts,
            "_type_b_research_v2_entry_context": frozen_entry_context,
        }
        ai_result = apply_trend_hierarchy_gate(ctx, ai_result)
        ai_result = normalize_research_ai_decision(ai_result)
        # Stage 1 Fix #3: hard-reject counter-structure directions before lane
        # spawn. Runs after trend_hierarchy (which may have already SOFT_REJECTed
        # weak counter-trend verdicts) so the worst-case LONG-vs-BEAR_CONTINUATION
        # pattern is blocked even when trend continuation does not hold.
        ai_result = apply_structure_agreement_gate(ctx, ai_result)
        ai_result = normalize_research_ai_decision(ai_result)
        if not shadow_only:
            ai_result = apply_phase_c_factor_gate(ai_result)
            ai_result = normalize_research_ai_decision(ai_result)
            if DOUBLE_CONFIRM_AI:
                ai_result = double_confirm_ai(ai_result, ctx)
                ai_result = apply_phase_c_factor_gate(ai_result)
                ai_result = normalize_research_ai_decision(ai_result)
        with state_lock:
            if not shadow_only:
                state["pipeline_outcome"] = "AI_EVALUATED"
        ai_result["_tranche_logged"] = True
        tranche_event = "AI_SHADOW" if shadow_only else "AI_DECISION"
        log_ai_tranche_outcome(ai_result, event=tranche_event)
        if not shadow_only or research_lane in (RESEARCH_LANE_TYPE_B_HUNTER_V1, RESEARCH_LANE_SR_MICRO_TILE_V1):
            _append_ai_history_row(ai_result)
            _sync_ai_dashboard_debug(ai_result)
            _emit_genome_ai_events(ai_result)
            with state_lock:
                eff = get_effective_edge_threshold()
                state["debug_state"]["ai_gate"] = {
                    "called": True,
                    "reason": ai_result.get("decision", "AI_DONE"),
                    "edge": state.get("last_edge", 0.0),
                    "threshold": eff,
                }
        log_pipeline_event(
            "AI", ai_result.get("decision", "UNKNOWN"),
            f"{research_lane}_{ai_result.get('factor_gate') or 'MODEL'}",
            ctx.get("trade_id"), state.get("last_edge"),
            {"win_prob": win_prob, "latency_ms": latency_ms, "lane": research_lane, "shadow": shadow_only},
            force=True,
        )
        logger.info(
            f"[AI CALL] lane={research_lane} shadow={shadow_only} dir={direction} prob={win_prob} "
            f"decision={ai_result.get('decision')} bull={factors.get('bull_score')} "
            f"bear={factors.get('bear_score')} gate={ai_result.get('factor_gate', 'none')} "
            f"approved={ai_result['approved']} [PIPELINE ENFORCEMENT]"
        )
        full_pipeline_trace("[AI]", "EVALUATE_COMPLETE", raw_context.get("trade_id"))
        trace("AI", "EVALUATE_COMPLETE", raw_context.get("trade_id"))
        if not shadow_only:
            debug_snapshot(None, ai_result, "POST_AI_EVAL")
        if not ai_result.get("ai_error"):
            with state_lock:
                state["ai_call_count"] = state.get("ai_call_count", 0) + 1
        if is_research_data_collection():
            log_ai_input_full(
                ctx, ai_result, replay_eval, temperature, trigger_reason,
                research_lane=research_lane, shadow_only=shadow_only,
            )
            # These are optional, derived research studies.  Never execute them
            # synchronously on the sole periodic-AI cadence thread: replay-lock
            # contention previously wedged all subsequent three-minute calls.
            enqueue_post_ai_research_hooks(ctx, ai_result, research_lane)
        if not shadow_only:
            increment_pipeline_funnel("AI_CALLED")
            tier = str(ai_result.get("execution_tier") or ai_result.get("decision") or "").upper()
            if tier in AI_EXECUTE_TIERS or ai_result.get("decision") == "APPROVE":
                increment_pipeline_funnel("AI_APPROVE")
            else:
                increment_pipeline_funnel("AI_REJECT")
            log_ai_edge_disagreement(
                ctx, ai_result, float(state.get("last_edge") or ctx.get("edge_score") or 0), research_lane,
            )
        logger.info(
            f"[AI RESULT] lane={research_lane} decision={ai_result['decision']} "
            f"prob={ai_result['win_prob']} temp={temperature} "
            f"replay={replay_eval.get('replay_score')} "
            f"replay_approve={replay_eval.get('replay_approve')} [PIPELINE ENFORCEMENT]"
        )
        if not shadow_only:
            update_debug_state_always("AI_COMPLETE", {"ai_decision": ai_result.get("decision")})
        return ai_result
    except Exception as e:
        logger.error(f"[AI CRASH] lane={research_lane} shadow={shadow_only} {e} [PIPELINE ENFORCEMENT]")
        ai_result = build_ai_error_result(e, raw_context.get("trade_id"))
        ai_result["research_lane"] = research_lane
        ai_result["shadow_only"] = shadow_only
        ai_result["prompt_id"] = SHARED_DIRECTION_PROMPT_ID
        if request_ts and frozen_entry_context:
            ai_result["_type_b_research_v2_request_ts"] = request_ts
            ai_result["_type_b_research_v2_entry_context"] = frozen_entry_context
        full_pipeline_trace("[AI]", "EVALUATE_CRASH", raw_context.get("trade_id"))
        trace("AI", "EVALUATE_CRASH", raw_context.get("trade_id"))
        if not shadow_only:
            debug_snapshot(None, ai_result, "AI_CRASH")
        log_ai_error_row(ai_result, raw_context)
        log_ai_tranche_outcome(ai_result, event="AI_SHADOW_ERROR" if shadow_only else "AI_ERROR")
        log_pipeline_event(
            "AI", "AI_ERROR", f"{research_lane}_{ai_result.get('error_type', 'UNKNOWN')}",
            raw_context.get("trade_id"), state.get("last_edge"),
            {"detail": (ai_result.get("error_detail") or "")[:200], "lane": research_lane, "shadow": shadow_only},
            force=True,
        )
        if not shadow_only or research_lane in (RESEARCH_LANE_TYPE_B_HUNTER_V1, RESEARCH_LANE_SR_MICRO_TILE_V1):
            _append_ai_history_row(ai_result)
            with state_lock:
                state["pipeline_outcome"] = "AI_CRASH"
                eff = get_effective_edge_threshold()
                state["debug_state"]["ai_gate"] = {
                    "called": True,
                    "reason": f"AI_ERROR:{ai_result.get('error_type', 'unknown')}",
                    "edge": state.get("last_edge", 0.0),
                    "threshold": eff,
                }
                state["debug_state"]["skip_reason"] = f"AI_ERROR:{ai_result.get('error_type', 'unknown')}"
            _sync_ai_dashboard_debug(ai_result)
            _emit_genome_ai_events(ai_result)
        with state_lock:
            state["ai_call_count"] = state.get("ai_call_count", 0) + 1
        logger.info(
            f"[AI RESULT] lane={research_lane} decision={ai_result['decision']} "
            f"prob={ai_result['win_prob']} err={ai_result.get('error_type')} [PIPELINE ENFORCEMENT]"
        )
        return ai_result

def is_research_data_collection() -> bool:
    with state_lock:
        return state.get("strategy_mode") == "RESEARCH" and not state.get("live_armed")

def _clamp_ai_threshold(value: float) -> float:
    return max(AI_THRESHOLD_MIN, min(AI_THRESHOLD_MAX, float(value)))

def get_ai_threshold():
    with state_lock:
        t = state.get("ai_threshold")
        research = state.get("strategy_mode") == "RESEARCH"
        default = RESEARCH_AI_THRESHOLD_DEFAULT if research else LIVE_AI_THRESHOLD_FLOOR
        raw = default if t is None else float(t)
        if research or state.get("_threshold_locked"):
            return _clamp_ai_threshold(raw)
        return _clamp_ai_threshold(max(raw, LIVE_AI_THRESHOLD_FLOOR))

def set_ai_threshold(value):
    with state_lock:
        research = state.get("strategy_mode") == "RESEARCH"
        default = RESEARCH_AI_THRESHOLD_DEFAULT if research else LIVE_AI_THRESHOLD_FLOOR
        raw = float(value) if value is not None else default
        state["ai_threshold"] = _clamp_ai_threshold(raw)
        state["_threshold_locked"] = True
        state["last_ai_ts"] = 0
        state["last_ai_signal_key"] = None
        state["last_ai_confidence"] = 0
        state["ai_verdict"] = _ai_execution_verdict_text()
        save_persistent_config()
        logger.info(f"[SET] AI threshold locked to {state['ai_threshold']} [PIPELINE ENFORCEMENT]")


def _ai_bands_from_legacy_threshold(threshold: float) -> dict:
    """Map old single min-threshold to band checkboxes (bands with any prob >= threshold)."""
    try:
        thr = float(threshold)
    except (TypeError, ValueError):
        thr = RESEARCH_AI_THRESHOLD_DEFAULT
    out = {band_id: False for band_id, _, _ in AI_EXECUTION_BAND_DEFS}
    for band_id, lo, hi in AI_EXECUTION_BAND_DEFS:
        if band_id == "65+":
            out[band_id] = thr <= 65
        elif band_id == "60-66":
            out[band_id] = thr <= 66
        else:
            out[band_id] = hi > thr
    return out


def _default_chase_execution_buckets() -> dict:
    """All OFF until admin ticks buckets on the dashboard — no implicit immediate placement."""
    return {k: False for k in CHASE_EXECUTION_BUCKET_ORDER}


def _normalize_chase_execution_buckets(raw) -> dict:
    """Normalize current exact buckets and migrate the earlier grouped schema."""
    out = _default_chase_execution_buckets()
    if not isinstance(raw, dict):
        return out
    if "3-5_chases" in raw:
        grouped_3_5 = bool(raw["3-5_chases"])
        out["3_chases"] = grouped_3_5
        out["4_chases"] = grouped_3_5
        out["5+_chases"] = grouped_3_5
    if "6+_chases" in raw:
        out["5+_chases"] = bool(raw["6+_chases"])
    for key in out:
        if key in raw:
            out[key] = bool(raw[key])
    return out


def _default_ai_execution_bands() -> dict:
    """All OFF until admin ticks AI bands on the dashboard."""
    return {band_id: False for band_id, _, _ in AI_EXECUTION_BAND_DEFS}


def _normalize_ai_execution_bands(raw, *, allow_empty: bool = False) -> dict:
    base = _default_ai_execution_bands()
    if isinstance(raw, dict):
        for band_id in base:
            if band_id in raw:
                base[band_id] = bool(raw[band_id])
    if not any(base.values()) and not allow_empty:
        return _default_ai_execution_bands()
    return base


def get_ai_execution_bands() -> dict:
    with state_lock:
        raw = state.get("ai_execution_bands")
    if raw is None:
        return _default_ai_execution_bands()
    return _normalize_ai_execution_bands(raw, allow_empty=True)


def set_ai_execution_bands(bands: dict):
    normalized = _normalize_ai_execution_bands(bands or {}, allow_empty=True)
    with state_lock:
        state["ai_execution_bands"] = normalized
        enabled = [k for k, v in normalized.items() if v]
        state["ai_verdict"] = _ai_execution_verdict_text()
        save_persistent_config()
    logger.info(f"[SET] AI execution bands={enabled} [PIPELINE ENFORCEMENT]")


def _ai_prob_in_band(prob: float, band_id: str, lo: float, hi: float) -> bool:
    if band_id == "65+":
        return prob >= 65
    if band_id == "60-66":
        return 60 <= prob <= 66
    return lo <= prob < hi


def ai_win_prob_in_execution_bands(prob) -> bool:
    """v12 — AI confidence no longer gates execution (constant-62, zero signal).

    The DeepSeek win-prob call returns ``62`` for 831/853 trades; it carries no
    discriminating information, so v12 makes it advisory-only. This function
    always returns True so no execution path is blocked on AI confidence. The
    dashboard still records the band selection (informational telemetry) and the
    raw value is still logged to ``ai_input_log.jsonl`` for future analysis, but
    the gate itself is a permanent pass-through.

    Per-tile deterministic gates (TYPE_B_HUNTER_V1 scorer, SR_MICRO_TILE_V2_STATIC
    ADX cap, CONTINUOUS spread/chase) decide entry; the AI is asked only for
    direction (LONG / SHORT / NO_TRADE).
    """
    return True


def dashboard_ai_band_blocks(prob) -> bool:
    """v12 — never blocks. See ``ai_win_prob_in_execution_bands``."""
    return False


def _ai_execution_verdict_text() -> str:
    bands = get_ai_execution_bands()
    enabled = [k for k, v in bands.items() if v]
    if enabled:
        return f"AI reviewer {'ON' if state.get('ai_enabled') else 'OFF'} | Bands {', '.join(enabled)}"
    return f"AI reviewer {'ON' if state.get('ai_enabled') else 'OFF'} | Threshold {state.get('ai_threshold', 'WAITING')}"


def chase_count_bucket(chase_count) -> str:
    try:
        n = int(chase_count or 0)
    except (TypeError, ValueError):
        n = 0
    if n <= 0:
        return "0_chases"
    if n == 1:
        return "1_chase"
    if n == 2:
        return "2_chases"
    if n == 3:
        return "3_chases"
    if n == 4:
        return "4_chases"
    return "5+_chases"


def chase_age_window_index(age_sec) -> int:
    """Map signal age onto the 5-minute chase schedule (0..5)."""
    try:
        age = max(0.0, float(age_sec or 0))
    except (TypeError, ValueError):
        age = 0.0
    return min(int(age // CHASE_WINDOW_SEC), CHASE_WINDOW_MAX_INDEX)


def chase_window_start_sec(window_idx) -> int:
    try:
        idx = max(0, int(window_idx or 0))
    except (TypeError, ValueError):
        idx = 0
    return min(idx, CHASE_WINDOW_MAX_INDEX) * CHASE_WINDOW_SEC


def last_enabled_chase_count():
    last = None
    for n in range(0, CHASE_WINDOW_MAX_INDEX + 1):
        if chase_bucket_allowed(n):
            last = n
    return last


def _order_signal_age_sec(order: dict, signal: dict, now: float) -> float:
    return _chase_lifecycle_age_sec(order, signal, now)


def chase_age_window_should_cancel(age_sec) -> bool:
    """Cancel only when every chase window is off.

    Early disabled windows (0/1 OFF) wait to submit; they must not kill a
    resting order just because count ticked to 5+ at ~9 min. After the last
    enabled window (5+ OFF), rest until 30 min TTL.
    """
    last = last_enabled_chase_count()
    if last is None:
        return True
    idx = chase_age_window_index(age_sec)
    if idx > last:
        return False
    mn = min_enabled_chase_count()
    if mn is not None and idx < mn:
        return False
    return not chase_bucket_allowed(idx)


def chase_age_window_may_reprice(age_sec) -> bool:
    idx = chase_age_window_index(age_sec)
    last = last_enabled_chase_count()
    if last is None:
        return False
    if idx > last:
        return False
    return chase_bucket_allowed(idx)


def get_chase_execution_buckets() -> dict:
    with state_lock:
        raw = state.get("chase_execution_buckets")
    return _normalize_chase_execution_buckets(raw)


def set_chase_execution_buckets(buckets: dict):
    out = _normalize_chase_execution_buckets(buckets)
    with state_lock:
        state["chase_execution_buckets"] = out
        save_persistent_config()
    enabled = [k for k, v in out.items() if v]
    logger.info(f"[SET] Chase execution buckets={enabled} [PIPELINE ENFORCEMENT]")
    _record_execution_settings_epoch("CHASE_CHANGED")
    _patch_api_state_cache_fields(
        chase_execution_buckets=out,
        dashboard_execution_gates=get_dashboard_execution_status(),
    )
    enforce_dashboard_chase_gates_on_pending()
    pipeline_state_sync()


def chase_bucket_allowed(chase_count) -> bool:
    bucket = chase_count_bucket(chase_count)
    buckets = get_chase_execution_buckets()
    if not any(buckets.values()):
        return False
    return bool(buckets.get(bucket, False))


def _spread_gate_bucket(spread) -> str:
    try:
        s = int(spread)
    except (TypeError, ValueError):
        s = 0
    if s >= 5:
        return "5+"
    if s < 0:
        return "0"
    return str(s)


def _default_spread_gate() -> dict:
    """Default: spread 0,1,2,3 BLOCKED (unchecked); 4 and 5+ ALLOWED (checked)."""
    return {k: (k not in ("0", "1", "2", "3")) for k in SPREAD_GATE_BUCKET_ORDER}


def get_spread_gate() -> dict:
    with state_lock:
        raw = state.get("spread_gate")
    if not isinstance(raw, dict):
        return _default_spread_gate()
    out = _default_spread_gate()
    for k in out:
        if k in raw:
            out[k] = bool(raw[k])
    return out


def set_spread_gate(gate: dict):
    out = _default_spread_gate()
    if isinstance(gate, dict):
        for k in out:
            if k in gate:
                out[k] = bool(gate[k])
    with state_lock:
        state["spread_gate"] = out
        save_persistent_config()
    enabled = [k for k, v in out.items() if v]
    logger.info(f"[SET] Spread gate allowed buckets={enabled} [PIPELINE ENFORCEMENT]")
    _record_execution_settings_epoch("GAP_CHANGED")
    _patch_api_state_cache_fields(
        spread_gate=out,
        dashboard_execution_gates=get_dashboard_execution_status(),
    )


def _enabled_execution_settings() -> dict:
    chase = get_chase_execution_buckets()
    gap = get_spread_gate()
    return {
        "gap_buckets": [key for key in SPREAD_GATE_BUCKET_ORDER if gap.get(key)],
        "chase_buckets": [
            key.replace("_chases", "").replace("_chase", "")
            for key in CHASE_EXECUTION_BUCKET_ORDER
            if chase.get(key)
        ],
    }


def _execution_settings_signature(settings: dict) -> str:
    return "gap=" + ",".join(settings.get("gap_buckets") or []) + "|chase=" + ",".join(
        settings.get("chase_buckets") or []
    )


def _record_execution_settings_epoch(reason: str, force: bool = False) -> None:
    """Append one durable epoch only when the canonical gap/chase selection changes."""
    global _cached_pathway_lane_specs
    settings = _enabled_execution_settings()
    signature = _execution_settings_signature(settings)
    row = {
        "ts": utc_iso(),
        "epoch": time.time(),
        "reason": str(reason or "SETTINGS_CHANGED"),
        "signature": signature,
        **settings,
    }
    with _execution_settings_history_lock:
        last = None
        try:
            with open(EXECUTION_SETTINGS_HISTORY_FILE, encoding="utf-8") as handle:
                for line in handle:
                    try:
                        candidate = json.loads(line)
                    except (TypeError, ValueError):
                        continue
                    if isinstance(candidate, dict):
                        last = candidate
        except FileNotFoundError:
            pass
        if not force and last and last.get("signature") == signature:
            return
        _safe_append_jsonl(EXECUTION_SETTINGS_HISTORY_FILE, row, label="EXECUTION_SETTINGS")
    _settings_breakdown_cache["key"] = None
    _cached_pathway_lane_specs = {}


def _fresh_collection_start_epoch() -> float:
    try:
        with open(RESEARCH_SESSION_FILE, encoding="utf-8") as handle:
            session = json.load(handle) or {}
        return float(
            session.get("fresh_collection_start_time")
            or session.get("bot_start_time")
            or bot_start_time
            or 0
        )
    except Exception:
        return float(bot_start_time or 0)


def _row_epoch(value) -> float:
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return datetime.fromisoformat(str(value or "").replace("Z", "+00:00")).timestamp()
    except Exception:
        return 0.0


def _settings_period_breakdown() -> dict:
    """Exact fresh-collection PnL by recorded settings epoch; legacy settings stay unknown."""
    files = (EXECUTION_SETTINGS_HISTORY_FILE, CSV_TRADES, TYPE_B_RESEARCH_V2_EVENT_FILE)
    key = tuple(
        (path, os.path.getmtime(path), os.path.getsize(path))
        for path in files
        if os.path.isfile(path)
    )
    if _settings_breakdown_cache.get("key") == key:
        return copy.deepcopy(_settings_breakdown_cache.get("value") or {})

    start = _fresh_collection_start_epoch()
    now = time.time()
    epochs = []
    try:
        with open(EXECUTION_SETTINGS_HISTORY_FILE, encoding="utf-8") as handle:
            for line in handle:
                try:
                    row = json.loads(line)
                except (TypeError, ValueError):
                    continue
                ts = float(row.get("epoch") or _row_epoch(row.get("ts")))
                if ts >= start:
                    epochs.append({**row, "epoch": ts})
    except FileNotFoundError:
        pass
    epochs.sort(key=lambda row: row["epoch"])
    compact = []
    for row in epochs:
        if compact and compact[-1].get("signature") == row.get("signature"):
            continue
        compact.append(row)
    periods = []
    if not compact or compact[0]["epoch"] > start + 1:
        periods.append({
            "start": start,
            "end": compact[0]["epoch"] if compact else now,
            "signature": "legacy-unrecorded",
            "gap_buckets": [],
            "chase_buckets": [],
            "settings_recorded": False,
        })
    for index, row in enumerate(compact):
        periods.append({
            "start": row["epoch"],
            "end": compact[index + 1]["epoch"] if index + 1 < len(compact) else now,
            "signature": row.get("signature"),
            "gap_buckets": row.get("gap_buckets") or [],
            "chase_buckets": row.get("chase_buckets") or [],
            "settings_recorded": True,
        })

    lanes = (RESEARCH_LANE_TYPE_B_HUNTER_V1, RESEARCH_LANE_CONTINUOUS)
    output = {lane: [] for lane in lanes}
    trades = []
    try:
        with open(CSV_TRADES, encoding="utf-8-sig", newline="") as handle:
            for row in csv.DictReader(handle):
                lane = str(row.get("research_lane") or "").upper()
                ts = _row_epoch(row.get("ts") or row.get("close_ts"))
                if lane in output and ts >= start:
                    trades.append((lane, ts, float(row.get("net_pnl_usd") or 0)))
    except (FileNotFoundError, OSError, ValueError):
        pass

    approvals = []
    try:
        for event in load_type_b_research_v2_events(os.getcwd()):
            if event.get("event") != "LANE_VERDICT":
                continue
            lane = str(event.get("lane") or "").upper()
            opportunity_id = str(event.get("opportunity_id") or "")
            if lane not in output or opportunity_id in ("scan-history-1", "scan-continuous-off"):
                continue
            payload = event.get("payload") or {}
            if not bool(payload.get("accepted") or payload.get("ok")):
                continue
            ts = float(payload.get("stamped_at") or _row_epoch(event.get("ts")))
            if ts >= start:
                approvals.append((lane, ts, opportunity_id))
    except Exception:
        pass

    for lane in lanes:
        for index, period in enumerate(periods):
            lane_trades = [
                pnl for trade_lane, ts, pnl in trades
                if trade_lane == lane and period["start"] <= ts < period["end"]
            ]
            approved_ids = {
                opportunity_id for approval_lane, ts, opportunity_id in approvals
                if approval_lane == lane and period["start"] <= ts < period["end"]
            }
            pnl = round(sum(lane_trades), 2)
            approved = len(approved_ids)
            output[lane].append({
                **period,
                "period_number": index + 1,
                "current": index == len(periods) - 1,
                "approvals": approved,
                "executed": len(lane_trades),
                "pnl_usd": pnl,
                "ev_per_approval": round(pnl / approved, 2) if approved else None,
            })
    _settings_breakdown_cache["key"] = key
    _settings_breakdown_cache["value"] = copy.deepcopy(output)
    return output


def _reconcile_settings_periods_to_headline(stats: dict, periods: list) -> list:
    """Keep the settings table on the same approval cohort as the analyzer headline."""
    rows = copy.deepcopy(periods or [])
    if not rows:
        return rows
    try:
        target = max(0, int((stats or {}).get("approves") or 0))
    except (TypeError, ValueError):
        return rows
    legacy = [row for row in rows if not row.get("settings_recorded")]
    if not legacy:
        return rows
    recorded = sum(
        max(0, int(row.get("approvals") or 0))
        for row in rows
        if row.get("settings_recorded")
    )
    # Analyzer stats exclude synthetic/duplicate research events. Assign the
    # remaining authoritative approvals to the single pre-tracking baseline
    # instead of exposing a contradictory raw-event count.
    legacy_target = max(0, target - recorded)
    for row in legacy[:-1]:
        row["approvals"] = 0
        row["ev_per_approval"] = None
    row = legacy[-1]
    row["approvals"] = legacy_target
    pnl = float(row.get("pnl_usd") or 0)
    row["ev_per_approval"] = (
        round(pnl / legacy_target, 2) if legacy_target else None
    )
    return rows


def spread_gate_allows(spread) -> bool:
    bucket = _spread_gate_bucket(spread)
    gate = get_spread_gate()
    return bool(gate.get(bucket, False))


def _signal_directional_spread(signal: dict, ai: dict) -> int:
    """Normalized directional score gap on the legacy 0–10 scale."""
    # The signal's frozen entry value is authoritative. The trades-map AI
    # payload can be intentionally compact and omit LONG/SHORT scores; blindly
    # recomputing from it turns a real gap into bucket 0.
    for key in ("directional_spread", "conviction_spread"):
        explicit = (signal or {}).get(key)
        if explicit is not None:
            try:
                return int(explicit)
            except (TypeError, ValueError):
                pass
    direction = str(
        (signal or {}).get("final_direction") or _signal_direction(signal) or "LONG"
    ).upper()
    merged_ai = dict(ai or {})
    if not merged_ai.get("long_score"):
        merged_ai["long_score"] = signal.get("long_score_at_entry")
    if not merged_ai.get("short_score"):
        merged_ai["short_score"] = signal.get("short_score_at_entry")
    if not merged_ai.get("bull_score"):
        merged_ai["bull_score"] = signal.get("bull_score_at_entry")
    if not merged_ai.get("bear_score"):
        merged_ai["bear_score"] = signal.get("bear_score_at_entry")
    return compute_directional_spread(direction, merged_ai)


def _signal_spread_gate_blocked(signal: dict, ai: dict) -> tuple:
    """Returns (blocked, bucket, spread). blocked=True means limit submit must be skipped."""
    spread = _signal_directional_spread(signal, ai or {})
    bucket = _spread_gate_bucket(spread)
    return (not spread_gate_allows(spread)), bucket, spread


def dashboard_chase_bucket_blocks(chase_count) -> bool:
    """Hard dashboard gate — blocks limit submit, chase steps, and fills for this chase count."""
    return not chase_bucket_allowed(chase_count)


def min_enabled_chase_count() -> Optional[int]:
    """Lowest limit_chase_count / virtual count allowed to submit a limit."""
    if not any(get_chase_execution_buckets().values()):
        return None
    for n in range(0, 20):
        if chase_bucket_allowed(n):
            return n
    return None


def _next_enabled_chase_after(chase_n: int) -> Optional[int]:
    """Next chase tick with an enabled bucket, or None if no later bucket is allowed."""
    for n in range(int(chase_n or 0) + 1, 20):
        if chase_bucket_allowed(n):
            return n
    return None


def dashboard_virtual_defer_required() -> bool:
    mn = min_enabled_chase_count()
    return mn is not None and mn > 0


def _signal_virtual_chase_count(signal: dict) -> int:
    if not isinstance(signal, dict):
        return 0
    return int(
        signal.get("dashboard_virtual_chase_count")
        or signal.get("chase_3plus_virtual_chase_count")
        or 0
    )


def dashboard_virtual_chase_submit_ready(signal: dict) -> bool:
    """True when signal age is inside an enabled 5-minute chase window at/after the minimum."""
    mn = min_enabled_chase_count()
    if mn is None:
        return False
    age = _signal_age_sec(signal) if isinstance(signal, dict) else 0.0
    if age < chase_window_start_sec(mn):
        return False
    idx = chase_age_window_index(age)
    if not chase_bucket_allowed(idx):
        return False
    return idx >= mn


def _resolve_selected_virtual_submit_limit(signal: dict) -> Optional[tuple]:
    """Carry the selected virtual-chase price into the first resting limit.

    The virtual gate has already advanced ``chase_3plus_virtual_limit`` toward
    market. Re-running the normal deterministic resolver at promotion would
    reset that price to the original 0.1% anchor while still labelling the
    order as chase 2/3/4. That breaks both execution fidelity and the research
    cohort. Preserve the chased price and its original anchor as separate
    values so later visible chase steps retain the correct gap baseline.
    """
    if not isinstance(signal, dict) or not dashboard_virtual_chase_submit_ready(signal):
        return None
    try:
        virtual_limit = float(
            signal.get("chase_3plus_virtual_limit")
            or signal.get("dashboard_virtual_limit")
            or signal.get("limit_price")
            or 0
        )
    except (TypeError, ValueError):
        return None
    if virtual_limit <= 0:
        return None
    try:
        original_limit = float(
            signal.get("chase_3plus_original_limit")
            or signal.get("original_limit_price")
            or virtual_limit
        )
    except (TypeError, ValueError):
        original_limit = virtual_limit
    if original_limit <= 0:
        original_limit = virtual_limit
    entry_mode = str(signal.get("entry_mode") or ENTRY_MODE_AI_DIRECT)
    return virtual_limit, entry_mode, {
        "reanchored": bool(signal.get("smart_submit_reanchored")),
        "immediate_chase": True,
        "original_planned": original_limit,
        "preserve_original_limit": True,
        "selected_virtual_chase_count": _signal_virtual_chase_count(signal),
    }


def get_dashboard_execution_status(signal: dict = None, ai: dict = None) -> dict:
    """Snapshot of dashboard execution gates for API / logging."""
    bands = get_ai_execution_bands()
    chase = get_chase_execution_buckets()
    sg = get_spread_gate()
    mn = min_enabled_chase_count()
    with state_lock:
        lev = int(state.get("leverage") or DEFAULT_RESEARCH_LEVERAGE)
        max_sig = get_effective_max_active_signals()
        ai_on = bool(state.get("ai_enabled", True))
        pull = float(state.get("pullback_threshold") or 0)
        bfx = bool(state.get("bitfinex_live_enabled"))
    vcount = _signal_virtual_chase_count(signal or {})
    return {
        "hard_wired": True,
        "ai_reviewer_enabled": ai_on,
        "ai_bands_enabled": [k for k, v in bands.items() if v],
        "chase_buckets_enabled": [k for k, v in chase.items() if v],
        "spread_gate_allowed": [k for k, v in sg.items() if v],
        "spread_gate_blocked": [k for k, v in sg.items() if not v],
        "min_chase_count_to_submit": mn,
        "chase_window_sec": CHASE_WINDOW_SEC,
        "chase_windows": {
            "0": "0-5m",
            "1": "5-10m",
            "2": "10-15m",
            "3": "15-20m",
            "4": "20-25m",
            "5+": "25-30m",
        },
        "virtual_defer_active": dashboard_virtual_defer_required(),
        "virtual_chase_count": vcount,
        "virtual_submit_ready": dashboard_virtual_chase_submit_ready(signal or {"dashboard_virtual_chase_count": vcount}),
        "max_concurrent_signals": max_sig,
        "leverage": lev,
        "pullback_threshold": pull,  # legacy schema only; direction-only lanes ignore it
        "entry_limit_policy": DETERMINISTIC_ENTRY_POLICY_VERSION,
        "deterministic_entry_offset_pct": DETERMINISTIC_ENTRY_OFFSET_PCT,
        "bitfinex_live_enabled": bfx,
    }


def evaluate_dashboard_execution_gate(
    signal: dict,
    ai: dict = None,
    *,
    stage: str = "promote",
) -> tuple:
    """
    Ultimate dashboard execution control — overrides lane programming for limit submit.
    Returns (allowed, reason, defer_virtual_chase).
    """
    ai = ai or {}
    if not isinstance(signal, dict):
        return False, "INVALID_SIGNAL", False
    lane = signal.get("research_lane")

    with state_lock:
        ai_on = bool(state.get("ai_enabled", True))
        lev = int(state.get("leverage") or 0)

    if not ai_on:
        return False, "AI_REVIEWER_OFF", False

    if not lane_orders_allowed(lane):
        return False, "LANE_DISABLED", False

    if (
        signal.get("structural_entry_valid") is False
        or signal.get("entry_path") == "STRUCTURAL_LIMIT_BLOCKED"
    ):
        return False, str(signal.get("entry_reason") or "STRUCTURAL_LIMIT_UNAVAILABLE"), False

    if is_patient_chase_lane(lane):
        # Registered paper policy: shared AI APPROVE places its exact 0.29%
        # resting limit immediately. Global spread/AI-band/chase-bucket gates
        # belong to Continuous experiments and must not rewrite this cohort.
        if not ensure_signal_capacity():
            return False, "MAX_ACTIVE_SIGNALS", False
        if lev < 1 or lev > MAX_RESEARCH_LEVERAGE:
            return False, "LEVERAGE_OUT_OF_RANGE", False
        return True, "OK_OFFSET029_REGISTERED_POLICY", False

    # V2 entry gate: age ≥180s before limit submit (chase 3–5 via virtual chase).
    # Does not affect CONTINUOUS or AI60_SP3.
    if str(lane or "").upper() == RESEARCH_LANE_A160_CONTEXT_CHASE_EXIT_V2:
        min_age = float(
            signal.get("v2_min_signal_age_sec")
            or (signal.get("context") or {}).get("v2_min_signal_age_sec")
            or V2_MIN_SIGNAL_AGE_SEC
        )
        age = _signal_age_sec(signal)
        if age < min_age:
            if stage == "promote":
                return False, "V2_MIN_AGE_DEFER", True
            return False, "V2_MIN_AGE_WAIT", False

    sg_blocked, sg_bucket, sg_spread = _signal_spread_gate_blocked(signal, ai)
    if sg_blocked:
        logger.info(
            f"[SPREAD GATE] spread_bucket={sg_bucket} spread={sg_spread} blocked "
            f"trade_id={signal.get('trade_id')} — skipping limit order [PIPELINE ENFORCEMENT]"
        )
        return False, "SPREAD_BUCKET_BLOCKED", False

    win_prob = _signal_ai_win_prob(signal, ai)
    if dashboard_ai_band_blocks(win_prob):
        return False, "AI_BAND_BLOCKED", False

    if not ensure_signal_capacity():
        return False, "MAX_ACTIVE_SIGNALS", False

    if lev < 1 or lev > MAX_RESEARCH_LEVERAGE:
        return False, "LEVERAGE_OUT_OF_RANGE", False

    if not any(get_chase_execution_buckets().values()):
        return False, "CHASE_BUCKETS_ALL_OFF", False

    if stage == "submit":
        if not dashboard_virtual_chase_submit_ready(signal):
            return False, "CHASE_BUCKET_NOT_READY", False
        return True, "OK", False

    # promote: enter virtual defer or proceed to micro/5m/limit path
    if not dashboard_virtual_chase_submit_ready(signal):
        st = signal.get("status")
        if st in VIRTUAL_CHASE_AWAITING_STATUSES:
            return False, "CHASE_BUCKET_WAIT", False
        return False, "CHASE_BUCKET_DEFER", True

    return True, "OK", False


def _signal_ai_win_prob(signal: dict, ai: dict = None) -> float:
    ai = ai or {}
    if not isinstance(ai, dict):
        ai = {}
    try:
        return float(
            signal.get("ai_win_prob")
            or ai.get("win_prob")
            or (signal.get("ai") or {}).get("win_prob")
            or 0
        )
    except (TypeError, ValueError):
        return 0.0


def _cancel_pending_for_chase_gate(order: dict, reason: str = "CHASE_BUCKET_BLOCKED") -> bool:
    """Pull limit off book when chase tick hits an unchecked bucket; remember signal for next enabled bucket."""
    tid = order.get("trade_id")
    if not tid:
        return False
    meta = trades_map.get(tid, {})
    signal = meta.get("signal_ref") or {}
    chase_n = chase_age_window_index(_order_signal_age_sec(order, signal if isinstance(signal, dict) else {}, time.time()))
    cancel_result = _cancel_pending_order_confirmed(
        order,
        reason,
        record_expired=False,
        expire_signal=False,
    )
    if not cancel_result.get("finalized"):
        logger.critical(
            f"[BITFINEX LIVE] chase-gate cancel unconfirmed; retained "
            f"trade_id={tid} oid={cancel_result.get('exchange_order_id') or '-'} "
            f"failure={cancel_result.get('failure_reason') or 'UNKNOWN'} "
            "[PIPELINE ENFORCEMENT]"
        )
        return False
    _emit_genome_execution_event("ORDER_CANCELLED", {
        "trade_id": tid,
        "reason": reason,
        "chase_count": chase_n,
        "research_lane": signal.get("research_lane") if isinstance(signal, dict) else order.get("research_lane"),
    })
    if not isinstance(signal, dict):
        logger.info(
            f"[DASHBOARD GATE] cancelled pending trade_id={tid} "
            f"chase_count={chase_n} reason={reason} [PIPELINE ENFORCEMENT]"
        )
        return True
    now = time.time()
    expires_ts = signal.get("expires_ts") or (signal.get("created_ts_ts", 0) + SIGNAL_TTL_SEC)
    next_enabled = _next_enabled_chase_after(chase_n)
    can_resume = (
        next_enabled is not None
        and (not expires_ts or now < expires_ts)
        and any(get_chase_execution_buckets().values())
    )
    if can_resume:
        signal["order_placed"] = False
        signal["limit_chase_count"] = chase_n
        signal["dashboard_virtual_chase_count"] = max(_signal_virtual_chase_count(signal), chase_n)
        signal["status"] = SIGNAL_STATUS_AWAITING_DASHBOARD_CHASE
        signal["awaiting_dashboard_chase_since"] = now
        signal["outcome"] = "PENDING"
        signal["exit_reason"] = None
        logger.info(
            f"[DASHBOARD GATE] pulled limit trade_id={tid} chase_count={chase_n} "
            f"reason={reason} — virtual wait for chase>={next_enabled} [PIPELINE ENFORCEMENT]"
        )
        pipeline_state_sync()
        return True
    signal.update({
        "status": "EXPIRED",
        "outcome": reason,
        "exit_reason": reason,
        "order_placed": False,
    })
    _record_expired_order(signal, reason)
    logger.info(
        f"[DASHBOARD GATE] cancelled pending trade_id={tid} "
        f"chase_count={chase_n} reason={reason} [PIPELINE ENFORCEMENT]"
    )
    return True


def enforce_dashboard_chase_gates_on_pending() -> None:
    """Cancel pending only when the current 5-minute age window is an early disabled bucket.

    After the last enabled window (e.g. 5+ OFF while 2/3/4 ON), rest until TTL.
    Do not cancel at ~9 min just because chase-count ticked to 5+.
    """
    now = time.time()
    with trade_lock:
        pending = [o for o in list(pending_orders) if isinstance(o, dict) and o.get("status") == "PENDING"]
    for order in pending:
        if is_patient_chase_lane(order.get("research_lane")):
            continue
        tid = order.get("trade_id")
        signal = trades_map.get(tid, {}).get("signal_ref") if tid else {}
        age_sec = _order_signal_age_sec(order, signal or {}, now)
        if chase_age_window_should_cancel(age_sec):
            _cancel_pending_for_chase_gate(order)


def _load_chase_analytics_snapshot() -> dict:
    buckets = []
    raw = {}
    generated_at = None
    path = _resolve_analytics_report_path(CHASE_EFFECTIVENESS_REPORT_FILE)
    if os.path.isfile(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            raw = data.get("buckets") or {}
            generated_at = data.get("generated_at")
        except Exception:
            pass
    report_key_by_control = {
        "0_chases": "0",
        "1_chase": "1",
        "2_chases": "2",
        "3_chases": "3",
        "4_chases": "4",
        "5+_chases": "5+",
    }
    for key in CHASE_EXECUTION_BUCKET_ORDER:
        b = raw.get(report_key_by_control[key]) if isinstance(raw, dict) else None
        if isinstance(b, dict):
            buckets.append({
                "bucket": key,
                "trades": b.get("trades", 0),
                "win_rate_pct": b.get("win_rate_pct", b.get("wr_pct", 0)),
                "sum_pnl_usd": b.get("sum_pnl_usd", 0),
                "ev_usd": b.get("ev_usd", 0),
            })
        else:
            buckets.append({"bucket": key, "trades": 0, "win_rate_pct": 0, "sum_pnl_usd": 0, "ev_usd": 0})
    assisted = saved = ttl_expired = total_fills = None
    attr_path = _resolve_analytics_report_path(CHASE_ATTRIBUTION_REPORT_FILE)
    if os.path.isfile(attr_path):
        try:
            with open(attr_path, "r", encoding="utf-8") as f:
                attr = json.load(f)
            totals = attr.get("totals") or attr.get("overnight_watch") or {}
            assisted = totals.get("chase_assisted_fills")
            saved = totals.get("saved_fills_heuristic") or totals.get("saved_fills")
            ttl_expired = totals.get("ttl_expired")
            total_fills = totals.get("total_fills") or attr.get("overnight_watch", {}).get("total_fills")
        except Exception:
            pass
    return {
        "buckets": buckets,
        "assisted": assisted,
        "assisted_total": total_fills,
        "saved": saved,
        "ttl_expired": ttl_expired,
        "generated_at": generated_at,
    }


def _load_spread_analytics_snapshot() -> dict:
    """Directional gap buckets aggregated once across exact chase-count cells."""
    buckets = []
    generated_at = None
    path = _resolve_analytics_report_path(CHASE_EFFICIENCY_MATRIX_FILE)
    raw_by_spread = {}
    if os.path.isfile(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            generated_at = data.get("generated_at")
            full = data.get("full_matrix") or {}
            for key, stats in full.items():
                if not isinstance(stats, dict):
                    continue
                parts = str(key).split("|")
                if len(parts) != 2 or not parts[1].startswith("spread="):
                    continue
                # Exact base cells are "0|spread=3", "1|spread=4", etc.
                # Longer keys include lane/AI dimensions and would double count.
                if parts[0] not in ("0", "1", "2", "3", "4", "5+"):
                    continue
                spread_key = parts[1].replace("spread=", "")
                display_key = "0-1" if spread_key in ("0", "1", "0-1") else spread_key
                cell = raw_by_spread.setdefault(display_key, {
                    "trades": 0,
                    "wins": 0,
                    "sum_pnl_usd": 0.0,
                })
                cell["trades"] += int(stats.get("trades") or 0)
                cell["wins"] += int(stats.get("wins") or 0)
                cell["sum_pnl_usd"] += float(stats.get("sum_pnl_usd") or 0)
        except Exception:
            pass
    for spread_key in SPREAD_BUCKET_ORDER:
        b = raw_by_spread.get(spread_key)
        if isinstance(b, dict):
            trades = int(b.get("trades") or 0)
            wins = int(b.get("wins") or 0)
            pnl = float(b.get("sum_pnl_usd") or 0)
            buckets.append({
                "spread": spread_key,
                "trades": trades,
                "win_rate_pct": round((wins / trades * 100.0), 1) if trades else 0,
                "sum_pnl_usd": round(pnl, 2),
                "ev_usd": round((pnl / trades), 2) if trades else 0,
            })
        else:
            buckets.append({"spread": spread_key, "trades": 0, "win_rate_pct": 0, "sum_pnl_usd": 0, "ev_usd": 0})
    return {
        "buckets": buckets,
        "generated_at": generated_at,
        "source": "chase_efficiency_matrix exact chase|spread cells",
        "definition": "normalized directional score gap = abs(LONG score - SHORT score) // 10",
    }

def hash_context(ctx):
    try:
        return hash((
            round(safe_float(ctx.get("price")), 2),
            safe_float(ctx.get("volume_ratio")),
            safe_float(ctx.get("delta")),
            safe_float(ctx.get("delta_change"))
        ))
    except:
        return hash(str(ctx))

