def _client_ip() -> str:
    xff = request.headers.get("x-forwarded-for", "")
    if xff:
        return xff.split(",")[0].strip()[:64]
    return (request.remote_addr or "unknown")[:64]


def _is_local_operator(ip: str) -> bool:
    """Home dashboard on :7002 — operator at the keyboard, not a remote attacker."""
    if not ip or ip == "unknown":
        return False
    if ip in ("127.0.0.1", "::1", "localhost"):
        return True
    if ip.startswith("127.") or ip.startswith("::ffff:127."):
        return True
    return False


def _trusted_dashboard_operator(ip: str) -> bool:
    """Local operator or request carrying a valid BOT_ADMIN_TOKEN cookie/header."""
    if _is_local_operator(ip):
        return True
    if _BOT_ADMIN_TOKEN and _admin_authed():
        return True
    return False


def _is_direct_local_control(ip: str) -> bool:
    """Trust a direct loopback control call, never a proxied tunnel call."""
    if not _is_local_operator(ip):
        return False
    forwarded_headers = (
        "X-Forwarded-For",
        "CF-Connecting-IP",
        "True-Client-IP",
        "Forwarded",
    )
    return not any((request.headers.get(name) or "").strip() for name in forwarded_headers)


def _rate_check(log: dict, key: str, window_s: int, limit: int) -> bool:
    """Sliding-window per-key rate check. True = allowed, False = over limit."""
    now = _now()
    with _AI_RATE_LOCK:
        q = log[key]
        while q and q[0] < now - window_s:
            q.popleft()
        if len(q) >= limit:
            return False
        q.append(now)
        return True


def _admin_authed() -> bool:
    """True if the request carries the admin token (cookie or header)."""
    if not _BOT_ADMIN_TOKEN:
        # Never turn a missing production secret into an open remote control
        # surface. Local tests/recovery may still use a direct, unproxied
        # loopback request; the canonical Fly wrapper requires the secret.
        return _is_direct_local_control(_client_ip())
    if request.headers.get("X-Bot-Admin-Token") == _BOT_ADMIN_TOKEN:
        return True
    if request.cookies.get("bot_admin_token") == _BOT_ADMIN_TOKEN:
        return True
    return False


def _admin_authed_strict() -> bool:
    """Strict admin check for IP-sensitive endpoints.

    Unlike `_admin_authed`, this FAILS CLOSED when no BOT_ADMIN_TOKEN is
    configured — strategy internals are scrubbed unless a valid token is
    presented. Used by /api/state and /debug_state to decide whether to
    return the full state or the sanitized public view.

    Local operator on :7002 (127.0.0.1 / ::1) is always trusted — the home
    showcase dashboard must render Pathway Lab tiles and controls without
    requiring a token cookie on every refresh.
    """
    if _is_local_operator(_client_ip()):
        return True
    if not _BOT_ADMIN_TOKEN:
        return False
    if request.headers.get("X-Bot-Admin-Token") == _BOT_ADMIN_TOKEN:
        return True
    if request.cookies.get("bot_admin_token") == _BOT_ADMIN_TOKEN:
        return True
    return False


def _analyzer_view_cookie_value() -> str:
    """Return an opaque, revocable session value for the read-only analyzer.

    The browser never receives BOT_ADMIN_TOKEN as a cookie on this path.  A
    token rotation invalidates this derived value automatically, while the
    cookie cannot authorize any trading or settings endpoint.
    """
    if not _BOT_ADMIN_TOKEN:
        return ""
    return hmac.new(
        _BOT_ADMIN_TOKEN.encode("utf-8"),
        b"doxxed-analyzer-view-v1",
        hashlib.sha256,
    ).hexdigest()


def _analyzer_view_authed() -> bool:
    """Accept full admin auth or the narrower analyzer-only browser session."""
    if _admin_authed_strict():
        return True
    expected = _analyzer_view_cookie_value()
    presented = request.cookies.get("analyzer_view_session", "")
    return bool(expected and presented and hmac.compare_digest(presented, expected))


@app.before_request
def _emergency_api_guard():
    path = request.path or ""
    method = (request.method or "GET").upper()

    # Bind the bounded Flask server at the start of main() so /api/ping stays
    # responsive while persistent paper state is restored. Never expose a
    # partially restored relay/dashboard snapshot during that handoff. The
    # regular /health and dashboard handlers acquire state_lock; allowing them
    # through while main() is restoring state can consume every bounded worker
    # and starve /api/ping. Return a minimal boot response here instead.
    if not _DASHBOARD_BOOTSTRAP_COMPLETE:
        if path in ("/", "/health", "/status", "/api/status"):
            return jsonify(
                {
                    "ok": True,
                    "status": "starting",
                    "boot": "starting",
                    "bot_pid": os.getpid(),
                    **_dashboard_owner_metadata(),
                    "bot_version": EXECUTION_FIX_VERSION,
                    "server_ts": utc_iso(),
                }
            ), 200
        if path in ("/api/ping", "/api/build"):
            return None
        response = jsonify(
            {
                "ok": False,
                "boot": "starting",
                "error": "dashboard state is restoring",
            }
        )
        response.status_code = 503
        response.headers["Retry-After"] = "1"
        return response

    # Only police /api/* (plus /debug_state and /). Static assets untouched.
    is_api = path.startswith("/api/") or path in ("/debug_state",)
    if not is_api and path != "/":
        return None

    ip = _client_ip()

    # General per-IP rate limit on every /api/* hit (read + write).
    # Local operator (127.0.0.1 / ::1) is exempt — demo harness + dashboard
    # polls would otherwise trip the 60/min cap and fail bot_ping/state checks.
    # The authenticated incremental mirror can legitimately request hundreds
    # of checksum-verified chunks during first sync/recovery. Counting those
    # private requests against the public 60/minute bucket made every large
    # mirror fail with 429 before it could acknowledge rotations. The admin
    # token already gates this narrow namespace; unauthorized callers remain
    # subject to the normal limiter and then fail authentication below.
    is_authenticated_data_sync = (
        path.startswith("/api/data-sync/")
        and bool(_BOT_ADMIN_TOKEN)
        and _admin_authed()
    )
    if (
        path.startswith("/api/")
        and not _is_local_operator(ip)
        and not is_authenticated_data_sync
    ):
        if not _rate_check(_API_RATE_LOG, ip, _API_RATE_WINDOW_S, _API_RATE_MAX_PER_IP):
            resp = jsonify({"error": "rate limit exceeded", "retry_after_s": _API_RATE_WINDOW_S})
            resp.status_code = 429
            resp.headers["Retry-After"] = str(_API_RATE_WINDOW_S)
            return resp

    # Read-only GETs are allowed without a token (still rate-limited above).
    if method == "GET" and path in _READ_ONLY_GET_PATHS:
        return None
    if method == "GET" and path in _OWNER_RESEARCH_EXPORT_PATHS:
        if _admin_authed_strict():
            return None
        resp = jsonify({"error": "unauthorized — owner token required for research export"})
        resp.status_code = 401
        return resp
    if method == "OPTIONS":
        return None  # CORS preflight — let route handlers respond

    # The home bridge is a direct 127.0.0.1 caller. Allow only its narrow
    # pause/resume path during secret rotation. Remote/proxy requests carry
    # forwarding headers and therefore remain protected by BOT_ADMIN_TOKEN.
    if (
        method == "POST"
        and path in ("/api/pause", "/api/resume")
        and _is_direct_local_control(ip)
    ):
        return None

    # Everything else (POST/PUT/DELETE, or GETs not in the safe list) requires
    # the admin token remotely and fails closed if the secret is missing.
    if not _admin_authed():
        resp = jsonify({"error": "unauthorized — admin token required"})
        resp.status_code = 401
        return resp

    # Tighter cap on AI-drain POSTs for untrusted remote callers only.
    if method == "POST" and path in _AI_DRAIN_POST_PATHS and not _trusted_dashboard_operator(ip):
        if not _rate_check(_AI_RATE_LOG, ip, _AI_RATE_WINDOW_S, _AI_RATE_MAX_PER_IP):
            resp = jsonify({
                "error": "AI-influencing endpoint rate limit exceeded",
                "limit": f"{_AI_RATE_MAX_PER_IP} per hour per IP",
                "retry_after_s": _AI_RATE_WINDOW_S,
            })
            resp.status_code = 429
            resp.headers["Retry-After"] = str(_AI_RATE_WINDOW_S)
            return resp

    return None

class _TrackedRLock:
    """RLock with bounded owner diagnostics for production stall evidence."""

    def __init__(self, name: str):
        self._lock = threading.RLock()
        self._name = name
        self._meta_lock = threading.Lock()
        self._owner_ident = None
        self._owner_name = None
        self._acquired_at = 0.0
        self._depth = 0

    def acquire(self, blocking=True, timeout=-1):
        acquired = self._lock.acquire(blocking, timeout)
        if acquired:
            ident = threading.get_ident()
            with self._meta_lock:
                if self._owner_ident == ident:
                    self._depth += 1
                else:
                    self._owner_ident = ident
                    self._owner_name = threading.current_thread().name
                    self._acquired_at = time.time()
                    self._depth = 1
        return acquired

    def release(self):
        ident = threading.get_ident()
        with self._meta_lock:
            if self._owner_ident == ident and self._depth > 0:
                self._depth -= 1
                if self._depth == 0:
                    self._owner_ident = None
                    self._owner_name = None
                    self._acquired_at = 0.0
        self._lock.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_value, tb):
        self.release()
        return False

    def _is_owned(self):
        return self._lock._is_owned()

    def diagnostics(self, now=None):
        with self._meta_lock:
            owner_ident = self._owner_ident
            owner_name = self._owner_name
            acquired_at = self._acquired_at
            depth = self._depth
        held_sec = max(0.0, float(now or time.time()) - acquired_at) if acquired_at else 0.0
        stack_tail = []
        if owner_ident is not None:
            frame = sys._current_frames().get(owner_ident)
            if frame is not None:
                stack_tail = [
                    f"{Path(item.filename).name}:{item.lineno}:{item.name}"
                    for item in traceback.extract_stack(frame)[-8:]
                ]
        return {
            "name": self._name,
            "owner_thread": owner_name,
            "owner_ident": owner_ident,
            "held_seconds": round(held_sec, 3),
            "depth": depth,
            "stack_tail": stack_tail,
        }


