def _wipe_reports_recursive() -> list:
    """All analyzer outputs under reports/ including history/ subdirs."""
    found = []
    reports_dir = "reports"
    if os.path.isdir(reports_dir):
        for root, _, files in os.walk(reports_dir):
            for name in files:
                found.append(os.path.join(root, name))
    return found


