def _fresh_collection_derived_history_paths() -> list:
    """Redundant histories superseded by the compact Past Analysis bundle."""
    found = []
    for parent in (
        "research_session_archives",
        os.path.join("research_retention", "daily"),
    ):
        if not os.path.isdir(parent):
            continue
        for root, _, files in os.walk(parent):
            found.extend(os.path.join(root, name) for name in files)
    return found


def _research_wipe_rotated_jsonl_paths() -> list:
    """Rotated JSONL siblings (signal_replay.jsonl.1 …) missed by single-path delete."""
    bases = [
        "signal_replay.jsonl", "signal_snapshot.jsonl", "trade_outcome.jsonl", "shadow_outcome.jsonl",
        "type_b_adx_v3_shadow_decisions.jsonl", TYPE_B_RESEARCH_V2_EVENT_FILE,
        PATH_REPLAY_FILE, POST_EXIT_REPLAY_FILE, COLLECTOR_V22_RESEARCH_EVENTS_FILE,
        CYCLE_3M_UNIVERSE_FILE,
        CHASE_OFFSET_TOUCH_GRID_FILE,
        ORDER_MULTIVERSE_FILE,
        OPPORTUNITY_CAPTURE_FILE,
        SOURCE_ORDER_MARKET_EVIDENCE_FILE,
        MICROSTRUCTURE_TAPE_FILE,
        "counterfactual.jsonl", FILL_QUALITY_FILE, "execution_funnel.jsonl",
        SHADOW_VS_LIVE_ENTRY_FILE,
        APPROVED_BUT_REJECTED_FILE, NEAR_MISS_FILE, SOFT_REJECT_SHADOW_FILE,
        GOLDEN_STACK_REJECTIONS_FILE, REVERSAL_STUDY_FILE, AI_REASON_RESEARCH_FILE,
        AI_CONFIDENCE_CALIBRATION_FILE, TRADE_LIFECYCLE_FILE, AI_INPUT_LOG_FILE, EDGE_CENSUS_FILE,
        LANE_OPPORTUNITY_CAPTURE_FILE, AI_EDGE_DISAGREEMENT_FILE, "shadow_runner_study.jsonl",
        DUPLICATE_INTENT_AUDIT_FILE,
        V2_AI_INPUT_LOG_FILE, V2_AI_DECISION_LOG_FILE, V2_CHECKER_LOG_FILE, V2_SHADOW_OUTCOME_FILE,
    ]
    found = []
    for base in bases:
        for path in glob.glob(base + ".*"):
            if os.path.isfile(path):
                found.append(path)
    return sorted(set(found))


def all_research_wipe_paths(
    include_validation_artifacts: bool = True,
    include_legacy_logs: bool = False,
) -> list:
    paths = set(research_wipe_file_paths())
    paths |= set(_research_wipe_rotated_jsonl_paths())
    paths |= set(_analyzer_output_wipe_globs())
    paths |= set(_wipe_reports_recursive())
    if include_validation_artifacts:
        paths |= set(_pathway_validation_artifact_paths())
    if include_legacy_logs:
        paths |= set(_legacy_redundant_log_paths())
    return sorted(paths)

def _delete_paths(paths) -> tuple:
    deleted = []
    errors = []
    seen = set()
    for path in paths:
        if not path or path in seen:
            continue
        seen.add(path)
        try:
            if os.path.exists(path):
                os.remove(path)
                deleted.append(path)
        except PermissionError as e:
            errors.append(f"{path}: locked — {e}")
        except Exception as e:
            errors.append(f"{path}: {e}")
    return deleted, errors

def _reset_runtime_log_handlers():
    """Truncate the rotating runtime log without restarting the process."""
    for h in logger.handlers:
        if not isinstance(h, RotatingFileHandler):
            continue
        try:
            with h.lock:
                if h.stream:
                    h.stream.close()
                    h.stream = None
                for i in range(LOG_BACKUP_COUNT + 5, -1, -1):
                    path = h.baseFilename if i == 0 else f"{h.baseFilename}.{i}"
                    if os.path.exists(path):
                        os.remove(path)
                h.stream = h._open()
        except Exception as e:
            logger.error(f"[FRESH COLLECTION] Log handler reset failed: {e} [PIPELINE ENFORCEMENT]")

def reset_all_research_files() -> dict:
    """Delete live epoch research files AND permanently purge quarantine trees.

    Infected fills must not be recoverable. Previous resets only moved files
    into research_epoch_quarantine; this path deletes both the live epoch
    JSONL/logs and every quarantine archive under the runtime root.
    """
    from research.epoch_quarantine import purge_quarantine_archives
    live_paths = all_research_wipe_paths(include_validation_artifacts=True, include_legacy_logs=True)
    deleted, errors = _delete_paths(live_paths)
    purge = purge_quarantine_archives(os.getcwd())
    errors.extend(purge.get("errors") or [])
    return {
        "epoch_id": None,
        "path": None,
        "cutoff_utc": utc_iso(),
        "moved": [],
        "deleted": deleted,
        "purged_quarantine": purge.get("deleted_trees") or [],
        "purged_files": int(purge.get("deleted_files") or 0),
        "errors": errors,
    }

def maintain_fresh_collection_files():
    """Periodic trim when fresh-collection mode is on (prevents silent re-accumulation)."""
    prune_aux_logs_on_startup()
    log_path = os.getenv("BOT_LOG_FILE", "bot_runtime.log")
    if os.path.exists(log_path) and os.path.getsize(log_path) > LOG_MAX_BYTES:
        _reset_runtime_log_handlers()

def perform_fresh_collection_reset(send_local_signal: bool = True) -> dict:
    """Dashboard-triggered archive+wipe: never delete without verified archive first.

    ``send_local_signal=True`` (the default, used by the Fresh Collection
    toggle) bumps ``state['fresh_collection_signal_ts']`` so the local sync
    loop wipes its mirror on the next manifest poll — a true fresh restart
    everywhere. ``send_local_signal=False`` is used by the operational
    ``/api/wipe_fly_only`` button which clears the Fly volume but retains
    the local mirror for offline analysis.
    """
    if not _fresh_collection_lock.acquire(blocking=False):
        logger.warning("[FRESH COLLECTION] Reset already in progress — ignored duplicate request [PIPELINE ENFORCEMENT]")
        return {
            "ok": False,
            "wipe_aborted": True,
            "error": "reset_already_in_progress",
            "summary": "Reset already running — wait a few seconds and refresh",
        }
    try:
        return _perform_fresh_collection_reset_locked(send_local_signal=send_local_signal)
    finally:
        _fresh_collection_lock.release()


# === WIPE FIX: _seal_past_analysis_with_fallback helper ===
def _seal_past_analysis_with_fallback(reason: str) -> dict:
    """Seal a past-analysis record, degrading gracefully on Fly.

    Fly's whitelist excludes the optional ``research.past_analysis`` module
    from the container image while retaining the small runtime-safe research
    helpers. When the wipe endpoint runs there, ``from research.past_analysis import
    seal_past_analysis`` raises ImportError and the safety guard turns
    that into HTTP 409 -- blocking every wipe.

    This helper tries the real seal first (preserving strict behavior
    for desktop / analyzer hosts that have the package). On ImportError
    it builds a minimal archive dict from in-memory bot state so the
    wipe can preserve a trade-by-trade audit trail without the research
    package being installed.
    """
    try:
        from research.past_analysis import seal_past_analysis
    except ImportError:
        # Fly image excludes the full past-analysis module -- build a minimal archive dict
        # inline using only stdlib + in-memory bot state.
        ts = utc_iso()
        with trade_lock:
            trades_snapshot = list(trades)
        trade_audit = [
            {
                "trade_id": t.get("trade_id"),
                "close_ts": t.get("close_ts"),
                "net_pnl_usd": t.get("net_pnl_usd"),
            }
            for t in trades_snapshot
            if isinstance(t, dict)
        ]
        session_pnl = float(_session_realized_pnl_usd() or 0.0)
        session_count = int(_session_trade_count() or 0)
        fingerprint = f"{ts}:{session_count}:{session_pnl:.6f}:{len(trade_audit)}".encode("utf-8")
        archive_id = "degraded_" + hashlib.sha1(fingerprint).hexdigest()[:16]
        return {
            "schema": "past_analysis_manifest_v1",
            "archive_id": archive_id,
            "created_at": ts,
            "reason": reason,
            "analysis_generated_at": ts,
            "analyzer_sync_id": ANALYZER_SYNC_ID,
            "data_scope": None,
            "performance": {
                "trades": session_count,
                "net_pnl_usd": session_pnl,
            },
            "coverage": {},
            "key_findings": [],
            "files": [],
            "source_inventory": [],
            "raw_payloads_included": False,
            "integrity": {
                "method": "in_memory_bot_state",
                "file_count": 0,
                "total_bytes": 0,
            },
            "degraded_mode": True,
            "note": "research.past_analysis unavailable (Fly image excludes research/); built from in-memory bot state",
            "trade_count_session": session_count,
            "session_pnl_usd": session_pnl,
            "trades": trade_audit,
        }
    # Package present -- defer to the real seal (strict behavior).
    return seal_past_analysis(os.getcwd(), reason=reason)


# === END WIPE FIX: helper ===

def _perform_fresh_collection_reset_locked(send_local_signal: bool = True) -> dict:
    """Inner fresh-collection wipe (caller holds _fresh_collection_lock)."""
    global bot_start_time, _last_fresh_maintain_ts, _cached_pathway_scorecard
    global _cached_pathway_lane_specs
    # A research epoch boundary must never become a money-path mutation. Read
    # the authoritative in-memory books before archiving or clearing anything,
    # and require the operator to have paused and disarmed the source first.
    # The reset preserves that pause; it is not an implicit resume command.
    with state_lock:
        pre_reset_paused = bool(state.get("execution_paused", False))
        pre_reset_reason = str(state.get("execution_reason") or "")
        pre_reset_pause_priority = int(state.get("_pause_priority") or 0)
        pre_reset_live_armed = bool(state.get("live_armed", False))
    with trade_lock:
        pending_count = len(pending_orders)
        open_count = len(open_positions)
    if pre_reset_live_armed or not pre_reset_paused or pending_count or open_count:
        blockers = []
        if pre_reset_live_armed:
            blockers.append("LIVE_ARMED")
        if not pre_reset_paused:
            blockers.append("EXECUTION_NOT_PAUSED")
        if pending_count:
            blockers.append(f"PENDING_ORDERS:{pending_count}")
        if open_count:
            blockers.append(f"OPEN_POSITIONS:{open_count}")
        logger.error(
            f"[FRESH COLLECTION] ABORT WIPE — unsafe boundary ({','.join(blockers)}) "
            "[PIPELINE ENFORCEMENT]"
        )
        return {
            "ok": False,
            "wipe_aborted": True,
            "error": "fresh_collection_requires_paused_disarmed_flat_boundary",
            "blockers": blockers,
            "pending_order_count": pending_count,
            "open_position_count": open_count,
            "summary": "Pause and disarm execution, then reach a flat order/position boundary",
        }
    try:
        # === WIPE FIX: callsite uses _seal_past_analysis_with_fallback ===
        past_analysis = _seal_past_analysis_with_fallback(reason="fresh_collection_dashboard")
        past_analysis_id = str(past_analysis.get("archive_id") or "")
        archive_path = create_research_archive_receipt(
            past_analysis,
            reason="fresh_collection_dashboard",
        )
    except (ArchiveIntegrityError, ImportError, OSError, RuntimeError, ValueError) as exc:
        logger.error(f"[FRESH COLLECTION] ABORT WIPE — preservation failed: {exc} [PIPELINE ENFORCEMENT]")
        return {
            "ok": False,
            "wipe_aborted": True,
            "error": str(exc),
            "summary": "ABORT WIPE — final analysis preservation failed",
        }
    logger.warning(f"[FRESH COLLECTION] Reset requested - archived to {archive_path}, wiping session state")
    genome_reset = {}
    bridge = get_genome_bridge()
    if bridge is not None:
        try:
            genome_reset = bridge.reset_research_store()
        except Exception as exc:
            logger.error(f"[FRESH COLLECTION] ABORT WIPE — research.db reset failed: {exc} [PIPELINE ENFORCEMENT]")
            return {
                "ok": False,
                "wipe_aborted": True,
                "error": str(exc),
                "summary": "ABORT WIPE — research database reset failed",
                "archive_path": archive_path,
                "past_analysis_id": past_analysis_id,
            }
    # Bind the new causal generation before clearing recovery state. A racing
    # maturation poll then either finishes wholly before this boundary or is
    # refused by the new cutoff; it cannot recreate old V3 ledgers afterward.
    reset_anchor = time.time()
    _reset_collector_epoch_state(reset_anchor)
    with trade_lock:
        pending_orders.clear()
        expired_orders.clear()
        open_positions.clear()
        trades_map.clear()
        trades.clear()
        recent_trades.clear()
        _canonical_source_order_market_evidence.clear()
    quarantine = reset_all_research_files()
    moved, errors = quarantine.get("moved") or [], quarantine.get("errors") or []
    deleted = list(quarantine.get("deleted") or [])
    purged_trees = list(quarantine.get("purged_quarantine") or [])
    # Fresh Collection is the operator boundary for every active holdout.  The
    # file wipe alone is insufficient because Tile 2 counters also live in
    # memory and would otherwise be written back with pre-reset/test values.
    reset_tile2_counters_for_fresh_holdout()
    _cached_pathway_scorecard = {}
    _cached_pathway_lane_specs = {}
    _reset_runtime_log_handlers()
    reset_runtime_state()
    reset_session_risk_state()
    bot_start_time = reset_anchor
    _last_fresh_maintain_ts = time.time()
    _write_research_session(bot_start_time, fresh_collection_reset=True)
    _record_execution_settings_epoch("FRESH_COLLECTION_STARTED", force=True)
    load_session_trades_from_csv()
    archive_compaction = {
        "past_analysis_id": past_analysis_id,
        "deleted_files": len(deleted),
        "deleted_bytes": 0,
        "raw_payloads_retained": False,
        "quarantined_files": 0,
        "quarantine_path": None,
        "purged_quarantine": purged_trees,
    }
    summary = (
        f"deleted {len(deleted)} live file(s), purged {len(purged_trees)} quarantine tree(s)"
        + (f", {len(errors)} error(s)" if errors else "")
    )
    for err in errors:
        logger.warning(f"[FRESH COLLECTION] delete skipped/failed: {err} [PIPELINE ENFORCEMENT]")
    with state_lock:
        state["last_fresh_reset_ts"] = time.time()
        state["last_fresh_reset_summary"] = summary
        if send_local_signal:
            # Bump the local-sync-loop signal so the mirror is wiped on the
            # next manifest poll. /api/wipe_fly_only passes False here.
            state["fresh_collection_signal_ts"] = time.time()
        state["execution_paused"] = pre_reset_paused
        state["execution_reason"] = pre_reset_reason
        state["_pause_priority"] = pre_reset_pause_priority
    save_persistent_config()
    logger.info(f"[FRESH COLLECTION] Reset complete - {summary} [PIPELINE ENFORCEMENT]")
    with state_lock:
        signal_ts = float(state.get("fresh_collection_signal_ts") or 0.0)
    if send_local_signal:
        logger.info(
            f"[FRESH COLLECTION] Local-sync signal bumped to {signal_ts} "
            f"— local mirror will be wiped on next manifest poll [PIPELINE ENFORCEMENT]"
        )
    return {
        "deleted": deleted,
        "quarantined": [],
        "quarantine_path": None,
        "purged_quarantine": purged_trees,
        "epoch_cutoff_utc": quarantine.get("cutoff_utc"),
        "errors": errors,
        "summary": summary,
        "archive_path": archive_path,
        "archive_compaction": archive_compaction,
        "past_analysis_id": past_analysis_id,
        "genome_reset": genome_reset,
        "ts": utc_iso(),
        "ok": True,
        "wipe_aborted": False,
        "fresh_collection_signal_ts": signal_ts,
        "local_mirror_will_wipe": False,
        "local_mirror_will_quarantine": bool(send_local_signal),
    }

