def _load_lane_metrics_from_disk() -> dict:
    """Benchmark report + ledger — PnL/fills for live tiles and retired archive."""
    bench_lanes = {}
    ledger = {}
    lab_ledger = {}
    try:
        bench_path = os.path.join(os.getcwd(), "benchmark_vs_lanes_report.json")
        if os.path.isfile(bench_path):
            with open(bench_path, encoding="utf-8") as f:
                bench_lanes = (json.load(f) or {}).get("lanes") or {}
    except Exception as e:
        logger.debug(f"[LANE_METRICS] benchmark read failed: {e}")
    try:
        if os.path.isfile(LANE_PNL_LEDGER_FILE):
            with open(LANE_PNL_LEDGER_FILE, encoding="utf-8") as f:
                ledger = (json.load(f) or {}).get("lanes") or {}
    except Exception as e:
        logger.debug(f"[LANE_METRICS] ledger read failed: {e}")
    try:
        if os.path.isfile(LANE_LAB_PNL_LEDGER_FILE):
            with open(LANE_LAB_PNL_LEDGER_FILE, encoding="utf-8") as f:
                lab_ledger = (json.load(f) or {}).get("lanes") or {}
    except Exception as e:
        logger.debug(f"[LANE_METRICS] lab ledger read failed: {e}")
    out = {}
    for lane in set(bench_lanes.keys()) | set(ledger.keys()) | set(lab_ledger.keys()):
        bm = bench_lanes.get(lane) or {}
        lb = ledger.get(lane) or {}
        lab = lab_ledger.get(lane) or {}
        fills = int(bm.get("real_fills") or bm.get("fills") or lb.get("closes") or 0)
        pnl = float(bm.get("net_pnl_real") or bm.get("net_pnl_usd") or lb.get("net_pnl_usd") or 0)
        approves = int(bm.get("approves") or 0)
        fill_pct = bm.get("approve_to_fill_pct")
        if approves and fill_pct is None:
            fill_pct = round(100.0 * fills / approves, 1)
        wins = int(lb.get("wins") or bm.get("wins") or 0)
        losses = int(lb.get("losses") or bm.get("losses") or 0)
        win_rate = round(100.0 * wins / fills, 1) if fills else float(bm.get("win_rate_pct") or 0)
        # The analyzer also emits policy-filtered LAB metrics from immutable
        # shadow_lane_outcome rows. Prefer the live convenience ledger when
        # present, but do not lose valid LAB results when that cache is absent.
        lab_closes = int(lab.get("closes") or bm.get("lab_closes") or 0)
        lab_pnl = float(
            lab.get("net_pnl_usd")
            if lab.get("net_pnl_usd") is not None
            else (bm.get("lab_net_pnl") or 0)
        )
        lab_wins = int(lab.get("wins") or bm.get("lab_wins") or 0)
        lab_losses = int(lab.get("losses") or bm.get("lab_losses") or 0)
        out[lane] = {
            "approves": approves,
            "real_fills": fills,
            "approve_to_fill_pct": float(fill_pct or 0),
            "shadow_fill_pct": float(bm.get("shadow_fill_pct") or 0),
            "net_pnl_real": round(pnl, 2),
            "per_approve_ev": round(float(bm.get("per_approve_ev") or 0), 2),
            "wins": wins,
            "losses": losses,
            "win_rate_pct": win_rate,
            "verdict": bm.get("verdict"),
            # LAB (OFF-combo) simulated metrics — parallel to real metrics, never mixed.
            "lab_mode": bool(lab_closes or lab_pnl),
            "lab_closes": lab_closes,
            "lab_net_pnl": round(lab_pnl, 2),
            "lab_wins": lab_wins,
            "lab_losses": lab_losses,
            "lab_win_rate": round(100.0 * lab_wins / lab_closes, 1) if lab_closes else 0.0,
            "lab_per_close_ev": round(lab_pnl / lab_closes, 2) if lab_closes else 0.0,
        }
    # CONTINUOUS benchmark proxy from Direct COMBO lanes
    if COMPARISON_BENCHMARK_LANE not in out or not int(out.get(COMPARISON_BENCHMARK_LANE, {}).get("real_fills") or 0):
        parts = [out.get(ln) for ln in CONTINUOUS_PROXY_LANES if out.get(ln)]
        if parts:
            approves = sum(int(p.get("approves") or 0) for p in parts)
            fills = sum(int(p.get("real_fills") or 0) for p in parts)
            pnl = round(sum(float(p.get("net_pnl_real") or 0) for p in parts), 2)
            ev = round(sum(float(p.get("per_approve_ev") or 0) for p in parts) / len(parts), 2) if parts else 0.0
            if approves:
                ev = round(pnl / approves, 2)
            out[COMPARISON_BENCHMARK_LANE] = {
                "approves": approves,
                "real_fills": fills,
                "approve_to_fill_pct": round(100.0 * fills / approves, 1) if approves else 0.0,
                "shadow_fill_pct": 0.0,
                "net_pnl_real": pnl,
                "per_approve_ev": ev,
                "verdict": "benchmark baseline",
            }
    return out


def _load_reconciled_lab_outcome_metrics() -> dict:
    """Derive active LAB tile metrics from immutable outcome rows.

    The legacy JSON ledger is a convenience cache and can lag process restarts.
    This reconciliation never rewrites it; it only deduplicates completed outcomes
    by study id so the dashboard reports the raw close count and PnL truthfully.
    """
    target_lanes = set(COMBO_EXECUTION_LANES)
    rows = {}
    if not os.path.isfile(SHADOW_LANE_OUTCOME_FILE):
        return {}
    try:
        with open(SHADOW_LANE_OUTCOME_FILE, encoding="utf-8") as f:
            for line in f:
                try:
                    row = json.loads(line)
                except (TypeError, ValueError):
                    continue
                lane = str(row.get("research_lane") or "").upper()
                trade_id = str(row.get("trade_id") or row.get("study_id") or "")
                if (
                    lane not in target_lanes
                    or not trade_id
                    or str(row.get("collection_mode") or "").upper() != "LAB"
                ):
                    continue
                if lane == RESEARCH_LANE_TYPE_B_HUNTER_V1 and row.get("policy_version") != _type_b_policy_version():
                    continue
                # A repeated study row replaces the earlier snapshot; only the
                # terminal row is counted, and unfilled/cancelled rows are not trades.
                rows[(lane, trade_id)] = row
    except Exception as e:
        logger.debug(f"[LAB_RECONCILE] outcome read failed: {e}")
        return {}

    result = {}
    for lane in target_lanes:
        completed = [r for (ln, _), r in rows.items() if ln == lane and bool(r.get("filled"))]
        if not completed and lane != RESEARCH_LANE_TYPE_B_HUNTER_V1:
            continue
        pnl = round(sum(float(r.get("net_pnl_usd") or 0.0) for r in completed), 2)
        wins = sum(1 for r in completed if float(r.get("net_pnl_usd") or 0.0) > 0)
        closes = len(completed)
        result[lane] = {
            "lab_mode": True,
            "lab_closes": closes,
            "lab_net_pnl": pnl,
            "lab_wins": wins,
            "lab_losses": closes - wins,
            "lab_win_rate": round(100.0 * wins / closes, 1) if closes else 0.0,
            "lab_per_close_ev": round(pnl / closes, 2) if closes else 0.0,
            "lab_pnl_source": "reconciled_shadow_outcomes",
            "policy_version": _type_b_policy_version() if lane == RESEARCH_LANE_TYPE_B_HUNTER_V1 else None,
        }
    return result


def _reconcile_type_b_trade_count() -> dict:
    """Pt 7b: Cross-source trade-count reconciliation for TYPE_B_HUNTER_V1.

    Surfaces mismatches between the three independent sources of Type B trade
    counts so the dashboard can render consistent totals and the operator can
    spot drift (e.g. a paper trade that did not produce a shadow outcome row,
    or a live fill that did not reach session_stats).

    Sources:
      - ``paper``   : ``session_stats``/ledger closes for TYPE_B_HUNTER_V1
      - ``shadow``  : ``shadow_lane_outcome.jsonl`` rows where
                      ``research_lane == TYPE_B_HUNTER_V1`` and ``filled == True``
                      and ``policy_version`` matches the running policy
      - ``live``    : ``open_positions`` for the same lane; only present in LIVE mode

    The output is purely diagnostic -- it never rewrites ledgers. The dashboard
    surfaces ``type_b_trade_reconciliation`` from this dict via ``/api/state``.
    """
    lane = RESEARCH_LANE_TYPE_B_HUNTER_V1
    policy_v = _type_b_policy_version()
    out = {
        "lane": lane,
        "policy_version": policy_v,
        "paper_closes": 0,
        "shadow_closes": 0,
        "counterfactual_closes": 0,
        "counterfactual_wins": 0,
        "counterfactual_losses": 0,
        "counterfactual_breakevens": 0,
        "counterfactual_pnl_usd": 0.0,
        "live_open": 0,
        "live_closed": 0,
        "consistent": True,
        "mismatch_note": "",
    }

    # Paper (ledger closes for the lane, excluding pure-LAB rows)
    try:
        if os.path.isfile(LANE_PNL_LEDGER_FILE):
            with open(LANE_PNL_LEDGER_FILE, encoding="utf-8") as f:
                ld = (json.load(f) or {}).get("lanes") or {}
            row = ld.get(lane) or {}
            out["paper_closes"] = int(row.get("closes") or 0)
    except Exception as e:
        logger.debug(f"[TYPE_B_RECONCILE] paper read failed: {e}")

    # Shadow outcome rows (authoritative for LAB)
    try:
        if os.path.isfile(SHADOW_LANE_OUTCOME_FILE):
            seen = set()
            with open(SHADOW_LANE_OUTCOME_FILE, encoding="utf-8") as f:
                for line in f:
                    try:
                        r = json.loads(line)
                    except (TypeError, ValueError):
                        continue
                    if str(r.get("research_lane") or "").upper() != lane:
                        continue
                    if r.get("policy_version") != policy_v:
                        continue
                    tid = str(r.get("trade_id") or r.get("study_id") or "")
                    if not tid or tid in seen:
                        continue
                    seen.add(tid)
                    if not bool(r.get("filled")):
                        continue
                    mode = str(r.get("collection_mode") or "").upper()
                    is_counterfactual = bool(r.get("is_counterfactual")) or (
                        r.get("policy_entered") is False
                    ) or mode == "CALIBRATION_COUNTERFACTUAL"
                    if is_counterfactual:
                        pnl = float(r.get("net_pnl_usd") or 0.0)
                        out["counterfactual_closes"] += 1
                        out["counterfactual_pnl_usd"] += pnl
                        if pnl > 0:
                            out["counterfactual_wins"] += 1
                        elif pnl < 0:
                            out["counterfactual_losses"] += 1
                        else:
                            out["counterfactual_breakevens"] += 1
                        continue
                    out["shadow_closes"] += 1
    except Exception as e:
        logger.debug(f"[TYPE_B_RECONCILE] shadow read failed: {e}")
    out["counterfactual_pnl_usd"] = round(
        float(out["counterfactual_pnl_usd"]), 4
    )

    # Live open positions for the lane
    try:
        with state_lock:
            positions = copy.deepcopy(state.get("open_positions") or [])
        out["live_open"] = sum(
            1 for p in positions
            if str(p.get("lane") or p.get("research_lane") or "").upper() == lane
        )
    except Exception as e:
        logger.debug(f"[TYPE_B_RECONCILE] open_positions read failed: {e}")

    # Consistency check -- paper and shadow should agree for the same policy
    # cohort. Allow paper >= shadow because the ledger may include older
    # policy cohorts before the policy_version gate was introduced.
    paper = int(out["paper_closes"])
    shadow = int(out["shadow_closes"])
    if paper != shadow:
        out["consistent"] = False
        if paper > shadow:
            out["mismatch_note"] = (
                f"paper ({paper}) > shadow ({shadow}) -- ledger likely includes "
                f"older policy cohorts; shadow count is the authoritative figure "
                f"for policy {policy_v}"
            )
        else:
            out["mismatch_note"] = (
                f"shadow ({shadow}) > paper ({paper}) -- a filled shadow outcome "
                f"did not reach lane_pnl_ledger; rebuild the ledger from jsonl"
            )
    return out


def _session_stats_from_lane_metrics(metrics: dict) -> dict:
    m = metrics or {}
    approves = int(m.get("approves") or 0)
    fills = int(m.get("real_fills") or 0)
    pnl = float(m.get("net_pnl_real") or 0)
    ev = float(m.get("per_approve_ev") or 0)
    fill_pct = m.get("approve_to_fill_pct")
    if approves and fill_pct is None:
        fill_pct = round(100.0 * fills / approves, 1)
    lab_closes = int(m.get("lab_closes") or 0)
    lab_pnl = float(m.get("lab_net_pnl") or 0)
    lab_wins = int(m.get("lab_wins") or 0)
    lab_win_rate = float(m.get("lab_win_rate") or 0.0)
    lab_ev = float(m.get("lab_per_close_ev") or 0.0)
    lab_open = int(m.get("lab_open_shadows") or 0)
    win_rate = float(m.get("win_rate_pct") or 0.0)
    shadow_sim = bool(m.get("shadow_sim_mode"))
    checker_pass_sims = int(m.get("checker_pass_sims") or 0)
    checker_pass_pnl = float(m.get("checker_pass_pnl") or 0)
    reject_sims = int(m.get("reject_counterfactual_sims") or 0)
    reject_pnl = float(m.get("reject_counterfactual_pnl") or 0)
    paper_fills = int(m.get("paper_fills") if m.get("paper_fills") is not None else (fills if not shadow_sim else 0))
    if lab_closes:
        lab_line = (
            f"LAB sim · {lab_closes} closes · {lab_win_rate:.0f}% win · ${lab_pnl:.2f} sim · EV ${lab_ev:.2f}/close"
        )
    elif lab_open:
        lab_line = f"LAB sim · {lab_open} open shadow(s) · collecting…"
    else:
        lab_line = "LAB sim · collecting…"

    if shadow_sim and (checker_pass_sims or reject_sims):
        summary_line = (
            f"shadow sim · n={approves} approves · {checker_pass_sims} chk pass · ${checker_pass_pnl:.2f} · "
            f"{reject_sims} reject sim · ${reject_pnl:.2f} · {paper_fills} paper fills"
        )
    elif shadow_sim and fills:
        summary_line = (
            f"shadow sim · n={approves} approves · {fills} sim trades · "
            f"{win_rate:.0f}% win · ${pnl:.2f} sim · EV ${ev:.2f}/approve"
        )
    else:
        summary_line = (
            f"n={approves} approves · {fills} trades · "
            f"{float(fill_pct or 0):.0f}% fill · ${pnl:.2f} real · EV ${ev:.2f}/approve"
        )
    return {
        "approves": approves,
        "real_fills": fills,
        "approve_to_fill_pct": float(fill_pct or 0),
        "shadow_fill_pct": float(m.get("shadow_fill_pct") or 0),
        "net_pnl_real": pnl,
        "per_approve_ev": ev,
        "verdict": m.get("verdict"),
        "summary_line": summary_line,
        "shadow_sim_mode": shadow_sim,
        "win_rate_pct": win_rate,
        "checker_pass_sims": checker_pass_sims,
        "checker_pass_pnl": round(checker_pass_pnl, 2),
        "reject_counterfactual_sims": reject_sims,
        "reject_counterfactual_pnl": round(reject_pnl, 2),
        "paper_fills": paper_fills,
        # LAB (OFF-combo) simulated metrics — surfaced on the tile when OFF; never mixed into real.
        "lab_mode": bool(m.get("lab_mode") or lab_closes or lab_open),
        "lab_closes": lab_closes,
        "lab_net_pnl": round(lab_pnl, 2),
        "lab_wins": lab_wins,
        "lab_losses": int(m.get("lab_losses") or 0),
        "lab_win_rate": lab_win_rate,
        "lab_per_close_ev": lab_ev,
        "lab_open_shadows": lab_open,
        "lab_open_filled": int(m.get("lab_open_filled") or 0),
        "lab_pnl_source": m.get("lab_pnl_source") or "lab_ledger",
        "lab_ledger_close_delta": int(m.get("lab_ledger_close_delta") or 0),
        "lab_summary_line": lab_line,
    }


def _scope_pathway_specs_to_signed_epoch(
    payload: dict,
    session_trades: list,
    lane_opportunity_counters: dict,
    epoch_cutoff_utc: str,
) -> dict:
    """Replace cumulative tile headlines with the current signed-epoch truth."""
    if not epoch_cutoff_utc:
        return payload
    scoped = copy.deepcopy(payload or {})
    ledger = _derive_lane_pnl_ledger_from_trades(session_trades or [])
    counters = lane_opportunity_counters or {}
    settings = _settings_period_breakdown()
    for row in scoped.get("lanes") or []:
        lane = str(row.get("lane") or "").upper()
        lb = ledger.get(lane) or {}
        lc = counters.get(lane) or {}
        closes = int(lb.get("closes") or 0)
        pnl = round(float(lb.get("net_pnl_usd") or 0.0), 2)
        approves = int(lc.get("approves") or 0)
        metrics = {
            "approves": approves,
            "real_fills": closes,
            "approve_to_fill_pct": round(100.0 * closes / approves, 1) if approves else 0.0,
            "net_pnl_real": pnl,
            "per_approve_ev": round(pnl / approves, 2) if approves else 0.0,
            "wins": int(lb.get("wins") or 0),
            "losses": int(lb.get("losses") or 0),
            "win_rate_pct": (
                round(100.0 * int(lb.get("wins") or 0) / closes, 1)
                if closes else 0.0
            ),
            "verdict": "current signed clean epoch",
        }
        stats = _session_stats_from_lane_metrics(metrics)
        stats["scope"] = "SIGNED_FRESH_EPOCH"
        stats["epoch_cutoff_utc"] = epoch_cutoff_utc
        stats["settings_periods"] = _reconcile_settings_periods_to_headline(
            stats, settings.get(lane) or []
        )
        row["session_stats"] = stats
    scoped["session_scope"] = "SIGNED_FRESH_EPOCH"
    scoped["epoch_cutoff_utc"] = epoch_cutoff_utc
    return scoped


def write_static_pathway_lane_specs(cwd: str = None) -> dict:
    payload = build_static_pathway_lane_specs()
    path = os.path.join(cwd or os.getcwd(), PATHWAY_LANE_SPECS_FILE)
    existing = {}
    if os.path.isfile(path):
        try:
            with open(path, encoding="utf-8") as f:
                existing = json.load(f)
        except Exception:
            pass
    merged = _merge_pathway_specs_with_session_stats(payload, existing)
    try:
        _atomic_file_replace(
            path,
            lambda handle: json.dump(merged, handle, indent=2),
            pathway_specs_file_lock,
            label="PATHWAY_LANE_SPECS",
        )
    except Exception as e:
        logger.debug(f"[PATHWAY_LANE_SPECS] write failed: {e}")
    return merged


def _merge_pathway_specs_with_session_stats(static_payload: dict, file_payload: dict = None) -> dict:
    """Code-owned lane tiles + session_stats from analyzer JSON and live reports."""
    file_payload = file_payload or {}
    file_by_lane = {
        str(s.get("lane") or ""): s
        for s in (file_payload.get("lanes") or [])
        if s.get("lane")
    }
    disk_metrics = _load_lane_metrics_from_disk()
    live_ledger = get_lane_pnl_ledger()
    # V2 checker approves + shadow outcomes (paper fills/PnL from lane_pnl_ledger when tile ON).
    try:
        v2_metrics = load_v2_shadow_metrics()
        prev_v2 = disk_metrics.get(RESEARCH_LANE_A160_CONTEXT_CHASE_EXIT_V2) or {}
        live_v2 = live_ledger.get(RESEARCH_LANE_A160_CONTEXT_CHASE_EXIT_V2) or {}
        live_v2_closes = int(live_v2.get("closes") or 0)
        if v2_metrics:
            chk_pass = int(v2_metrics.get("checker_pass_sims") or v2_metrics.get("real_fills") or 0)
            chk_pnl = float(v2_metrics.get("checker_pass_pnl") or v2_metrics.get("net_pnl_real") or 0)
            reject_sims = int(v2_metrics.get("reject_counterfactual_sims") or 0)
            reject_pnl = float(v2_metrics.get("reject_counterfactual_pnl") or 0)
            use_shadow_primary = live_v2_closes <= 0 and (chk_pass > 0 or reject_sims > 0)
            disk_metrics[RESEARCH_LANE_A160_CONTEXT_CHASE_EXIT_V2] = {
                **prev_v2,
                "approves": max(
                    int(prev_v2.get("approves") or 0),
                    int(v2_metrics.get("approves") or 0),
                ),
                "real_fills": int(live_v2_closes)
                or int(prev_v2.get("real_fills") or 0)
                or chk_pass,
                "net_pnl_real": float(live_v2.get("net_pnl_usd") or 0)
                or float(prev_v2.get("net_pnl_real") or 0)
                or chk_pnl,
                "per_approve_ev": float(prev_v2.get("per_approve_ev") or 0)
                or float(v2_metrics.get("per_approve_ev") or 0),
                "win_rate_pct": float(v2_metrics.get("win_rate_pct") or prev_v2.get("win_rate_pct") or 0),
                "checker_pass_sims": chk_pass,
                "checker_pass_pnl": round(chk_pnl, 2),
                "reject_counterfactual_sims": reject_sims,
                "reject_counterfactual_pnl": round(reject_pnl, 2),
                "paper_fills": live_v2_closes,
                "shadow_sim_mode": use_shadow_primary,
                "verdict": (
                    "shadow sim (tile OFF)"
                    if use_shadow_primary
                    else (prev_v2.get("verdict") or v2_metrics.get("verdict") or "independent paper orders")
                ),
            }
        elif RESEARCH_LANE_A160_CONTEXT_CHASE_EXIT_V2 not in disk_metrics:
            disk_metrics[RESEARCH_LANE_A160_CONTEXT_CHASE_EXIT_V2] = {
                "approves": 0,
                "real_fills": 0,
                "approve_to_fill_pct": 0.0,
                "shadow_fill_pct": 0.0,
                "net_pnl_real": 0.0,
                "per_approve_ev": 0.0,
                "win_rate_pct": 0.0,
                "shadow_sim_mode": False,
                "verdict": "independent paper orders",
            }
    except Exception as e:
        logger.debug(f"[V2_METRICS] load failed: {e}")
    for lane, lb in live_ledger.items():
        closes = int(lb.get("closes") or 0)
        pnl = float(lb.get("net_pnl_usd") or 0)
        if closes or pnl:
            prev = disk_metrics.get(lane) or {}
            approves = int(prev.get("approves") or 0)
            # EV/appr updates as paper trades complete (prefer live ledger closes).
            per_ev = round(pnl / approves, 2) if approves else float(prev.get("per_approve_ev") or 0)
            if not approves and closes:
                per_ev = round(pnl / closes, 2)
            disk_metrics[lane] = {
                "approves": approves or closes,
                "real_fills": closes or int(prev.get("real_fills") or 0),
                "approve_to_fill_pct": prev.get("approve_to_fill_pct"),
                "shadow_fill_pct": float(prev.get("shadow_fill_pct") or 0),
                "net_pnl_real": round(pnl, 2),
                "per_approve_ev": per_ev,
                "wins": int(lb.get("wins") or 0),
                "losses": int(lb.get("losses") or 0),
                "win_rate_pct": (
                    round(100.0 * int(lb.get("wins") or 0) / closes, 1)
                    if closes else float(prev.get("win_rate_pct") or 0.0)
                ),
                "verdict": prev.get("verdict"),
            }
    # Fold live LAB (OFF-combo) simulated ledger into the per-lane metrics so the dashboard
    # reflects simulated PnL in real time. Kept under lab_* keys; never merged into real_*.
    live_lab_ledger = get_lane_lab_pnl_ledger()
    open_lab = count_open_lab_shadows()
    lab_lanes = set(live_lab_ledger.keys()) | set(open_lab.keys())
    for lane in lab_lanes:
        # Tile 1's convenience ledger predates policy v2 and has no policy
        # dimension.  Its live dashboard metrics come only from versioned raw
        # outcomes below, never from this aggregate legacy cache.
        if lane == RESEARCH_LANE_TYPE_B_HUNTER_V1:
            continue
        lb = live_lab_ledger.get(lane) or {}
        lab_closes = int(lb.get("closes") or 0)
        lab_pnl = float(lb.get("net_pnl_usd") or 0)
        open_info = open_lab.get(lane) or {}
        open_n = int(open_info.get("open") or 0)
        if not (lab_closes or lab_pnl or open_n):
            continue
        prev = disk_metrics.get(lane) or {}
        lab_wins = int(lb.get("wins") or 0)
        disk_metrics[lane] = {
            **prev,
            "lab_mode": True,
            "lab_closes": lab_closes,
            "lab_net_pnl": round(lab_pnl, 2),
            "lab_wins": lab_wins,
            "lab_losses": int(lb.get("losses") or 0),
            "lab_win_rate": round(100.0 * lab_wins / lab_closes, 1) if lab_closes else 0.0,
            "lab_per_close_ev": round(lab_pnl / lab_closes, 2) if lab_closes else 0.0,
            "lab_open_shadows": open_n,
            "lab_open_filled": int(open_info.get("filled") or 0),
            "lab_pnl_source": "lab_ledger",
        }
    # Raw terminal outcomes are the authoritative source for active LAB tiles.
    # Merge after the convenience ledger so stale ledger counts cannot mask results.
    for lane, raw in _load_reconciled_lab_outcome_metrics().items():
        prev = disk_metrics.get(lane) or {}
        disk_metrics[lane] = {
            **prev,
            **raw,
            "lab_ledger_close_delta": int(raw.get("lab_closes") or 0) - int(prev.get("lab_closes") or 0),
        }
    # Ensure every Pathway Lab tile has session_stats (zeros / LAB collecting) so OFF
    # tiles never render blank Trades/PnL/EV fields.
    for spec in static_payload.get("lanes") or []:
        lane = spec.get("lane")
        if lane and lane not in disk_metrics:
            disk_metrics[lane] = {
                "approves": 0,
                "real_fills": 0,
                "approve_to_fill_pct": 0.0,
                "shadow_fill_pct": 0.0,
                "net_pnl_real": 0.0,
                "per_approve_ev": 0.0,
                "lab_mode": False,
                "lab_closes": 0,
                "lab_net_pnl": 0.0,
                "lab_open_shadows": 0,
            }
    settings_breakdown = _settings_period_breakdown()
    merged = []
    for spec in static_payload.get("lanes") or []:
        lane = spec.get("lane")
        row = copy.deepcopy(spec)
        extra = file_by_lane.get(lane) or {}
        for key in ("session_stats", "delta_vs_benchmark"):
            if extra.get(key):
                row[key] = copy.deepcopy(extra[key])
        dm = disk_metrics.get(lane)
        if dm:
            row["session_stats"] = _session_stats_from_lane_metrics(dm)
        row.setdefault("session_stats", {})
        row["session_stats"]["settings_periods"] = _reconcile_settings_periods_to_headline(
            row["session_stats"],
            settings_breakdown.get(lane) or [],
        )
        merged.append(row)
    out = copy.deepcopy(static_payload)
    out["lanes"] = merged
    if file_payload.get("generated_at"):
        out["session_stats_generated_at"] = file_payload.get("generated_at")
    return out


def get_pathway_lane_specs_cached(for_api: bool = False) -> dict:
    """Pathway Lab tiles — static lane defs from code; merge session stats from JSON."""
    global _cached_pathway_lane_specs
    if for_api and not _API_STATE_INLINE_RESEARCH_AGGREGATES:
        # The analyzer owns the expensive aggregation. The API snapshot may
        # read its small materialized JSON, but must never rescan raw ledgers.
        # This also primes tile statistics after a source-only restart.
        static_payload = build_static_pathway_lane_specs()
        exec_mode_sig = tuple(
            (
                str(row.get("lane") or ""),
                str(row.get("exec_mode") or ""),
                str(row.get("exec_block_reason") or ""),
            )
            for row in (static_payload.get("lanes") or [])
        )
        path = os.path.join(os.getcwd(), PATHWAY_LANE_SPECS_FILE)
        analyzer_mtime = None
        try:
            analyzer_mtime = os.path.getmtime(path)
        except OSError:
            pass
        cached = _cached_pathway_lane_specs or {}
        if (
            cached.get("lanes")
            and cached.get("_cached_analyzer_mtime") == analyzer_mtime
            and cached.get("_cached_static_version") == EXECUTION_FIX_VERSION
            and cached.get("_cached_exec_mode_sig") == exec_mode_sig
        ):
            return cached
        if analyzer_mtime is not None:
            try:
                with open(path, encoding="utf-8") as f:
                    analyzer_payload = json.load(f)
                analyzer_by_lane = {
                    str(row.get("lane") or ""): row
                    for row in (analyzer_payload.get("lanes") or [])
                    if row.get("lane")
                }
                settings_breakdown = _settings_period_breakdown()
                merged_lanes = []
                for spec in static_payload.get("lanes") or []:
                    row = copy.deepcopy(spec)
                    analyzer_row = analyzer_by_lane.get(str(spec.get("lane") or "")) or {}
                    for key in ("session_stats", "delta_vs_benchmark"):
                        if analyzer_row.get(key) is not None:
                            row[key] = copy.deepcopy(analyzer_row[key])
                    row.setdefault("session_stats", {})
                    row["session_stats"]["settings_periods"] = _reconcile_settings_periods_to_headline(
                        row["session_stats"],
                        settings_breakdown.get(str(spec.get("lane") or "")) or [],
                    )
                    merged_lanes.append(row)
                payload = copy.deepcopy(static_payload)
                payload["lanes"] = merged_lanes
                payload["session_stats_source"] = "analyzer"
                payload["session_stats_generated_at"] = analyzer_payload.get("generated_at")
                payload["_cached_analyzer_mtime"] = analyzer_mtime
                payload["_cached_static_version"] = EXECUTION_FIX_VERSION
                payload["_cached_exec_mode_sig"] = exec_mode_sig
                _cached_pathway_lane_specs = payload
                return payload
            except Exception as e:
                logger.debug(f"[PATHWAY_LANE_SPECS] analyzer cache load failed: {e}")
        payload = static_payload
        payload["session_stats_deferred"] = True
        payload["session_stats_source"] = "analyzer"
        payload["_cached_exec_mode_sig"] = exec_mode_sig
        return payload
    static_payload = build_static_pathway_lane_specs()
    exec_mode_sig = tuple(
        (
            str(row.get("lane") or ""),
            str(row.get("exec_mode") or ""),
            str(row.get("exec_block_reason") or ""),
        )
        for row in (static_payload.get("lanes") or [])
    )
    path = os.path.join(os.getcwd(), PATHWAY_LANE_SPECS_FILE)
    file_payload = {}
    mtime = None
    ledger_mtime = None
    lab_ledger_mtime = None
    v2_mtime = None
    outcome_mtime = None
    open_lab_sig = ()
    if os.path.isfile(LANE_PNL_LEDGER_FILE):
        try:
            ledger_mtime = os.path.getmtime(LANE_PNL_LEDGER_FILE)
        except Exception:
            pass
    if os.path.isfile(LANE_LAB_PNL_LEDGER_FILE):
        try:
            lab_ledger_mtime = os.path.getmtime(LANE_LAB_PNL_LEDGER_FILE)
        except Exception:
            pass
    if os.path.isfile(SHADOW_LANE_OUTCOME_FILE):
        try:
            outcome_mtime = os.path.getmtime(SHADOW_LANE_OUTCOME_FILE)
        except Exception:
            pass
    try:
        open_lab = count_open_lab_shadows()
        open_lab_sig = tuple(
            sorted((k, int(v.get("open") or 0), int(v.get("filled") or 0)) for k, v in open_lab.items())
        )
    except Exception:
        open_lab_sig = ()
    for v2_path in (V2_SHADOW_OUTCOME_FILE, V2_CHECKER_LOG_FILE):
        if os.path.isfile(v2_path):
            try:
                mt = os.path.getmtime(v2_path)
                v2_mtime = mt if v2_mtime is None else max(v2_mtime, mt)
            except Exception:
                pass
    if os.path.isfile(path):
        try:
            mtime = os.path.getmtime(path)
            cached_at = (_cached_pathway_lane_specs or {}).get("_cached_mtime")
            cached_ver = (_cached_pathway_lane_specs or {}).get("_cached_static_version")
            cached_ledger = (_cached_pathway_lane_specs or {}).get("_cached_ledger_mtime")
            cached_lab_ledger = (_cached_pathway_lane_specs or {}).get("_cached_lab_ledger_mtime")
            cached_v2 = (_cached_pathway_lane_specs or {}).get("_cached_v2_mtime")
            cached_outcome = (_cached_pathway_lane_specs or {}).get("_cached_outcome_mtime")
            cached_open_lab = (_cached_pathway_lane_specs or {}).get("_cached_open_lab_sig")
            cached_exec_mode_sig = (_cached_pathway_lane_specs or {}).get("_cached_exec_mode_sig")
            if (
                cached_at == mtime
                and cached_ver == EXECUTION_FIX_VERSION
                and cached_ledger == ledger_mtime
                and cached_lab_ledger == lab_ledger_mtime
                and cached_v2 == v2_mtime
                and cached_outcome == outcome_mtime
                and cached_open_lab == open_lab_sig
                and cached_exec_mode_sig == exec_mode_sig
                and _cached_pathway_lane_specs.get("lanes")
            ):
                return _cached_pathway_lane_specs
            with open(path, encoding="utf-8") as f:
                file_payload = json.load(f)
        except Exception as e:
            logger.debug(f"[PATHWAY_LANE_SPECS] load failed: {e}")
    merged = _merge_pathway_specs_with_session_stats(static_payload, file_payload)
    merged["_cached_static_version"] = EXECUTION_FIX_VERSION
    if mtime is not None:
        merged["_cached_mtime"] = mtime
    merged["_cached_ledger_mtime"] = ledger_mtime
    merged["_cached_lab_ledger_mtime"] = lab_ledger_mtime
    merged["_cached_v2_mtime"] = v2_mtime
    merged["_cached_outcome_mtime"] = outcome_mtime
    merged["_cached_open_lab_sig"] = open_lab_sig
    merged["_cached_exec_mode_sig"] = exec_mode_sig
    _cached_pathway_lane_specs = merged
    return merged


def get_pathway_scorecard_cached(for_api: bool = False) -> dict:
    global _cached_pathway_scorecard, _last_pathway_scorecard_api_ts
    if not is_research_data_collection():
        return _cached_pathway_scorecard or {}
    if for_api:
        now = time.time()
        if _cached_pathway_scorecard:
            return _cached_pathway_scorecard
        if now - _last_pathway_scorecard_api_ts < 60:
            return {}
        try:
            from pathway_scorecard_engine import load_pathway_scorecard
            loaded = load_pathway_scorecard(os.getcwd())
            if loaded:
                _cached_pathway_scorecard = loaded
            _last_pathway_scorecard_api_ts = now
            return loaded or {}
        except Exception as e:
            logger.debug(f"[PATHWAY_SCORECARD] api load failed: {e}")
            _last_pathway_scorecard_api_ts = now
            return {}
    now = time.time()
    if _cached_pathway_scorecard and now - _last_pathway_scorecard_api_ts < PATHWAY_SCORECARD_API_MIN_SEC:
        return _cached_pathway_scorecard
    try:
        from pathway_scorecard_engine import load_pathway_scorecard, scorecard_is_stale, refresh_pathway_scorecard
        if scorecard_is_stale(os.getcwd()):
            _cached_pathway_scorecard = refresh_pathway_scorecard(
                os.getcwd(),
                bot_version=EXECUTION_FIX_VERSION,
                lanes_live=_pathway_lanes_live(),
                fresh_collection_mode=bool(state.get("fresh_collection_mode", False)),
            )
            _last_pathway_scorecard_api_ts = now
        else:
            loaded = load_pathway_scorecard(os.getcwd())
            if loaded:
                _cached_pathway_scorecard = loaded
                _last_pathway_scorecard_api_ts = now
            elif not _cached_pathway_scorecard:
                _cached_pathway_scorecard = refresh_pathway_scorecard_live()
                _last_pathway_scorecard_api_ts = now
    except Exception as e:
        logger.debug(f"[PATHWAY_SCORECARD] load failed: {e}")
    return _cached_pathway_scorecard or {}


def refresh_pathway_scorecard_live() -> dict:
    global _cached_pathway_scorecard
    try:
        from pathway_scorecard_engine import refresh_pathway_scorecard
        _cached_pathway_scorecard = refresh_pathway_scorecard(
            os.getcwd(),
            bot_version=EXECUTION_FIX_VERSION,
            lanes_live=_pathway_lanes_live(),
            fresh_collection_mode=bool(state.get("fresh_collection_mode", False)),
        )
    except Exception as e:
        logger.warning(f"[PATHWAY_SCORECARD] refresh failed: {e}")
    return _cached_pathway_scorecard or {}


def get_research_kpis_cached(for_api: bool = False) -> dict:
    """Dashboard KPIs — false reject rate, calibration, AI vs shadow."""
    global _last_research_kpi_ts, _cached_research_kpis, _research_kpi_disabled
    if _research_kpi_disabled:
        return _cached_research_kpis or {}
    if not is_research_data_collection():
        return {}
    if for_api:
        return _cached_research_kpis or {}
    now = time.time()
    if now - _last_research_kpi_ts < RESEARCH_KPI_INTERVAL_SEC and _cached_research_kpis:
        return _cached_research_kpis
    # Stamp the interval BEFORE the import attempt so a missing module doesn't
    # re-trigger this every call.
    _last_research_kpi_ts = now
    try:
        from research_kpi_engine import refresh_all_research_kpis
        _cached_research_kpis = refresh_all_research_kpis(os.getcwd())
    except ModuleNotFoundError as e:
        _research_kpi_disabled = True
        logger.info(
            "RESEARCH_KPI module missing — disabling periodic KPI refresh "
            f"(missing={getattr(e, 'name', 'research_kpi_engine')}) [PIPELINE ENFORCEMENT]"
        )
    except Exception as e:
        logger.warning(f"[RESEARCH_KPI] refresh failed: {e}")
    return _cached_research_kpis or {}


def _buf_float(val, default=0.0):
    """Replay buffer numeric — never pass None to float()."""
    return nz(val, default)


def _buf_int(val, default=0):
    return int(_buf_float(val, default))


def _replay_leverage_default() -> int:
    return _buf_int(state.get("leverage"), DEFAULT_RESEARCH_LEVERAGE)


def _state_leverage() -> int:
    """Canonical showcase leverage — never fall back to legacy 20x on live paths."""
    return max(1, int(state.get("leverage") or DEFAULT_RESEARCH_LEVERAGE))
