def _relay_order_row_lite(row: dict, now_ts: float, tick_px) -> dict:
    """Exact resting-limit state needed for copy, chase, and abandon checks."""
    if not isinstance(row, dict):
        return {}
    out = {
        "trade_id": row.get("trade_id"),
        "shared_ai_call_id": row.get("shared_ai_call_id"),
        "shared_ai_call_ts": row.get("shared_ai_call_ts"),
        "source_trade_id": row.get("source_trade_id"),
        "status": row.get("status"),
        "side": row.get("side") or row.get("signal_dir") or row.get("dir"),
        "signal_dir": row.get("signal_dir") or row.get("dir") or row.get("side"),
        "dir": row.get("dir") or row.get("signal_dir") or row.get("side"),
        "qty": row.get("qty"),
        "requested_margin_usd": (
            row.get("margin_usdt")
            if row.get("requested_margin_usd") is None
            else row.get("requested_margin_usd")
        ),
        "requested_notional_usd": row.get("requested_notional_usd"),
        "accepted_margin_usd": row.get("accepted_margin_usd"),
        "accepted_notional_usd": row.get("accepted_notional_usd"),
        "limit_price": row.get("limit_price"),
        "original_limit_price": row.get("original_limit_price") or row.get("planned_limit_price"),
        "signal_price": row.get("signal_price"),
        "created_ts": row.get("created_ts"),
        "age_min": (now_ts - row["created_ts"]) / 60 if row.get("created_ts") else 0,
        "limit_chase_count": row.get("limit_chase_count") or 0,
        "dashboard_chase_activation_count": row.get("dashboard_chase_activation_count"),
        "chase_3plus_virtual_chase_count": row.get("chase_3plus_virtual_chase_count"),
        "entry_limit_policy": row.get("entry_limit_policy"),
        "entry_reason": row.get("entry_reason"),
        "research_lane": row.get("research_lane"),
        "research_model": row.get("research_model"),
        "ttl_sec": row.get("ttl_sec"),
        "expires_ts": row.get("expires_ts"),
    }
    if tick_px and float(tick_px) > 0:
        out["limit_touched"] = _pending_limit_touched(row, float(tick_px))
    return out


def _relay_position_row_lite(row: dict, tick_px) -> dict:
    """Open position truth required by flatness, mirror, and exit checks."""
    if not isinstance(row, dict):
        return {}
    protection_view = _position_protection_view(row)
    out = {
        "trade_id": row.get("trade_id"),
        "shared_ai_call_id": row.get("shared_ai_call_id"),
        "shared_ai_call_ts": row.get("shared_ai_call_ts"),
        "source_trade_id": row.get("source_trade_id"),
        "status": row.get("status"),
        "dir": row.get("dir") or row.get("side"),
        "side": row.get("side") or row.get("dir"),
        "entry": row.get("entry"),
        "qty": row.get("qty"),
        "requested_margin_usd": row.get("requested_margin_usd") or row.get("margin_usdt"),
        "requested_notional_usd": row.get("requested_notional_usd"),
        "accepted_margin_usd": row.get("accepted_margin_usd"),
        "accepted_notional_usd": row.get("accepted_notional_usd"),
        "sl": protection_view["sl"],
        "sl_enforced": protection_view["sl_enforced"],
        "stop_policy": protection_view["stop_policy"],
        "tp": protection_view["tp"],
        "tp_policy": protection_view["tp_policy"],
        "leverage": row.get("leverage"),
        "funding_fees": row.get("funding_fees"),
        "created_ts": row.get("created_ts") or row.get("signal_created_ts"),
        "signal_created_ts": row.get("signal_created_ts") or row.get("created_ts"),
        "order_created_ts": row.get("order_created_ts"),
        "entry_ts": row.get("entry_ts") or row.get("fill_ts"),
        "fill_ts": row.get("fill_ts") or row.get("entry_ts"),
        "current_price": tick_px,
        "research_lane": row.get("research_lane"),
        "research_model": row.get("research_model"),
        "policy_remaining_fraction": row.get("policy_remaining_fraction"),
        "partial_exit_receipts": copy.deepcopy(row.get("partial_exit_receipts") or []),
        "partial_reduction_outbox": copy.deepcopy(row.get("partial_reduction_outbox") or []),
    }
    # The active dashboard overlays this bounded relay row while paper execution
    # is running. Keep the presentation P&L fields in the overlay too; otherwise
    # a real open paper position renders as "-% $-" even though its mark is fresh.
    try:
        entry = float(row.get("entry") or 0)
        mark = float(tick_px or 0)
        leverage = float(row.get("leverage") or DEFAULT_RESEARCH_LEVERAGE)
        if entry > 0 and mark > 0 and leverage > 0:
            direction = str(row.get("dir") or row.get("side") or "LONG").upper()
            dir_factor = -1.0 if direction == "SHORT" else 1.0
            move_pct = ((mark - entry) / entry) * 100.0 * dir_factor
            gross_usd = (move_pct / 100.0) * FIXED_MARGIN_USDT * leverage
            funding_acc = float(row.get("funding_fees") or 0.0)
            out["pnl_pct_margin"] = move_pct * leverage
            out["unreal_usd_gross"] = gross_usd
            out["funding_fees_accrued"] = funding_acc
            out["unreal_usd"] = round(gross_usd - funding_acc, 4)
    except (TypeError, ValueError, OverflowError):
        # Position identity/flatness remains authoritative even if a malformed
        # optional presentation value cannot be calculated.
        pass
    return out


def _build_relay_execution_state_snapshot() -> dict:
    """Small canonical money-path snapshot built directly from in-memory truth.

    The public relay/dashboard snapshot contains research history and presentation
    ledgers and can take seconds to rebuild on the home PC.  Live execution must
    never queue behind that work.  This endpoint deliberately contains only the
    exact limit/order/position/closure fields consumed by the isolated executor.
    """
    now_ts = time.time()
    runtime = _recompute_system_readiness(now_ts)
    exchange_audit = _exchange_exposure_audit_snapshot(now_ts)
    exit_tick_px = _observable_exit_price()
    session_start = _showcase_trade_session_start()
    state_acquired = state_lock.acquire(timeout=_RELAY_EXECUTION_LOCK_TIMEOUT_SEC)
    if not state_acquired:
        raise TimeoutError("relay execution snapshot timed out waiting for state_lock")
    try:
        debug_state = state.get("debug_state") or {}
        tick_px = state.get("price")
        price_ts = float(state.get("price_ts") or 0)
        snapshot = {
            "price": tick_px,
            "price_ts": state.get("price_ts"),
            "price_source": state.get("price_source"),
            "data_source": state.get("data_source"),
            "data_quality": state.get("data_quality"),
            "ws_ready": bool(state.get("ws_ready", False)),
            "ws_transport_connected": bool(state.get("ws_transport_connected", False)),
            "ws_age": (
                now_ts - float(state.get("ws_last_tick") or 0)
                if state.get("ws_last_tick")
                else None
            ),
            "ws_last_tick": state.get("ws_last_tick"),
            "rest_price": state.get("rest_price"),
            "rest_price_ts": state.get("rest_price_ts"),
            "rest_last_tick": state.get("rest_last_tick"),
            "bot_version": EXECUTION_FIX_VERSION,
            **_dashboard_owner_metadata(),
            "bot_start_time": bot_start_time,
            "last_fresh_reset_ts": state.get("last_fresh_reset_ts"),
            "fresh_collection_mode": bool(state.get("fresh_collection_mode", False)),
            "execution_paused": bool(state.get("execution_paused", False)),
            "execution_reason": state.get("execution_reason"),
            "manual_admin_pause": bool(state.get("manual_admin_pause", False)),
            "continuous_ai_research_enabled": bool(
                state.get("continuous_ai_research_enabled", CONTINUOUS_AI_DEFAULT_ENABLED)
            ),
            "continuous_paper_orders_enabled": bool(
                state.get("continuous_ai_research_enabled", CONTINUOUS_AI_DEFAULT_ENABLED)
            ),
            "shared_research_ai_observation_enabled": shared_research_ai_observation_enabled(),
            "research_lane_enabled": copy.deepcopy(state.get("research_lane_enabled") or {}),
            "max_active_signals": state.get("max_active_signals", MAX_CONCURRENT_POSITIONS_DEFAULT),
            "strategy_mode": state.get("strategy_mode"),
            "last_approve_outcome": copy.deepcopy(state.get("last_approve_outcome")),
            "last_ai": copy.deepcopy(state.get("last_ai")),
            "pullback_threshold": state.get("pullback_threshold"),
            "last_edge": state.get("last_edge"),
            "leverage": state.get("leverage"),
            "regime": state.get("regime"),
            # Dashboard diagnostics are presentation-only, but they must come
            # from the same live state receipt as price and execution rows.
            # Keeping only last_edge_score froze heartbeat, AI-call, funnel,
            # and lane-opportunity fields at the first heavy dashboard build.
            "debug_state": copy.deepcopy(debug_state),
            "heartbeat": state.get("heartbeat"),
            "last_heartbeat": state.get("last_heartbeat"),
            "pipeline_funnel_counters": copy.deepcopy(
                state.get("pipeline_funnel_counters") or {}
            ),
            "lane_opportunity_counters": copy.deepcopy(
                state.get("lane_opportunity_counters") or {}
            ),
            "live_armed": bool(state.get("live_armed", False)),
            "system_ready": runtime["system_ready"],
            "signal_generation_ready": runtime["signal_generation_ready"],
            "new_entry_progress_ready": runtime["signal_generation_ready"],
            "new_entry_block_reason": (
                None
                if runtime["signal_generation_ready"]
                else (
                    runtime["readiness_reasons"][0]
                    if runtime["readiness_reasons"]
                    else "NEW_ENTRY_NOT_READY"
                )
            ),
            "runtime_readiness": runtime,
            "server_ts": utc_iso(),
        }
    finally:
        state_lock.release()
    trade_acquired = trade_lock.acquire(timeout=_RELAY_EXECUTION_LOCK_TIMEOUT_SEC)
    if not trade_acquired:
        raise TimeoutError("relay execution snapshot timed out waiting for trade_lock")
    try:
        pending_copy = copy.deepcopy(pending_orders)
        positions_copy = copy.deepcopy(open_positions)
        recent_trades = copy.deepcopy(_snapshot_trades_for_api(session_start))
        relay_trades_copy = copy.deepcopy(trades[-_RELAY_TRADES_MAP_MAX:])
        fidelity_trades = [
            _relay_fidelity_trade_row(row)
            for row in trades[-_RELAY_FIDELITY_TRADES_MAX:]
            if isinstance(row, dict)
        ]
        visible_expired = [
            row
            for row in expired_orders
            if isinstance(row, dict)
            and str(row.get("research_lane") or "").upper() != "AI_SCAN"
        ]
        expired_orders_total = len(visible_expired)
        recent_expired = copy.deepcopy(visible_expired[-MAX_EXPIRED_ORDERS:])
        bounded_trades_map = _snapshot_bounded_trades_map_locked(
            pending_copy,
            positions_copy,
        )
    finally:
        trade_lock.release()
    active_list, _ = _collect_dashboard_active_signals(
        pending_copy,
        positions_copy,
        bounded_trades_map,
        default_strategy=snapshot.get("strategy_mode", "-"),
        default_regime=snapshot.get("regime", "-"),
    )
    trades_map_lite = _relay_trades_map_lite(
        bounded_trades_map,
        relay_trades_copy,
    )
    snapshot["orders"] = [
        _relay_order_row_lite(row, now_ts, tick_px)
        for row in pending_copy
        if isinstance(row, dict)
    ]
    snapshot["positions"] = [
        _relay_position_row_lite(row, exit_tick_px)
        for row in positions_copy
        if isinstance(row, dict)
    ]
    snapshot["trades"] = [
        _relay_trade_row_lite(row)
        for row in recent_trades
        if isinstance(row, dict)
    ]
    snapshot["fidelity_trades"] = fidelity_trades
    snapshot["expired_orders"] = _dashboard_expired_order_rows(recent_expired)
    snapshot["expired_orders_total"] = expired_orders_total
    snapshot["signal_info"] = {
        "active": bool(active_list),
        "count": len(active_list),
        "signals": active_list,
    }
    # Keep per-lane tile exposure aligned with the same bounded execution
    # snapshot used for Positions and Pending Orders.  The heavy presentation
    # payload is intentionally cached while paper execution is running, so
    # these counts must travel through the live overlay as well or they freeze
    # at the values observed during the first heavy build.
    snapshot["lane_position_counts"] = {}
    for lane_name in dict.fromkeys(
        PATHWAY_LAB_LANES + (RESEARCH_LANE_CONTINUOUS,)
    ):
        snapshot["lane_position_counts"][lane_name] = {
            "open": sum(
                1
                for position in positions_copy
                if position.get("status") == "OPEN"
                and _normalize_lane_key(position) == lane_name
            ),
            "pending": sum(
                1
                for order in pending_copy
                if _normalize_lane_key(order) == lane_name
            ),
        }
    snapshot["trades_map"] = trades_map_lite
    # Money-path PnL / counters / lane ledger: these feed the dashboard
    # tiles via the ACTIVE_EXECUTION_OVERLAY path (see
    # _api_state_cache_refresher_loop). Computing them here from the same
    # `recent_trades` slice already shipped as snapshot["trades"] keeps the
    # tile numbers identical to the trades table. Previously these keys
    # were only emitted by the heavy _build_api_state_snapshot and the
    # overlay did not include them, so under live trading the tile froze
    # at the first heavy build and under-counted every trade that closed
    # afterwards.
    session_trade_count = sum(1 for _r in recent_trades if isinstance(_r, dict))
    session_realized_pnl = 0.0
    for _r in recent_trades:
        if not isinstance(_r, dict):
            continue
        try:
            session_realized_pnl += float(_r.get("net_pnl_usd") or _r.get("net") or 0.0)
        except (TypeError, ValueError):
            continue
    session_realized_pnl = round(session_realized_pnl, 2)
    snapshot["trade_count_session"] = session_trade_count
    snapshot["trade_count"] = session_trade_count
    snapshot["session_pnl_usd"] = session_realized_pnl
    snapshot["trades_display_limit"] = _DASHBOARD_TRADES_MAX
    snapshot["lane_pnl_ledger"] = _derive_lane_pnl_ledger_from_trades(recent_trades)
    _display_balance = get_display_balance()
    snapshot["account_balance"] = _display_balance
    # Best-effort equity: account_balance + unrealized PnL of open positions.
    # The heavy path computes this with full funding/mark enrichment; for the
    # overlay we accept the already-computed position rows so the tile stays
    # within ~1 tick of the authoritative number and never freezes again.
    try:
        _overlay_unreal = 0.0
        for _p in positions_copy:
            if isinstance(_p, dict) and _p.get("unreal_usd") is not None:
                try:
                    _overlay_unreal += float(_p.get("unreal_usd") or 0.0)
                except (TypeError, ValueError):
                    pass
        snapshot["equity"] = round(float(_display_balance) + _overlay_unreal, 4)
    except Exception:
        snapshot["equity"] = _display_balance
    snapshot["snapshot_age_sec"] = 0
    snapshot["relay_cache"] = {"mode": "EXECUTION_DIRECT", "age_sec": 0}
    # Surface relay-push health and DDollar gate state on this lightweight
    # money-path snapshot too. The full /api/relay-state endpoint exposes
    # both via its own integrity builder; without mirroring them here, audit
    # dashboards and verification checklists that only read
    # /api/relay-execution-state cannot confirm relay delivery health or
    # DDollar entry-gate state, which has previously led to false "field
    # missing" reports. Read-only — never places orders or mutates state.
    relay_url_exec = (os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip()
    relay_push_summary = {
        "configured": bool(relay_url_exec),
        "seq": _relay_push_state["seq"],
        "last_event": _relay_push_state["last_event"],
        "last_ok": _relay_push_state["last_ok"],
        "last_error": _relay_push_state["last_error"],
        "last_latency_ms": _relay_push_state["last_latency_ms"],
        "last_sec_ago": (
            now_ts - _relay_push_state["last_ts"]
        ) if _relay_push_state["last_ts"] else None,
        "recent_deliveries_count": len(_relay_delivery_history_snapshot(10)),
    }
    ddollar_gate_summary = None
    try:
        import bitfinex_live_executor as _bx_exec
        ddollar_gate_summary = _bx_exec.ddollar_gate_status()
    except Exception as exc:
        ddollar_gate_summary = {"error": str(exc)[:200]}
    snapshot["state_integrity"] = {
        "snapshot_ts": snapshot["server_ts"],
        "snapshot_age_sec": 0,
        "bot_version": EXECUTION_FIX_VERSION,
        "execution_paused": snapshot["execution_paused"],
        "live_armed": snapshot["live_armed"],
        "rest_healthy": bool(
            snapshot.get("rest_last_tick")
            and now_ts - float(snapshot.get("rest_last_tick")) < 30
        ),
        "price_age_sec": (now_ts - price_ts) if price_ts else None,
        "orders_synced": bool(exchange_audit.get("fresh") and exchange_audit.get("orders_synced")),
        "positions_synced": bool(exchange_audit.get("fresh") and exchange_audit.get("positions_synced")),
        "trades_synced": bool(exchange_audit.get("fresh") and exchange_audit.get("trades_synced")),
        "exchange_sync_audit": exchange_audit,
        "system_ready": runtime["system_ready"],
        "signal_generation_ready": runtime["signal_generation_ready"],
        "readiness_reasons": runtime["readiness_reasons"],
        "relay_push": relay_push_summary,
        "ddollar_gate": ddollar_gate_summary,
    }
    return snapshot


@app.route('/api/relay-execution-state')
def api_relay_execution_state():
    """Canonical execution authority served without money-state lock access."""
    payload, body, age = _cached_relay_execution_snapshot()
    if body is None:
        # Cold bootstrap gets one bounded synchronous attempt. Concurrent cold
        # callers fail closed rather than becoming duplicate snapshot builders.
        try:
            _publish_relay_execution_snapshot()
        except Exception as exc:
            logger.error(f"/api/relay-execution-state cold build error: {exc}")
        payload, body, age = _cached_relay_execution_snapshot()
    if body is None or age is None or age > _RELAY_EXECUTION_MAX_STALE_SEC:
        stale_age = round(age, 3) if isinstance(age, (int, float)) else None
        response = jsonify({
            "api_state_error": "canonical execution snapshot unavailable or stale",
            "snapshot_age_sec": stale_age,
            "bot_version": EXECUTION_FIX_VERSION,
        })
        response.status_code = 503
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
        response.headers["X-Relay-State-Cache"] = "EXECUTION_STALE"
        return response
    response = app.response_class(body, status=200, mimetype="application/json")
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    response.headers["X-Relay-State-Cache"] = "EXECUTION_BACKGROUND"
    response.headers["X-Relay-State-Age"] = f"{age:.3f}"
    return response


@app.route('/api/relay-state')
def api_relay_state(force_rebuild: bool = False):
    """Fast subset for Railway relay / Agent Hub — no heavy research KPIs."""
    global _RELAY_STATE_CACHE, _RELAY_STATE_CACHE_AT
    if not force_rebuild:
        cached = _cached_relay_state_response("BACKGROUND")
        if cached is not None:
            return cached
        return jsonify({
            "api_state_error": "no bounded-fresh relay snapshot is available",
            "bot_version": EXECUTION_FIX_VERSION,
        }), 503
    refresh_acquired = _RELAY_STATE_REFRESH_LOCK.acquire(blocking=False)
    if not refresh_acquired:
        cached = _cached_relay_state_response("STALE_WHILE_REFRESHING")
        if cached is not None:
            return cached
        return jsonify({
            "api_state_error": "relay snapshot refresh busy and no bounded-fresh cache is available",
            "bot_version": EXECUTION_FIX_VERSION,
        }), 503
    try:
        now_ts = time.time()
        session_start = _showcase_trade_session_start()
        with state_lock:
            price = state.get("price")
            debug_state = state.get("debug_state") or {}
            snapshot = {
                "price": price,
                "bot_version": EXECUTION_FIX_VERSION,
                **_dashboard_owner_metadata(),
                "bot_start_time": bot_start_time,
                "last_fresh_reset_ts": state.get("last_fresh_reset_ts"),
                "fresh_collection_mode": bool(state.get("fresh_collection_mode", False)),
                "execution_paused": bool(state.get("execution_paused", False)),
                "execution_reason": state.get("execution_reason"),
                "max_active_signals": state.get("max_active_signals", MAX_CONCURRENT_POSITIONS_DEFAULT),
                "strategy_mode": state.get("strategy_mode"),
                "dashboard_port": DASHBOARD_PORT,
                # Relay execution path (pollBotForIntents + buildIntentEnvelope) needs these.
                # Without last_approve_outcome the relay never creates INTENT cycles => sim
                # mirrors nothing. /api/state carries them but is 108KB and times out through
                # the canonical Fly route; relay-state is bounded, so include them here.
                "last_approve_outcome": copy.deepcopy(state.get("last_approve_outcome")),
                "last_ai": copy.deepcopy(state.get("last_ai")),
                "pullback_threshold": state.get("pullback_threshold"),
                "last_edge": state.get("last_edge"),
                "leverage": state.get("leverage"),
                "regime": state.get("regime"),
                "debug_state": {"last_edge_score": debug_state.get("last_edge_score")},
            }
        with trade_lock:
            pending_orders_copy = copy.deepcopy(pending_orders)
            positions_copy = copy.deepcopy(open_positions)
            relay_trades_copy = copy.deepcopy(trades[-_RELAY_TRADES_MAP_MAX:])
            fidelity_trades = [
                _relay_fidelity_trade_row(row)
                for row in trades[-_RELAY_FIDELITY_TRADES_MAX:]
                if isinstance(row, dict)
            ]
            trades_for_relay = [
                _relay_trade_row_lite(copy.deepcopy(row))
                for row in _snapshot_trades_for_api(session_start)
                if isinstance(row, dict)
            ]
            bounded_trades_map = _snapshot_bounded_trades_map_locked(
                pending_orders_copy,
                positions_copy,
            )
            orders = []
            tick_px = snapshot.get("price")
            for o in pending_orders_copy:
                oc = copy.deepcopy(o)
                oc["age_min"] = (now_ts - o["created_ts"]) / 60 if o.get("created_ts") else 0
                if tick_px and tick_px > 0:
                    oc["limit_touched"] = _pending_limit_touched(o, float(tick_px))
                orders.append(oc)
            expired_orders_copy = copy.deepcopy(expired_orders)
        active_list, _exposure = _collect_dashboard_active_signals(
            pending_orders_copy,
            positions_copy,
            bounded_trades_map,
            default_strategy=snapshot.get("strategy", "-"),
            default_regime=snapshot.get("regime", "-"),
        )
        snapshot["orders"] = orders
        snapshot["positions"] = positions_copy
        snapshot["trades"] = trades_for_relay
        snapshot["fidelity_trades"] = fidelity_trades
        snapshot["expired_orders"] = _dashboard_expired_order_rows(
            expired_orders_copy,
            _DASHBOARD_HISTORY_MAX,
        )
        snapshot["signal_info"] = {
            "active": len(active_list) > 0,
            "count": len(active_list),
            "signals": active_list,
        }
        snapshot["chase_execution_buckets"] = get_chase_execution_buckets()
        snapshot["spread_gate"] = get_spread_gate()
        snapshot["ai_execution_bands"] = get_ai_execution_bands()
        snapshot["dashboard_execution_gates"] = get_dashboard_execution_status()
        _enrich_orders_for_relay(snapshot)
        snapshot["trades_map"] = _relay_trades_map_lite(
            bounded_trades_map,
            relay_trades_copy,
        )
        snapshot["paper_book"] = build_paper_order_book(_DASHBOARD_TRADES_MAX)
        snapshot["server_ts"] = utc_iso()
        bridge = get_genome_bridge()
        if bridge:
            snapshot["genome_bus_seq"] = bridge.bus_seq
            snapshot["genome_stats"] = bridge.stats()
        snapshot["state_integrity"] = build_state_integrity()
        snapshot["snapshot_age_sec"] = 0
        snapshot["relay_cache"] = {"mode": "REBUILT", "age_sec": 0}
        with _RELAY_STATE_CACHE_LOCK:
            _RELAY_STATE_CACHE = copy.deepcopy(snapshot)
            _RELAY_STATE_CACHE_AT = time.monotonic()
        resp = jsonify(snapshot)
        resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
        resp.headers["X-Relay-State-Cache"] = "REBUILT"
        return resp
    except Exception as e:
        logger.error(f"/api/relay-state error: {e}")
        return jsonify({"api_state_error": str(e)[:500], "bot_version": EXECUTION_FIX_VERSION}), 500
    finally:
        if refresh_acquired:
            _RELAY_STATE_REFRESH_LOCK.release()


@app.route('/api/build')
def api_build():
    """Single source of truth for which code build is running (cache-bust dashboards)."""
    return jsonify({
        "stack_version": EXECUTION_FIX_VERSION,
        "analyzer_sync_id": ANALYZER_SYNC_ID,
        "bot_pid": os.getpid(),
        **_dashboard_owner_metadata(),
        "cwd": os.getcwd(),
        "dashboard_url": dashboard_public_url(),
        "agent_hub_url": AGENT_HUB_PUBLIC_URL,
        "analyzer_url": research_dashboard_public_url(),
        "features": RESEARCH_STACK_FEATURES,
        "server_ts": utc_iso(),
    }), 200


# ---- Read-only analyzer proxy (exposes :9001 research dashboard through the
#      bot's public Cloudflare tunnel so Vercel/Railway can reach it). The
#      analyzer itself is not publicly tunneled; the bot is. These routes only
#      forward GETs to localhost:9001 — no writes, no bot state mutation.
def _analyzer_proxy_fetch(path: str, timeout: float = 6.0):
    base = research_dashboard_public_url().rstrip("/")
    url = f"{base}{path}"
    import urllib.request
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            body = resp.read()
            return resp.status, body
    except Exception as exc:
        logger.warning(f"analyzer proxy {url} failed: {exc}")
        return None, None


def _external_analyzer_status_payload(endpoint: str) -> dict:
    """Truthful Fly response: analysis is uploaded, never localhost-proxied."""
    mirror_status = {}
    active = _active_analyzer_mirror_dir()
    if active is not None:
        mirror_dir = active
    else:
        mirror_dir = _analyzer_mirror_dir()
    try:
        mirror_status = json.loads(
            (mirror_dir / "status.json").read_text(encoding="utf-8")
        )
    except (OSError, ValueError, TypeError):
        mirror_status = {}
    return {
        "ok": False,
        "endpoint": endpoint,
        "mode": "external_desktop_analyzer",
        "source": "Fly trading owner + uploaded desktop analyzer mirror",
        "live_analyzer_process": False,
        "mirror_available": (mirror_dir / "analysis_dashboard.html").is_file(),
        "mirror_status": mirror_status,
        "dashboard_path": "/analysis",
        "status_path": "/api/analyzer-mirror/status",
        "note": (
            "Fly intentionally runs the trading owner only; fresh analyzer and "
            "genome outputs are produced externally and uploaded as a mirror."
        ),
    }


def _external_analyzer_response(endpoint: str):
    resp = jsonify(_external_analyzer_status_payload(endpoint))
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    return resp, 200


@app.route('/api/analyzer/summary')
def api_analyzer_summary():
    """Proxy to research dashboard /api/summary — full-session PnL/WR/trade count."""
    if (os.getenv("FLY_APP_NAME") or "").strip():
        return _external_analyzer_response("summary")
    status, body = _analyzer_proxy_fetch("/api/summary")
    if status is None:
        return jsonify({"ok": False, "error": "analyzer unreachable on :9001"}), 502
    try:
        payload = json.loads(body)
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "analyzer returned invalid JSON"}), 502
    resp = jsonify(payload)
    resp.headers["Cache-Control"] = "public, max-age=15"
    return resp


@app.route('/api/analyzer/genome')
def api_analyzer_genome():
    """Proxy to research dashboard /api/genome — decision genome library/discoveries."""
    if (os.getenv("FLY_APP_NAME") or "").strip():
        return _external_analyzer_response("genome")
    status, body = _analyzer_proxy_fetch("/api/genome", timeout=10.0)
    if status is None:
        return jsonify({"ok": False, "error": "analyzer unreachable on :9001"}), 502
    try:
        payload = json.loads(body)
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "analyzer returned invalid JSON"}), 502
    resp = jsonify(payload)
    resp.headers["Cache-Control"] = "public, max-age=30"
    return resp


_DASHBOARD_TRADE_API_KEYS = (
    "ts", "ts_melbourne", "trade_id", "research_lane", "research_model",
    "final_direction", "dir", "entry", "exit", "dur_min", "pnl",
    "net_pnl_usd", "gross_pnl_usd", "trading_fees_usd", "fees_usd",
    "funding_fees_usd", "ai_band", "exit_reason", "close_ts_melbourne",
    "dual_execution_truth", "copy_fill_observed",
    "exchange_confirmed_shadow_overlay",
)


def _slim_trade_for_dashboard(trade: dict) -> dict:
    """Dashboard trades table only needs a small column subset — full CSV rows are megabytes."""
    if not isinstance(trade, dict):
        return trade
    row = _enrich_melbourne_time_fields(trade)
    return {k: row.get(k) for k in _DASHBOARD_TRADE_API_KEYS if row.get(k) not in (None, "")}


def _session_trade_count() -> int:
    """Count session trades for dashboard totals without copying rows."""
    session_start = _showcase_trade_session_start()
    with trade_lock:
        if not session_start:
            return len(trades)
        return sum(1 for t in trades if _trade_row_in_session(t, session_start))


def _session_realized_pnl_usd() -> float:
    """Cumulative realized session P&L (closed trades only) in USD.

    Stable across polls -- does NOT include unrealized P&L of open positions,
    so the dashboard's "SESSION P&L" stays consistent instead of swinging with
    the mark price. This is the value the analyzer/Agent Hub display as the
    showcase bot's session P&L.
    """
    session_start = _showcase_trade_session_start()
    with trade_lock:
        if session_start:
            src = [t for t in trades if _trade_row_in_session(t, session_start)]
        else:
            src = list(trades)
        total = 0.0
        for t in src:
            val = t.get("net_pnl_usd")
            if val is None or val == "":
                val = t.get("net")
            try:
                total += float(val or 0.0)
            except (TypeError, ValueError):
                continue
        return round(total, 2)


def _snapshot_trades_for_api(session_start: float):
    """Session-filtered trade rows for /api/state — cap size so dashboard polls stay fast."""
    if session_start:
        src = [t for t in trades if _trade_row_in_session(t, session_start)]
    else:
        src = list(trades)
    if len(src) > _DASHBOARD_TRADES_MAX:
        src = src[-_DASHBOARD_TRADES_MAX:]
    try:
        from research.dual_execution_truth import split_execution_truth
        from research.platform_relay_evidence import (
            _platform_relay_evidence_index,
            _snapshot_with_platform_relay_evidence,
        )
        index = _platform_relay_evidence_index()
    except Exception:
        split_execution_truth = None
        index = {}
    rows = []
    for trade in src:
        row = dict(trade) if isinstance(trade, dict) else trade
        tid = str((row or {}).get("trade_id") or "") if isinstance(row, dict) else ""
        if isinstance(row, dict) and tid and index and tid in index:
            row = _snapshot_with_platform_relay_evidence(row, tid, index)
        if isinstance(row, dict) and callable(split_execution_truth):
            try:
                row["dual_execution_truth"] = split_execution_truth(row)
            except Exception:
                pass
        rows.append(row)
    return rows


def _attach_patient_chase_routes(
    ai_history: list,
    *,
    signals=(),
    pending=(),
    positions=(),
    closed=(),
    expired=(),
) -> tuple[list, dict]:
    """Attach genuine Patient Chase lifecycle state to each shared AI call."""
    lane = RESEARCH_LANE_OFFSET_029_ATR_TP_25
    priority = {"APPROVED_NO_ORDER": 0, "EXPIRED": 1, "CLOSED": 2, "PENDING": 3, "OPEN": 4}
    by_call = {}
    counts = {
        "pending": 0,
        "open": 0,
        "closed": 0,
        "expired": 0,
        "unlinked_lifecycle_rows": 0,
    }
    lifecycle_by_trade = {}
    unlinked_lifecycle_trade_ids = set()

    # The lightweight relay overlay intentionally receives sanitized orders and
    # positions without private causal identity fields.  It runs after the full
    # state snapshot has already joined those rows.  Seed that verified result
    # so the overlay cannot downgrade OPEN/PENDING to NOT_SELECTED merely
    # because its reduced payload cannot repeat the join.
    for existing in ai_history or ():
        if not isinstance(existing, dict):
            continue
        call_id = str(existing.get("shared_ai_call_id") or existing.get("trade_id") or "")
        route = existing.get("patient_chase_route")
        status = str((route or {}).get("status") or "").upper()
        if call_id and isinstance(route, dict) and status in priority:
            by_call[call_id] = copy.deepcopy(route)

    def canonical_call_id(row):
        """Read current identity and recover pre-fix children from their AI snapshot."""
        direct = str(row.get("shared_ai_call_id") or row.get("source_trade_id") or "")
        if direct:
            return direct
        for key in ("ai_output", "ai_result", "ai"):
            nested = row.get(key)
            if not isinstance(nested, dict):
                continue
            nested_id = str(nested.get("shared_ai_call_id") or "")
            if nested_id:
                return nested_id
            scan_id = str(nested.get("trade_id") or "")
            if scan_id.startswith("scan-"):
                return scan_id
        return ""

    # Index identities from signals first so pre-fix pending/open/terminal rows
    # with the same Patient child id become visible after this repair.
    trade_to_call = {}
    for items, nested_signal in (
        (signals, True), (pending, False), (positions, False),
        (closed, False), (expired, False),
    ):
        for raw in items or ():
            row = (raw or {}).get("signal_ref") if nested_signal else raw
            if not isinstance(row, dict) or _normalize_lane_key(row) != lane:
                continue
            call_id = canonical_call_id(row)
            trade_id = str(row.get("trade_id") or "")
            if call_id and trade_id:
                trade_to_call[trade_id] = call_id

    def add(items, status, *, nested_signal=False):
        for raw in items or ():
            row = (raw or {}).get("signal_ref") if nested_signal else raw
            if not isinstance(row, dict) or _normalize_lane_key(row) != lane:
                continue
            trade_id = str(row.get("trade_id") or "")
            # Dashboard lifecycle totals describe actual orders/positions and
            # terminal rows.  They must not disappear merely because an older
            # child row is missing its parent shared-AI identity.  Keep the
            # AI-history join separate and surface any identity gap explicitly.
            if status != "APPROVED_NO_ORDER" and trade_id:
                previous = lifecycle_by_trade.get(trade_id)
                if previous is None or priority[status] >= priority[previous]:
                    lifecycle_by_trade[trade_id] = status
            call_id = canonical_call_id(row) or trade_to_call.get(str(row.get("trade_id") or ""), "")
            if not call_id:
                if status != "APPROVED_NO_ORDER" and trade_id:
                    unlinked_lifecycle_trade_ids.add(trade_id)
                continue
            actual = str(row.get("status") or status).upper()
            route_status = status
            if status == "APPROVED_NO_ORDER" and actual in VIRTUAL_CHASE_AWAITING_STATUSES:
                route_status = "APPROVED_NO_ORDER"
            detail = {
                "status": route_status,
                "lifecycle_status": actual,
                "trade_id": row.get("trade_id"),
                "limit_price": row.get("limit_price") or row.get("planned_limit_price"),
                "entry_price": row.get("entry") or row.get("fill_price"),
                "exit_reason": row.get("exit_reason") or row.get("outcome"),
            }
            current = by_call.get(call_id)
            if current is None or priority[route_status] >= priority[current["status"]]:
                by_call[call_id] = detail

    add(signals, "APPROVED_NO_ORDER", nested_signal=True)
    add(expired, "EXPIRED")
    add(closed, "CLOSED")
    add(pending, "PENDING")
    add(positions, "OPEN")
    for lifecycle_status in lifecycle_by_trade.values():
        key = lifecycle_status.lower()
        if key in counts:
            counts[key] += 1
    counts["unlinked_lifecycle_rows"] = len(unlinked_lifecycle_trade_ids)
    enriched = []
    for original in ai_history or ():
        row = dict(original)
        row.pop("type_b_verdict", None)
        verdicts = dict(row.get("lane_verdicts") or {})
        verdicts.pop(RESEARCH_LANE_TYPE_B_HUNTER_V1, None)
        row["lane_verdicts"] = verdicts
        call_id = str(row.get("shared_ai_call_id") or row.get("trade_id") or "")
        route = by_call.get(call_id)
        if route is None:
            route = {
                "status": "NOT_SELECTED",
                "lifecycle_status": None,
                "trade_id": None,
                "limit_price": None,
                "entry_price": None,
                "exit_reason": None,
            }
        row["patient_chase_route"] = route
        enriched.append(row)
    counts["selected_calls"] = len(by_call)
    return enriched, counts


def _build_api_state_snapshot():
    """Build the full /api/state payload dict.

    Runs on a background refresher thread (~1.5s cadence) so the HTTP route
    handler stays O(1) — this is the thread-exhaustion OOM fix. Kept as a
    standalone function so the route handler's cold-start fallback and the
    background refresher share one code path (identical JSON shape).
    """
    t0 = time.perf_counter()
    try:
        # Never block HTTP on Bitfinex REST here — state_monitor_loop refreshes price/funding in background.
        # Lock order: state_lock before trade_lock (close_position may take trade_lock after state work).
        now_ts = time.time()
        session_start = _showcase_trade_session_start()
        state_acquired = state_lock.acquire(timeout=_API_STATE_LOCK_TIMEOUT_SEC)
        if not state_acquired:
            raise TimeoutError("api-state snapshot timed out waiting for state_lock")
        try:
            # The raw order book is large and fast-moving. Deep-copying it only
            # to discard it afterwards held state_lock for up to 38 seconds,
            # starving the dashboard, webhook reads, and /api/ping.
            snapshot = copy.deepcopy({
                key: value
                for key, value in state.items()
                if key not in _DASHBOARD_STATE_DEEPCOPY_EXCLUDED_KEYS
            })
            ai_hist_src = state.get("ai_history") or []
            ai_history_total = len(ai_hist_src)
            ai_history_copy = [dict(r) for r in ai_hist_src[-_DASHBOARD_HISTORY_MAX:]]
        finally:
            state_lock.release()
        # Snapshot construction can take long enough for newer WS ticks to
        # arrive after ``now_ts`` was captured.  Reusing that older timestamp
        # makes the fresh tick appear to have a negative age, which resets the
        # readiness-stability epoch on every dashboard refresh.  Readiness is
        # execution state, not presentation snapshot state, so always evaluate
        # it against a fresh wall-clock receipt after the state copy completes.
        runtime = _recompute_system_readiness()
        snapshot["strategy_price"] = snapshot.get("price")
        snapshot["strategy_price_ts"] = snapshot.get("price_ts")
        rest_display_price = float(snapshot.get("rest_price") or 0)
        rest_display_ts = float(snapshot.get("rest_price_ts") or 0)
        if (
            not runtime["ws_transport_ready"]
            and rest_display_price > 0
            and rest_display_ts
            and 0 <= (now_ts - rest_display_ts) <= 30.0
        ):
            snapshot["price"] = rest_display_price
            snapshot["price_ts"] = rest_display_ts
            snapshot["price_source"] = "REST_DISPLAY_ONLY"
        snapshot["system_ready"] = runtime["system_ready"]
        snapshot["signal_generation_ready"] = runtime["signal_generation_ready"]
        snapshot["runtime_readiness"] = runtime
        trade_acquired = trade_lock.acquire(timeout=_API_STATE_LOCK_TIMEOUT_SEC)
        if not trade_acquired:
            raise TimeoutError("api-state snapshot timed out waiting for trade_lock")
        try:
            trades_copy = _snapshot_trades_for_api(session_start)
            visible_expired = [
                row
                for row in expired_orders
                if isinstance(row, dict)
                and str(row.get("research_lane") or "").upper() != "AI_SCAN"
            ]
            expired_orders_total = len(visible_expired)
            expired_orders_copy = copy.deepcopy(visible_expired[-_DASHBOARD_HISTORY_MAX:])
            for pos in open_positions:
                if pos.get("status") == "OPEN":
                    # Snapshot construction must never perform exchange I/O.
                    # A Bitfinex TLS outage previously held trade_lock through
                    # several retry ladders for 15+ minutes, starving the
                    # dashboard and making its listener appear dead.
                    accrue_position_funding(pos, now_ts, refresh=False)
            positions_copy = copy.deepcopy(open_positions)
            pending_orders_copy = copy.deepcopy(pending_orders)
            relay_trades_copy = copy.deepcopy(trades[-_RELAY_TRADES_MAP_MAX:])
            bounded_trades_map = _snapshot_bounded_trades_map_locked(
                pending_orders_copy,
                positions_copy,
            )
            # Derive dashboard counts from the same immutable snapshots that
            # are returned below.  The auxiliary per-lane registries can lag
            # after a restored paper position, which previously made a real
            # row appear under Positions while its tile incorrectly said
            # "Open 0".
            lane_position_counts = {}
            for ln in dict.fromkeys(
                PATHWAY_LAB_LANES + (RESEARCH_LANE_CONTINUOUS,)
            ):
                lane_position_counts[ln] = {
                    "open": sum(
                        1
                        for pos in positions_copy
                        if pos.get("status") == "OPEN"
                        and _normalize_lane_key(pos) == ln
                    ),
                    "pending": sum(
                        1
                        for order in pending_orders_copy
                        if _normalize_lane_key(order) == ln
                    ),
                }
        finally:
            trade_lock.release()
        active_list, exposure_count = _collect_dashboard_active_signals(
            pending_orders_copy,
            positions_copy,
            bounded_trades_map,
            default_strategy=snapshot.get("strategy", "-"),
            default_regime=snapshot.get("regime", "-"),
        )
        pending_by_tid = {o.get("trade_id"): o for o in pending_orders_copy if o.get("trade_id")}
        for sig in active_list:
            tid = sig.get("trade_id")
            if tid and not sig.get("fill_price"):
                po = pending_by_tid.get(tid) or {}
                sig["fill_price"] = po.get("fill_price") or po.get("limit_price") or sig.get("limit_price")
        expired_orders_copy = _dashboard_expired_order_rows(
            expired_orders_copy,
            _DASHBOARD_HISTORY_MAX,
        )
        ai_history_copy = _session_ai_history(ai_history_copy, _DASHBOARD_HISTORY_MAX)
        ai_history_copy, patient_chase_counts = _attach_patient_chase_routes(
            ai_history_copy,
            signals=list(bounded_trades_map.values()),
            pending=pending_orders_copy,
            positions=positions_copy,
            closed=trades_copy,
            expired=expired_orders_copy,
        )
        snapshot["ai_history"] = ai_history_copy
        snapshot["ai_history_total"] = ai_history_total
        snapshot["patient_chase_counts"] = patient_chase_counts
        snapshot["expired_orders_total"] = expired_orders_total
        snapshot["dashboard_history_limit"] = _DASHBOARD_HISTORY_MAX
        snapshot["last_ai_best"] = _pick_dashboard_last_ai(snapshot, ai_history_copy)
        snapshot["deepseek_key_present"] = bool(_deepseek_api_key())
        snapshot["bot_pid"] = os.getpid()
        snapshot.update(_dashboard_owner_metadata())
        snapshot["bot_cwd"] = os.getcwd()
        snapshot["bot_script"] = os.path.abspath(__file__)
        # Section 1: surface the running commit + Tile 2 frozen policy so that
        # /api/state (the dashboard's primary poll) cannot be silent about a
        # stale running process or a drifted ADX cap.
        snapshot["git_rev"] = _runtime_git_rev()
        coord = live_copy_coordination_state()
        snapshot["live_copy_coordination_state"] = coord
        snapshot["live_copy_coordination_ui_reason"] = (
            LIVE_RELAY_COORDINATION_REASON
            if coord != COORD_STATE_RUNNING_TOGETHER
            else ""
        )
        snapshot["tile2_policy"] = tile2_policy_descriptor()
        # Section 2: Tile 2 dashboard funnel metrics (raw + derived) so the
        # tile can render the full Section 2 spec without re-deriving from
        # raw opportunity events each poll.
        snapshot["tile2_counters"] = tile2_dashboard_metrics()
        if _API_STATE_INLINE_RESEARCH_AGGREGATES:
            snapshot["paused_shadow_stats"] = paused_shadow_dashboard_stats()
        else:
            with _paused_shadow_stats_lock:
                snapshot["paused_shadow_stats"] = copy.deepcopy(
                    _paused_shadow_stats_cache.get("payload") or {}
                )
            snapshot["paused_shadow_stats"].setdefault("deferred", True)
            snapshot["paused_shadow_stats"].setdefault("source", "analyzer")
        # Pt 7b: TYPE_B_HUNTER_V1 cross-source trade-count reconciliation.
        # Surfaces paper/shadow/live count mismatches so the dashboard never
        # silently reports inconsistent totals across the three sources.
        snapshot["type_b_trade_reconciliation"] = (
            _reconcile_type_b_trade_count()
            if _API_STATE_INLINE_RESEARCH_AGGREGATES
            else {
                "lane": RESEARCH_LANE_TYPE_B_HUNTER_V1,
                "deferred": True,
                "source": "analyzer",
            }
        )
        snapshot["weak_setup_min_edge"] = get_weak_setup_min_edge()
        snapshot["ai_cooldown_sec"] = get_effective_ai_cooldown_sec()
        snapshot["ai_cooldown_remaining_sec"] = ai_cooldown_remaining_sec()
        snapshot["profit_gates_lane_enabled"] = profit_gates_lane_enabled()
        snapshot["profit_gates_enforced"] = profit_gates_enforced()
        snapshot["research_lane_enabled"] = research_lane_enabled_map()
        snapshot["pathway_lane_status"] = dict(PATHWAY_LANE_STATUS)
        snapshot["research_lane_labels"] = dict(RESEARCH_LANE_LABELS)
        snapshot["research_lanes_independent"] = research_lanes_independent()
        snapshot["pipeline_funnel_counters"] = copy.deepcopy(snapshot.get("pipeline_funnel_counters") or {})
        snapshot["research_isolation_mode"] = research_isolation_enabled()
        snapshot["lane_opportunity_counters"] = copy.deepcopy(snapshot.get("lane_opportunity_counters") or {})
        snapshot["lane_pnl_ledger"] = _derive_lane_pnl_ledger_from_trades(trades_copy)
        snapshot["lane_lab_pnl_ledger"] = get_lane_lab_pnl_ledger()
        snapshot["lab_open_shadows"] = count_open_lab_shadows()
        snapshot["retired_lane_archive"] = (
            get_retired_lane_archive_rows()
            if _API_STATE_INLINE_RESEARCH_AGGREGATES
            else []
        )
        snapshot["lane_position_counts"] = lane_position_counts
        snapshot["research_execution_mode"] = (
            "INDEPENDENT_LANES" if is_research_data_collection() else "LIVE"
        )
        snapshot["dashboard_port"] = DASHBOARD_PORT
        snapshot["dashboard_url"] = dashboard_public_url()
        snapshot["sim_realism"] = {
            "bbo": True,
            "book_depth_vwap": True,
            "executable_marks": True,
            "fee_profile": EXCHANGE_FEE_PROFILE,
            "funding_sim": FUNDING_SIMULATION_ENABLED,
            "book_ts": snapshot.get("book_ts"),
            "bid_size_btc": snapshot.get("bid_size_btc"),
            "ask_size_btc": snapshot.get("ask_size_btc"),
            "deriv_mark_price": (snapshot.get("funding") or {}).get("mark_price"),
        }
        snapshot["positions"] = []
        # Dedupe by trade_id: a position must never appear twice. If the fill path
        # double-appended an identical trade_id, render it once (real exposure = 1x)
        # and warn so the underlying open_positions double-entry stays visible.
        _seen_pos_ids = set()
        _deduped_positions = []
        for _p in positions_copy:
            _tid = _p.get("trade_id")
            if _tid and _tid in _seen_pos_ids:
                logger.warning(f"/api_state duplicate position suppressed trade_id={_tid} (open_positions double-entry - investigate fill path)")
                continue
            if _tid:
                _seen_pos_ids.add(_tid)
            _deduped_positions.append(_p)
        positions_copy = _deduped_positions
        total_unreal = 0.0
        funding_snap = snapshot.get("funding") or {}
        for pos in positions_copy:
            pos_copy = copy.deepcopy(pos)
            entry_ts = pos_copy.get("entry_ts") or pos_copy.get("fill_ts") or pos_copy.get("open_ts")
            pos_copy["entry_ts_melbourne"] = (
                _timestamp_to_melbourne_display(entry_ts) if entry_ts else "-"
            )
            mark = get_executable_mark_price(pos, fallback=snapshot.get("price"))
            pos_copy["current_price"] = mark
            pos_copy["mark_side"] = "depth_vwap" if float(pos.get("qty") or 0) > 0 else ("bid" if pos.get("dir") == "LONG" else "ask")
            dir_factor = 1 if pos["dir"] == "LONG" else -1
            move_pct = ((mark - pos["entry"]) / pos["entry"] * 100 * dir_factor) if mark and pos["entry"] else 0
            pnl_usd = (move_pct / 100) * FIXED_MARGIN_USDT * pos.get("leverage", DEFAULT_RESEARCH_LEVERAGE)
            pnl_pct_margin = move_pct * pos.get("leverage", DEFAULT_RESEARCH_LEVERAGE)
            funding_acc = round(float(pos.get("funding_fees", 0.0) or 0.0), 4)
            pos_copy["pnl_pct_margin"] = pnl_pct_margin
            pos_copy["unreal_usd_gross"] = pnl_usd
            pos_copy["funding_fees_accrued"] = funding_acc
            pos_copy["unreal_usd"] = round(pnl_usd - funding_acc, 4)
            pos_copy["funding_projected_to_settlement"] = round(
                projected_funding_to_next_settlement(pos, funding_snap), 4
            )
            pos_copy["funding_side"] = funding_side_label(
                float(funding_snap.get("rate") or 0.0), pos.get("dir", "LONG")
            )
            total_unreal += pos_copy["unreal_usd"]
            pos_copy["side"] = "LONG" if pos["dir"] == "LONG" else "SHORT"
            pos_copy["leg"] = "Main"
            snapshot["positions"].append(pos_copy)
        snapshot["equity"] = snapshot["account_balance"] + total_unreal
        orders = []
        tick_px = snapshot.get("price")
        for o in pending_orders_copy:
            age = (time.time() - o["created_ts"]) / 60 if o["created_ts"] else 0
            oc = copy.deepcopy(o)
            oc["age_min"] = age
            oc["created_ts_melbourne"] = (
                _timestamp_to_melbourne_display(oc.get("created_ts"))
                if oc.get("created_ts")
                else "-"
            )
            if tick_px and tick_px > 0:
                oc["limit_touched"] = _pending_limit_touched(o, float(tick_px))
            orders.append(oc)
        snapshot["orders"] = orders
        snapshot["trades"] = trades_copy
        snapshot["expired_orders"] = expired_orders_copy
        snapshot["ai_history"] = ai_history_copy
        snapshot["ai_verdict"] = _ai_execution_verdict_text()
        snapshot["ai_execution_bands"] = get_ai_execution_bands()
        snapshot["chase_execution_buckets"] = get_chase_execution_buckets()
        snapshot["spread_gate"] = get_spread_gate()
        snapshot["dashboard_execution_gates"] = get_dashboard_execution_status()
        snapshot["chase_analytics"] = _load_chase_analytics_snapshot()
        snapshot["spread_analytics"] = _load_spread_analytics_snapshot()
        snapshot.setdefault("regime", "UNKNOWN")
        snapshot.setdefault("strategy", "SR")
        snapshot.setdefault("direction", "FLAT")
        snapshot.setdefault("ema_status", {})
        snapshot.setdefault("support_resistance", {"pivot": None, "s1": None, "s2": None, "r1": None, "r2": None, "swing_high": None, "swing_low": None, "ts": None, "window": "96x15m (~24h rolling)", "dist_to_resistance": 0.0, "dist_to_support": 0.0, "sr_zone_pct": SR_ZONE_PCT, "sr_state": "UNKNOWN", "sr_bias": "BOTH_ALLOWED"})
        snapshot.setdefault("signal_info", {"active": False, "count": 0, "signals": []})
        snapshot.setdefault("heartbeat", 0)
        snapshot.setdefault("price_ts", 0)
        snapshot["server_ts"] = utc_iso()
        price_ts = snapshot.get("price_ts") or 0
        snapshot["price_age"] = (now_ts - price_ts) if price_ts else None
        ws_tick = float(snapshot.get("ws_last_tick") or 0)
        snapshot["ws_age"] = (now_ts - ws_tick) if ws_tick else None
        if snapshot.get("price") is None:
            snapshot["price"] = None
        sync_cooldown_debug_state()
        branding = build_dashboard_display(snapshot)
        snapshot.update(branding)
        if state_lock.acquire(timeout=_API_STATE_LOCK_TIMEOUT_SEC):
            try:
                state.update(branding)
            finally:
                state_lock.release()
        snapshot["signal_info"] = {
            "active": len(active_list) > 0,
            "count": get_active_signal_count(),
            "max": get_effective_max_active_signals(),
            "signals": active_list,
        }
        _enrich_orders_for_relay(snapshot)
        snapshot["trades_map"] = _relay_trades_map_lite(
            bounded_trades_map,
            relay_trades_copy,
        )
        snapshot.setdefault("diag", {})
        snapshot["diag"]["signals_last_hour"] = 0
        snapshot["account_balance"] = get_display_balance()
        snapshot["equity"] = snapshot["account_balance"] + total_unreal
        session_trades = trades_copy
        snapshot["trade_count_session"] = _session_trade_count()
        snapshot["trade_count"] = snapshot["trade_count_session"]
        snapshot["session_pnl_usd"] = _session_realized_pnl_usd()
        snapshot["trades_display_limit"] = _DASHBOARD_TRADES_MAX
        snapshot["trades"] = [_slim_trade_for_dashboard(t) for t in session_trades]
        snapshot["bot_start_time"] = bot_start_time
        snapshot["fresh_collection_mode"] = bool(state.get("fresh_collection_mode", False))
        _epoch_id, _epoch_cutoff, _epoch_kind = _fresh_epoch_identity_from_session()
        snapshot["fresh_epoch_id"] = _epoch_id
        snapshot["fresh_epoch_cutoff_utc"] = _epoch_cutoff
        snapshot["fresh_epoch_kind"] = _epoch_kind
        snapshot["trade_scope"] = "SIGNED_FRESH_EPOCH" if _epoch_cutoff else "ALL_HISTORY"
        snapshot["trade_scope_cutoff_utc"] = _epoch_cutoff
        # Stage 1 Fix #6 (2026-08-06): when LAST_AI_PAYLOAD is empty (e.g.
        # after restart), report an honest "NO_AI_CALL_YET" status instead of
        # silently falling back to state.feature_snapshot (a live orderflow
        # buffer with different keys). The previous fallback made the dashboard
        # look like AI features were "stripped" when they actually weren't.
        if LAST_AI_PAYLOAD:
            snapshot["ai_input"] = LAST_AI_PAYLOAD
        else:
            snapshot["ai_input"] = {
                "status": "NO_AI_CALL_YET",
                "message": (
                    "No AI call has been made since startup. Real payload will "
                    "appear here after the first scan cycle."
                ),
            }
        snapshot["ai_input_time"] = LAST_AI_TIMESTAMP
        snapshot["dashboard_ws_stale_sec"] = DASHBOARD_WS_STALE_SEC
        snapshot["feature_snapshot"] = state.get("feature_snapshot", {})
        snapshot["data_quality"] = state.get("data_quality", 0.0)
        snapshot["edge_threshold"] = get_edge_threshold()
        snapshot["edge_threshold_max"] = get_edge_threshold_max()
        snapshot["edge_range_preset"] = state.get("edge_range_preset", DEFAULT_EDGE_RANGE_PRESET)
        snapshot["edge_threshold_display"] = _edge_range_label()
        snapshot["effective_threshold"] = get_effective_edge_threshold()
        snapshot["research_data_collection"] = is_research_data_collection()
        snapshot["edge_options"] = EDGE_OPTIONS
        snapshot["edge_range_presets"] = EDGE_RANGE_PRESETS
        snapshot["max_active_signals"] = state.get("max_active_signals", MAX_CONCURRENT_POSITIONS_DEFAULT)
        snapshot["max_longs"] = MAX_LONGS
        snapshot["max_shorts"] = MAX_SHORTS
        snapshot["last_direction_cap_block"] = state.get("last_direction_cap_block")
        m_fee, t_fee = get_trading_fee_rates()
        snapshot["fee_profile"] = EXCHANGE_FEE_PROFILE
        snapshot["maker_fee_pct"] = m_fee
        snapshot["taker_fee_pct"] = t_fee
        snapshot["funding_simulation_enabled"] = FUNDING_SIMULATION_ENABLED
        snapshot["bot_version"] = EXECUTION_FIX_VERSION
        snapshot["collector_version"] = COLLECTOR_V31_VERSION
        snapshot["legacy_collector_version"] = COLLECTOR_V22_VERSION
        snapshot["analyzer_sync_id"] = ANALYZER_SYNC_ID
        snapshot["research_kpis"] = get_research_kpis_cached(for_api=True)
        snapshot["pathway_scorecard"] = get_pathway_scorecard_cached(for_api=True)
        snapshot["pathway_lane_specs"] = _scope_pathway_specs_to_signed_epoch(
            get_pathway_lane_specs_cached(for_api=True),
            trades_copy,
            snapshot.get("lane_opportunity_counters") or {},
            _epoch_cutoff,
        )
        snapshot["continuous_ai_direct_entry_enabled"] = continuous_ai_direct_entry_enabled()
        snapshot["golden_stack_config"] = golden_stack_config_for_dashboard()
        snapshot["duplicate_limit_block_enabled"] = duplicate_limit_block_enabled()
        snapshot["min_signal_age_enabled"] = min_signal_age_enabled()
        snapshot["min_signal_age_sec"] = get_min_signal_age_sec()
        snapshot["smart_submit_enabled"] = smart_submit_enabled()
        snapshot["research_config"] = research_config_for_dashboard()
        if not state_lock.acquire(timeout=_API_STATE_LOCK_TIMEOUT_SEC):
            raise TimeoutError("api-state snapshot timed out waiting for final state_lock")
        try:
            snapshot["last_replay_model_eval"] = copy.deepcopy(state.get("last_replay_model_eval"))
            snapshot["funding"] = copy.deepcopy(state.get("funding") or {})
        finally:
            state_lock.release()
        snapshot["display_timezone"] = "Australia/Melbourne"
        snapshot["server_ts_melbourne"] = _format_melbourne_hm(snapshot.get("server_ts") or utc_iso())
        snapshot["ai_input_time_melbourne"] = (
            _format_melbourne_hm(LAST_AI_TIMESTAMP) if LAST_AI_TIMESTAMP else "-"
        )
        session_meta = _load_research_session_meta()
        if session_meta.get("fresh_collection_start_time"):
            snapshot["fresh_collection_start_melbourne"] = _timestamp_to_melbourne_display(
                session_meta["fresh_collection_start_time"]
            )
        fund_out = snapshot.get("funding") or {}
        if fund_out.get("next_time"):
            fund_out["next_time_melbourne"] = _timestamp_to_melbourne_display(fund_out["next_time"])
        elif fund_out.get("next_time_iso"):
            fund_out["next_time_melbourne"] = _format_melbourne_hm(fund_out["next_time_iso"])
        snapshot["funding"] = fund_out
        snapshot["state_integrity"] = build_state_integrity()
        logger.info(
            f"[API STATE] edge_threshold synced to UI: {snapshot['edge_threshold']} "
            f"elapsed_ms={int((time.perf_counter() - t0) * 1000)} [PIPELINE ENFORCEMENT]"
        )
        return snapshot
    except Exception:
        # Let the caller (background refresher or route fallback) handle/log.
        raise


_api_state_refresher_started = False
_api_state_refresher_start_lock = threading.Lock()


def _start_api_state_cache_refresher():
    """Start the daemon background thread that rebuilds the /api/state snapshot
    every 1.5s so the HTTP route handler stays O(1). Idempotent — safe to call
    from multiple startup paths."""
    global _api_state_refresher_started
    with _api_state_refresher_start_lock:
        if _api_state_refresher_started:
            return
        _api_state_refresher_started = True
        # Prime canonical authority before the HTTP listener sees relay polls.
        try:
            _publish_relay_execution_snapshot()
        except Exception as e:
            logger.error(f"/api/relay-execution-state initial cache build error: {e}")
        threading.Thread(target=_api_state_cache_refresher_loop, daemon=True).start()
        threading.Thread(target=_relay_state_cache_refresher_loop, daemon=True).start()
        threading.Thread(target=_relay_execution_cache_refresher_loop, daemon=True).start()
        logger.info(
            f"[API STATE] independent dashboard ({_API_STATE_REFRESH_INTERVAL_SEC:.1f}s), relay "
            f"({_RELAY_STATE_REFRESH_INTERVAL_SEC:.2f}s), and canonical execution "
            f"({_RELAY_EXECUTION_REFRESH_INTERVAL_SEC:.2f}s) cache refreshers started"
        )


def _api_state_cache_refresher_loop():
    while not shutdown_event.is_set():
        try:
            if manual_admin_pause_active():
                snap = _build_api_state_snapshot()
            else:
                # Full presentation snapshots perform analytics, scorecard,
                # history, and formatting work. On the home runtime those
                # rebuilds reached 25-68s under active paper load and starved
                # the canonical relay endpoint. While trading is enabled,
                # retain the paused-built presentation payload and overlay
                # only bounded money-path state. Heavy presentation work
                # resumes automatically when the operator pauses.
                with _api_state_cache_lock:
                    base = _api_state_cache.get("payload")
                base_source = str((base or {}).get("data_source") or "").strip().lower()
                if (
                    not isinstance(base, dict)
                    or not base.get("bot_start_time")
                    or base_source in ("", "booting")
                ):
                    # A clean Windows restart can launch with paper execution
                    # already enabled. In that case there is no paused-built
                    # presentation payload to overlay, and the local dashboard
                    # would otherwise remain a truthful-but-empty relay view
                    # forever. Build the heavy presentation once here, on the
                    # dedicated background thread, then use bounded overlays
                    # for every subsequent refresh.
                    base = _build_api_state_snapshot()
                relay, _, relay_age = _cached_relay_execution_snapshot()
                if relay is None or relay_age is None or relay_age > _RELAY_EXECUTION_MAX_STALE_SEC:
                    raise RuntimeError("canonical execution cache unavailable for dashboard overlay")
                snap = dict(base or {})
                for key in (
                    "price",
                    "price_ts",
                    "price_source",
                    "data_source",
                    "data_quality",
                    "ws_ready",
                    "ws_age",
                    "ws_last_tick",
                    "rest_last_tick",
                    "ws_transport_connected",
                    "system_ready",
                    "signal_generation_ready",
                    "new_entry_progress_ready",
                    "new_entry_block_reason",
                    "runtime_readiness",
                    "execution_paused",
                    "execution_reason",
                    "manual_admin_pause",
                    "continuous_ai_research_enabled",
                    "research_lane_enabled",
                    "live_armed",
                    "max_active_signals",
                    "strategy_mode",
                    "last_approve_outcome",
                    "last_ai",
                    "pullback_threshold",
                    "last_edge",
                    "leverage",
                    "regime",
                    "debug_state",
                    "heartbeat",
                    "last_heartbeat",
                    "pipeline_funnel_counters",
                    "lane_opportunity_counters",
                    "orders",
                    "positions",
                    "trades",
                    "expired_orders",
                    "signal_info",
                    "trades_map",
                    "state_integrity",
                    "server_ts",
                    "bot_version",
                    "collector_version",
                    "legacy_collector_version",
                    # PnL / counters / lane ledger must overlay each cycle --
                    # otherwise the tile freezes at the first heavy build
                    # and under-counts any trade that closed afterwards
                    # (regression detected 2026-08-06 after wipe + restart).
                    "trade_count_session",
                    "trade_count",
                    "session_pnl_usd",
                    "trades_display_limit",
                    "lane_pnl_ledger",
                    "lane_position_counts",
                    "account_balance",
                    "equity",
                    "source_git_rev",
                    "dashboard_pid",
                    "dashboard_port",
                    "dashboard_owner",
                    "bot_instance_id",
                ):
                    if key in relay:
                        snap[key] = relay[key]
                relay_expired = relay.get("expired_orders") or []
                snap["expired_orders"] = copy.deepcopy(
                    relay_expired[-_DASHBOARD_HISTORY_MAX:]
                )
                snap["expired_orders_total"] = int(
                    relay.get("expired_orders_total")
                    if relay.get("expired_orders_total") is not None
                    else len(relay_expired)
                )
                with state_lock:
                    ai_history_all = _session_ai_history(
                        list(state.get("ai_history") or []),
                        50,
                    )
                    snap["ai_history"] = copy.deepcopy(
                        ai_history_all[-_DASHBOARD_HISTORY_MAX:]
                    )
                    snap["ai_history_total"] = len(ai_history_all)
                    snap["ai_history_updated"] = state.get("ai_history_updated", 0.0)
                    snap["ai_call_count"] = int(state.get("ai_call_count") or 0)
                    snap["stability_ai_call_count"] = int(
                        state.get("stability_ai_call_count") or 0
                    )
                    # The heavy presentation snapshot is intentionally reused
                    # while entries are enabled.  Refresh the live AI clock and
                    # payload explicitly so the dashboard cannot show a
                    # pre-resume/pre-epoch "Last AI Call" beside advancing AI
                    # History and a healthy strategy-progress clock.
                    snap["last_ai_call_ts"] = float(
                        state.get("last_ai_call_ts") or 0.0
                    )
                    snap["lane_last_ai_call_ts"] = copy.deepcopy(
                        state.get("lane_last_ai_call_ts") or {}
                    )
                    snap["ai_input"] = copy.deepcopy(
                        LAST_AI_PAYLOAD
                        or {
                            "status": "NO_AI_CALL_YET",
                            "message": (
                                "No AI call has been made since startup. Real payload "
                                "will appear here after the first scan cycle."
                            ),
                        }
                    )
                    snap["ai_input_time"] = LAST_AI_TIMESTAMP
                    snap["shared_ai_lane_counters"] = copy.deepcopy(
                        state.get("shared_ai_lane_counters") or {}
                    )
                snap["collector_version"] = COLLECTOR_V31_VERSION
                snap["legacy_collector_version"] = COLLECTOR_V22_VERSION
                # Rebuild the small server-side display projection after the
                # live diagnostic overlay. Otherwise display_pipeline and the
                # AI/debug labels still describe the paused-built base.
                snap.update(build_dashboard_display(snap))
                snap["strategy_progress"] = _strategy_progress_health_snapshot()
                snap["server_ts_melbourne"] = _format_melbourne_hm(
                    snap.get("server_ts") or utc_iso()
                )
                snap["ai_input_time_melbourne"] = (
                    _format_melbourne_hm(LAST_AI_TIMESTAMP)
                    if LAST_AI_TIMESTAMP
                    else "-"
                )
                overlay_signals = snap.get("trades_map") or {}
                snap["ai_history"], snap["patient_chase_counts"] = _attach_patient_chase_routes(
                    snap.get("ai_history") or [],
                    signals=(
                        list(overlay_signals.values())
                        if isinstance(overlay_signals, dict)
                        else overlay_signals
                    ),
                    pending=snap.get("orders") or [],
                    positions=snap.get("positions") or [],
                    closed=snap.get("trades") or [],
                    expired=snap.get("expired_orders") or [],
                )
                snap["pathway_lane_specs"] = get_pathway_lane_specs_cached(
                    for_api=True
                )
                paused_shadow_stats = snap.get("paused_shadow_stats")
                if isinstance(paused_shadow_stats, dict):
                    # The expensive presentation payload may have been built
                    # while the operator was paused. Keep its historical
                    # aggregates, but never let that cached build freeze the
                    # *current* control-state label after execution resumes.
                    paused_shadow_stats = copy.deepcopy(paused_shadow_stats)
                    paused_shadow_stats["manual_pause_active"] = bool(
                        relay.get("manual_admin_pause")
                        or (
                            relay.get("execution_paused")
                            and relay.get("execution_reason") == "ADMIN_MANUAL"
                        )
                    )
                    snap["paused_shadow_stats"] = paused_shadow_stats
                snap["api_state_mode"] = "ACTIVE_EXECUTION_OVERLAY"
                snap["api_state_overlay_build_ms"] = relay.get("build_ms")
            with _api_state_cache_lock:
                _api_state_cache["payload"] = snap
                _api_state_cache["built_at"] = time.time()
        except Exception as e:
            logger.error(f"/api/state background refresher error: {e}")
        shutdown_event.wait(_API_STATE_REFRESH_INTERVAL_SEC)


def _relay_state_cache_refresher_loop():
    """Refresh the money-path snapshot independently of the heavy dashboard.

    A slow report/state build must never starve the canonical relay cache.
    """
    while not shutdown_event.is_set():
        try:
            with app.app_context():
                api_relay_state(force_rebuild=True)
        except Exception as e:
            logger.error(f"/api/relay-state background refresher error: {e}")
        shutdown_event.wait(_RELAY_STATE_REFRESH_INTERVAL_SEC)


def _relay_execution_cache_refresher_loop():
    """Continuously publish canonical authority from exactly one builder."""
    while not shutdown_event.is_set():
        try:
            _publish_relay_execution_snapshot()
        except Exception as e:
            # Keep the last immutable response. The HTTP route turns it into a
            # truthful 503 once bounded staleness is exceeded.
            logger.error(f"/api/relay-execution-state background refresher error: {e}")
        shutdown_event.wait(_RELAY_EXECUTION_REFRESH_INTERVAL_SEC)


# ─────────────────────────────────────────────────────────────────────────────
# IP protection: public dashboard sanitization
#
# /api/state and /debug_state are on the read-only allowlist and bypass the
# BOT_ADMIN_TOKEN gate. The snapshot they return includes strategy internals
# (AI thresholds, edge/spread gates, lane names, exit policy, AI prompts,
# chase buckets, golden-stack config, etc.). These whitelists strip everything
# except marketing-safe fields (PnL, position, trades, bot status, market data)
# before the response is sent to an unauthenticated viewer.
# ─────────────────────────────────────────────────────────────────────────────

# Top-level snapshot keys that are safe to show publicly. Everything else
# (strategy, regime, edge_threshold*, ai_*, chase_*, spread_gate, lane specs,
# golden_stack_config, research_config, signal_info internals, etc.) is omitted.
_PUBLIC_STATE_SAFE_TOP_KEYS = {
    # bot identity / status
    "bot_status", "bot_pid", "bot_instance_id", "dashboard_owner",
    "dashboard_pid", "dashboard_port", "source_git_rev",
    "bot_version", "bot_start_time",
    "analyzer_sync_id",
    # dashboard meta
    "dashboard_url", "dashboard_port", "display_timezone",
    "server_ts", "server_ts_melbourne",
    # market data
    "price", "price_ts", "price_age", "ws_age", "ws_last_tick",
    "rest_last_tick", "ws_transport_connected",
    "last_heartbeat", "heartbeat", "time_since_heartbeat",
    # account / PnL (marketing)
    "equity", "account_balance", "session_pnl_usd",
    "trade_count", "trade_count_session", "trades_display_limit",
    "funding",
    # collections (each item sanitized further below)
    "positions", "trades",
}

# Per-position keys safe for public display. Drops strategy/regime/lane/score
# and any threshold/exit-policy metadata.
_PUBLIC_POSITION_SAFE_KEYS = {
    "trade_id", "dir", "side", "entry", "current_price", "qty",
    "leverage", "status", "pnl_pct_margin", "unreal_usd",
    "unreal_usd_gross", "funding_fees_accrued",
    "funding_projected_to_settlement", "funding_side", "leg",
    "created_ts", "age_min", "mark_side",
}

# Per-trade keys safe for public display. Drops research_lane, research_model,
# ai_band, exit_reason (all reveal strategy internals).
_PUBLIC_TRADE_SAFE_KEYS = {
    "ts", "ts_melbourne", "trade_id", "final_direction", "dir",
    "entry", "exit", "dur_min", "pnl", "net_pnl_usd",
    "gross_pnl_usd", "trading_fees_usd", "fees_usd",
    "funding_fees_usd", "close_ts_melbourne",
}


def _sanitize_public_state(state: dict) -> dict:
    """Return a copy of `state` containing only marketing-safe fields.

    Strategy internals (AI thresholds, edge/spread gates, lane names, exit
    policy, chase params, AI prompts, golden-stack/research config, signal
    reasoning) are stripped. Safe fields (PnL, position, recent trades, bot
    status, market data, account equity) are preserved so the public
    dashboard keeps working as a marketing surface.
    """
    if not isinstance(state, dict):
        return {}

    out = {k: state.get(k) for k in _PUBLIC_STATE_SAFE_TOP_KEYS if k in state}

    # Sanitize positions — keep only the safe per-position keys.
    positions_in = state.get("positions") or []
    if isinstance(positions_in, list):
        out["positions"] = [
            {k: p.get(k) for k in _PUBLIC_POSITION_SAFE_KEYS if p.get(k) is not None}
            for p in positions_in if isinstance(p, dict)
        ]
    else:
        out["positions"] = []

    # Sanitize trades — drop lane/model/ai_band/exit_reason.
    trades_in = state.get("trades") or []
    if isinstance(trades_in, list):
        out["trades"] = [
            {k: t.get(k) for k in _PUBLIC_TRADE_SAFE_KEYS if t.get(k) not in (None, "")}
            for t in trades_in if isinstance(t, dict)
        ]
    else:
        out["trades"] = []

    # Funding is market data, but strip any debug/reason fields that may have
    # been attached to it.
    funding = out.get("funding")
    if isinstance(funding, dict):
        out["funding"] = {
            k: v for k, v in funding.items()
            if k in ("rate", "next_time", "next_time_melbourne", "mark_price",
                     "next_funding_time", "ts", "predicted_rate")
        }

    # Truthfully expose the mode while keeping mutation admin-only.
    invert = bool(state.get("invert_signal", False))
    out["public_sanitized"] = True
    out["invert_signal"] = invert
    out["invert_on"] = invert
    out["operator_authed"] = False
    out["invert_control"] = "admin_login_required"
    out["ai_input"] = {
        "status": "OWNER_ONLY",
        "message": (
            "Last AI payload is on the owner dashboard (login). "
            "The public view does not include the model input."
        ),
    }
    return out


@app.route('/api/state')
def api_state():
    # O(1) cache return — the heavy ~108KB snapshot rebuild runs on a background
    # refresher thread (see _api_state_cache_refresher_loop) so request threads
    # never block on it. This is the thread-exhaustion OOM fix.
    admin_authed = _admin_authed_strict()
    with _api_state_cache_lock:
        cached = _api_state_cache.get("payload")
        if cached is not None:
            payload = cached if admin_authed else _sanitize_public_state(cached)
            resp = jsonify(payload)
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["X-Api-State-Cache"] = "hit"
            if not admin_authed:
                resp.headers["X-Api-State-Sanitized"] = "1"
            return resp
    # Cache warming must never consume a request worker. During the July 26
    # incident, eight simultaneous dashboard polls all entered the synchronous
    # fallback and waited behind trade/state locks for ~97 seconds. That
    # exhausted the bounded server and made /api/ping look dead, so the external
    # monitor killed a process that was still progressing. Only the dedicated
    # refresher may build this presentation snapshot.
    resp = jsonify({
        "api_state_error": "dashboard snapshot is warming",
        "bot_version": EXECUTION_FIX_VERSION,
        "bot_pid": os.getpid(),
        **_dashboard_owner_metadata(),
        "retry_after_sec": 2,
    })
    resp.status_code = 503
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
    resp.headers["Retry-After"] = "2"
    resp.headers["X-Api-State-Cache"] = "warming"
    return resp


def _market_data_health_snapshot(now: float = None) -> dict:
    """Separate genuine WS transport health from an intentional REST fallback."""
    now = float(now or time.time())
    with state_lock:
        ws_tick = float(state.get("ws_last_tick") or 0)
        rest_tick = float(state.get("rest_last_tick") or 0)
        ws_price_tick = float(state.get("price_ts") or 0)
        rest_price_tick = float(
            state.get("rest_price_ts") or state.get("rest_last_tick") or 0
        )
        ws_connected = bool(state.get("ws_transport_connected", False))
    ws_age = max(0.0, now - ws_tick) if ws_tick else None
    rest_age = max(0.0, now - rest_tick) if rest_tick else None
    price_tick = max(ws_price_tick, rest_price_tick)
    price_age = max(0.0, now - price_tick) if price_tick else None
    ws_transport_ready = _genuine_ws_transport_ready(now)
    rest_fallback_ready = bool(
        rest_age is not None
        and rest_age < 30.0
        and price_age is not None
        and price_age < 30.0
    )
    market_data_ready = bool(ws_transport_ready or rest_fallback_ready)
    if ws_transport_ready:
        mode = "WS"
    elif rest_fallback_ready:
        mode = "REST_FALLBACK"
    elif ws_tick or rest_tick or price_tick:
        mode = "STALE"
    else:
        mode = "BOOTING"
    return {
        "market_data_ready": market_data_ready,
        "market_data_mode": mode,
        "ws_ready": ws_transport_ready,
        "ws_transport_ready": ws_transport_ready,
        "ws_transport_connected": ws_connected,
        "ws_age": ws_age,
        "rest_fallback_ready": rest_fallback_ready,
        "rest_age": rest_age,
        "price_age": price_age,
    }


def _bbo_refresh_telemetry_snapshot(now: float = None) -> dict:
    now = float(now or time.time())
    with _bbo_refresh_lock:
        inflight = bool(_bbo_refresh_claim_token)
        inflight_age = (
            max(0.0, now - float(_bbo_refresh_claim_started_ts or 0))
            if inflight
            else 0.0
        )
    with state_lock:
        return {
            "inflight": inflight,
            "inflight_age_sec": inflight_age,
            "last_attempt_ts": state.get("bbo_refresh_last_attempt_ts"),
            "last_success_ts": state.get("bbo_refresh_last_success_ts"),
            "last_error": state.get("bbo_refresh_last_error"),
            "consecutive_failures": int(
                state.get("bbo_refresh_consecutive_failures") or 0
            ),
            "stale_claims": int(state.get("bbo_refresh_stale_claims") or 0),
        }


def _book_refresh_telemetry_snapshot(now: float = None) -> dict:
    now = float(now or time.time())
    with _book_refresh_lock:
        inflight = bool(_book_refresh_claim_token)
        inflight_age = (
            max(0.0, now - float(_book_refresh_claim_started_ts or 0))
            if inflight
            else 0.0
        )
    with state_lock:
        book_ts = float(state.get("book_ts") or 0)
        return {
            "inflight": inflight,
            "inflight_age_sec": inflight_age,
            "book_age_sec": max(0.0, now - book_ts) if book_ts else None,
            "last_attempt_ts": state.get("book_refresh_last_attempt_ts"),
            "last_success_ts": state.get("book_refresh_last_success_ts"),
            "last_error": state.get("book_refresh_last_error"),
            "consecutive_failures": int(
                state.get("book_refresh_consecutive_failures") or 0
            ),
            "stale_claims": int(state.get("book_refresh_stale_claims") or 0),
        }


@app.route('/health')
@app.route('/api/status')
@app.route('/status')
def health():
    with state_lock:
        hb = state.get("last_heartbeat", last_heartbeat)
        paused = bool(state.get("execution_paused", False))
        reason = state.get("execution_reason", "")
        manual = bool(state.get("manual_admin_pause", False))
        bot_version = state.get("bot_version") or EXECUTION_FIX_VERSION
        analyzer_sync_id = state.get("analyzer_sync_id") or ANALYZER_SYNC_ID
        live_armed = bool(state.get("live_armed", False))
        bitfinex_live_enabled = bool(state.get("bitfinex_live_enabled", False))
    now = time.time()
    heartbeat_age = max(0.0, now - float(hb or 0))
    market_health = _market_data_health_snapshot(now)
    runtime = _recompute_system_readiness(now)
    armable, arm_block_reason, _ = can_open_live_entry(
        require_armed=False,
        now=now,
    )
    trading_ready, trading_block_reason, _ = can_open_live_entry(
        require_armed=True,
        now=now,
    )
    force_paper_mode = _force_paper_mode_active()
    relay_configured = bool((os.getenv("SHOWCASE_RELAY_WEBHOOK_URL") or "").strip())
    process_alive = heartbeat_age <= 15.0
    strategy_progress = _strategy_progress_health_snapshot(now)
    strategy_progress_incident = _strategy_progress_incident_snapshot(now)
    status = "paused" if paused else (
        "alive" if process_alive and strategy_progress["ok"] else "degraded"
    )
    return jsonify({
        "status": status,
        **_dashboard_owner_metadata(),
        "last_heartbeat": hb,
        "time_since_heartbeat": heartbeat_age,
        "process_alive": process_alive,
        "strategy_progress": strategy_progress,
        "strategy_progress_incident": strategy_progress_incident,
        "execution_paused": paused,
        "execution_reason": reason,
        "manual_admin_pause": manual,
        "system_ready": runtime["system_ready"],
        "signal_generation_ready": runtime["signal_generation_ready"],
        "runtime_readiness": runtime,
        "bbo_refresh": _bbo_refresh_telemetry_snapshot(now),
        "book_refresh": _book_refresh_telemetry_snapshot(now),
        **market_health,
        "live_entry_armable": armable,
        "live_entry_arm_block_reason": None if armable else arm_block_reason,
        "trading_ready": trading_ready,
        "trading_block_reason": None if trading_ready else trading_block_reason,
        "live_armed": live_armed,
        "bitfinex_live_enabled": bitfinex_live_enabled,
        "force_paper_mode": force_paper_mode,
        "relay_configured": relay_configured,
        # Section 1: explicit running source revision + policy identifiers.
        # The running bot must not lie about which commit produced it.
        "bot_version": bot_version,
        "analyzer_sync_id": analyzer_sync_id,
        "collector_version": COLLECTOR_V31_VERSION,
        "legacy_collector_version": COLLECTOR_V22_VERSION,
        "git_rev": _runtime_git_rev(),
        "tile2_policy": tile2_policy_descriptor(),
        "collection": {
            "path_replay": PATH_REPLAY_POLICY_TAG,
            "cycle_universe": CYCLE_3M_UNIVERSE_TAG,
            "path_replay_file": PATH_REPLAY_FILE,
            "cycle_universe_file": CYCLE_3M_UNIVERSE_FILE,
            "post_exit_file": POST_EXIT_REPLAY_FILE,
            "order_multiverse_file": ORDER_MULTIVERSE_FILE,
            "collector_version": COLLECTOR_V31_VERSION,
            "legacy_collector_version": COLLECTOR_V22_VERSION,
            "feature_schema_version": FEATURE_SCHEMA_VERSION,
            "path_schema_version": PATH_SCHEMA_VERSION,
            "replay_version": REPLAY_VERSION,
            "fill_model": FILL_MODEL_IDEAL_TOUCH,
            "microstructure_tape": {
                "schema": MICROSTRUCTURE_TAPE_SCHEMA,
                "file": MICROSTRUCTURE_TAPE_FILE,
                "last_bucket_ts": int(_microstructure_last_bucket or 0),
                "rows_written_this_process": int(_microstructure_rows_written),
                "write_failures_this_process": int(_microstructure_write_failures),
                "qualification_model": "CONSERVATIVE_BBO_DEPTH_TAPE",
            },
            "control_cell": CONTROL_CELL,
            "alt_tp": ["atr_k_tp", "chandelier", "structure_tp"],
            "alt_sl": ["atr_k_stop", "structure_stop"],
            "live_exits_unchanged": True,
            "live_thesis_cut": -12.0,
            "hard_stop_closes_paper": bool(CONTROL_CELL.get("hard_stop_closes_paper")),
            "writers_hooked": True,
        },
    })


@app.route('/ready')
@app.route('/api/ready')
def ready():
    """Strict strategy readiness; /health remains the process-liveness probe."""
    with state_lock:
        hb = state.get("last_heartbeat", last_heartbeat)
        ohlcv_ready = bool(state.get("ohlcv_ready", False))
    now = time.time()
    heartbeat_age = max(0.0, now - float(hb or 0))
    market_health = _market_data_health_snapshot(now)
    runtime = _recompute_system_readiness(now)
    armable, arm_block_reason, _ = can_open_live_entry(
        require_armed=False,
        now=now,
    )
    trading_ready, trading_block_reason, _ = can_open_live_entry(
        require_armed=True,
        now=now,
    )
    dashboard_owner = is_active_dashboard_owner()
    strategy_progress = _strategy_progress_health_snapshot(now)
    strategy_progress_incident = _strategy_progress_incident_snapshot(now)
    process_ready = bool(
        dashboard_owner
        and heartbeat_age <= 15.0
        and ohlcv_ready
        and market_health["market_data_ready"]
        and strategy_progress["ok"]
    )
    # A deliberate operator pause must not make Fly mark the process unhealthy
    # or remove the sole risk manager from service. Readiness proves that the
    # canonical owner is alive, warmed and receiving genuine market data;
    # signal_generation_ready separately proves whether new entries may run.
    ready_ok = bool(process_ready and runtime["system_ready"])
    return jsonify({
        "ok": ready_ok,
        "process_ready": process_ready,
        "status": (
            "ready" if ready_ok else ("alive_not_strategy_ready" if process_ready else "not_ready")
        ),
        **_dashboard_owner_metadata(),
        "bot_version": EXECUTION_FIX_VERSION,
        "heartbeat_age": heartbeat_age,
        "strategy_progress": strategy_progress,
        "strategy_progress_incident": strategy_progress_incident,
        **market_health,
        "ohlcv_ready": ohlcv_ready,
        "system_ready": runtime["system_ready"],
        "signal_generation_ready": runtime["signal_generation_ready"],
        "runtime_readiness": runtime,
        "live_entry_armable": armable,
        "live_entry_arm_block_reason": None if armable else arm_block_reason,
        "trading_ready": trading_ready,
        "trading_block_reason": None if trading_ready else trading_block_reason,
    }), (200 if ready_ok else 503)


@app.route('/debug_state')
def get_debug_state():
    # /debug_state exposes strategy internals (edge components, AI cooldown,
    # block reasons, pipeline stage). Fail closed — admin token required.
    if not _admin_authed_strict():
        resp = jsonify({
            "status": "auth_required",
            "message": "strategy internals are admin-only — present X-Bot-Admin-Token",
        })
        resp.headers["X-Debug-State-Sanitized"] = "1"
        resp.status_code = 401
        return resp
    with state_lock:
        return jsonify(state.get("debug_state", {}))

@app.route('/api/pause', methods=['POST'])
def api_pause():
    with state_lock:
        state["manual_admin_pause"] = True
    disarm = _disarm_live_control("ADMIN_MANUAL")
    set_execution_paused("ADMIN_MANUAL")
    with trade_lock:
        paper_orders = copy.deepcopy(pending_orders)
        paper_positions = copy.deepcopy(open_positions)
    _patch_api_state_cache_fields(
        execution_paused=True,
        execution_reason="ADMIN_MANUAL",
        manual_admin_pause=True,
        live_armed=False,
        bitfinex_live_enabled=False,
        orders=paper_orders,
        positions=paper_positions,
    )
    logger.warning("[ADMIN] Manual pause via /api/pause [PIPELINE ENFORCEMENT]")
    response = jsonify({
        "status": "paused",
        "execution_paused": True,
        "execution_reason": "ADMIN_MANUAL",
        "live_pending_cancel": disarm["cancel"],
        "exit_only_lanes": list(disarm["exit_only"].keys()),
    })
    response.status_code = 409 if disarm["cancel"]["failed"] else 200
    return response

# Pause reasons that /api/resume is allowed to clear even when the readiness
# latch (system_ready) is still stabilizing. system_ready can't stabilize while
# the bot is paused (the pipeline doesn't run), so requiring it on resume
# created a deadlock: once DAILY_DRAWDOWN tripped, /api/resume would 409
# forever and only a process restart could recover. These reasons are
# operator/risk-initiated pauses — they are not symptoms of a broken
# market-data feed, so it is safe to clear them before system_ready latches.
_RESUMABLE_PAUSE_REASONS = frozenset({
    "DAILY_DRAWDOWN",
    "LOSS_STREAK",
    "ADMIN_MANUAL",
    "MANUAL",
})



@app.route('/api/live-copy-coordination', methods=['POST'])
def api_live_copy_coordination():
    """Railway safety-pause / re-arm coordination for Showcase executable entries."""
    if not _admin_authed():
        resp = jsonify({"ok": False, "error": "unauthorized"})
        resp.status_code = 401
        return resp
    body = request.get_json(silent=True) or {}
    wanted = str(body.get("state") or body.get("coordination_state") or "").strip().upper()
    reason = str(body.get("reason") or "").strip()
    try:
        result = set_live_copy_coordination_state(wanted, reason)
    except ValueError as exc:
        resp = jsonify({"ok": False, "error": str(exc)})
        resp.status_code = 400
        return resp
    with state_lock:
        result["execution_paused"] = bool(state.get("execution_paused"))
        result["execution_reason"] = state.get("execution_reason")
        result["live_copy_coordination_state"] = state.get("live_copy_coordination_state")
        result["ui_reason"] = (
            LIVE_RELAY_COORDINATION_REASON
            if result["state"] != COORD_STATE_RUNNING_TOGETHER
            else ""
        )
    _patch_api_state_cache_fields(
        live_copy_coordination_state=result["state"],
        live_copy_coordination_reason=result.get("reason") or "",
        execution_paused=result.get("execution_paused"),
        execution_reason=result.get("execution_reason") or "",
    )
    return jsonify(result)

@app.route('/api/resume', methods=['POST'])
def api_resume():
    runtime = _recompute_system_readiness()
    # The system_ready latch can't stabilize while the bot is paused (the
    # pipeline doesn't run, so readiness components never get ticked). Requiring
    # system_ready=true on resume created a deadlock: once DAILY_DRAWDOWN
    # tripped, /api/resume 409'd forever. Allow resume to clear a resumable
    # pause even when system_ready is false, as long as the WS transport is
    # genuinely healthy — that proves the market-data feed is alive, which is
    # the only safety property system_ready was indirectly checking here.
    with state_lock:
        active_reason = str(state.get("execution_reason") or "")
        manual_paused = bool(state.get("manual_admin_pause", False))
    ws_healthy = bool(runtime.get("ws_transport_ready", False))
    if not runtime.get("system_ready"):
        # Real WS issue (not just a paused pipeline) — keep blocking.
        actionable_reason = (
            runtime.get("readiness_reasons", ["SYSTEM_NOT_READY"])[0]
            if runtime.get("readiness_reasons")
            else "SYSTEM_NOT_READY"
        )
        can_resume_while_unready = (
            ws_healthy
            and (active_reason in _RESUMABLE_PAUSE_REASONS or manual_paused)
        )
        if not can_resume_while_unready:
            response = jsonify({
                "status": "resume_blocked",
                "execution_paused": True,
                "reason": actionable_reason,
                "active_pause_reason": active_reason,
                "ws_transport_ready": ws_healthy,
                "runtime_readiness": runtime,
            })
            response.status_code = 409
            return response
        logger.info(
            f"[ADMIN] /api/resume proceeding while system_ready=False "
            f"(ws_healthy={ws_healthy}, active_reason={active_reason!r}, "
            f"manual_paused={manual_paused}) — deadlock workaround [PIPELINE ENFORCEMENT]"
        )
    with state_lock:
        state["manual_admin_pause"] = False
    save_persistent_config()
    set_execution_paused("")
    _patch_api_state_cache_fields(
        execution_paused=False,
        execution_reason="",
        manual_admin_pause=False,
    )
    logger.info("[ADMIN] Manual resume via /api/resume [PIPELINE ENFORCEMENT]")
    return jsonify({"status": "resumed", "execution_paused": False})


@app.route('/api/positions/close', methods=['POST'])
def api_close_showcase_position():
    """Close one exact showcase paper position through normal accounting."""
    body = request.get_json(silent=True) or {}
    trade_id = str(body.get("trade_id") or "").strip()
    if not trade_id:
        return jsonify({"error": "trade_id is required"}), 400
    with state_lock:
        matches = [
            pos for pos in open_positions
            if str(pos.get("trade_id") or "") == trade_id
            and pos.get("status") != "CLOSED"
        ]
    if not matches:
        return jsonify({"error": "open showcase position not found", "trade_id": trade_id}), 404
    if len(matches) != 1:
        logger.error(
            "[ADMIN] Refusing ambiguous paper close trade_id=%s matches=%s",
            trade_id,
            len(matches),
        )
        return jsonify({"error": "ambiguous showcase position", "trade_id": trade_id}), 409
    close_position(matches[0], "ADMIN_MANUAL_CLOSE")
    with state_lock:
        still_open = any(
            str(pos.get("trade_id") or "") == trade_id
            and pos.get("status") != "CLOSED"
            for pos in open_positions
        )
    if still_open:
        return jsonify({"error": "showcase close did not complete", "trade_id": trade_id}), 409
    with trade_lock:
        paper_orders = copy.deepcopy(pending_orders)
        paper_positions = copy.deepcopy(open_positions)
        paper_trades = copy.deepcopy(trades[-50:])
    _patch_api_state_cache_fields(
        orders=paper_orders,
        positions=paper_positions,
        trades=paper_trades,
    )
    logger.warning("[ADMIN] Showcase paper position closed trade_id=%s", trade_id)
    return jsonify({
        "status": "closed",
        "trade_id": trade_id,
        "scope": "showcase_paper_only",
    })


@app.route('/api/orders/cancel', methods=['POST'])
def api_cancel_showcase_pending_order():
    """Cancel one exact pending Showcase order without wiping research history.

    This is intentionally narrower than ``/api/reset``: it is an authenticated
    deployment-boundary recovery tool.  It refuses an unknown or ambiguous
    trade ID and uses the normal confirmed-cancellation primitive so the
    expired-order audit remains truthful.
    """
    body = request.get_json(silent=True) or {}
    trade_id = str(body.get("trade_id") or "").strip()
    if not trade_id:
        return jsonify({"error": "trade_id is required"}), 400
    with trade_lock:
        matches = [
            order for order in pending_orders
            if str(order.get("trade_id") or "") == trade_id
            and str(order.get("status") or "").upper()
            not in ("CANCELLED", "EXPIRED", "REJECTED", "FILLED", "OPEN", "CLOSED")
        ]
    if not matches:
        return jsonify({"error": "pending showcase order not found", "trade_id": trade_id}), 404
    if len(matches) != 1:
        logger.error("[ADMIN] Refusing ambiguous pending cancel trade_id=%s matches=%s", trade_id, len(matches))
        return jsonify({"error": "ambiguous pending showcase order", "trade_id": trade_id}), 409
    result = _cancel_pending_order_confirmed(
        matches[0],
        "ADMIN_FORCE_FLAT",
        record_expired=True,
        expire_signal=True,
        final_status="CANCELLED",
    )
    if not result.get("finalized"):
        return jsonify({"error": "pending cancel unconfirmed", "trade_id": trade_id, "result": result}), 409
    with trade_lock:
        paper_orders = copy.deepcopy(pending_orders)
        paper_positions = copy.deepcopy(open_positions)
    _patch_api_state_cache_fields(orders=paper_orders, positions=paper_positions)
    logger.warning("[ADMIN] Showcase pending order cancelled trade_id=%s", trade_id)
    return jsonify({"status": "cancelled", "trade_id": trade_id, "result": result})


# ---------------------------------------------------------------------------
# Cure 2 — Phantom paper position cancellation (Railway-initiated).
#
# When Railway's real Bitfinex limit MISSES but Fly paper "filled", Fly is
# left holding a phantom paper position that corrupts its strategy state:
#   - It consumes capacity (MAX_ACTIVE_SIGNALS / CLUSTER_ENTRY) and can
#     block fresh entries.
#   - It skews session PnL / win-rate / analytics.
#   - Fly keeps emitting exits for the phantom; Railway's real account has
#     nothing to mirror.
#
# This admin-only endpoint lets Railway cancel the phantom cleanly without
# touching real Bitfinex money. It is the symmetric counterpart of
# /api/positions/close but with two important differences:
#   1. Zero-PnL accounting — the paper fill never corresponded to a real
#      fill, so we record a synthetic $0 outcome tagged
#      PHANTOM_CANCEL_BY_RELAY (not the close_position fee/PnL math).
#   2. No Bitfinex reduce-only attempt — there is no real position to close.
#
# Auth: the global _emergency_api_guard before_request hook already rejects
# any unauthenticated POST with 401, so this endpoint inherits the
# X-Bot-Admin-Token gate (same pattern as /api/pause, /api/positions/close,
# /api/reset). No extra in-handler auth is needed.
# ---------------------------------------------------------------------------

PHANTOM_CANCEL_REASON = "PHANTOM_CANCEL_BY_RELAY"
PHANTOM_CANCEL_MAX_BODY_LEN = 4096


@app.route('/api/reconcile/phantom-cancel', methods=['POST'])
def api_reconcile_phantom_cancel():
    """Cancel a phantom paper position left behind by a MISSED_SHOWCASE_FILL.

    Body:
      {
        "trade_id": "<cont-...>",          # required
        "reason":   "<human-readable>"      # optional, audited
      }

    Idempotent: a second call for a trade_id that is already CLOSED returns
    200 with ``already_cancelled=true`` and does NOT double-write the trade
    outcome or re-emit the relay event.
    """
    raw_body = request.get_data(as_text=True) or ""
    if len(raw_body) > PHANTOM_CANCEL_MAX_BODY_LEN:
        return (
            jsonify({"error": "request body too large", "max_len": PHANTOM_CANCEL_MAX_BODY_LEN}),
            413,
        )
    body = request.get_json(silent=True) or {}
    trade_id = str(body.get("trade_id") or "").strip()
    if not trade_id:
        return jsonify({"error": "trade_id is required"}), 400
    caller_reason = str(body.get("reason") or "").strip()[:200]

    # Snapshot search under state_lock (consistent read of open_positions).
    with state_lock:
        matches = [
            pos for pos in open_positions
            if str(pos.get("trade_id") or "") == trade_id
        ]
        already_closed = [
            pos for pos in matches
            if pos.get("status") == "CLOSED"
            or pos.get("exit_reason") == PHANTOM_CANCEL_REASON
        ]
        live_matches = [
            pos for pos in matches
            if pos.get("status") != "CLOSED"
            and pos.get("exit_reason") != PHANTOM_CANCEL_REASON
        ]
        # Idempotency case 1 — the position exists but is already cancelled
        # by a prior phantom-cancel call. Return ok without re-writing.
        if not live_matches and already_closed:
            logger.info(
                "[ADMIN] Phantom-cancel idempotent skip trade_id=%s (already cancelled)",
                trade_id,
            )
            return jsonify({
                "ok": True,
                "already_cancelled": True,
                "cancelled_trade_id": trade_id,
                "timestamp": utc_iso(),
            })

    if not live_matches:
        # Idempotency case 2 — trade_id is not in open_positions at all.
        # Could be: (a) already rotated out of the in-memory list, or
        # (b) never existed. Either way, return ok so Railway's caller is
        # not blocked by a stale state on Fly. Audit the not-found.
        logger.warning(
            "[ADMIN] Phantom-cancel no-op trade_id=%s not in open_positions "
            "(caller_reason=%s) — returning ok for idempotency",
            trade_id,
            caller_reason or "<none>",
        )
        return jsonify({
            "ok": True,
            "already_cancelled": True,
            "cancelled_trade_id": trade_id,
            "note": "trade_id not currently open; treated as already cancelled",
            "timestamp": utc_iso(),
        })

    if len(live_matches) > 1:
        # Defensive — should never happen (trade_id is unique), but refuse
        # to operate on an ambiguous state rather than risk double-accounting.
        logger.error(
            "[ADMIN] Phantom-cancel refused ambiguous trade_id=%s matches=%s",
            trade_id,
            len(live_matches),
        )
        return (
            jsonify({
                "error": "ambiguous open position",
                "trade_id": trade_id,
                "matches": len(live_matches),
            }),
            409,
        )

    pos = live_matches[0]

    # Validation guard: refuse to cancel a position that has any marker of a
    # real Bitfinex fill against it. The paper bot does not currently track
    # real fills per position (no bitfinex_real_fill flag), so we use the
    # best-available proxies: explicit bitfinex_position_id / bitfinex_live_entry
    # markers (set when /api/bitfinex_live arms live mode for this trade).
    # If real-fill tracking is added later, this guard should consult it.
    has_real_marker = bool(
        pos.get("bitfinex_position_id")
        or pos.get("bitfinex_live_entry")
        or pos.get("real_fill_recorded")
    )
    if has_real_marker:
        logger.error(
            "[ADMIN] Phantom-cancel REFUSED trade_id=%s — position has a real "
            "Bitfinex marker (bitfinex_position_id=%s, bitfinex_live_entry=%s, "
            "real_fill_recorded=%s); cancelling would orphan real money",
            trade_id,
            pos.get("bitfinex_position_id"),
            pos.get("bitfinex_live_entry"),
            pos.get("real_fill_recorded"),
        )
        return (
            jsonify({
                "error": "refused: position has a real Bitfinex fill marker",
                "trade_id": trade_id,
                "bitfinex_position_id": pos.get("bitfinex_position_id"),
                "bitfinex_live_entry": pos.get("bitfinex_live_entry"),
                "real_fill_recorded": pos.get("real_fill_recorded"),
            }),
            409,
        )

    # ---- Perform the cancellation --------------------------------------
    # Use position_close_lock (same as close_position) so we cannot race a
    # simultaneous strategy-driven close on the same dict. The dict mutation
    # itself is tiny; the lock serializes concurrent claimants.
    cancel_ts = time.time()
    cancel_iso = utc_iso()
    cancel_mel = _format_melbourne_hm(cancel_iso)
    entry_price = float(pos.get("entry") or 0.0)
    direction = str(pos.get("dir") or "UNKNOWN")
    qty = float(pos.get("qty") or 0.0)
    margin_usdt = float(pos.get("margin_usdt") or FIXED_MARGIN_USDT)
    research_lane = pos.get("research_lane")

    with position_close_lock:
        # Re-validate under the close lock — a concurrent close_position may
        # have already terminalized this pos while we were waiting.
        if pos.get("status") == "CLOSED" or pos.get("_close_in_progress"):
            logger.info(
                "[ADMIN] Phantom-cancel late skip trade_id=%s (closed under lock)",
                trade_id,
            )
            return jsonify({
                "ok": True,
                "already_cancelled": True,
                "cancelled_trade_id": trade_id,
                "timestamp": cancel_iso,
            })
        pos["_close_in_progress"] = True

        # Zero-PnL synthetic outcome row. We deliberately do NOT call the
        # full close_position() path because that path accrues funding, fees,
        # and attempts a Bitfinex reduce-only close — none of which apply to
        # a phantom paper position.
        trade_row = {
            "ts": cancel_iso,
            "close_ts": cancel_iso,
            "ts_melbourne": cancel_mel,
            "close_ts_melbourne": cancel_mel,
            "trade_id": trade_id,
            "dir": direction,
            "entry": entry_price,
            "exit": entry_price,  # $0 PnL → exit == entry
            "dur_min": (cancel_ts - float(pos.get("entry_ts") or cancel_ts)) / 60,
            "pnl": 0.0,
            "margin_usdt": margin_usdt,
            "net_pnl_usd": 0.0,
            "gross_pnl_usd": 0.0,
            "trading_fees_usd": 0.0,
            "fees_usd": 0.0,
            "funding_fees_usd": 0.0,
            "total_cost_usd": 0.0,
            "exit_reason": PHANTOM_CANCEL_REASON,
            "phantom_cancel": True,
            "phantom_cancel_caller_reason": caller_reason or None,
            "leverage": pos.get("leverage", DEFAULT_RESEARCH_LEVERAGE),
            "r_multiple": 0.0,
            "outcome_exit_reason": PHANTOM_CANCEL_REASON,
            "outcome_net_pnl_usd": 0.0,
            "outcome_pnl_pct": 0.0,
            "execution_qty": qty,
            "final_direction": direction,
            "strategy": pos.get("strategy_birth", "PHANTOM"),
            "regime": pos.get("signal_regime", state.get("regime", "UNKNOWN")),
        }

        # Mark the position CLOSED and release lane capacity.
        pos["status"] = "CLOSED"
        pos["exit_reason"] = PHANTOM_CANCEL_REASON
        pos["phantom_cancelled"] = True
        pos["phantom_cancel_ts"] = cancel_iso
        lane_unregister_open_position(pos)

        # Append to trades list + persist.
        trades.append(trade_row)
        try:
            log_trade_outcome_jsonl(trade_row, pos)
        except Exception as exc:  # pragma: no cover — best-effort audit
            logger.warning("[ADMIN] Phantom-cancel outcome jsonl failed trade_id=%s: %s", trade_id, exc)

        # Update the master signal_ref so reconcile_stale_signals sees it as
        # terminal (mirrors close_position's master.update block).
        master_entry = trades_map.get(trade_id)
        if master_entry:
            master = master_entry.get("signal_ref")
            if isinstance(master, dict):
                master.update({
                    "status": "CLOSED",
                    "exit_reason": PHANTOM_CANCEL_REASON,
                    "outcome": "PHANTOM",
                    "closed_ts": cancel_ts,
                    "expires_ts": cancel_ts - 1,
                })

    # ---- Outside the close lock: persistence + relay + audit -----------
    persist_signal_close(trade_id, "CLOSED")
    _sync_order_multiverse(
        {
            **(pos or {}),
            "trade_id": trade_id,
            "status": "CLOSED",
            "ticket_closed": True,
            "live_fill_ts": (pos or {}).get("entry_ts"),
            "live_fill_price": (pos or {}).get("entry") or entry_price,
            "invert_on": _coerce_invert_on(pos or {}, trade_row),
            "exit_reason": PHANTOM_CANCEL_REASON,
        },
        path_complete=False,
    )
    save_positions()
    save_persistent_config()

    # Refresh the cached /api/state snapshot so Railway's next /api/state
    # poll reflects the cancellation immediately (otherwise the stale cache
    # can show the phantom OPEN for up to API_STATE_REFRESH_INTERVAL_SEC).
    with trade_lock:
        paper_orders = copy.deepcopy(pending_orders)
        paper_positions = copy.deepcopy(open_positions)
        paper_trades = copy.deepcopy(trades[-50:])
    _patch_api_state_cache_fields(
        orders=paper_orders,
        positions=paper_positions,
        trades=paper_trades,
    )

    # Emit a POSITION_CLOSED relay event so any downstream subscriber that
    # mirrors Fly's paper state (the dashboard, type-b research) learns the
    # trade is no longer open. Use the same channel as close_position.
    _push_showcase_relay_event(
        "POSITION_CLOSED",
        trade_id,
        {
            "exit_reason": PHANTOM_CANCEL_REASON,
            "direction": direction,
            "exit_price": entry_price,
            "research_lane": research_lane,
            "phantom_cancel": True,
            "caller_reason": caller_reason or None,
        },
    )

    # Clear pending_trade_id if the phantom happened to be the active one.
    with state_lock:
        if state.get("pending_trade_id") == trade_id:
            state["pending_trade_id"] = None

    logger.warning(
        "[ADMIN] Phantom paper position cancelled trade_id=%s dir=%s entry=%s "
        "qty=%s caller_reason=%s [PAPER ONLY — no Bitfinex action]",
        trade_id,
        direction,
        entry_price,
        qty,
        caller_reason or "<none>",
    )

    return jsonify({
        "ok": True,
        "cancelled_trade_id": trade_id,
        "exit_reason": PHANTOM_CANCEL_REASON,
        "timestamp": cancel_iso,
        "scope": "showcase_paper_only",
    })


