    logger.info(
        f"[RESEARCH_LANE] {lane} set {'ON' if enabled[lane] else 'OFF'} [PIPELINE ENFORCEMENT]"
    )
    return jsonify({
        "lane": lane,
        "enabled": enabled[lane],
        "research_lane_enabled": enabled,
        "suspend": suspend_result,
    })

