@app.route('/api/toggle_fresh_collection', methods=['POST'])
def toggle_fresh_collection():
    data = request.get_json() or {}
    expected_current = data.get("expected_current")
    with state_lock:
        current_mode = bool(state.get("fresh_collection_mode", False))
    if expected_current is not None:
        if not isinstance(expected_current, bool):
            return jsonify({"error": "expected_current must be a JSON boolean"}), 400
        if expected_current != current_mode:
            logger.warning(
                "[FRESH COLLECTION] Rejected stale/replayed toggle "
                f"expected_current={expected_current} actual={current_mode} "
                "[PIPELINE ENFORCEMENT]"
            )
            return jsonify({
                "error": "Fresh Collection state changed; refresh before trying again",
                "fresh_collection_mode": current_mode,
                "stale_request": True,
            }), 409
    want_on = data.get("enabled")
    if want_on is None:
        want_on = not state.get("fresh_collection_mode", False)
    if want_on:
        with state_lock:
            if state.get("live_armed"):
                return jsonify({"error": "Disable LIVE ARM before fresh collection reset"}), 400
        result = perform_fresh_collection_reset()
        if not result.get("ok"):
            return jsonify({
                "error": result.get("summary") or result.get("error") or "reset failed",
                "fresh_collection_mode": bool(state.get("fresh_collection_mode")),
                "reset": result,
            }), 409
        return jsonify({"fresh_collection_mode": True, "reset": result})
    with state_lock:
        state["fresh_collection_mode"] = False
        save_persistent_config()
    _write_research_session(bot_start_time)
    logger.info(
        f"[COLLECTOR] canonical={COLLECTOR_V31_VERSION} "
        f"legacy_writer={COLLECTOR_V22_VERSION} analyzer_sync_id={ANALYZER_SYNC_ID} "
        "[PIPELINE ENFORCEMENT]"
    )
    logger.info("[FRESH COLLECTION] Mode turned OFF - no file wipe [PIPELINE ENFORCEMENT]")
    return jsonify({"fresh_collection_mode": False})

@app.route('/api/wipe_fly_only', methods=['POST'])
def wipe_fly_only():
    """Operational wipe of Fly volume data WITHOUT signalling the local mirror.

    Distinct from Fresh Collection: clears the Fly data files and resets
    in-memory state exactly like Fresh Collection, but leaves
    ``state['fresh_collection_signal_ts']`` untouched so the local sync loop
    keeps its mirrored history for offline analysis. Use when the Fly volume
    is filling up but local history should be retained.
    """
    if not _admin_authed_strict():
        return jsonify({
            "status": "error",
            "message": "admin token required",
        }), 401
    with state_lock:
        if state.get("live_armed"):
            return jsonify({
                "status": "error",
                "message": "Disable LIVE ARM before wiping Fly data",
            }), 400
    wiped_at = time.time()
    result = perform_fresh_collection_reset(send_local_signal=False)
    if not result.get("ok"):
        return jsonify({
            "status": "error",
            "message": result.get("summary") or result.get("error") or "wipe failed",
            "reset": result,
        }), 409
    # Force fresh_collection_mode back off — this endpoint is a one-shot Fly
    # clear, not the auto-trim Fresh Collection mode. The reset above set it
    # True; flip it off so the hourly auto-trim doesn't kick in unexpectedly.
    with state_lock:
        state["fresh_collection_mode"] = False
        save_persistent_config()
    logger.warning(
        "[WIPE FLY ONLY] Fly data wiped; local mirror retained by design "
        f"[PIPELINE ENFORCEMENT]"
    )
    return jsonify({
        "status": "ok",
        "message": "Fly data wiped. Local mirror retained.",
        "wiped_at": wiped_at,
        "reset": result,
        "fresh_collection_signal_ts": float(state.get("fresh_collection_signal_ts") or 0.0),
    })

_FRESH_EPOCH_CONFIRMATION = "QUARANTINE_OBSOLETE_RESEARCH_START_FRESH_EPOCH"
_FRESH_EPOCH_ZERO_FIELDS = (
    "showcase_positions", "showcase_pending_orders",
    "relay_active_participants", "relay_open_lots", "relay_pending_lots",
    "exchange_positions", "exchange_active_orders", "exchange_delta_btc",
)


def _utc_isoformat_ns(ts: float) -> str:
    """Analyzer-compatible UTC isoformat (pandas ns when available)."""
    try:
        import pandas as pd
        return pd.to_datetime(float(ts), unit="s", utc=True).isoformat()
    except Exception:
        pass
    whole = int(ts)
    frac = float(ts) - whole
    nsec = int(round(frac * 1_000_000_000))
    if nsec >= 1_000_000_000:
        whole += 1
        nsec = 0
    if nsec < 0:
        whole -= 1
        nsec += 1_000_000_000
    dt = datetime.fromtimestamp(whole, tz=timezone.utc)
    base = dt.strftime("%Y-%m-%dT%H:%M:%S")
    if nsec:
        return f"{base}.{nsec:09d}+00:00"
    return f"{base}+00:00"


def _fresh_epoch_identity_from_session():
    """Stable SHOWCASE_FRESH_COLLECTION epoch id from research_session.json."""
    session = _load_research_session_meta() or {}
    raw = session.get("fresh_collection_start_time")
    if raw in (None, "", 0, 0.0):
        return None, None, None
    try:
        cutoff = _utc_isoformat_ns(float(raw))
    except (TypeError, ValueError):
        return None, None, None
    kind = "SHOWCASE_FRESH_COLLECTION"
    material = f"fresh_research_epoch_v1|{kind}|{cutoff}"
    epoch_id = "epoch-" + hashlib.sha256(material.encode("utf-8")).hexdigest()[:24]
    return epoch_id, cutoff, kind


def _fresh_epoch_strict_flat_proof() -> dict:
    """Fly-local books for the official POST /api/fresh_epoch_reset proof."""
    now = datetime.now(timezone.utc)
    with trade_lock:
        pending_count = len(pending_orders)
        open_count = len(open_positions)
    with state_lock:
        live_armed = bool(state.get("live_armed", False))
    audit = _exchange_exposure_audit_snapshot()
    paper_only = _force_paper_mode_active() and not live_armed
    try:
        exch_pos = int(audit.get("open_position_count") or 0)
    except (TypeError, ValueError):
        exch_pos = 0
    try:
        exch_ord = int(audit.get("open_order_count") or 0)
    except (TypeError, ValueError):
        exch_ord = 0
    try:
        delta = float(audit.get("delta_btc") or audit.get("net_btc") or 0)
    except (TypeError, ValueError):
        delta = 0.0
    if paper_only and not audit.get("authoritative"):
        exch_pos = 0
        exch_ord = 0
        delta = 0.0
    return {
        "checked_at": now.isoformat(),
        "showcase_positions": int(open_count),
        "showcase_pending_orders": int(pending_count),
        "relay_active_participants": 0,
        "relay_open_lots": 0,
        "relay_pending_lots": 0,
        "exchange_positions": exch_pos,
        "exchange_active_orders": exch_ord,
        "exchange_delta_btc": delta,
        "relay_paused": (not live_armed),
        "relay_disarmed": (not live_armed),
        "source": "fly_local_books",
    }


def _fresh_epoch_proof_blockers(proof: dict) -> list:
    blockers = []
    if not isinstance(proof, dict):
        return ["strict_flat_proof required"]
    for key in _FRESH_EPOCH_ZERO_FIELDS:
        if proof.get(key) != 0:
            blockers.append(f"{key}={proof.get(key)}")
    if proof.get("relay_paused") is not True:
        blockers.append("relay_paused")
    if proof.get("relay_disarmed") is not True:
        blockers.append("relay_disarmed")
    try:
        checked_at = datetime.fromisoformat(str(proof.get("checked_at") or "").replace("Z", "+00:00"))
        age_s = (datetime.now(timezone.utc) - checked_at.astimezone(timezone.utc)).total_seconds()
    except (TypeError, ValueError):
        age_s = float("inf")
    if age_s < 0 or age_s > 60:
        blockers.append("strict_flat_proof_stale")
    return blockers


def _fresh_epoch_status_payload() -> dict:
    """Read-only contract for the dashboard button — never wipes."""
    epoch_id, cutoff, kind = _fresh_epoch_identity_from_session()
    with state_lock:
        paused = bool(state.get("execution_paused", False))
        live_armed = bool(state.get("live_armed", False))
        mode = bool(state.get("fresh_collection_mode", False))
        invert = bool(state.get("invert_signal", False))
    with trade_lock:
        pending_count = len(pending_orders)
        open_count = len(open_positions)
    proof = _fresh_epoch_strict_flat_proof()
    blockers = []
    if live_armed:
        blockers.append("LIVE_ARMED")
    if not paused:
        blockers.append("EXECUTION_NOT_PAUSED")
    if pending_count:
        blockers.append(f"PENDING_ORDERS:{pending_count}")
    if open_count:
        blockers.append(f"OPEN_POSITIONS:{open_count}")
    blockers.extend(_fresh_epoch_proof_blockers(proof))
    seen = set()
    uniq = []
    for item in blockers:
        if item in seen:
            continue
        seen.add(item)
        uniq.append(item)
    return {
        "ok": True,
        "dry_run": True,
        "wiped": False,
        "fresh_collection_mode": mode,
        "off_allowed": False,
        "one_way_on": True,
        "epoch_id": epoch_id,
        "epoch_cutoff_utc": cutoff,
        "epoch_kind": kind,
        "invert_signal": invert,
        "wipe_ready": not uniq,
        "blockers": uniq,
        "strict_flat_proof": proof,
        "confirmation_required": _FRESH_EPOCH_CONFIRMATION,
        "endpoint": "/api/fresh_epoch_reset",
        "hint": (
            "Fresh Collection stays ON for the bound epoch. "
            "POST /api/fresh_epoch_reset with confirmation starts a NEW Fly epoch wipe."
        ),
    }


@app.route('/api/fresh_epoch_reset', methods=['GET', 'POST'])
def api_fresh_epoch_reset():
    """Strict operator-only research epoch reset for the Fly execution mirror.

    GET (or POST dry_run=true) returns the wipe contract without mutating.
    POST with confirmation runs the existing perform_fresh_collection_reset
    path — the same Fly-volume quarantine used by the official epoch wipe.
    """
    if not _admin_authed_strict():
        return jsonify({"ok": False, "error": "admin token required"}), 401
    data = request.get_json(silent=True) or {}
    if request.method == "GET" or data.get("dry_run") is True:
        return jsonify(_fresh_epoch_status_payload())
    if data.get("confirmation") != _FRESH_EPOCH_CONFIRMATION:
        return jsonify({
            "ok": False,
            "error": "explicit fresh-epoch confirmation required",
        }), 400
    proof = data.get("strict_flat_proof")
    if not isinstance(proof, dict):
        return jsonify({"ok": False, "error": "strict_flat_proof required"}), 400
    required_zero = _FRESH_EPOCH_ZERO_FIELDS
    if any(proof.get(key) != 0 for key in required_zero):
        return jsonify({
            "ok": False,
            "error": "strict flat proof is not zero",
            "required_zero_fields": list(required_zero),
        }), 409
    if proof.get("relay_paused") is not True or proof.get("relay_disarmed") is not True:
        return jsonify({"ok": False, "error": "relay must be paused and disarmed"}), 409
    try:
        checked_at = datetime.fromisoformat(str(proof.get("checked_at") or "").replace("Z", "+00:00"))
        age_s = (datetime.now(timezone.utc) - checked_at.astimezone(timezone.utc)).total_seconds()
    except (TypeError, ValueError):
        age_s = float("inf")
    if age_s < 0 or age_s > 60:
        return jsonify({"ok": False, "error": "strict flat proof is stale"}), 409

    result = perform_fresh_collection_reset(send_local_signal=True)
    epoch_id, cutoff, kind = _fresh_epoch_identity_from_session()
    if result.get("ok"):
        # The presentation snapshot is intentionally long-lived.  Publish the
        # new signed identity and empty evidence scope synchronously so the
        # successful reset response cannot be followed by an authenticated
        # /api/state response from the previous epoch.
        _patch_api_state_cache_fields(
            fresh_collection_mode=True,
            fresh_epoch_id=epoch_id,
            fresh_epoch_cutoff_utc=cutoff,
            fresh_epoch_kind=kind,
            trade_scope="SIGNED_FRESH_EPOCH" if cutoff else "ALL_HISTORY",
            trade_scope_cutoff_utc=cutoff,
            trades=[],
            trade_count_session=0,
            session_pnl_usd=0.0,
        )
    status = 200 if result.get("ok") else 409
    return jsonify({
        "ok": bool(result.get("ok")),
        "reset": result,
        "deleted": result.get("deleted") or [],
        "purged_quarantine": result.get("purged_quarantine") or [],
        "strict_flat_checked_at": proof.get("checked_at"),
        "epoch_id": epoch_id,
        "epoch_cutoff_utc": cutoff,
        "epoch_kind": kind,
        "fresh_collection_mode": True if result.get("ok") else bool(state.get("fresh_collection_mode")),
    }), status

@app.get("/api/data_size")
def api_data_size():
    """Report Fly volume data size for the dashboard cleanup panel.

    Returns the total size of the runtime data directory (``/app/data/runtime``
    on Fly, or wherever ``BOT_DATA_DIR`` points), the percentage of the 1GB
    Fly volume in use, the top-5 largest files, and line counts for the key
    research evidence files. Local mirror size is reported by the desktop
    sync loop into ``_size_report.json`` — this endpoint intentionally only
    reports Fly-side numbers so the dashboard never confuses the two.
    """
    if not _admin_authed_strict():
        return jsonify({
            "status": "error",
            "message": "admin token required",
        }), 401

    runtime_root = _data_sync_volume_root()
    volume_total_mb = 1024.0
    try:
        usage = shutil.disk_usage(runtime_root)
        volume_total_mb = round(float(usage.total) / (1024.0 * 1024.0), 2)
    except OSError:
        env_mb = os.getenv("FLY_VOLUME_MB", "").strip()
        if env_mb:
            try:
                volume_total_mb = float(env_mb)
            except ValueError:
                pass
    runtime_path = str(runtime_root)

    def _run(cmd, timeout=10):
        try:
            out = subprocess.run(
                cmd,
                cwd=runtime_path,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            if out.returncode != 0:
                return ""
            return (out.stdout or "").strip()
        except Exception as exc:
            logger.warning("[DATA SIZE] cmd %r failed: %s", cmd, exc)
            return ""

    def _run_bytes(cmd, timeout=10):
        try:
            out = subprocess.run(
                cmd,
                cwd=runtime_path,
                capture_output=True,
                timeout=timeout,
            )
            if out.returncode != 0:
                return b""
            return out.stdout or b""
        except Exception as exc:
            logger.warning("[DATA SIZE] byte cmd %r failed: %s", cmd, exc)
            return b""

    # Total MB of the runtime dir via du -sm. du is present in the Fly image
    # (Debian) and on the home analyzer host. Fallback to os.walk if missing.
    total_mb = None
    du_total = _run(["du", "-sm", runtime_path])
    if du_total:
        # Output: "<mb>	<path>"
        first = du_total.splitlines()[0].split("	")[0].strip()
        try:
            total_mb = float(first)
        except ValueError:
            total_mb = None
    if total_mb is None:
        try:
            bytes_total = 0
            for dirpath, _dirs, files in os.walk(runtime_root):
                for name in files:
                    try:
                        bytes_total += os.path.getsize(os.path.join(dirpath, name))
                    except OSError:
                        continue
            total_mb = round(bytes_total / (1024.0 * 1024.0), 2)
        except Exception as exc:
            logger.warning("[DATA SIZE] os.walk size failed: %s", exc)
            total_mb = None

    # Top-5 largest files via Python walk (reliable). Avoid `du path/*` — without
    # shell expansion that argv is a literal `*` and silently returns nothing,
    # which left the dashboard "Top files" table looking frozen.
    top_files = []
    try:
        sized = []
        for dirpath, _dirs, files in os.walk(runtime_root):
            for name in files:
                fp = os.path.join(dirpath, name)
                try:
                    sized.append((os.path.getsize(fp), fp))
                except OSError:
                    continue
        sized.sort(key=lambda r: r[0], reverse=True)
        for bytes_size, fp in sized[:5]:
            top_files.append({
                "name": os.path.basename(fp),
                "path": fp,
                "size_mb": round(bytes_size / (1024.0 * 1024.0), 2),
            })
    except Exception as exc:
        logger.warning("[DATA SIZE] os.walk top-files failed: %s", exc)

    # Line counts for the key research evidence files. Use wc -l when present,
    # fall back to Python counting so the endpoint still works on hosts
    # without coreutils.
    key_files = ["trades_3factor.csv", "ai_reason_research.jsonl", "signal_replay.jsonl"]
    line_counts = {}
    wc_out = _run_bytes(["wc", "-l"] + [os.path.join(runtime_path, f) for f in key_files])
    wc_parsed = {}
    if wc_out:
        try:
            text = wc_out.decode("utf-8", errors="replace")
            for line in text.splitlines():
                parts = line.split(None, 1)
                if len(parts) != 2:
                    continue
                try:
                    count = int(parts[0].strip())
                except ValueError:
                    continue
                fname = os.path.basename(parts[1].strip())
                wc_parsed[fname] = count
        except Exception as exc:
            logger.warning("[DATA SIZE] wc parse failed: %s", exc)
    for fname in key_files:
        if fname in wc_parsed:
            line_counts[fname] = wc_parsed[fname]
            continue
        # Fallback line counter.
        fpath = runtime_root / fname
        count = None
        try:
            if fpath.exists() and fpath.is_file():
                with open(fpath, "rb") as fh:
                    count = sum(1 for _ in fh)
        except OSError as exc:
            logger.warning("[DATA SIZE] count %s failed: %s", fname, exc)
        line_counts[fname] = count

    volume_pct = None
    if total_mb is not None:
        volume_pct = round((total_mb / volume_total_mb) * 100.0, 1)

    cleanup_status = "ok"
    if volume_pct is not None:
        if volume_pct > 80.0:
            cleanup_status = "critical"
        elif volume_pct > 60.0:
            cleanup_status = "warn"

    storage_payload = {}
    capacity_payload = {}
    try:
        storage_payload = storage_state(str(runtime_root))
        capacity_payload = project_capacity(data_dir=str(runtime_root))
    except Exception as exc:
        logger.warning("[DATA SIZE] storage/capacity probe failed: %s", exc)

    return jsonify({
        "status": "ok",
        "source": "fly" if os.path.exists("/.dockerenv") or os.path.exists("/app/fly-entrypoint.sh") else "local",
        "runtime_path": runtime_path,
        "volume_total_mb": volume_total_mb,
        "runtime_size_mb": total_mb,
        "volume_pct": volume_pct,
        "cleanup_status": cleanup_status,
        "top_files": top_files,
        "line_counts": line_counts,
        "key_files": key_files,
        "computed_at": int(time.time()),
        "collector_version": COLLECTOR_V31_VERSION,
        "legacy_collector_version": COLLECTOR_V22_VERSION,
        "storage_state": storage_payload,
        "capacity_projection": capacity_payload,
    })

def _arm_live_control() -> tuple:
    exchange_audit = _refresh_bitfinex_exposure_audit()
    # Private exchange rows are caller-internal recovery material, never an API
    # response. The central gate reads the sanitized state audit.
    exchange_audit.pop("_rebuild_payload", None)
    with _live_control_lock:
        armable, block_reason, runtime = can_open_live_entry(require_armed=False)
        if not armable:
            return False, block_reason, runtime, exchange_audit
        with state_lock:
            state["live_armed"] = True
            state["bitfinex_live_enabled"] = True
        save_persistent_config()
        return True, "READY", runtime, exchange_audit


def _disarm_live_control(reason: str) -> dict:
    with _live_control_lock:
        with state_lock:
            state["live_armed"] = False
            state["bitfinex_live_enabled"] = False
        save_persistent_config()
    # Flags are already false before cancellation begins. A concurrent submit
    # must acquire the same lock and will fail its armed gate; private I/O is
    # never performed while holding trade_lock/state_lock.
    cancel_result = _cancel_managed_live_pending_entries(reason)
    exit_only = _mark_exit_only_for_open_bitfinex_positions(reason=reason)
    return {
        "cancel": cancel_result,
        "exit_only": exit_only,
    }


@app.route('/api/exchange_exposure_audit', methods=['GET'])
def api_exchange_exposure_audit():
    """Refresh the private Bitfinex boundary without changing live controls.

    This operator-only endpoint exists so deployment and epoch-reset tooling can
    prove the real exchange boundary directly.  It performs private read calls
    only; it never arms live execution, submits/cancels orders, or returns raw
    private exchange rows.
    """
    if not _admin_authed_strict():
        return jsonify({"ok": False, "error": "admin token required"}), 401
    audit = _refresh_bitfinex_exposure_audit()
    audit.pop("_rebuild_payload", None)
    authoritative = bool(audit.get("authoritative"))
    fresh = bool(audit.get("fresh"))
    flat = bool(audit.get("flat"))
    return jsonify({
        "ok": authoritative and fresh,
        "authoritative": authoritative,
        "fresh": fresh,
        "flat": flat,
        "checked_ts": audit.get("checked_ts"),
        "open_order_count": audit.get("open_order_count"),
        "open_position_count": audit.get("open_position_count"),
        "orphan_order_ids": list(audit.get("orphan_order_ids") or []),
        "orphan_position_ids": list(audit.get("orphan_position_ids") or []),
        "orders_synced": bool(audit.get("orders_synced")),
        "positions_synced": bool(audit.get("positions_synced")),
        "trades_synced": bool(audit.get("trades_synced")),
        "error": audit.get("error"),
        "live_armed": bool(state.get("live_armed", False)),
        "bitfinex_live_enabled": bool(state.get("bitfinex_live_enabled", False)),
        "mutating": False,
    }), (200 if authoritative and fresh else 503)


@app.route('/api/live_arm', methods=['POST'])
def live_arm():
    data = request.get_json(silent=True)
    armed = _strict_json_boolean(data, "armed")
    if armed is None:
        return jsonify({
            "error": "'armed' must be a JSON boolean",
            "example": {"armed": True},
        }), 400
    if armed:
        ok, block_reason, runtime, exchange_audit = _arm_live_control()
        if not ok:
            return jsonify({
                "error": "Live arming blocked by the runtime safety gate",
                "block_reason": block_reason,
                "runtime_readiness": runtime,
                "exchange_sync_audit": exchange_audit,
                **_market_data_health_snapshot(),
            }), 409
        control = {"cancel": {"cancelled": [], "failed": []}, "exit_only": {}}
    else:
        control = _disarm_live_control("LIVE_ARM_DISARMED")
    cancel_result = control["cancel"]
    exit_only = control["exit_only"]
    with state_lock:
        live_armed_now = bool(state.get("live_armed"))
        live_enabled_now = bool(state.get("bitfinex_live_enabled"))
    payload = {
        "live_armed": live_armed_now,
        "bitfinex_live_enabled": live_enabled_now,
        "exit_only_lanes": list(exit_only.keys()),
        "live_pending_cancel": cancel_result,
    }
    return jsonify(payload), (409 if cancel_result["failed"] else 200)


@app.route('/api/bitfinex_live', methods=['POST'])
def api_bitfinex_live():
    data = request.get_json(silent=True)
    enabled = _strict_json_boolean(data, "enabled")
    if enabled is None:
        return jsonify({
            "error": "'enabled' must be a JSON boolean",
            "example": {"enabled": True},
        }), 400
    if enabled:
        ok, block_reason, runtime, exchange_audit = _arm_live_control()
        if not ok:
            return jsonify({
                "error": "Bitfinex live execution blocked by the runtime safety gate",
                "block_reason": block_reason,
                "runtime_readiness": runtime,
                "exchange_sync_audit": exchange_audit,
                **_market_data_health_snapshot(),
            }), 409
        control = {"cancel": {"cancelled": [], "failed": []}, "exit_only": {}}
    else:
        control = _disarm_live_control("BITFINEX_DISARMED")
    with state_lock:
        live_enabled_now = bool(state.get("bitfinex_live_enabled"))
        live_armed_now = bool(state.get("live_armed"))
    import bitfinex_live_executor as bx

    # Pt 4b (toggle contract): when Bitfinex is disarmed while positions remain
    # open, mark those lanes EXIT_ONLY -- no new entries, but exit management
    # continues until flat.
    cancel_result = control["cancel"]
    disarm_exit_only = control["exit_only"]

    logger.warning(
        f"[BITFINEX LIVE] dashboard toggle -> {'ON' if enabled else 'OFF'} "
        f"keys_ok={_private_api_keys_ok()} "
        f"exit_only_lanes={list(disarm_exit_only.keys()) if disarm_exit_only else []} "
        f"[PIPELINE ENFORCEMENT]"
    )
    response = jsonify({
            "bitfinex_live_enabled": live_enabled_now,
            "live_armed": live_armed_now,
            "keys_ok": _private_api_keys_ok(),
            "exit_only_lanes": list(disarm_exit_only.keys()) if disarm_exit_only else [],
            "live_pending_cancel": cancel_result,
            **bx.live_status(state, _private_api_keys_ok()),
        })
    return response, (409 if cancel_result["failed"] else 200)


def _mark_exit_only_for_open_bitfinex_positions(reason: str = "BITFINEX_DISARMED") -> dict:
    """Pt 4b: after Bitfinex disarm, mark lanes with open filled positions as
    EXIT_ONLY so new entries stop but exits continue. Returns dict lane->count.
    """
    out: dict = {}
    try:
        with trade_lock:
            for p in open_positions:
                if p.get("status") not in ("FILLED", "OPEN"):
                    continue
                if not (
                    p.get("bitfinex_position_id")
                    or p.get("bitfinex_order_id")
                ):
                    continue
                lane = _normalize_lane_key(p)
                if not lane:
                    continue
                out[lane] = out.get(lane, 0) + 1
        for lane in out.keys():
            mark_lane_exit_only(lane, reason=reason)
    except Exception as exc:
        logger.warning(f"[EXIT_ONLY MARK] error: {exc}")
    return out

@app.route('/api/set_leverage', methods=['POST'])
def set_leverage():
    data = request.get_json() or {}
    raw = data.get("value", DEFAULT_RESEARCH_LEVERAGE)
    try:
        requested = int(raw)
    except (TypeError, ValueError):
        return jsonify({"status": "error", "msg": "invalid leverage"}), 400
    val = max(1, min(requested, MAX_RESEARCH_LEVERAGE))
    with state_lock:
        state["leverage"] = val
        save_persistent_config()
    if requested > MAX_RESEARCH_LEVERAGE:
        logger.warning(f"[LEVERAGE] Capped request to {MAX_RESEARCH_LEVERAGE}x (max allowed) [PIPELINE ENFORCEMENT]")
    return jsonify({"leverage": val})

