# Fly is the sole 24/7 raw-data owner after cutover; the home analyzer pulls an
# authenticated incremental mirror when the PC is online. These endpoints are
# intentionally absent from _READ_ONLY_GET_PATHS, so the global API guard
# requires BOT_ADMIN_TOKEN even for downloads.
_DATA_SYNC_EXTENSIONS = frozenset({
    ".csv", ".json", ".jsonl", ".log", ".db", ".sqlite", ".sqlite3", ".txt",
})
_DATA_SYNC_EXCLUDED_NAMES = frozenset({
    "manifest.json", "genome_cluster_library.json",
    # Mutable crash-recovery state belongs only to the Fly collector. It can
    # change between chunk requests and is not research/analyzer evidence.
    "research_events_v22.provisional.json",
    # High-frequency operational storage telemetry is exposed through the
    # status API; it is not research evidence and is replaced too frequently
    # to belong to a generation-consistent evidence mirror.
    "collector_storage_state.json",
})
_DATA_SYNC_EXCLUDED_DIR_NAMES = frozenset({
    "research_epoch_quarantine",
    "research_archive",
    "research_session_archives",
    "archive-v2",
    "object-store",
    "object_store",
    # Original corrupt evidence is preserved with a hash/line receipt for
    # manual review. It must not starve the active mirror sync repeatedly.
    "corrupt_evidence_quarantine",
})
_DATA_SYNC_CHUNK_MAX = 4 * 1024 * 1024
_DATA_SYNC_APPEND_PREFIX_NAMES = frozenset({
    # Collector v2.2 is a write-once, serialized JSONL ledger. It may grow
    # during a large mirror download; inode replacement remains fenced.
    "research_events_v22.jsonl",
    "decisions_3factor.csv", "trades_3factor.csv",
    "expired_orders_3factor.csv", "blocked_signals_3factor.csv",
    "ai_tranche_log.csv", "setup_log_3factor.csv", "candles_3factor.csv",
    "pipeline_events_3factor.csv", "ai_errors_3factor.csv",
    "trend_health.csv",
})


def _data_sync_rotation_parts(raw_name: str):
    """Return ``(base_name, generation)`` for a supported numbered rotation.

    ``Path.suffix`` sees ``signal_replay.jsonl.28`` as ``.28``. Treating only
    the final suffix as the file type silently excluded every closed replay
    generation from the desktop mirror, so the Fly volume could never receive
    an acknowledgement and eventually filled. A rotation is supported only
    when the filename before its numeric generation has an explicitly allowed
    data extension.
    """
    name = Path(str(raw_name or "")).name
    base_name, separator, generation = name.rpartition(".")
    if not separator or not generation.isdigit():
        return None
    if Path(base_name).suffix.lower() not in _DATA_SYNC_EXTENSIONS:
        return None
    return base_name, int(generation)


def _data_sync_runtime_root() -> Path:
    return Path.cwd().resolve()


def _data_sync_volume_root() -> Path:
    raw = (os.getenv("BOT_DATA_DIR") or "").strip()
    if raw:
        return Path(raw).resolve()
    return _data_sync_runtime_root()


def _data_sync_allowed_roots() -> list:
    runtime = _data_sync_runtime_root()
    roots = [runtime]
    for name in ("research", "research_accumulator", "research_archive"):
        candidate = runtime / name
        if candidate.exists():
            roots.append(candidate)
    return roots


def _data_sync_relpath(path: Path) -> str:
    runtime = _data_sync_runtime_root()
    try:
        return path.resolve().relative_to(runtime).as_posix()
    except ValueError:
        # Volume-backed research directories can be symlinked beside runtime.
        for name in ("research", "research_accumulator", "research_archive"):
            link = runtime / name
            try:
                return f"{name}/{path.resolve().relative_to(link.resolve()).as_posix()}"
            except (ValueError, OSError):
                continue
    raise ValueError("path is outside runtime data roots")


def _data_sync_path_allowed(path: Path) -> bool:
    try:
        resolved = path.resolve(strict=True)
        volume = _data_sync_volume_root()
        resolved.relative_to(volume)
    except (OSError, ValueError):
        return False
    name_lower = resolved.name.lower()
    volume_parts = {part.lower() for part in resolved.parts}
    if volume_parts.intersection(_DATA_SYNC_EXCLUDED_DIR_NAMES):
        return False
    if resolved.name in _DATA_SYNC_EXCLUDED_NAMES:
        return False
    if name_lower.startswith(".env") or "secret" in name_lower or "credential" in name_lower:
        return False
    supported_type = (
        resolved.suffix.lower() in _DATA_SYNC_EXTENSIONS
        or _data_sync_rotation_parts(resolved.name) is not None
    )
    return resolved.is_file() and supported_type


def _data_sync_resolve_relpath(raw_rel: str) -> Path:
    rel = str(raw_rel or "").replace("\\", "/").strip("/")
    if not rel or rel.startswith(".") or ".." in rel.split("/"):
        raise ValueError("invalid relative path")
    runtime = _data_sync_runtime_root()
    candidate = runtime.joinpath(*rel.split("/"))
    if not _data_sync_path_allowed(candidate):
        raise ValueError("path is not an allowed runtime data file")
    return candidate.resolve()


def _data_sync_complete_record_size(path: Path, size: int) -> int:
    """Return the last complete-record boundary for JSONL/CSV evidence."""
    if size <= 0 or path.suffix.lower() not in {".jsonl", ".csv"}:
        return max(0, int(size))
    cursor = int(size)
    block_size = 64 * 1024
    with path.open("rb") as handle:
        while cursor > 0:
            start = max(0, cursor - block_size)
            handle.seek(start)
            block = handle.read(cursor - start)
            newline = block.rfind(b"\n")
            if newline >= 0:
                return start + newline + 1
            cursor = start
    return 0


def _data_sync_generation_matches(stat, *, size: int, mtime_ns: int, inode: int) -> bool:
    return (
        int(stat.st_size) == int(size)
        and int(stat.st_mtime_ns) == int(mtime_ns)
        and int(getattr(stat, "st_ino", 0) or 0) == int(inode)
    )


def _data_sync_consistency_mode(path: Path) -> str:
    """Declare only proven append-only files eligible for fixed-prefix reads.

    JSONL and CSV remain strict: several active writers patch or atomically
    rewrite those files in place. Runtime .log files are logging-handler-owned
    append streams; rotation changes the inode and is therefore still fenced.
    """
    # Some ledgers use the serialized append helper for new rows but are also
    # atomically rewritten when an outcome is patched.  They are not true
    # append-only generations and must retain the full inode/mtime/size fence.
    rewrite_targets = {
        os.path.abspath(value)
        for value in (globals().get("SIGNAL_SNAPSHOT_FILE"),)
        if isinstance(value, str) and value
    }
    resolved = str(path.resolve())
    parts_lower = tuple(part.lower() for part in path.resolve().parts)
    v3_append_only_ledger = (
        len(parts_lower) >= 3
        and parts_lower[-3:-1] == ("v3", "ledgers")
        and path.suffix.lower() == ".jsonl"
    )
    append_prefix = resolved not in rewrite_targets and (
        path.suffix.lower() == ".log"
        or path.name in _DATA_SYNC_APPEND_PREFIX_NAMES
        or resolved in globals().get("_jsonl_serialized_append_targets", set())
        or v3_append_only_ledger
    )
    return "append_prefix_v1" if append_prefix else "strict_generation_v1"


def _data_sync_append_prefix_matches(stat, *, minimum_size: int, inode: int) -> bool:
    return bool(
        int(getattr(stat, "st_ino", 0) or 0) == int(inode)
        and int(stat.st_size) >= int(minimum_size)
    )


def _data_sync_inventory() -> list:
    runtime = _data_sync_runtime_root()
    seen = set()
    rows = []
    for root in _data_sync_allowed_roots():
        for dirpath, _dirnames, filenames in os.walk(root, followlinks=True):
            _dirnames[:] = [
                name for name in _dirnames
                if name.lower() not in _DATA_SYNC_EXCLUDED_DIR_NAMES
            ]
            for filename in filenames:
                path = Path(dirpath) / filename
                try:
                    resolved = path.resolve(strict=True)
                    if resolved in seen or not _data_sync_path_allowed(path):
                        continue
                    seen.add(resolved)
                    stat = resolved.stat()
                    published_size = _data_sync_complete_record_size(resolved, int(stat.st_size))
                    rows.append({
                        "path": _data_sync_relpath(path),
                        "size": published_size,
                        "physical_size": int(stat.st_size),
                        "mtime_ns": int(stat.st_mtime_ns),
                        "inode": int(getattr(stat, "st_ino", 0) or 0),
                        "consistency_mode": _data_sync_consistency_mode(resolved),
                    })
                except (OSError, ValueError):
                    continue
                if len(rows) >= 5000:
                    break
            if len(rows) >= 5000:
                break
        if len(rows) >= 5000:
            break
    rows.sort(key=lambda row: row["path"])
    return rows


def _data_sync_ack_path() -> Path:
    return _data_sync_volume_root() / "sync_ack.json"


def _read_data_sync_ack() -> dict:
    try:
        raw = json.loads(_data_sync_ack_path().read_text(encoding="utf-8"))
        return raw if isinstance(raw, dict) else {}
    except (OSError, ValueError, TypeError):
        return {}


def _write_data_sync_ack(payload: dict) -> None:
    target = _data_sync_ack_path()
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_suffix(".tmp")
    tmp.write_text(json.dumps(payload, separators=(",", ":"), sort_keys=True), encoding="utf-8")
    os.replace(tmp, target)


def _prune_acknowledged_rotations(acks: dict, volume_used_pct: float | None = None) -> list:
    """Delete only fully acknowledged, old closed rotation files.

    Active files and the newest numeric rotations are never touched.
    Unacknowledged evidence is never deleted, even under disk pressure.

    v2.2: raw research JSONL is NEVER pruned here — archive checksum ack required
    first. Aggressive 70% pruning disabled to prevent silent tape loss.
    """
    removed = []
    keep_newest = 2
    age_hours = 24
    cutoff = time.time() - (age_hours * 3600)
    newest_by_family = {}
    for rel, ack in list((acks or {}).items()):
        rotation = _data_sync_rotation_parts(rel)
        if rotation is None or not isinstance(ack, dict):
            continue
        try:
            path = _data_sync_resolve_relpath(rel)
            base_name, rotation_index = rotation
            if base_name in _RESEARCH_RAW_JSONL_NEVER_PRUNE:
                continue
            family_key = (path.parent, base_name)
            newest_kept = newest_by_family.get(family_key)
            if newest_kept is None:
                generations = []
                for sibling in path.parent.iterdir():
                    sibling_rotation = _data_sync_rotation_parts(sibling.name)
                    if (
                        sibling_rotation is not None
                        and sibling_rotation[0] == base_name
                        and _data_sync_path_allowed(sibling)
                    ):
                        generations.append(sibling_rotation[1])
                newest_kept = frozenset(sorted(generations)[-keep_newest:])
                newest_by_family[family_key] = newest_kept
            # Retention invariant: active/unacked files retained. The newest
            # rotations are active evidence and cannot be removed by cleanup.
            if rotation_index in newest_kept:
                continue
            stat = path.stat()
            if (
                stat.st_mtime <= cutoff
                and int(ack.get("size") or -1) == int(stat.st_size)
                and int(ack.get("mtime_ns") or -1) == int(stat.st_mtime_ns)
            ):
                path.unlink()
                removed.append(rel)
        except (OSError, ValueError):
            continue
    return removed


@app.route('/api/data-sync/manifest')
def api_data_sync_manifest():
    files = _data_sync_inventory()
    usage = shutil.disk_usage(_data_sync_volume_root())
    ack = _read_data_sync_ack()
    with state_lock:
        fresh_collection_signal_ts = float(state.get("fresh_collection_signal_ts") or 0.0)
    if fresh_collection_signal_ts <= 0:
        # The in-memory notification is lost on a normal machine restart, but
        # research_session.json is the durable epoch authority. Re-publish the
        # same cutoff (the sync client compares monotonically) so manifests do
        # not falsely claim that no Fresh Collection has ever run.
        session = _load_research_session_meta() or {}
        try:
            fresh_collection_signal_ts = float(
                session.get("fresh_collection_start_time") or 0.0
            )
        except (TypeError, ValueError):
            fresh_collection_signal_ts = 0.0
    return jsonify({
        "schema": "fly_runtime_incremental_sync_v1",
        "generated_at": utc_iso(),
        "source_git_rev": _runtime_git_rev(),
        "bot_version": EXECUTION_FIX_VERSION,
        "files": files,
        "file_count": len(files),
        "total_bytes": sum(row["size"] for row in files),
        "acknowledged_files": len(ack),
        # Monotonic signal — local sync loop wipes its mirror when this advances.
        # 0.0 means no Fresh Collection has run yet; the loop treats any
        # strictly-greater value as a wipe trigger.
        "fresh_collection_signal_ts": fresh_collection_signal_ts,
        "volume": {
            "total": int(usage.total),
            "used": int(usage.used),
            "free": int(usage.free),
            "used_pct": round((usage.used / usage.total) * 100, 2) if usage.total else None,
        },
    })


@app.route('/api/data-sync/file')
def api_data_sync_file():
    try:
        path = _data_sync_resolve_relpath(request.args.get("path"))
        offset = max(0, int(request.args.get("offset") or 0))
        limit = min(
            _DATA_SYNC_CHUNK_MAX,
            max(1, int(request.args.get("limit") or _DATA_SYNC_CHUNK_MAX)),
        )
        before = path.stat()
        expected_size = request.args.get("expected_physical_size")
        expected_mtime = request.args.get("expected_mtime_ns")
        expected_inode = request.args.get("expected_inode")
        expected_published_size = request.args.get("expected_published_size")
        requested_mode = str(request.args.get("consistency_mode") or "strict_generation_v1")
        server_mode = _data_sync_consistency_mode(path)
        if requested_mode != server_mode:
            return jsonify({"error": "file consistency mode mismatch"}), 409
        append_prefix = requested_mode == "append_prefix_v1"
        if append_prefix:
            if None in (expected_size, expected_inode, expected_published_size):
                return jsonify({"error": "append prefix fence is incomplete"}), 409
            published_boundary = int(expected_published_size)
            physical_boundary = int(expected_size)
            if not (0 <= published_boundary <= physical_boundary):
                return jsonify({"error": "append prefix boundary is invalid"}), 409
            if not _data_sync_append_prefix_matches(
                before, minimum_size=physical_boundary, inode=int(expected_inode),
            ):
                return jsonify({"error": "append file generation changed after manifest"}), 409
            if offset > published_boundary:
                return jsonify({"error": "offset beyond published prefix", "size": published_boundary}), 416
            limit = min(limit, max(0, published_boundary - offset))
        elif None not in (expected_size, expected_mtime, expected_inode) and not _data_sync_generation_matches(
            before, size=int(expected_size), mtime_ns=int(expected_mtime), inode=int(expected_inode),
        ):
            return jsonify({"error": "file generation changed after manifest"}), 409
        if offset > before.st_size:
            return jsonify({"error": "offset beyond current file size", "size": before.st_size}), 416
        with path.open("rb") as handle:
            handle.seek(offset)
            payload = handle.read(limit)
        after = path.stat()
        if append_prefix:
            if not _data_sync_append_prefix_matches(
                after, minimum_size=int(before.st_size),
                inode=int(getattr(before, "st_ino", 0) or 0),
            ):
                return jsonify({"error": "append file generation changed during download"}), 409
        elif not _data_sync_generation_matches(
            after, size=int(before.st_size), mtime_ns=int(before.st_mtime_ns),
            inode=int(getattr(before, "st_ino", 0) or 0),
        ):
            return jsonify({"error": "file generation changed during download"}), 409
        response = make_response(payload)
        response.headers["Content-Type"] = "application/octet-stream"
        response.headers["X-Data-Path"] = _data_sync_relpath(path)
        response.headers["X-Data-Offset"] = str(offset)
        response.headers["X-Data-Size"] = str(after.st_size)
        response.headers["X-Data-Mtime-Ns"] = str(after.st_mtime_ns)
        response.headers["X-Data-Inode"] = str(int(getattr(after, "st_ino", 0) or 0))
        response.headers["X-Chunk-Sha256"] = hashlib.sha256(payload).hexdigest()
        eof_size = published_boundary if append_prefix else after.st_size
        response.headers["X-Data-Published-Size"] = str(eof_size)
        response.headers["X-Data-Eof"] = "1" if offset + len(payload) >= eof_size else "0"
        return response
    except (OSError, TypeError, ValueError) as exc:
        return jsonify({"error": str(exc)}), 400


@app.route('/api/data-sync/ack', methods=['POST'])
def api_data_sync_ack():
    body = request.get_json(silent=True) or {}
    received = body.get("files") or []
    acks = _read_data_sync_ack()
    accepted = 0
    for row in received[:5000]:
        if not isinstance(row, dict):
            continue
        rel = str(row.get("path") or "")
        try:
            path = _data_sync_resolve_relpath(rel)
            stat = path.stat()
        except (OSError, ValueError):
            continue
        if (
            int(row.get("size") or -1) == int(stat.st_size)
            and int(row.get("mtime_ns") or -1) == int(stat.st_mtime_ns)
        ):
            acks[rel] = {
                "size": int(stat.st_size),
                "mtime_ns": int(stat.st_mtime_ns),
                "acknowledged_at": utc_iso(),
            }
            accepted += 1
    _write_data_sync_ack(acks)
    try:
        usage = shutil.disk_usage(_data_sync_volume_root())
        volume_used_pct = round((usage.used / usage.total) * 100, 2) if usage.total else None
    except OSError:
        volume_used_pct = None
    removed = _prune_acknowledged_rotations(acks, volume_used_pct=volume_used_pct)
    return jsonify({
        "ok": True,
        "accepted": accepted,
        "removed_acknowledged_rotations": removed,
        "volume_used_pct": volume_used_pct,
        "policy": (
            "acknowledged rotations older than 24h are pruned except newest 2 generations; "
            "raw research JSONL never pruned without archive ack; STORAGE_PRESSURE at 85%"
        ),
    })


_PLATFORM_RELAY_EVIDENCE_MAX_BYTES = 25 * 1024 * 1024


def _validate_platform_relay_evidence_payload(payload: dict) -> tuple[bool, str]:
    return _pure_validate_platform_relay_evidence_payload(payload)


@app.route('/api/data-sync/platform-relay-evidence', methods=['POST'])
def api_data_sync_platform_relay_evidence():
    """Install a validated Neon/Bitfinex evidence snapshot for the bot's
    append-derived counterfactual join. The data-sync namespace is protected by
    the strict admin-token middleware; no trading state is mutated here."""
    raw = request.get_data(cache=False)
    if not raw or len(raw) > _PLATFORM_RELAY_EVIDENCE_MAX_BYTES:
        return jsonify({"ok": False, "errorCode": "SIZE_INVALID"}), 413
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return jsonify({"ok": False, "errorCode": "JSON_INVALID"}), 400
    valid, code = _validate_platform_relay_evidence_payload(payload)
    if not valid:
        return jsonify({"ok": False, "errorCode": code}), 400
    destination = Path(PLATFORM_RELAY_EVIDENCE_FILE)
    if not destination.is_absolute():
        destination = _data_sync_volume_root() / destination.name
    destination.parent.mkdir(parents=True, exist_ok=True)
    temp = destination.with_name(f".{destination.name}.{uuid.uuid4().hex}.tmp")
    digest = hashlib.sha256(raw).hexdigest()
    try:
        with temp.open("wb") as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, destination)
    finally:
        try:
            temp.unlink(missing_ok=True)
        except OSError:
            pass
    return jsonify({
        "ok": True,
        "schema": payload["schema"],
        "sha256": digest,
        "records": len(payload["records"]),
        "generatingRevision": payload["generatingRevision"],
    })


def _analyzer_mirror_dir() -> Path:
    return _data_sync_volume_root() / "analyzer_mirror"


_ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES = 50 * 1024 * 1024
_ANALYZER_BUNDLE_MAX_EXPANDED_BYTES = 150 * 1024 * 1024
_ANALYZER_BUNDLE_MAX_MEMBERS = 256
_ANALYZER_BUNDLE_MAX_MEMBER_BYTES = 50 * 1024 * 1024
_ANALYZER_BUNDLE_MAX_COMPRESSION_RATIO = 1000
_ANALYZER_BUNDLE_ALLOWED_SUFFIXES = frozenset((".html", ".txt", ".json", ".log"))
_ANALYZER_BUNDLE_MANIFEST = "bundle_manifest.json"
_ANALYZER_BUNDLE_SCHEMA = "analyzer_mirror_bundle_v2"
_ANALYZER_INSTALL_LOCK = threading.RLock()
if app.config.get("MAX_CONTENT_LENGTH") is None:
    # Bound multipart spooling before Flask parses request.files. The analyzer
    # ZIP is the largest accepted upload in this service.
    app.config["MAX_CONTENT_LENGTH"] = _ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES + 1024 * 1024


def _analyzer_generations_dir() -> Path:
    return _data_sync_volume_root() / "analyzer_generations"


def _analyzer_current_pointer_path() -> Path:
    return _data_sync_volume_root() / "analyzer_current.json"


def _valid_analyzer_generation(candidate: Path) -> bool:
    """Accept only a complete, hash-bound bundle-v2 generation on disk."""
    try:
        status = json.loads((candidate / "status.json").read_text(encoding="utf-8"))
        manifest = json.loads(
            (candidate / _ANALYZER_BUNDLE_MANIFEST).read_text(encoding="utf-8")
        )
        if not (
            candidate.is_dir()
            and status.get("complete") is True
            and status.get("schema") == _ANALYZER_BUNDLE_SCHEMA
            and manifest.get("schema") == _ANALYZER_BUNDLE_SCHEMA
            and isinstance(manifest.get("files"), list)
        ):
            return False
        declared = {}
        for row in manifest["files"]:
            rel = str((row or {}).get("path") or "").replace("\\", "/")
            rel_path = Path(rel)
            digest = str((row or {}).get("sha256") or "").lower()
            size = int((row or {}).get("size_bytes"))
            if (
                not rel or rel_path.is_absolute() or ".." in rel_path.parts
                or rel != str(rel_path).replace("\\", "/")
                or rel == _ANALYZER_BUNDLE_MANIFEST
                or rel.casefold() in declared
                or rel_path.suffix.lower() not in _ANALYZER_BUNDLE_ALLOWED_SUFFIXES
                or not re.fullmatch(r"[0-9a-f]{64}", digest)
                or size < 0 or size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES
            ):
                return False
            declared[rel.casefold()] = (rel, digest, size)
        if "analysis_dashboard.html" not in {row[0] for row in declared.values()}:
            return False
        actual = set()
        root = candidate.resolve()
        for path in candidate.rglob("*"):
            if not path.is_file() or path.is_symlink():
                continue
            rel = path.relative_to(candidate).as_posix()
            if rel in ("status.json", _ANALYZER_BUNDLE_MANIFEST):
                continue
            resolved = path.resolve()
            resolved.relative_to(root)
            actual.add(rel.casefold())
            expected = declared.get(rel.casefold())
            if expected is None or path.stat().st_size != expected[2]:
                return False
            if hashlib.sha256(path.read_bytes()).hexdigest() != expected[1]:
                return False
        return actual == set(declared)
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return False


def _recover_latest_analyzer_generation() -> Path | None:
    """Recover from a missing/corrupt pointer without selecting staging data."""
    generations = _analyzer_generations_dir()
    try:
        candidates = sorted(
            (
                path for path in generations.iterdir()
                if path.name.startswith("generation-") and _valid_analyzer_generation(path)
            ),
            key=lambda path: path.stat().st_mtime_ns,
            reverse=True,
        )
    except OSError:
        return None
    return candidates[0] if candidates else None


def _active_analyzer_mirror_dir() -> Path | None:
    """Resolve only a fully validated immutable generation; never serve legacy HTML."""
    pointer = _analyzer_current_pointer_path()
    try:
        row = json.loads(pointer.read_text(encoding="utf-8"))
        generation = str(row.get("generation") or "")
        if not generation or generation != Path(generation).name:
            raise ValueError("invalid analyzer generation pointer")
        root = _analyzer_generations_dir().resolve()
        candidate = (_analyzer_generations_dir() / generation).resolve()
        candidate.relative_to(root)
        if _valid_analyzer_generation(candidate):
            return candidate
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        pass
    recovered = _recover_latest_analyzer_generation()
    if recovered is not None:
        return recovered
    return None


def _prune_analyzer_generations(active_generation: str, keep: int = 3) -> None:
    """Bound immutable snapshot storage while never deleting the active tree."""
    root = _analyzer_generations_dir()
    try:
        generations = sorted(
            (path for path in root.iterdir() if path.name.startswith("generation-") and path.is_dir()),
            key=lambda path: path.stat().st_mtime_ns,
            reverse=True,
        )
    except OSError:
        return
    retained = {path.name for path in generations[:max(1, keep)]}
    retained.add(active_generation)
    for path in generations:
        if path.name not in retained:
            shutil.rmtree(path, ignore_errors=True)


def _safe_analyzer_bundle_members(archive: zipfile.ZipFile) -> list:
    """Validate a complete read-only analyzer bundle before extracting it."""
    members = []
    expanded = 0
    infos = archive.infolist()
    if len(infos) > _ANALYZER_BUNDLE_MAX_MEMBERS:
        raise ValueError("analyzer bundle contains too many members")
    seen = set()
    for info in infos:
        if info.is_dir():
            continue
        raw_name = str(info.filename or "").replace("\\", "/")
        parts = [part for part in raw_name.split("/") if part]
        if (
            not parts
            or raw_name.startswith("/")
            or any(part in (".", "..") for part in parts)
            or ":" in parts[0]
        ):
            raise ValueError("analyzer bundle contains an unsafe path")
        rel = Path(*parts)
        normalized = str(rel).replace("\\", "/")
        collision_key = normalized.casefold()
        if collision_key in seen:
            raise ValueError(f"analyzer bundle contains a duplicate path: {raw_name}")
        seen.add(collision_key)
        if rel.suffix.lower() not in _ANALYZER_BUNDLE_ALLOWED_SUFFIXES:
            raise ValueError(f"analyzer bundle contains an unsupported file: {raw_name}")
        # Unix symlinks are not report files and could escape the mirror root.
        unix_mode = (int(info.external_attr) >> 16) & 0o170000
        if unix_mode == 0o120000:
            raise ValueError("analyzer bundle contains a symbolic link")
        member_size = int(info.file_size or 0)
        compressed_size = int(info.compress_size or 0)
        if member_size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES:
            raise ValueError(f"analyzer bundle member exceeds 50 MB: {raw_name}")
        if normalized == _ANALYZER_BUNDLE_MANIFEST and member_size > 2 * 1024 * 1024:
            raise ValueError("analyzer bundle manifest exceeds 2 MB")
        if (
            member_size > 1024 * 1024
            and compressed_size > 0
            and member_size / compressed_size > _ANALYZER_BUNDLE_MAX_COMPRESSION_RATIO
        ):
            raise ValueError(f"analyzer bundle member has an unsafe compression ratio: {raw_name}")
        expanded += member_size
        if expanded > _ANALYZER_BUNDLE_MAX_EXPANDED_BYTES:
            raise ValueError("analyzer bundle expands beyond the 150 MB limit")
        members.append((info, rel))
    paths = {str(rel).replace("\\", "/") for _, rel in members}
    if _ANALYZER_BUNDLE_MANIFEST not in paths:
        raise ValueError(f"analyzer bundle is missing {_ANALYZER_BUNDLE_MANIFEST}")
    return members


def _validated_analyzer_bundle_manifest(archive: zipfile.ZipFile, members: list) -> dict:
    """Require an exact, hash-bound set of files from one analyzer run."""
    try:
        manifest = json.loads(archive.read(_ANALYZER_BUNDLE_MANIFEST).decode("utf-8"))
    except (KeyError, UnicodeDecodeError, ValueError, TypeError) as exc:
        raise ValueError(f"invalid analyzer bundle manifest: {exc}") from exc
    if manifest.get("schema") != _ANALYZER_BUNDLE_SCHEMA:
        raise ValueError("unsupported analyzer bundle schema")
    required_text = (
        "snapshot_id", "analyzer_run_id", "analyzer_generated_at",
        "source_data_revision", "analyzer_generation_revision",
        "analyzer_version", "cohort_schema", "data_scope",
        "source_report_manifest_sha256",
    )
    if any(not str(manifest.get(key) or "").strip() for key in required_text):
        raise ValueError("analyzer bundle provenance is incomplete")
    rows = manifest.get("files")
    if not isinstance(rows, list) or not rows:
        raise ValueError("analyzer bundle manifest has no files")
    declared = {}
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("analyzer bundle manifest contains an invalid file row")
        path = str(row.get("path") or "").replace("\\", "/")
        key = path.casefold()
        if not path or key in declared:
            raise ValueError("analyzer bundle manifest contains a duplicate or empty file path")
        digest = str(row.get("sha256") or "").lower()
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise ValueError(f"analyzer bundle manifest has an invalid hash: {path}")
        try:
            size = int(row.get("size_bytes"))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"analyzer bundle manifest has an invalid size: {path}") from exc
        if size < 0 or size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES:
            raise ValueError(f"analyzer bundle manifest size is out of bounds: {path}")
        declared[key] = {"path": path, "sha256": digest, "size_bytes": size}
    actual = {
        str(rel).replace("\\", "/").casefold()
        for _, rel in members
        if str(rel).replace("\\", "/") != _ANALYZER_BUNDLE_MANIFEST
    }
    if actual != set(declared):
        raise ValueError("analyzer bundle membership does not exactly match its manifest")
    if "analysis_dashboard.html" not in {row["path"] for row in declared.values()}:
        raise ValueError("analyzer bundle is missing analysis_dashboard.html")
    for revision_key in ("source_data_revision", "analyzer_generation_revision"):
        if not re.fullmatch(r"[0-9a-fA-F]{7,64}", str(manifest[revision_key])):
            raise ValueError(f"analyzer bundle has an invalid {revision_key}")
    try:
        datetime.fromisoformat(str(manifest["analyzer_generated_at"]).replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError("analyzer bundle has an invalid analyzer_generated_at") from exc
    try:
        report_payload = archive.read("report_manifest.json")
        report_manifest = json.loads(report_payload.decode("utf-8"))
    except (KeyError, UnicodeDecodeError, ValueError, TypeError) as exc:
        raise ValueError(f"invalid source report manifest: {exc}") from exc
    if hashlib.sha256(report_payload).hexdigest() != str(manifest["source_report_manifest_sha256"]).lower():
        raise ValueError("source report manifest hash does not match bundle provenance")
    provenance = report_manifest.get("analysis_provenance") or {}
    comparisons = {
        "analyzer_run_id": report_manifest.get("analyzer_sync_id"),
        "analyzer_version": report_manifest.get("analyzer_version"),
        "analyzer_generated_at": report_manifest.get("generated_at"),
        "data_scope": report_manifest.get("data_scope"),
        "cohort_schema": provenance.get("cohort_schema"),
        "analyzer_generation_revision": provenance.get("generation_revision"),
    }
    if any(str(manifest.get(key)) != str(value) for key, value in comparisons.items()):
        raise ValueError("bundle provenance does not match the source report manifest")
    expected_paths = {"report_manifest.json"}
    for raw_path in report_manifest.get("text_artifacts") or []:
        path = str(raw_path or "")
        if not path or path != Path(path).name:
            raise ValueError("source report manifest contains an unsafe text artifact path")
        expected_paths.add(path)
    reports = report_manifest.get("reports") or []
    try:
        report_count = int(report_manifest.get("report_count"))
    except (TypeError, ValueError) as exc:
        raise ValueError("source report manifest has an invalid report_count") from exc
    if len(reports) != report_count:
        raise ValueError("source report manifest report_count does not match its reports")
    for row in reports:
        path = str((row or {}).get("file") or "")
        if not path or path != Path(path).name:
            raise ValueError("source report manifest contains an unsafe report path")
        expected_paths.add(f"reports/{path}")
    if expected_paths != {row["path"] for row in declared.values()}:
        raise ValueError("bundle files do not exactly match the source report manifest")
    return manifest


def _install_analyzer_bundle(payload: bytes, meta: dict) -> dict:
    """Install an immutable generation, then atomically select it."""
    generations = _analyzer_generations_dir()
    generations.mkdir(parents=True, exist_ok=True)
    nonce = f"{os.getpid()}-{time.time_ns()}"
    staging = generations / f".staging-{nonce}"
    pointer_tmp = _analyzer_current_pointer_path().with_name(f"analyzer_current.{nonce}.tmp")
    with _ANALYZER_INSTALL_LOCK:
        try:
            with zipfile.ZipFile(io.BytesIO(payload), "r") as archive:
                members = _safe_analyzer_bundle_members(archive)
                manifest = _validated_analyzer_bundle_manifest(archive, members)
                staging.mkdir(parents=True, exist_ok=False)
                declared = {
                    str(row["path"]).replace("\\", "/").casefold(): row
                    for row in manifest["files"]
                }
                extracted = 0
                for info, rel in members:
                    rel_text = str(rel).replace("\\", "/")
                    target = staging / rel
                    target.parent.mkdir(parents=True, exist_ok=True)
                    digest = hashlib.sha256()
                    actual_size = 0
                    with archive.open(info, "r") as source, open(target, "wb") as destination:
                        while True:
                            chunk = source.read(1024 * 1024)
                            if not chunk:
                                break
                            actual_size += len(chunk)
                            if actual_size > _ANALYZER_BUNDLE_MAX_MEMBER_BYTES:
                                raise ValueError(f"analyzer bundle member exceeds limit: {rel_text}")
                            digest.update(chunk)
                            destination.write(chunk)
                    if rel_text != _ANALYZER_BUNDLE_MANIFEST:
                        expected = declared[rel_text.casefold()]
                        if (
                            actual_size != int(expected["size_bytes"])
                            or digest.hexdigest() != expected["sha256"]
                        ):
                            raise ValueError(f"analyzer bundle file integrity mismatch: {rel_text}")
                    extracted += 1
            bundle_sha = hashlib.sha256(payload).hexdigest()
            generation = f"generation-{bundle_sha[:20]}-{time.time_ns()}"
            final_dir = generations / generation
            status = {
                **meta,
                **{key: value for key, value in manifest.items() if key != "files"},
                "schema": _ANALYZER_BUNDLE_SCHEMA,
                "complete": True,
                "file_count": extracted - 1,
                "bundle_sha256": bundle_sha,
                "generation": generation,
            }
            (staging / "status.json").write_text(
                json.dumps(status, separators=(",", ":")), encoding="utf-8"
            )
            os.replace(staging, final_dir)
            pointer_tmp.write_text(
                json.dumps(
                    {"schema": "analyzer_current_v1", "generation": generation},
                    separators=(",", ":"),
                ),
                encoding="utf-8",
            )
            os.replace(pointer_tmp, _analyzer_current_pointer_path())
            _prune_analyzer_generations(generation)
            return status
        finally:
            shutil.rmtree(staging, ignore_errors=True)
            try:
                pointer_tmp.unlink()
            except FileNotFoundError:
                pass


@app.route('/api/data-sync/analyzer-report', methods=['POST'])
def api_data_sync_analyzer_report():
    if (
        request.content_length
        and request.content_length > _ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES + 1024 * 1024
    ):
        return jsonify({"error": "analyzer upload request exceeds 51 MB"}), 413
    bundle = request.files.get("bundle")
    if bundle is not None:
        payload = bundle.read(_ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES + 1)
        if len(payload) > _ANALYZER_BUNDLE_MAX_COMPRESSED_BYTES:
            return jsonify({"error": "analyzer bundle exceeds 50 MB"}), 413
        meta = {
            "uploaded_at": utc_iso(),
            "size": len(payload),
        }
        try:
            installed = _install_analyzer_bundle(payload, meta)
        except (OSError, RuntimeError, ValueError, zipfile.BadZipFile) as exc:
            return jsonify({"error": f"invalid analyzer bundle: {exc}"}), 400
        return jsonify({"ok": True, **installed})

    # The retired HTML-only publisher produced dashboards with broken report
    # links. Existing files remain untouched for forensic review, but new
    # legacy publications are rejected and can never become active.
    upload = request.files.get("report")
    if upload is None:
        return jsonify({"error": "multipart field 'report' is required"}), 400
    return jsonify({
        "error": "HTML-only analyzer publication is retired",
        "required_schema": _ANALYZER_BUNDLE_SCHEMA,
        "legacy_data_preserved": True,
    }), 410


@app.route('/api/analyzer-mirror/status')
def api_analyzer_mirror_status():
    active = _active_analyzer_mirror_dir()
    if active is None:
        legacy_preserved = _analyzer_mirror_dir().exists()
        return jsonify({
            "available": False,
            "reason": "no complete validated analyzer bundle is installed",
            "required_schema": _ANALYZER_BUNDLE_SCHEMA,
            "legacy_data_preserved": legacy_preserved,
        }), 404
    try:
        payload = json.loads(
            (active / "status.json").read_text(encoding="utf-8")
        )
        resp = jsonify({"available": True, **payload})
        resp.headers['Cache-Control'] = 'no-store'
        return resp
    except (OSError, ValueError, TypeError):
        return jsonify({"available": False, "reason": "no local analyzer report uploaded yet"}), 404


